const o=[{Name:"Agony",Description:"",Cost:"",Book:"Pure 113",Content:[{type:"paragraph",text:"Silver Wolf is a creature of honor through pain. Despite constant agony that would kill any mortal werewolf, Silver Wolf retains his vision, wisdom and honor. Through the pain, he guides his subjects. His advice and power can lend them the ability to see through their own pain, and enable them to inflict a small fraction of that pain on his enemies. These Gifts are taught by spirits of pain or venomous animals, mostly in the service of Silver Wolf."}],Ranks:[{Rank:"•",Name:"Stoicism",Description:"For the remainder of the scene, the character suffers no wound penalties.",Cost:"●",Book:"Pure 113",fullDescription:[{type:"paragraph",text:["Silver Wolf teaches his subjects that their own pain is nothing in comparison to his own. Through this Gift, they learn to ignore their suffering. They do ",{text:"feel",italic:!0}," pain that is inflicted on them while this Gift is active; however, they are able to shunt that pain aside and act as fully capable warriors despite it."]}],fullCost:"1 Essence",dicePool:"Composure + Survival + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf taps into Silver Wolf’s agony. The werewolf suffers a -1 wound penalty even when unhurt, and all other wound penalties are increased by one for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"For the remainder of the scene, the character suffers no wound penalties."]},{type:"paragraph",text:[{text:"Dramatic Success: ",bold:!0},"For the remainder of the day, the character suffers no wound penalties."]}]},{Rank:"••",Name:"Barbed Arrow",Description:"The target suffers an additional -1 die penalty on all actions for the rest of the scene",Cost:"●",Book:"Pure 113",fullDescription:[{type:"paragraph",text:"The character taps into Silver Wolf’s pain and lets it flow through her into her foes. The werewolf must touch her foe in order to activate the Gift; if the target is unwilling (and he probably is), then this requires an ordinary melee attack roll. Only if the attack succeeds does the character spend Essence and make this Gift’s roll. The attack does damage as normal."},{type:"paragraph",text:"If the target of the attack is Uratha (whether Pure or Forsaken), any dice penalties from pain are increased by one, as the Gift’s user is tapping into the pain that silver causes."}],fullCost:"1 Essence",dicePool:"Intelligence + Medicine + Purity versus target’s Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf taps into Silver Wolf’s pain; she suffers the -1 die penalty that would ordinarily be inflicted on the target. The target suffers no effect at all."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The target suffers no effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The target suffers an additional -1 die penalty on all actions for the rest of the scene."]},{type:"paragraph",text:[{text:"Dramatic Success: ",bold:!0},"The target is knocked prone by the pain, and must take an action to stand."]}]},{Rank:"•••",Name:"Pangs of Anguish",Description:"The target takes a number of points of bashing damage equal to 3 + the successes gained on the roll",Cost:"●",Book:"Pure 114",fullDescription:[{type:"paragraph",text:"This Gift allows the user to take pain he has suffered before and inflict a sympathetic agony in his victim. With a glance, the werewolf is able to create stabbing pain in the target. The pain usually mirrors some event in the Gift user’s past, though the pain might also take the form of a remembered anguish — a cardiac victim might suffer chest pains, while a mother might relive the agony of childbirth within the space of a few seconds."}],fullCost:"1 Essence",dicePool:"Presence + Medicine + Cunning - target’s Composure",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Gift user suffers backlash, taking one point of bashing damage."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect. The werewolf may try to use this Gift again next turn normally."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The target takes a number of points of bashing damage equal to 3 + the successes gained on the roll."]},{type:"paragraph",text:[{text:"Dramatic Success: ",bold:!0},"The target must succeed at a Stamina roll versus the Gift user’s Presence, or be knocked down by the Gift’s sudden pain."]}]},{Rank:"••••",Name:"World of Pain",Description:"One spirit suffers real pain, and the spirit’s wound penalties get worse as though it were a living creature.",Cost:"○",Book:"Pure 114",fullDescription:[{type:"paragraph",text:"As creatures of quicksilver and smoke, spirits do not suffer from the indignities of the physical world. When spirits are attacked by creatures of mud and blood, spirits simply lose drabs of their cohesion — they take points of Corpus damage, in game terms. But spirits do not suffer from wound penalties."},{type:"paragraph",text:"When this Gift is successfully activated, one spirit designated by the Uratha suffers real pain, and the spirit’s wound penalties get worse as though it were a living creature. In fact, the agonies are often even more distracting, as the pain of the flesh is something few spirits have previously encountered. In game terms, the spirit suffers a -2 dice penalty immediately. When the spirit has just three Corpus points left, it has -3 to all non-reflexive dice pools. When the spirit is down to two, it suffers -4, and when it is down to its last Corpus point, the spirit suffers a -5 penalty."},{type:"paragraph",text:"The Uratha does not have to touch his target to activate this Gift, but the spirit must be within five yards in order for the werewolf to target it."}],fullCost:"1 Willpower",dicePool:"Intelligence + Occult + Glory versus the spirit’s Resistance",action:"Instant contested",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The spirit suffers no penalty, and may reflexively use one of its Numina against the Uratha, even out of turn."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The spirit is grounded in just a fraction of the pain of the physical world; effects are as above."]},{type:"paragraph",text:[{text:"Dramatic Success: ",bold:!0},"The spirit suffers a point of Corpus damage, in addition to the wound penalties inflicted by this Gift."]}]},{Rank:"•••••",Name:"All-Consuming Excruciation",Description:"Target suffers the effects of a severe derangement for the remainder of the scene, and a permanent mild derangement of the same type",Cost:"○○",Book:"Pure 114",fullDescription:[{type:"paragraph",text:"The Uratha using this Gift temporarily soothes Silver Wolf’s pain by tugging a large fraction of it away from the great totem spirit and onto a living being. No living being can withstand such agony and remain sane. Though the target of this Gift suffers no wound penalties, his mind breaks under the onslaught that Silver Wolf stoically suffers every second. The werewolf must touch his target to activate this Gift; however, it is not a reflexive Gift (meaning that either the target must be unawares or willing, or that the werewolf must touch the target on one turn and hold the target until he activates this Gift on the following turn)."}],fullCost:"2 Willpower",dicePool:"Manipulation + Empathy + Wisdom versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The user of the Gift feels a fraction of the agony he’d intended to inflict; he suffers a mild derangement for the rest of the scene."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The target suffers the effects of a severe derangement (see p. 96 of ",{text:"World of Darkness",bold:!0},") for the remainder of the scene, and a ",{text:"permanent",italic:!0}," mild derangement of the same type. The Storyteller determines the type of derangement. Subsequent uses of this Gift on the same subject cannot inflict additional derangements; however, use of the Gift may temporarily magnify a mild derangement gained from this Gift into a severe one for the duration of the scene."]},{type:"paragraph",text:[{text:"Dramatic Success: ",bold:!0},"The target collapses in gibbering agony, and suffers from a permanent severe derangement."]}]}]},{Name:"Alpha",Description:"",Cost:"",Book:"Storm Lords",Content:[{type:"paragraph",text:["The ",{text:"Iminir",italic:!0}," aspire to the role of the alpha tribe, the leaders of the Forsaken. Not every Storm Lord will be a pack leader or hold a position of authority, but it is the tribe’s duty to lead the others by example and guide their brethren, even when in a subordinate role. Alpha Gifts are often referred to as Winter Wolf’s Gifts, for the spirits that bestow them upon the Storm Lords are closely associated with the Firstborn totem of the tribe. The Gifts are traditionally sought out by ",{text:"Iminir",italic:!0}," werewolves who want to present a more authoritative demeanor in their packs, most notably by alphas or Uratha that want the top slot."]}],Ranks:[{Rank:"•",Name:"Sense Guilt",Description:"Sense any serious shame or guilt the target feels over past actions",Cost:"●",Book:"Rage 107",fullDescription:[{type:"paragraph",text:"Being the leader means knowing your friends and foes. Storm Lords use this Gift to detect any hidden shame or guilt in their packmates and enemies, to see if such a weakness can be neutralized or exploited, depending on the werewolf’s decision."},{type:"paragraph",text:"By meeting the target’s eyes for a turn, the character can search the other’s soul for evidence of guilt or past shame that still haunts the subject. This is a sensory Gift, not an invasive one."}],fullCost:"1 Essence",dicePool:"Intelligence + Empathy + Honor versus subject’s Resolve + Resistance",action:"Instant and contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The character either believes she sees a grave guilt that isn’t there in reality, or sees innocence where a great shame truly lies."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The character detects nothing about the target’s guilt."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character senses any serious shame or guilt the target feels over past actions. The subject need not be feeling the emotion at the time of the Gift, because the sense detects any shame buried deep in the werewolf’s heart. The information provided by this Gift is vague, offering only conformation of whether the target feels any serious guilt, rather than exact details of why."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"As with a success, but the information provided is much more detailed. The character gets a general sensation of whatever deed fuels the guilt, such as “crime against family,” “crime against a stranger,” “violation of Uratha law,” or so on."]}]},{Rank:"••",Name:"Alpha’s Aura",Description:"May use Composure or Intimidation rating in combat instead of Defense",Cost:"○",Book:"Rage 107",fullDescription:[{type:"paragraph",text:"An alpha should be an inspiration in war as well as peace. This Gift heightens the werewolf’s outward projection of confidence, creating a palpable aura around the Storm Lord in battle. Enemies suddenly fear the werewolf, re-evaluating their attacks and rethinking strategies in the face of such an impressive opponent."}],fullCost:"1 Willpower",dicePool:"Composure + Intimidation + Honor versus subject’s Resolve + Resistance",action:"Contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The failed Gift backfires and the effects of a success are applied to the Storm Lord instead of his opponent."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The Storm Lord fails to project his aura to intimidate the target. The Storm Lord may not try again on the same subject for the rest of the scene."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character emits a fearsome wave of authority and competence. For the remainder of the scene, the werewolf may use his Composure or his Intimidation rating in combat instead of his Defense against the target, depending on which is higher."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"As with a success, though the effects apply against the target for an entire night, until the next sunrise."]}]},{Rank:"•••",Name:"Taste of Flaws",Description:"+2 bonus to all rolls made against the subject, including combat rolls. Lasts a whole scene.",Cost:"●",Book:"Rage 108",fullDescription:[{type:"paragraph",text:"A good leader finds out all he can about his enemies before confronting them. This Gift allows the Storm Lord to sense his foe’s weaknesses, detecting flaws in his opponent’s speech, mental faculties or combat style. This Gift does not reveal specific weaknesses as with the New Moon Gift: Sense Weakness, but instead reveals an overall picture of the target’s flaws and shortcomings, allowing the Storm Lord to work around them."}],fullCost:"1 Essence",dicePool:"Wits + Empathy + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Storm Lord receives a false impression of the target’s flaws and reacts to weaknesses that do not exist. For the next three turns, the werewolf suffers a -3 penalty to all dice rolls made against the subject, whether they are combat rolls or social rolls made to intimidate, charm or negotiate, etc."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The werewolf remains unsure of the target’s flaws."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The Storm Lord receives a clear impression of the target’s flaws. The character senses how to seize upon the advantage in combat and social situations, such as exploiting weaknesses in his opponent’s combat style, pinpointing openings in his arguments and so on. For the remainder of the scene, the character receives a +2 bonus to all rolls made against the subject, including combat rolls."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"Per success, but the bonus rises to +3."]}]},{Rank:"••••",Name:"Lordly Will",Description:"Makes the character automatically immune to all Gifts, Disciplines, Numina and other supernatural mind-affecting powers.",Cost:"●●",Book:"Rage 108",fullDescription:[{type:"paragraph",text:"The strongest leaders render themselves immune to unwanted outside influence, hearing only the voice of their own authority and those of their advisors. This Gift reinforces the alpha’s dominance over his own mind in the face of psychic or other supernatural manipulation."},{type:"paragraph",text:"When activated, this Gift makes the character automatically immune to all Gifts, Disciplines, Numina and other supernatural powers that affect the mind — such as Dominance Gifts, Majesty Disciplines, etc. The Gift’s effects last for the turn in which the Gift is activated; if the opponent attempts to use another mind-affecting power on the werewolf next turn, the werewolf must spend another two Essence to invoke Lordly Will for that next turn if he so chooses."}],fullCost:"2 Essence",dicePool:"No roll is necessary.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Alpha’s Howl",Description:"For every success on the roll, an enemy within earshot loses the ability to use supernatural powers for a turn",Cost:"●●●",Book:"Rage 108",fullDescription:[{type:"paragraph",text:"With a long and powerful roar, the Storm Lord exalts in his prowess, skill and nobility over his enemies. The howl thunders through the ears of his foes, temporarily stripping them of courage and mastery of their own supernatural abilities. Any enemies within earshot of the howl (beings who actively wish to harm the character) will suffer the Gift’s effects. In cases of more than one opponent, the Storyteller should use the highest Resolve among the group to resist the Gift’s effects."}],fullCost:"3 Essence",dicePool:"Presence + Intimidation + Glory minus subjects’ Resolve",action:"Instant and resisted",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Storm Lord fails to instill dread in his enemies and may not use this Gift on anyone for another cycle of the moon."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The roar has no effect beyond its natural intimidation value."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"For every success on the roll, an enemy within earshot loses the ability to use his supernatural powers (including shapeshifting, unless in Death Rage) for a turn. Gifts fail, Disciplines don’t function, vampires are unable to spend blood to enhance Traits, etc."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"No further benefit beyond the additional successes."]}]}]},{Name:"Battle",Description:"",Cost:"",Book:"Rage 108",Content:[{type:"paragraph",text:"The Gifts that heighten a werewolf’s killing power in war are much prized by the Blood Talons, who regard these powers as a blessing from Destroyer Wolf. As such, they are often named after their totem or referred to as Destruction Gifts or Battle Gifts. While they do not specifically increase combat Skills, they add to a Blood Talon’s intimidation and efficiency in combat when facing enemies on the Wild Hunt."}],Ranks:[{Rank:"•",Name:"Visage of Fenris",Description:"Intimidate enemies suffer -2 penalty to initiative",Cost:"○",Book:"Rage 108",fullDescription:[{type:"paragraph",text:"By channeling their tribal totem’s rage, the Blood Talons can plunge themselves into the connection with Fenris-Ur and manifest an aspect of his fearsome presence to intimidate their foes. Eyes blaze with primal fury, and the werewolf’s snarl drops several octaves to mimic the growl of Destroyer Wolf."}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Glory versus subject’s Resolve + Composure",action:"Instant; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf fails to manifest Destroyer Wolf’s rage and is unable to use the Gift for the remainder of the night."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"Channeling the ferocity of Fenris-Ur, the werewolf suddenly seems more intimidating and threatening to those who oppose him. All enemies facing the character suffer a -2 reduction to their Initiative totals as they flinch back from his presence."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"As with a success, but enemies attacking the character suffer a -4 penalty instead -2."]}]},{Rank:"••",Name:"Worry the Prey’s Heels",Description:"Shame and pain slow the target's speed to half for the scene",Cost:"●",Book:"Rage 109",fullDescription:[{type:"paragraph",text:"The werewolf who wishes to catch a fleeing enemy can use this power to halt his foe’s limbs, slowing down any attempts at flight. The Gift is most often used on cowards who seek to flee a fair fight, or when a pack desperately needs to catch someone who doesn’t wish to be caught. It is said that a coward’s shame fills the heart of a fleeing enemy and slows his muscles."}],fullCost:"1 Essence",dicePool:"Presence + Intimidation + Honor versus the target’s Stamina + Primal Urge",action:"Instant; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf fails to prevent the target from fleeing and is unable to use the Gift on that subject again for another cycle of the moon."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The target is not hindered at all."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"Shame and pain slow the target’s limbs as he seeks to flee. His speed is halved for the remainder of the scene, or until the werewolf lifts the power."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"In addition to the previous effect, the target is so cowed that he suffers a -1 penalty to all Social rolls with the Blood Talon character who used this power against him for the rest of the night."]}]},{Rank:"•••",Name:"Savaging",Description:"Do 1 additional damage. Enemy witnesses suffer -2 on attack rolls for the rest of turn.",Cost:"●●",Book:"Rage 110",fullDescription:[{type:"paragraph",text:"The injuries inflicted by a Blood Talon in his Rage can be a terrifying sight. This Gift focuses on channeling Destroyer Wolf’s legendary ability to rend his foes apart as he fought them, making the wounds inflicted by a character strike fear into the hearts of those watching."},{type:"paragraph",text:"To use the Gift, the character spends the necessary Essence and makes his attack roll as normal. The power is considered a success if the character inflicts three levels of damage."}],fullCost:"2 Essence",dicePool:"No roll is required beyond the natural roll to hit an enemy in combat.",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"No additional penalty beyond the dramatic failure of the attack roll."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No additional penalty beyond missing the opponent in combat."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The attack does an additional point of damage, and the wound inflicted is so grave that those enemies of the Blood Talon who witnessed the attack suffer a -2 dice penalty to all combat rolls made against him for the rest of the turn. This penalty is psychological, and may not affect certain enemies (such as unliving automatons that are incapable of any emotion)."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"As with a success, but the dice penalty that attackers suffer is raised to -3."]}]},{Rank:"••••",Name:"Primal Anger",Description:"Add Primal Urge to attack rolls for scene",Cost:"●●",Book:"Rage 110",fullDescription:[{type:"paragraph",text:"The more a Blood Talon loses himself to his primal bloodlust, the more dangerous he becomes. Characters using this Gift harness the ferocity and wild-hearted anger of their wolfish natures, using it to enhance their strikes in battle. Every blow falls with the desperate strength of an enraged wolf on the hunt biting at its prey."},{type:"paragraph",text:"The werewolf spends the required Essence and then can add his Primal Urge rating to any attack rolls for the remainder of the scene."}],fullCost:"2 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Heartstopping Howl",Description:"Howling make enemies loose -3 to combat rolls and defense for the scene",Cost:"●●",Book:"Rage 110",fullDescription:[{type:"paragraph",text:"The howl of Destroyer Wolf roared across the Pangaean night in prehistory, terrifying spirits and mortal beings alike. His Blood Talons are children are capable of emulating this great howl to strike terror into the hearts of their enemies, reducing them to gibbering, panicking wretches."},{type:"paragraph",text:"The character howls with all of his breath, loud and long, creating a roaring howl filled with his rage and hatred. Enemies affected by the blood-chilling howl find themselves overcome with fear, trembling and weeping as they attempt to strike the Blood Talon in their midst. In cases of more than one opponent, the Storyteller should use the highest Resolve + Primal Urge among the group to resist the Gift’s effects."}],fullCost:"2 Essence",dicePool:"Presence + Intimidation + Glory versus target’s Resolve + Primal Urge",action:"Instant; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Blood Talon fails to strike terror into his foes and may not use the Gift on the same enemies again for another cycle of the moon."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The werewolf’s howl (no matter which form he is in) strikes terrible fear into the hearts of his enemies within earshot. Opponents affected suffer debilitating tremors throughout their bodies, and their eyes water with panicky tears. Every affected opponent suffers a -3 penalty on all combat dice rolls, including a -3 penalty to the opponent’s Defense, for the remainder of the scene."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"Per success, but with the penalty on opponent’s rolls raised to -4."]}]}]},{Name:"Blending",Description:"",Cost:"",Book:"Rage 111",Content:[{type:"paragraph",text:"Red Wolf asks that his Iron Masters adapt to the changes wrought by humanity and keep pace with the changes shaping the modern world. The Blending Gifts help werewolves to do that, adding a little edge against the harshness of life in the dark places of city and wilderness, the Shadow and among the unseeing human herd. Thus, these Gifts are often referred to as Red Wolf’s Gifts."}],Ranks:[{Rank:"•",Name:"Shadow Coat",Description:"-3 penalty to all dice rolls made to notice the werewolf for a scene. The Gift works only in the Shadow",Cost:"●",Book:"Rage 111",fullDescription:[{type:"paragraph",text:"The careful werewolf is interested in blending into both the physical and the spirit world. This Gift makes him seem less remarkable when in the spirit world. Spirits are less likely to notice him at all, though if they do, their ire toward one of the Uratha is not diminished."},{type:"paragraph",text:"Once activated, this Gift imposes a -3 penalty to all dice rolls made to notice the werewolf. The Gift works only in the Shadow; the Gift’s effects end at the end of the scene or when the werewolf re-enters the physical world, whichever comes first."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"••",Name:"Manytongues",Description:"Can understand but not speak the language of any human he is speaking with",Cost:"●",Book:"Rage 111",fullDescription:[{type:"paragraph",text:"Humanity has hundreds of languages in use today, and hundreds more that have seen use during past centuries. Iron Masters have fallen back on this Gift a great many times over the years, especially when moving to claim territory in a new area. Manytongues allows the werewolf to understand but not speak the language of any human he is speaking with, whether it is face-to-face or over the phone, as long as he can hear the subject’s voice."}],fullCost:"1 Essence per targeted subject",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"•••",Name:"Resist Toxin",Description:"Purify system immediately and take no damage from poisoning",Cost:"●",Book:"Rage 111",fullDescription:[{type:"paragraph",text:"Cities produce a great deal of foulness as they grow and develop. Between artificial human-made toxins that can affect the Shadow and the powers of some spirits to poison their enemies, this Gift is a handy defense mechanism."},{type:"paragraph",text:"Any time the character suffers the harmful effects of poisoning, he can activate this Gift to purify his system immediately and take no damage."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"••••",Name:"Mask the Hunter",Description:"Lose social penalties of Primal Urge for the rest of the scene",Cost:"●●●",Book:"Rage 111",fullDescription:[{type:"paragraph",text:"Even when werewolves don’t wish to, they attract attention. The burden of Primal Urge can seem to be a blessing in a werewolf’s life, but Primal Urge subconsciously alerts nearby humans that there is a predator in their midst. This Gift is one of the most valuable offered by Red Wolf, allowing an Iron Master to suppress the wolf within for a short time and interacting with humans normally."},{type:"paragraph",text:"Once the power is activated by the expenditure of Essence, the character is no longer subject to the social penalties of Primal Urge for the rest of the scene. Unfortunately, this advantage comes at significant cost in Essence. There is simply no easy way for the hunters to walk among the herd, and this Gift is treasured by those who use it even for short durations."}],fullCost:"3 Essence",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"•••••",Name:"Hide the Curse",Description:"Lose the ability to channel any supernatural abilities, including shapeshifting, until nightfall",Cost:"●●●",Book:"Rage 111",fullDescription:[{type:"paragraph",text:"Mastering the most powerful elements of change and adapting to one’s environment, this Gift from Sagrim-Ur allows a werewolf to mask himself completely among the human herd. For a single day, the werewolf has the ability to suppress his own curse, living from sunrise until sunset as a perfectly normal human. Of course, with no fear of Death Rage and no Primal Urge making humans uncomfortable also comes the inability to shapeshift and use any Gifts, so werewolves should be very careful when they use this power. This Gift only functions during the day; the power of Luna over her children renders any attempts to use this Gift past nightfall completely impossible."}],fullCost:"3 Essence",dicePool:"Harmony",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Gift fails, and the Lunes of the character’s choir are angered by her presumption. At the Storyteller’s discretion, the character may suffer minor social penalties in dealings with the Lunes associated with her choir, and is unable to use the Gift again for a full lunar cycle."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The Gift simply fails."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character loses the ability to channel any of her supernatural abilities, including shapeshifting, until nightfall. The character is considered completely mortal in all respects, lacking even regeneration and Primal Urge."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"No further effect."]}]}]},{Name:"Blood",Description:"",Cost:"",Book:"Lore 116",Content:[{type:"paragraph",text:"Blood pumping, hearts pounding, the Uratha hunt down their prey. Their claws open deep wounds, casting scarlet blood over the ground as their victim breathes his last. Werewolves are inextricably linked with blood as a sign of their violence and Rage, and the Gifts of Blood arise from that. Unlike the bones of the long dead, spilled blood is a sign of action, and these Gifts allow an Uratha to pick up on those signs. Uratha seek predatory animal-spirits, especially wolverines and sharks, to learn Blood Gifts."}],Ranks:[{Rank:"•",Name:"Blood Divination",Description:"View symbolic future in a patch of blood",Cost:"-",Book:"Lore 116",fullDescription:[{type:"paragraph",text:"This Gift allows the user to see possible knots in the future in the fall of a few drops of blood. The visions that the Gift provides a werewolf are glimpses of a place and time clouded in symbolism, and she may not know what she has seen until she encounters it. The character must spill blood in order to use this Gift, though a few drops from a self-inflicted cut will work."}],fullCost:"None",dicePool:"Resolve + Occult + Wisdom",action:"Extended (20 successes required; each roll represents one minute of concentration)",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The seer is rattled by the omen he sees. The character loses one Willpower point."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No successes are gained for this minute."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"Successes are gained. If the character achieves 20 or more successes, the patterns of blood resolve into a symbolic warning in the character’s mind. At any point in the next six hours, the player may nominate a given die roll to receive an additional +1 circumstance bonus as the werewolf recognizes the situation he’s in and instinctively acts as the blood omen had warned. The character can benefit from only one application of this Gift at a time."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"No additional effect apart from the omen being gained more rapidly."]}]},{Rank:"••",Name:"Shark's Scent",Description:"Can follow blood scent in air",Cost:"-",Book:"Lore 116",fullDescription:[{type:"paragraph",text:"Sharks have an uncanny ability to follow a trail of blood through water, picking up on the tiniest trace to find the bleeding creature. A werewolf with this Gift can replicate that feat in air. He can pick up on the scent of blood when even other Uratha would not notice it, and can follow the trail to its source through the smog of rush-hour."}],fullCost:"None",dicePool:"Wits + Composure + Purity",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The trail is misleading or stops abruptly, leaving the werewolf in unfamiliar territory without an easy way out."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The Gift fails. Either the trail vanishes soon after starting, or there is no trail that the character can follow to begin with."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character can track anyone who has bled within an acre (a city block in urban areas) within the last six hours. He can pick out individual trails well enough to track by scent without penalty, and can reflexively re-activate this Gift when its effects fade without losing the trail. This Gift lasts for one scene. Note that using this Gift does not count as having tasted the target’s blood for purposes of other means of tracking."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The werewolf’s heightened sense of smell allows him to pick up old trails even in a storm or a busy part of a city. Using the Gift, he can track people who have bled in the area up to a day before."]}]},{Rank:"•••",Name:"Clot",Description:"Close a wound and increase healing time of the target",Cost:"●",Book:"Lore 116",fullDescription:[{type:"paragraph",text:"Spilled blood clots, sealing over an injury and giving the skin beneath a chance to heal. Werewolves who possess this Gift can cause any bleeding wound to clot instantly, even if the target is hemophilic or bleeding from an artery. The Uratha lays her hands on her subject, letting her Essence flow. The blood clots created by this Gift can stop wolf-blooded or even other werewolves from bleeding to death, and the protection they offer allows the wound to heal much faster. The Uratha cannot use this Gift on herself."}],fullCost:"1 Essence",dicePool:"Stamina + Medicine + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The subject of the Gift immediately takes one point of lethal damage as the wound bleeds freely."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The Gift fails to take effect."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The subject’s blood thickens and clots. If the subject is bleeding to death, (see “Incapacitation,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 173) she loses no more points of Health, and her rightmost Health box is changed to bashing damage.",{type:"lineBreak"},"On a less grievously injured subject, the healing time for all bleeding lethal damage taken from a single source is reduced to three-quarters normal. Humans heal the damage at a rate of one and a half days per point, rather than two. Storytellers should use their discretion as to which injuries this Gift can affect."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"If bleeding to death, the subject’s rightmost aggravated wound is converted to lethal, or her two rightmost lethal wounds are converted to bashing. Characters with lesser injuries heal at twice the normal rate rather than one and a half times."]}]},{Rank:"••••",Name:"Scent Weakness",Description:"Sense any weakness from the target blood",Cost:"●",Book:"Lore 116",fullDescription:[{type:"paragraph",text:"When a wolf is close enough to its prey to track it by scent, it uses the smell of blood to isolate weaker prey. This Gift expands upon that principle, identifying a target’s weaknesses from the scent of his blood. The Uratha becomes aware of all of the target’s weaknesses, not just physical illness or infirmity, so that she knows how best to approach her target and the best tactics to take him down."}],fullCost:"1 Essence",dicePool:"Wits + Survival + Cunning versus subject’s Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf detects weaknesses that her subject does not have. Any actions the character takes against her target suffer a -1 penalty for a day. The werewolf cannot re-use this Gift on the same target for a week."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"If the user’s roll fails or the subject rolls as many or more successes than the user, nothing happens."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The user rolls more successes than the subject. The werewolf catches scent of the target’s weaknesses, and understands instinctively how to exploit them. For the next hour, the werewolf gains a +1 bonus to all contested rolls made against the target — it becomes equally harder to grapple mentally or physically with a werewolf who knows your weak spots.",{type:"lineBreak"},"A werewolf can use this Gift on a subject she is tracking with Shark’s Scent. The werewolf can have this Gift active against only one target at a time."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The Gift lasts for 4 hours."]}]},{Rank:"•••••",Name:"Sacrifice",Description:"Trade blood with essence",Cost:"-",Book:"Lore 117",fullDescription:[{type:"paragraph",text:"An Uratha with this Gift can make the ultimate sacrifice. Cutting herself with her own claws, the werewolf gives up a measure of her own blood to the spirits. In return for her self-sacrifice, the spirits imbue her with a measure of their power, imbuing her with Essence. This is a dangerous Gift, as it makes the werewolf physically weaker — but those who think that an Uratha can only be physically dangerous do not understand their opponents."},{type:"paragraph",text:"Each point of aggravated damage that the character inflicts upon herself when activating this Gift gives the character three points of Essence. The werewolf using this Gift must be the one to inflict the damage, and cannot use this Gift without inflicting at least one point of damage. The character may have more Essence than her Primal Urge score would normally allow, but any excess points are lost at the end of the turn."}],fullCost:"None",dicePool:"This power requires no roll",action:"Reflexive",rollResults:[]}]},{Name:"Bone",Description:"",Cost:"",Book:"Lore 117",Content:[{type:"paragraph",text:"Whether cleaving their enemies’ skulls or smashing their bones clean through, speaking with the spirit of a skull or chilling the very marrow of whoever sees them, there is no doubt that the Uratha are tied to bone as a sign of fear and death. Some werewolves capitalize on this, learning Gifts that play upon their mythic links to the bones of their enemies. Spirits associated with death, including owl-spirits and raven-spirits, teach Gifts of Bone. These Gifts exploit the bone as a link to the dead as well as the integral part of a living person, giving a werewolf power over the full range of influence."}],Ranks:[{Rank:"•",Name:"Strip Carcass",Description:"Remove flesh from bones of a dead corpse",Cost:"-",Book:"Lore 117",fullDescription:[{type:"paragraph",text:"Werewolves have many uses for the bones of their foes, from ritual aids to jewelry and fetish-making. Waiting for the flesh to decay can take too long, and the presence of a butchered corpse missing its skull often causes too many awkward questions. This Gift causes already dead flesh to decay, sloughing off the bones of the fallen in grey-brown puddles of rotten meat."}],fullCost:"None",dicePool:"Composure + Survival + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The meat rots under the werewolf’s touch, but the bone fragments and dissolves as well, leaving a half-melted puddle of flesh and bone."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"Nothing happens."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"Flesh sloughs away from the bone. Each success strips the meat from an area equivalent to point of Size, equivalent to a human arm or leg. This process takes two full turns per point of Size cleaned to complete, but the character does not have to concentrate upon it."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The character strips all the flesh from a normal-sized (Size 5) human corpse in two turns."]}]},{Rank:"••",Name:"Dead Men's Bones",Description:"Reveal from a body's bones the way he died",Cost:"-",Book:"Lore 118",fullDescription:[{type:"paragraph",text:"Legends tell of a dead man’s eyes holding the last thing they saw long after the life had passed from the body. That may not be true, but an Uratha who knows this Gift can interrogate the bones of a dead creature to find out how he died. Note that this does not contact the creature’s ghost, if any; it is rather a method of divination based on the bones themselves."}],fullCost:"None",dicePool:"Presence + Investigation + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The bones do not care to tell the werewolf what they know. This Gift cannot be used again on the same carcass."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The bones do not tell the character anything she does not already know."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The bones tell the werewolf the specific cause and time of death, but not the who’s or why’s. A poisoning victim could transmit the information “ingested cyanide an hour past sunset,” but could not reveal how the cyanide was hidden or who the poisoner was."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The character learns an additional bit of information about the cause of death. In the case of the poisoning victim, the character may learn “ingested cyanide in coffee an hour past sunset.”"]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Circumstance"],rows:[["+1","Skull is intact"]]}]},{Rank:"•••",Name:"Freeze Marrow",Description:"Inflict freezing fear to the target",Cost:"●",Book:"Lore 118",fullDescription:[{type:"paragraph",text:"Even those who are not afflicted with Lunacy are often rightly frightened to see an Uratha in one of his mixed forms. This Gift allows the werewolf that same effect even in Hishu or Urhan forms, striking fear deep into his target’s bones with just a look. The fear that this Gift inspires lasts for at least a scene, and memories of it can scar weaker-willed people for life."}],fullCost:"1 Essence",dicePool:"Presence + Intimidation + Glory versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Gift’s effects fail completely. The werewolf cannot use this Gift on the same target for a lunar month."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"If equal or more successes are rolled for the target, or the user’s roll fails, then the subject does not feel any more fear than normal."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"If the character using this Gift rolls more successes, the target suffers a -1 modifier to all actions that directly oppose the user. Attempts to flee or otherwise avoid the character are not penalized. The Gift’s effects last for a scene."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The subject will suffer the effects of this Gift over again the next time he encounters the werewolf."]}]},{Rank:"••••",Name:"Fracture",Description:"Break the target's bones",Cost:"●●",Book:"Lore 118",fullDescription:[{type:"paragraph",text:"The teeth and claws of a werewolf’s Gauru and Urshul form can cut through flesh and bone easily enough. When a werewolf finds herself unable to use those shapes, then this Gift is a useful alternative. An Uratha who knows this Gift can break the bones of any creature with little more than a touch. When backed with the force of a werewolf’s muscle, the target will often lose a limb even if he survives."},{type:"paragraph",text:"The werewolf using this Gift must first strike her target for at least one point of damage. The werewolf cannot attack with a weapon, but, other than that, there is no restriction on the kind of attack that can be used for this Gift."}],fullCost:"2 Essence",dicePool:"Strength + Medicine + Glory",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The werewolf wrenches one of his own bones trying to strike, taking one point of bashing damage."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The character hits no harder than normal."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The user deals one extra point of lethal damage per success rolled. If the character hits an arm, the target drops anything he was carrying in that hand. If the attack hits a leg, the target’s Speed is halved for the duration of a scene. Strikes to the torso or head give the target an additional -1 modifier on all physical actions for one turn per success."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"As a success, and the bone shatters into hundreds of fragments. Unless the target receives supernatural healing, the bone will never set properly and may need amputating."]}]},{Rank:"•••••",Name:"Bone Carapace",Description:"Grow bones to serve as armor or weapon",Cost:"●",Book:"Lore 119",fullDescription:[{type:"paragraph",text:"The werewolf turns his mastery over bones back within himself, forcing his skeleton to extend spurs through his skin. These wickedly sharp plates not only turn aside attacks that would harm him, but the keen edges slice open anyone who manages to land a blow. Having parts of his bones burst out of his skin does hurt the werewolf, but his pain is often worth the extra protection."}],fullCost:"1 Essence",dicePool:"Stamina + Medicine + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"Bones split the character’s skin but are ill-formed and weak; the character takes one point of lethal damage but gains no benefit."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"Nothing happens. The character takes no damage, and human witnesses do not suffer Lunacy."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The werewolf takes one point of lethal damage and gains two points of Armor against physical attacks and firearms. The bone spurs may be used as weapons, inflicting +1 lethal damage. Once per turn, the werewolf may make a Dexterity + Brawl check against anyone grappling him as a reflexive action; the target contests with Dexterity + Brawl as a reflexive action. If the werewolf wins this reflexive contest, the target takes one point of lethal damage for each success by which the werewolf won.",{type:"lineBreak"},"The Armor provided by this Gift cannot protect the werewolf against damage done by silver."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The werewolf gains three points of Armor rather than two."]}]}]},{Name:"City",Description:"",Cost:"",Book:"Lore 119",Content:[{type:"paragraph",text:"Metal scraps bang on fire escapes and empty trashcans, beating out a rhythm that pulses with the beat of a werewolf’s heart. Trash fires burn, casting the city in living, yellow light. For many humans, their walls and buildings are their refuge, a place that they retreat to for safety. But to an Uratha who knows these Gifts, the spirit of the City is an ally in the hunt. Building- and road-spirits teach these Gifts, as do the spirits of urban animals."}],Ranks:[{Rank:"•",Name:"City Eyes",Description:"See by the windows of a building",Cost:"-",Book:"Lore 119",fullDescription:[{type:"paragraph",text:"Windows are the eyes of a city, everything recorded by the spirits in the panes of glass. For an urban hunter, this extra perspective can help her track prey or be aware of danger. The Uratha using this Gift places her hand to one window of the building and communes with the building’s spirit to see everything its eyes can with perfect clarity."}],fullCost:"None",dicePool:"Wits + Composure + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The window shatters under the werewolf’s hand, and nobody can use the Gift on that building for at least a half-hour."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The werewolf is unable to see through any of the building’s windows."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The werewolf can see through any of the windows of the building, looking either in or out, though she can only see through one at a time. She can change views once per turn, but cannot see through her own eyes while the Gift is active. The Gift’s effects last for thirty seconds per success."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The werewolf can see through more than one window at a time. Perception tasks to keep track of someone within the building get a +1 modifier. The Gift’s effects last for thirty seconds per success."]}]},{Rank:"••",Name:"Word on the Street",Description:"Gain information from streets",Cost:"●",Book:"Lore 120",fullDescription:[{type:"paragraph",text:"People may come and go, but a city street never forgets. From the moment people fixed the idea of the road into place, the spirit of the road has remembered everything that transpires upon it. Great speeches, uprisings, murders — the street knows it all until the day people tear it up, and nobody remembers it any more. The werewolf using this Gift touches the blacktop lightly and allows his Essence to flow through to the spirit of the road. The werewolf may delve into the road’s “memory” in such a fashion."}],fullCost:"Essence",dicePool:"Wits + Investigation + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The road’s memory is patchy and unreliable, infecting the werewolf with a temporary state of urban forgetfulness. The character suffers a -1 penalty to Streetwise rolls until the next moonrise."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The user does not learn anything more than he already knows."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The road responds directly to the character’s questions about one incident in the past, giving him a complete understanding of what transpired from the perspective of the road and possibly granting new insight. For example, “",{text:"Freddie was running but was out of breath and turned off onto Ninth a couple of minutes before something tore his head off.",italic:!0},"”"]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The road responds with more detailed information. “",{text:"Freddie was running oddly, bleeding from one leg, and clutching something to his chest. He collapsed twice, and lost something on the sidewalk the second time, in front of the burned-out hotel.",italic:!0},"”"]}]},{Rank:"•••",Name:"Gridlock",Description:"Forbid a target to escape with the help of the city",Cost:"●",Book:"Lore 120",fullDescription:[{type:"paragraph",text:"Uratha are the master hunters of the city as well as the wilderness, and this Gift helps demonstrate that fact to their prey. The werewolf reaches out into the spirit of his city and breaks the lines of escape around his prey. Busses never arrive. Traffic is jammed solid. Subway trains do not stop at any platform the target waits at. Rubble and trash snare the prey’s feet, if a crowd doesn’t form to block his way through. The werewolf must know roughly where his prey is and must be in the same city for this Gift to work. This Gift can be used only in an urban environment."}],fullCost:"1 Essence",dicePool:"Resolve + Streetwise + Glory versus Composure + Primal Urge",action:"Instant, contested",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"Everything the city does to stop the target is seconds too late. The truck pulls out just after his taxi; the crowd is just thin enough that he can squeeze through and away from the werewolf. All attempts to follow the target for the rest of the scene have a -1 penalty."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The city does not react, and the target can escape without hindrance."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The target cannot escape his immediate surroundings by any vehicular means, and his Speed on foot is reduced by 2 due to the little inconveniences the city throws in his path. The Gift’s effects last for one minute per success."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The target’s Speed is reduced by 3."]}]},{Rank:"••••",Name:"City Running",Description:"Use impossible shortcut through the city",Cost:"●●",Book:"Lore 120",fullDescription:[{type:"paragraph",text:"The city arranges things between the werewolf and his destination to ensure a direct path that is much faster than walking. Fire escapes drop at just the right time for the werewolf to grab, buildings seem to lean closer to catch him when he may fall short and balconies are just where he needs them to be for a perfect landing. A werewolf with this Gift is the fastest predator in any city, capable of outpacing cars and trains, but must run over roofs and leap between buildings."}],fullCost:"2 Essence",dicePool:"Dexterity + Streetwise + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"A fire escape is not in position, or a crucial jump is just two inches too far. The character falls at an appropriate point in the run and takes damage for the resulting fall."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The werewolf reaches his destination in the same time as it would have taken to walk, but by a more impressive route."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character must know his destination when activating the Gift. From that point, he can run across rooftops, balconies, fire escapes and other urban features in a shortcut across the city skyline. The next time he stops moving is when he reaches his destination. Divide the time taken to reach the destination on foot by the number of successes rolled plus one. This is the time it takes the werewolf to travel the full distance. Architectural impossibilities, gang wars and major rivers are no obstacles to this Gift, as long as the start and end points are in the same city."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"The werewolf outpaces the best transport that humans can offer, arriving at his destination incredibly quickly. On the turn that his run ends, the character doubles his Speed."]}]},{Rank:"•••••",Name:"Urban Chaos",Description:"Unleash chaos in the city",Cost:"●●●",Book:"Lore 121",fullDescription:[{type:"paragraph",text:"Humans may have built the first cities, but all have spiritual reflections apart from their creators. The spirit of a city can exist without the people crammed into it, and sometimes it is actively displeased with the humans who cram its streets and foul its alleyways. This Gift allows an Uratha to direct the anger of a suddenly very active city against its population. Fire hydrants explode like cannon shells, streetlights over-charge and ground out through people and windows shatter, raining razor shards of glass as the city seeks to reclaim its streets."}],fullCost:"3 Essence",dicePool:"Intelligence + Streetwise + Wisdom",action:"Extended (35 successes needed; each roll represents five minutes of concentration)",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"All accumulated successes are lost. The werewolf cannot use this gift on the same city block again."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"No successes are gained yet. If three successive rolls fail, the werewolf cannot continue, and the Gift fails."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"Successes are added. Once 35 are gathered, the block lashes out at the people within it by launching fire hydrants, raining broken glass, dropping billboards or any other appropriate means. The block makes two attacks per turn until the end of the scene. Each attack is resolved as a thrown attack with a seven-dice basic pool that occurs on the werewolf’s initiative. The means of attack determines the statistics of the ‘weapon’ the angered city uses: fire hydrants are 3 (L), broken glass is 2 (L) and a billboard is 2 (B).",{type:"lineBreak"},"Everyone in the city block suffers a -2 reduction in Speed, and may suffer a -1 penalty to other tasks at the Storyteller’s discretion due to smoke, dust and falling debris."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"If the user rolls five more successes than needed, one of the buildings in the affected block collapses. Anyone underneath or inside takes 10 points of lethal damage to which only armor, not defense, applies."]}]}]},{Name:"Crescent Moon",Description:"",Cost:"",Book:"WtF 104",Content:[{type:"paragraph",text:"The Shadow Realm is a dangerous place of ideas and knowledge given shape. Charged with the task of deciphering this knowledge and confronting the dark side of the spirit world, Ithaeur take special care to explore and learn as much about the Shadow as they can. The spirits of the Crescent Moon Choir favor such pursuits, in their own aloof way. It is up to the People, however, to temper their intellectual curiosity with restraint, lest a lack of wisdom lead them into trouble and make an unfavorable impression on the Ithalunim."},{type:"paragraph",text:"The following Gifts are available only to Ithaeur."}],Ranks:[{Rank:"•",Name:"Two-World Eyes",Description:"Peer on two sides of the Gauntlet",Cost:"-",Book:"WtF 104",fullDescription:[{type:"paragraph",text:"Although they’re creatures of two worlds, the Uratha can exist fully in only one or the other. They can look from one to the other or cross the boundary that separates them, but doing so is still an all-or-nothing proposition. Ithaeur, however, can peer across the line between worlds without sacrificing their perception of either. In one eye, the werewolf sees the physical world, while in the other eye, she sees what happens in the corresponding area of the Shadow. The eye that sees the world that the werewolf does not currently inhabit films over with the deep indigo of the night sky, lit by pinpoints of starlight."},{type:"paragraph",text:"None of the werewolf’s senses except sight stretch across the Gauntlet while this Gift is active, but the werewolf suffers no penalties for having her attention divided. The effect lasts for as many turns as the player rolls successes. The presence or influence of a locus has no effect on the use of this Gift."},{type:"paragraph",text:"Using this Gift does not make characters on the opposite side of the Gauntlet aware of your character’s attention. Mundane effects that impair your character’s eyesight (such as a flashbulb going off in his face, a smoke grenade occluding the air, or simple darkness) impose the same penalties while the character’s attention is divided as they normally would."}],fullCost:"None",dicePool:"Wits + Occult + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The landscape across the Gauntlet overwhelms the character’s senses rather than dividing them evenly. He is subject to the normal penalties for peeking across the Gauntlet (see p. 252), for the remainder of the scene. Crossing the Gauntlet during this period only causes his perceptions to shift back to the other side, rather than clearing up the problem."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The character cannot peer across the Gauntlet."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The character can see and understand what’s happening on both sides of the Gauntlet without penalty."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"In addition to sight, the character can divide his sense of either smell or hearing across the Gauntlet as well."]}]},{Rank:"••",Name:"Read Spirit",Description:"Analyze spirit characteristics",Cost:"●",Book:"WtF 105",fullDescription:[{type:"paragraph",text:"The spirit servants of Luna see and know more than they let on, and wise Ithaeur can gain a portion of their Ithaeur allies’ insight for their own. As a reward for such wisdom, the spirits of the Crescent Moon Choir share what information they have, singing in a high, lilting whisper that only a werewolf using this Gift can hear."},{type:"paragraph",text:["With the expenditure of one Essence point and a single success achieved on an Intelligence + Occult + Cunning roll, the werewolf hears an internal voice like that of the ethereal Ithalunim. The voice reveals the name, type and Rank of a spirit under scrutiny. Another pertinent fact is also gained for each success after the first. “Pertinent facts” include the spirit’s Power, Finesse or Resistance score; its Willpower; its Essence; its Speed; or what Charms it has (on a one-Charm-per-success basis). These revelations are always couched in in-character terms. The Gift reveals that a spirit “has an exceptional strength of will,” not that the spirit “has Willpower 9.” This Gift may be used only once on any given spirit during a particular scene."]},{type:"paragraph",text:"The Ithaeur’s player decides the facts for which her successes count. If the Ithaeur is exceptionally lucky, the Lune might also reveal an even more interesting fact about the spirit. Such facts include what the spirit was doing at a specific time, what ban it asks of werewolf supplicants, what languages it speaks other than the First Tongue or what obscure behavior might offend it."},{type:"paragraph",text:["Alternatively, if the player wants to roleplay the use of this Gift as an actual scene and an Ithalunim Lune is on hand, you may choose to have the Lune truthfully answer one question per success on the Intelligence + Occult + Cunning roll. For the sake of the scene, the Lune in question is assumed to know the answers to the werewolf’s questions. Getting the Lune to ",{text:"give",italic:!0}," those answers, however, is a matter of roleplaying and dice rolling."]},{type:"paragraph",text:"The spirit to be read need not be under the werewolf’s power or even be present for this Gift to work, but the Ithaeur has to have at least had some personal experience with the spirit in order to invoke this Gift. (One scene of any sort of interaction suffices for a spirit that is not present.) If she’s only read about a particular spirit or heard stories about it, the knowledge of the Ithaeur doesn’t help."},{type:"paragraph",text:"This power does not give information about ghosts or supernatural beings who use a power to render themselves immaterial (such as vampires using the Twilight Projection power). Nor does it offer information on werewolves, Beshilu, Azlu or other creatures of both flesh and spirit."}],fullCost:"1 Essence",dicePool:"Intelligence + Occult + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Lune’s response is filtered through a haze of lunar madness, offering inaccurate information about the spirit."},{type:"line",label:"Failure",text:"The Gift does not provide answers to the Ithaeur’s question; she is met with silence or perhaps by garbled lunatic nonsense."},{type:"line",label:"Success",text:"The Gift reveals the spirit’s name (if it has an individual name), type and Rank, as well as one additional fact per success rolled after the first."},{type:"line",label:"Exceptional Success",text:"As a success, and the Lune reveals one specific fact about the spirit that could prove pertinent to the plot of the story."}]},{Rank:"•••",Name:"Gauntlet Cloak",Description:"Hide inside the Gauntlet",Cost:"●",Book:"WtF 105",fullDescription:[{type:"paragraph",text:["As an Ithaeur’s understanding of the workings of the spirit world grows, he begins to learn how to manipulate the Gauntlet itself. The first step in doing so lies in pulling at the warp and weft of it to draw it around himself protectively, partially immersing himself in the spirit boundary without crossing over. When a werewolf activates this Gift, the very stuff of the Gauntlet swirls around and over him, partially obscuring him behind a shifting membrane that appears to be made of the nighttime ",{text:"Hisil",italic:!0}," sky."]},{type:"paragraph",text:["Use of this Gift inflicts a –2 penalty upon mundane and supernatural attempts to spot the character, as well as a –1 penalty against attempts to recognize the character should someone spot her. The effect also offers a –2 concealment modifier against ranged attacks. A character who is already substantially concealed (–3 to ranged attacks made against her) now imposes a –5 penalty to incoming ranged attacks. See the ",{text:"World of Darkness Rulebook",bold:!0},", p. 162, for details on concealment. These effects last for a number of turns equal to the number of successes achieved on the Dexterity + Occult + Purity roll. A character may cross the Gauntlet after activating this Gift, but she receives no special bonuses to the attempt. If she wishes to be cloaked again when she arrives on the other side, she must re-activate the power."]},{type:"paragraph",text:"Due to the effort it takes to enwrap oneself and disentangle oneself from the Gauntlet, a werewolf cannot use Between the Weave or Crash the Gates during a turn in which he’s using Gauntlet Cloak."}],fullCost:"1 Essence",dicePool:"Dexterity + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The character does not manipulate the Gauntlet to his advantage. In fact, he warps it in such a way that he tears it. This tear reseals itself instantly like the walls of a burst blood vessel, but a hostile spirit in the area might take the opportunity to leap from the Shadow to the physical world. (The tear does not allow any being other than a spirit to cross over, though.)"},{type:"line",label:"Failure",text:"The character is unable to manipulate the Gauntlet."},{type:"line",label:"Success",text:"The character manipulates the Gauntlet, accruing the listed bonuses and inflicting the listed penalties."},{type:"line",label:"Exceptional Success",text:"The character’s split condition inflicts a –3 penalty on ranged attacks (as if she were substantially concealed), as well as a +1 bonus to the Ithaeur’s Defense against close-combat attacks."}]},{Rank:"••••",Name:"Between the Weave",Description:"Cross Gauntlet reflexively",Cost:"●",Book:"WtF 106",fullDescription:[{type:"paragraph",text:"As a Ithaeur’s mastery of the ways of the spirit world grows, she learns even better how to manipulate the Gauntlet. She is now adept at finding and slipping through local points of least resistance, making travel between worlds all but effortless. In a locus’ area of influence, she is perhaps the most dangerous member of her pack."},{type:"paragraph",text:["A werewolf using this Gift can cross the Gauntlet as a reflexive action and still take an action in the same turn. She can leap through the Gauntlet and attack an opponent, for example, inflicting a surprise penalty on her foe (unless her foe is using Two-World Eyes at that very moment or succeeds on a reflexive Wits + Composure roll at a -4 penalty). She could also escape a particularly gruesome situation in one world and spend a few moments regenerating in the other before rejoining the fray. She could even attack a foe ",{text:"then",italic:!0}," disappear across the Gauntlet before the foe has a chance to take an action. If she’s of a mind to really devour her Essence, she can slip back and forth across the Gauntlet multiple times in a combat situation to disorient enemies or help embattled allies who are across the Gauntlet from each other."]},{type:"paragraph",text:"Using this Gift only makes crossing the Gauntlet a reflexive action, however. It does not grant the character any additional actions. Also, this Gift still requires the Ithaeur to be within the area of influence of a locus. It only allows her to step sideways quickly, not to step sideways anywhere."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Crash the Gates",Description:"Grant Between the Weave to packmates",Cost:"● (●+)",Book:"WtF 106",fullDescription:[{type:"paragraph",text:"The Ithaeur’s knowledge of the nature of the Gauntlet has grown such that she can extend the effect of the Gift: Between the Weave to her packmates. As with Between the Weave, this Gift does not allow for instantaneous side-stepping away from a locus."},{type:"paragraph",text:"The effects are the same as for Between the Weave, but the Ithaeur must spend one point of Essence per packmate she intends to usher across the Gauntlet in addition to the Essence she must spend on her own behalf. This Gift works only for the Ithaeur and her packmates, and each packmate must be present, conscious and willing to cross the Gauntlet with the others. The unconscious and the unwilling will be left behind, and the Ithaeur does not have to pay the Essence cost for them."},{type:"paragraph",text:"Most packs who use this Gift to good effect do so as a way to launch devastating surprise attacks on those who have entered the heart of their territory. Should they try to use the tactic once combat has already started (i.e., once Initiative has already been rolled), they do so on the Ithaeur’s Initiative. Characters who act before the Ithaeur can attack a foe on the same side of the Gauntlet before crossing over in that turn, but they cannot attack a foe on the opposite side unless they delays their actions until after the Ithaeur has acted. Characters whose Initiative falls after the Ithaeur’s cross over with the rest of their packmates, but they don’t have a chance to act until after they have crossed over. The Ithaeur can take an action before or after crossing the Gauntlet, but not both in that same turn. The Ithaeur’s packmates cross the Gauntlet only in the same direction as the Ithaeur does. They can’t pass like ships in the night just because the Ithaeur is using this Gift."},{type:"paragraph",text:"The experience cost to learn this Gift is doubled if the character does not already know Between the Weave."}],fullCost:"1 Essence + (1 Essence per additional packmate)",dicePool:"No roll is required",action:"Instant",rollResults:[]}]},{Name:"Cunning",Description:"",Cost:"",Book:"SotM 33",Content:[{type:"paragraph",text:"The secrets of the trickster, the thief, the liar, and the assassin, the Gifts of Cunning light the way for those who walk under the shadows of Mother Moon. All Cunning Gifts can be taught by Irralunim, in addition to any other type of spirit listed under their respective descriptions. These are affinity Gifts for Irraka and cannot be learned by Uratha of other auspices."}],Ranks:[{Rank:"•",Name:"Wolf-Heart Lies",Description:"Conceal the nature as Uratha",Cost:"○",Book:"SotM 33",fullDescription:[{type:"paragraph",text:"Sometimes, it just doesn’t pay to be a werewolf. Hostile spirits and Pure can sense the Primal Urge inside one of the Forsaken and then things go all to hell. In fact, one of the Forsaken occasionally wants to go unknown among his own. Maybe he needs to violate the territory of another pack or he’s just hoping to go incognito through an unknown area. With this Gift, a New Moon can quell the subtle scent of his Primal Urge, so that it becomes difficult or even impossible for other werewolves to know him for what he is."}],fullCost:"1 Willpower",dicePool:"Manipulation + Subterfuge + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure: ",bold:!0},"The Irraka unintentionally ",{text:"enhances",italic:!0}," the elusive scent of his Primal Urge in a way that rankles the bestial nature of other werewolves, causing Uratha in his vicinity to suffer a -1 penalty to any roll to resist a Death Rage specifically directed toward the New Moon."]},{type:"paragraph",text:[{text:"Failure: ",bold:!0},"The Irraka fails to conceal his nature as Uratha."]},{type:"paragraph",text:[{text:"Success: ",bold:!0},"The supernatural scent of the New Moon’s Primal Urge is suppressed for the remainder of the scene. Any attempt to discern his nature as Forsaken by scent (see ",{text:"Werewolf: The Forsaken",bold:!0},", p. 180; “Wolf’s Blood”) fails, unless the scenting Uratha scores more successes on her Wits + Primal Urge roll than the Irraka has dots in Cunning Renown. Other powers can still detect an Irraka thus concealed for what he is and this Gift will not deceive any senses other than scent (so an Irraka who moves in any shape other than Hishu or Urhan can easily be discerned as Uratha)."]},{type:"paragraph",text:[{text:"Exceptional Success: ",bold:!0},"No number of successes on the part of a scenting werewolf can penetrate the New Moon’s olfactory concealment."]}]},{Rank:"••",Name:"Crack in the Armor",Description:"Can detect flaws",Cost:"●",Book:"SotM 33",fullDescription:[{type:"paragraph",text:"While Glory inspires and Wisdom teaches, Cunning seeks out and exploits flaws in individuals, societies, devices, or whatever else. An Irraka has to be ready to take advantage of any weakness and, to do that, she first needs to be able to find those hidden vulnerabilities. Upon activating this Gift, the New Moon’s player adds the character’s dots in the Cunning Renown as bonus dice on any roll to discern flaws, weaknesses, or other shortcomings in a person, organization, structure, item, or any other thing: an Intelligence + Crafts roll to find the breaking point for a powerful fetish, for example, or a Wits + Socialize roll to determine the best manner in which to infiltrate a secret society."}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"Deep Pockets",Description:"Hide an object from sight",Cost:"●",Book:"SotM 34",fullDescription:[{type:"paragraph",text:["Part of the creed of Cunning is the ability to conceal what must remain hidden, even from the most intense scrutiny. An Irraka who learns this Gift finds that his feats of legerdemain are more than mere parlor tricks. With a single success, the character can hide an inanimate object of up to Size 3 untraceably upon her person. Alternately, the Irraka may hide an item (of up to Size 6) that is ",{text:"not",italic:!0}," carried on her person: a big-screen television, for example, or even a door. The Gift’s effects last for a scene or less, should the Stalker wish to end it prematurely, and any successes beyond the first rolled in the Gift’s activation are automatically applied to the results of any roll that the Irraka’s player must make to keep the object hidden from supernatural scrutiny."]}],fullCost:"1 Essence",dicePool:"Dexterity + Larceny + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The item is not concealed and, in fact, becomes especially conspicuous to all within visual range, adding two dice to any mundane or supernatural attempts to locate the object for the remainder of the scene."},{type:"line",label:"Failure",text:"The Irraka fails to conceal the object."},{type:"line",label:"Success",text:"The object is hidden from scrutiny, as above."},{type:"line",label:"Exceptional Success",text:"No additional effect."}]},{Rank:"••••",Name:"Reshape Ban",Description:"Change a Spirits pan",Cost:"●○",Book:"SotM 34",fullDescription:[{type:"paragraph",text:["Calling upon his nature as a shapeshifter and a trickster, a New Moon is capable of temporarily altering even the seemingly-immutable laws that govern the realm of spirits. With a successful use of this Gift, the Irraka can redefine a spirit’s ban for the remainder of a scene and so gain great power over it (or, in some cases, remove others’ power over it). This new ban must be comparable in severity to the spirit’s true ban (see ",{text:"Werewolf: The Forsaken",bold:!0},", pp. 191-2, for a general sense of the relative severity of various sorts of bans), but can otherwise be radically different: a spirit who suffers lethal damage from the touch of purified salt, for instance, may be rendered incapable of crossing any barrier anointed with holy water. Likewise, one that must kill any human child that it sees might be compelled to flee from any object made completely out of metal. A willing spirit need not resist having its ban changed, though few trust the Uratha enough to allow a werewolf to influence such fundamental aspects of their nature."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Manipulation + Empathy + Cunning versus Power + Resistance",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Irraka temporarily fails to change the spirit’s ban and any bans or compulsions that she has become known to the spirit."},{type:"line",label:"Failure",text:"The character fails to change the spirit’s ban."},{type:"line",label:"Success",text:"For the remainder of the scene, the spirit’s ban is changed to a comparable ban of the New Moon’s choosing."},{type:"line",label:"Exceptional Success",text:"The changed ban lasts for a full day, if desired."}]},{Rank:"•••••",Name:"Cheating Fate",Description:"Reflexively gain the Rote Quality to a dice roll",Cost:"●○",Book:"SotM 34",fullDescription:[{type:"paragraph",text:"Some believe that luck is what it is: uncaring fortune that the individual must simply endure, whether for good or for ill. Those chosen by the Stalker’s Moon, however, know that luck is a learned skill, the same as any other. By embracing the path of Cunning, the Irraka discovers that it can be far better to be lucky than good, gaining a second chance when she most needs it."},{type:"paragraph",text:["This Gift enables the werewolf’s player to re-roll any dice that do not come up as successes on a die roll; effectively, she retroactively gives the action the rote quality (see the ",{text:"World of Darkness Rulebook",bold:!0},", pp. 134-5). As per a normal rote action, she may do so for a failed action, though not a dramatically failed one. This Gift may only be used once for any given use of a particular action. (In other words, the player may not pay the cost for this Gift repeatedly until all of her dice come up as successes.)"]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Wits + Occult + Cunning",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Irraka dramatically fails the action to which she attempts to assign the rote quality."},{type:"line",label:"Failure",text:"The character does not get to re-roll any failed dice on the action in question."},{type:"line",label:"Success",text:"The character retroactively assigns the rote quality to an action taken within the current turn for which she has not rolled a dramatic failure."},{type:"line",label:"Exceptional Success",text:"No additional effect."}]}]},{Name:"Darkness",Description:"",Cost:"",Book:"Rage 112",Content:[{type:"paragraph",text:"Moonlight casts long shadows, and in those shadows the Uratha lurk. Legends of werewolves often tell that the creatures can only come out at night, preying on an ancient fear of the dark passed down for generations in the form of old stories. Werewolves who have learned Gifts of Darkness embody some of that fear, slipping unseen between patches of shadow and striking with the sudden intensity of a single moonbeam into a blackened room. The spirits of nocturnal creatures (such as foxes, owls or bats) teach these Gifts, as will some Irralunim — though a non-Irraka will need to offer plentiful chiminage. The suggested modifiers below apply to all Darkness Gifts when a roll is necessary."},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+2","Only light comes from nighttime stars"],["+1","Only light comes from the new moon"],["-1","Only light comes from electric lights (street lights, etc.)"],["-3","Gift used during daytime"]]}],Ranks:[{Rank:"•",Name:"Darksight",Description:"Ignore all penalties to rolls based on visual perception that are applied due to darkness",Cost:"-",Book:"Rage 112",fullDescription:[{type:"paragraph",text:"Though a werewolf can track by sound and scent, in cities and other human-dominated areas the forms necessary to do so can attract more attention than they’re worth. This Gift mitigates that risk, allowing a werewolf in human form to see perfectly no matter the level of light. Where there is any illumination, the user of this Gift can see as if it were bright daylight. In situations in which there is no light at all, the character can see as if her surroundings were bathed in the light of a full moon. Whichever the case, the character’s eyes glow yellow when using this Gift."}],fullCost:"None",dicePool:"Wits + Composure + Wisdom",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The character’s night vision is entirely lost, as if someone had shone a bright torch in her eyes. All penalties for darkness are doubled until the end of the scene. This character also cannot use this Gift for the same period."},{type:"line",label:"Failure",text:"The werewolf’s eyes do not adapt to the darkness."},{type:"line",label:"Success",text:"Night becomes as day to the character. Ignore all penalties to rolls based on visual perception that are applied due to darkness (such as Perception rolls). The character can see colors to the same degree she could if it were daylight. If there is no available light at all, the character can see in monochrome, though all rolls relying on vision suffer a -2 penalty. Sudden bright lights will stop this Gift working as the enhanced vision shuts off to deal with the visual stimulus, but do not have any other detrimental effects. The Gift’s effects last for 30 seconds per success."},{type:"line",label:"Exceptional Success",text:"The Gift is as effective as for a success, but lasts until the end of the scene."}]},{Rank:"••",Name:"Aura of Dread",Description:"The next Composure roll each person present makes this scene, suffers a -1 modifier.",Cost:"●",Book:"Rage 112",fullDescription:[{type:"paragraph",text:"A werewolf who knows this Gift has an edge beyond the obvious. The darkness hides many things, and through subtle spiritual urging onlookers worry about what will follow her out of the shadows. The darkness may conceal the rest of her pack, or she could be a harbinger of a far deadlier threat. This Gift exacerbates the ancient human fear of the dark places outside of the cave, and though it doesn’t actually alter anything visible, it does instill a feeling in the minds of everyone present. The werewolf is the face at the window on a moonless night; the chill howl heard by campers when there are only stars for light."}],fullCost:"1 Essence",dicePool:"Presence + Empathy + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"People who witness the werewolf gain just that bit more confidence, shrugging off minor fears and being more willing to confront her. The werewolf suffers a -1 modifier on any attempts to scare or intimidate anyone who would have been affected by the Gift."},{type:"line",label:"Failure",text:"The victims are unperturbed by this Gift."},{type:"line",label:"Success",text:"Everyone who can see the character (including through a window or one-way mirror, but not a broken or time-lapsed link such as television or photographs) is on edge, fearing what will come for the witness out of the darkness. The next Composure roll each person present makes this scene suffers a -1 modifier."},{type:"line",label:"Exceptional Success",text:"As a success, plus the user of the Gift can focus on one person and attempt to instill a powerful fear of the dark (as a Phobia derangement). The target resists the effect as a reflexive action with Resolve + Primal Urge. If the werewolf’s number of successes is still over five after the resistance, the target suffers the phobia until the end of the scene."}]},{Rank:"•••",Name:"Shadow Step",Description:"Can move to any patch of shadow she can see that is within twice her Primal Urge in yards",Cost:"●●",Book:"Rage 112",fullDescription:[{type:"paragraph",text:"Huddled in stone houses, humans looked out at the dark in fear, never knowing if some beast was going to attack, and if so where from. This Gift allows a werewolf to play on that fear, letting him slip from one patch of shadow to another to confuse prey — or predators — as to his location. Though hardly the fastest means of getting around, slipping between shadows in this way does allow the werewolf to move without being seen, strike from odd angles and convince her victims that there is more than just one of her."}],fullCost:"2 Essence",dicePool:"Manipulation + Stealth + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf finds herself unable to slip between shadows at all, as reflections and flashes of light stop her from being unseen. The character suffers a -1 penalty to all Stealth rolls for the remainder of the scene."},{type:"line",label:"Failure",text:"The shadows reject the character for now."},{type:"line",label:"Success",text:"The character must be stood in a patch of shadow or darkness large enough to conceal herself. She can move to any patch of shadow she can see that is within twice her Primal Urge in yards, and that would be large enough to conceal her. The shadows swallow her whole when this Gift is used, and next turn she emerges in her desired patch of darkness."},{type:"line",label:"Exceptional Success",text:"The character can see out of her destination from the moment she vanishes. She gains +2 Initiative on the turn that she arrives."}]},{Rank:"••••",Name:"Moonlit Talons",Description:"The character makes a surprise attack; the target may not make a Wits + Composure roll to act normally.",Cost:"○",Book:"Rage 113",fullDescription:[{type:"paragraph",text:"A character with this Gift can strike from concealment with incredible swiftness and power, like a beam of light that dispels the shadows around him. His claws leave faint contrails of darkness in the air behind them, as though they were sharp enough to slice through light itself, and once he has struck, the character fades back into the darkness that concealed him to await his next victim. This Gift is the province of hunters and assassins, allowing the Uratha to strike from hiding without betraying his position, and finds little favor among those who would rather face an opponent with honor."},{type:"paragraph",text:"A werewolf can only use this Gift to augment a surprise attack made from the cover of darkness."}],fullCost:"1 Willpower",dicePool:"Strength + Stealth + Glory - subject’s Composure",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf’s strike is mistimed, leaving him both vulnerable to a counter-attack and visible. The attacker can make an automatic surprise attack against the character."},{type:"line",label:"Failure",text:"Though the attack proceeds as normal, the character’s claws move as swiftly as normal and the shadows do not welcome him once his strike is made. The Gift has no effect."},{type:"line",label:"Success",text:["The character makes a surprise attack as normal (see “Surprise” in the ",{text:"World of Darkness Rulebook",bold:!0},", p. 151); however, the target of the attack may not make a Wits + Composure roll to act normally. Next turn, the victim must make a Wits + Composure roll in order to act, as if the surprise attack happened that turn."]},{type:"line",label:"Exceptional Success",text:"As a success, with the werewolf’s first attack receiving a +2 bonus."}]},{Rank:"•••••",Name:"Nightblind",Description:"The target remains blinded for one turn per success. If made as an extended action, the effect is permanent.",Cost:"●●○",Book:"Rage 114",fullDescription:[{type:"paragraph",text:"Fear of the darkness lurking outside of the cave is one thing, but that fear pales in comparison with the fear many people have of the darkness in their own heads. Using this Gift on a target lets a werewolf reach into a human’s head and turn the brightness right down. A normally blinding light provides no more illusion than the stars alone, and anything less than that leaves the target totally blind, his eyes unable to see. Being struck blind tends to make people panic, making this the perfect Gift to use on a band of hunters. After all, most people need to see what they’re shooting at."}],fullCost:"2 Essence and 1 Willpower",dicePool:"Wits + Occult + Honor - Composure",action:"Instant or Extended (20 successes required)",rollResults:[{type:"line",label:"Dramatic Failure",text:"The would-be victim can see the werewolf with incredible clarity. Efforts to track the werewolf and ranged attacks against her have a +1 bonus until the end of the scene."},{type:"line",label:"Failure",text:"The character cannot affect the target’s sight this time."},{type:"line",label:"Success",text:["The werewolf strikes her target blind, greatly reducing the amount of light his eyes can process. In any light less than a full-on searchlight, the target cannot see. For humans, this means visual perception rolls automatically fail, and uses the “Fighting Blind” rules in combat (see the ",{text:"World of Darkness Rulebook",bold:!0},", p. 166). In excessively bright light, the target has a -3 penalty on visual perception rolls, and can see as well as if the only illumination came from the stars on a dark night. The target remains blinded for one turn per success.",{lineBreak:!0},"This Gift can also strike a person permanently blind. In that case, the roll is extended, with 20 successes needed. Once the 20 successes have been acquired, the target is struck blind but does not recover after a scene. The extended version of this Gift takes two minutes per roll."]},{type:"line",label:"Exceptional Success",text:"For the normal version of this Gift, the werewolf can target up to three people in an area of her Primal Urge in yards. If the character is using the permanent version of this Gift, the extra targets suffer only the effects of the temporary version."}]}]},{Name:"Death",Description:"",Cost:"",Book:"WtF 106",Content:[{type:"paragraph",text:"Some cultures claimed that the wolf was the messenger between life and death, the one who walked between both worlds. In part, these legends reflect the legend of Father Wolf. In part, though, they are also real. They reflect the secrets of mortality uncovered by Death Wolf, and later passed onto her Bone Shadow children. Gifts of Death allow a werewolf to manipulate the border between this world and the next in subtle but effective ways. They are usually taught by death-spirits or by spirits of animals associated with death (such as vultures, serpents, ravens or jackals)."}],Ranks:[{Rank:"•",Name:"Death Sight",Description:"See death based resonance",Cost:"-",Book:"WtF 106",fullDescription:[{type:"paragraph",text:"To understand something, one must first be able to perceive it. The werewolf with this Gift is able to adjust his sight to see the impressions left by death. He can see ghosts and perceive the spiritual imprint left where a person or higher animal died, though the knowledge could bring him grief. While this Gift is in effect, a character’s eyes turn a milky white, as if covered with cataracts, but he can still perceive what’s going on around him."},{type:"paragraph",text:"For the duration of a scene, the character’s sight is attuned to the dead. The werewolf can perceive ghosts, even if they would ordinarily be invisible. Doing so requires the character to simply will the capability into effect with an action."},{type:"paragraph",text:"While the Gift is active, the player may make an Intelligence + Occult roll for his werewolf to detect any “stains” of death in an area. Making such a search is an instant action. Success allows the werewolf to see a phantom bloodstain wherever a creature at least the size of a cat died within the last lunar month. The size of the bloodstain reveals the rough emotional discharge of the death. A human being who died peacefully and a dog who died in pain leave approximately the same size stain (about the size of a human torso). The darker the stain, the more recent the death. This Gift cannot reveal anything more about the circumstances of any death in question, although a werewolf can use both this Gift and Echo Dream (p. 123) to pinpoint and analyze the scene of a murder."},{type:"paragraph",text:"The effects of Death Sight apply only when a character is in the physical world."}],fullCost:"None",dicePool:"No roll is made to activate this Gift.",action:"Instant",rollResults:[]},{Rank:"••",Name:"Ghost Knife",Description:"Imbue a weapon to harm ghosts",Cost:"●",Book:"WtF 107",fullDescription:[{type:"paragraph",text:"Not all ghosts are harmless, and this Gift allows a werewolf to deal with one who isn’t in a particularly expedient fashion. By imbuing a weapon with a portion of his own Essence, a werewolf can enchant it so that it strikes an immaterial ghost as readily as it would strike a living target."},{type:"paragraph",text:["The werewolf must be holding or touching the weapon in question in order to infuse it with Essence. The object need not be specifically designed as a weapon; this Gift can be used to imbue a crowbar, 2x4 or chainsaw as readily as a sword or gun. For the duration of the scene, the imbued weapon is considered enchanted for purposes of damaging ghosts (",{text:"World of Darkness Rulebook",bold:!0},", p. 214). A weapon enchanted by Ghost Knife may inflict bashing or lethal damage, depending on the character’s choice. A klaive sword can be given a merciful enchantment so that it inflicts only bashing damage on ghosts (though it still inflicts lethal damage to corporeal targets). A weapon affected by this Gift also adds a bonus die to any attack rolls made with the weapon against a ghost."]},{type:"paragraph",text:"This Gift does not grant a weapon the ability to strike any ephemeral entity - only ghosts. Thus, a weapon imbued with Ghost Knife could not harm a spirit that is in Twilight (p. 252) or an Irraka using the Gift: Ghost Step (p. 133). However, the +1 bonus to attack spirits does still apply if the spirit could normally be struck, such as if the spirit was using a Numen to materialize or if both spirit and werewolf were in the Shadow."},{type:"paragraph",text:"If Ghost Knife is used to imbue a gun with Essence, the Gift effects apply to any bullets loaded at the time of infusion — bullets loaded into the gun after infusion do not acquire the Gift’s effects. Muscle-powered projectile weapons such as bows do not convey the Gift’s properties to ammunition. The werewolf must instead use the Gift on a quiver of arrows or a handful of javelins."},{type:"paragraph",text:"A character may use this Gift to imbue his own natural weaponry, allowing him to tear into a ghost as if it were solid, or even punch or grapple it. This Gift cannot be used to empower the natural weaponry of another creature. Only the Gift user can benefit."},{type:"paragraph",text:"This Gift in itself does not grant the ability to see or otherwise perceive ghosts."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"•••",Name:"Corpse Witness",Description:"Interrogate a corpse",Cost:"●",Book:"WtF 108",fullDescription:[{type:"paragraph",text:["Many occultists believe that a corpse retains some memory of the moments just before its death. The Bone Shadows, however, know that a corpse can sometimes know more. With this Gift, a corpse can be ordered to give up the secrets of all that it has “",{text:"seen",italic:!0},"” since its death. This Gift works only on corpses that still have some flesh to them, and only the head is necessary. The werewolf opens the jaws of the corpse and breathes into the corpse’s mouth. If the Gift works, the breath returns with the corpse’s words."]},{type:"paragraph",text:"Some Bone Shadows have historically exploited this Gift in gruesome fashion, setting up the severed heads of their foes (or victims) as sentinels on the boundaries of their territory. In the modern era, it’s hard — but not impossible — to set such morbid guardians in place without attracting the wrong sort of attention."}],fullCost:"1 Essence",dicePool:"Manipulation + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The corpse speaks a garbled litany of blasphemies from the darkest corners of Death’s realm. The werewolf loses a point of Willpower from the experience. This Gift may not be used again on the same corpse."},{type:"line",label:"Failure",text:"The corpse divulges nothing more than a death rattle. This Gift may not be used again on the same corpse in the same day."},{type:"line",label:"Success",text:"The corpse breathes out a report of what it has “perceived” — the key notes of what has transpired within view of its eyes or eye sockets within the last day and night. The report is not incredibly detailed, but generally hews to the facts that the werewolf would consider important. For example, the corpse might mention that 18 cars had appeared along the country road it “watched” during the day. It would only single out an individual car if the vehicle was significantly remarkable, such as a pickup with several armed men sitting in the bed. A corpse’s account for any given day can be attained only once."},{type:"line",label:"Exceptional Success",text:"The corpse demonstrates vestiges of its former intelligence and can actually clarify its account by answering the character’s questions. The character may ask one question per success gained on the roll before the corpse goes dormant again. Information gained may still be somewhat imprecise, though. A corpse is not likely to have retained a license-plate number unless the plate remained in its line of sight for a few minutes."}]},{Rank:"••••",Name:"Word of Quiet",Description:"Inflicts 1 bashing damage to living creatures and 1 lethal damage per succes to undead (includes vampires)",Cost:"○",Book:"WtF 108",fullDescription:[{type:"paragraph",text:"One of the greater secrets of the Bone Shadows is Word of Quiet, a complicated word in the First Tongue that bears great power. The sound was allegedly spoken by the first Incarna of Death, and a portion of that great spirit’s authority lingers in its twisted syllables. When spoken, the word tugs at the hearts of all living beings that hear it, brushing them with the stillness of the grave. And yet, the word’s true power comes when it is spoken against the undead, for it compels them to lie down in their graves and rest again."},{type:"paragraph",text:"All living creatures capable of hearing the word within a radius of (10 x the user’s Presence) yards suffer one point of bashing damage. All undead creatures such as ghosts and vampires in the same range (and within the same realm as the speaker) suffer one point of lethal damage per success. If multiple undead creatures are present, the highest Stamina (or Resistance in the case of ghosts) among them is subtracted from the werewolf’s pool."}],fullCost:"1 Willpower",dicePool:"Presence + Occult + Honor - subject’s Stamina",action:"Instant",rollResults:[]},{Rank:"•••••",Name:"Vengeance of the Slain",Description:"Return a recently dead werewolf to life for 1 hour per success",Cost:"●",Book:"WtF 109",fullDescription:[{type:"paragraph",text:"A werewolf armed with this powerful Gift can defy Death itself, at least for a short time. This capability allows a werewolf to return a soul to its body briefly. This Gift cannot prevent death; it can only deny it for a few seconds. The Gift works on Uratha only, not on ordinary people or other supernatural beings."}],fullCost:"1 Essence",dicePool:"Stamina + Occult + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The subject returns to a semblance of life, but is possessed by a spirit other than that of the deceased. The new spirit controls the body for the duration of the scene (but cannot use the body’s supernatural powers, if any), and is likely hostile toward the character."},{type:"line",label:"Failure",text:"The soul has already fled, and the subject remains dead. This Gift cannot be used again on the subject."},{type:"line",label:"Success",text:["For this Gift to be successful, the subject must not have been dead for more than a day, and her corpse must still possess some form of structural integrity. The Gift still works if she is missing one arm and half her face, for example, but not if her flesh has mostly been eaten away by immersion in acid.",{lineBreak:!0},"The deceased returns to a semblance of life for one hour per success rolled, though the subject is still clearly dead. Any wounds she died from remain on her body, although she no longer suffers any wound penalties (she is beyond pain). She may speak (if she still possesses a mouth and vocal cords), shapeshift or use any supernatural powers she possessed when alive. Her Essence, Willpower and other traits are where they were at the time of her death. In addition, she regains all her Health, and in effect must be “killed” again. She cannot regenerate thereafter, however. The subject is most likely focused on vengeance against her killer, but she may use her few seconds of borrowed time to do something else she would consider greatly important — attempting to save a friend, or telling a packmate she has always loved him, for example.",{lineBreak:!0},"Once the subject loses all her Health to lethal or aggravated damage for a second time, or the duration of the Gift expires, she returns to death. This Gift cannot be used on her again."]},{type:"line",label:"Exceptional Success",text:"The subject is invigorated with the will to do the most with her borrowed time. She returns to activity with full Willpower."}]}]},{Name:"Disease",Description:"",Cost:"",Book:"Pure 115",Content:[{type:"paragraph",text:"The Fire-Touched relationship with disease bears many obscene fruits, among them a tribal affinity for learning from disease-spirits. These spirits can bestow Gifts upon the Uratha (though “infect” might be a better word). The Fire-Touched, for their part, feel that they are the only werewolves who can truly benefit from these Gifts, blessed as the Fire-Touched are with the fortitude of Gurim-Ur. Any other werewolves, the Fire-Touched believe, would sicken and die if they were to receive one of these Gifts."},{type:"paragraph",text:"Unless otherwise stated, the Natural Immunity Merit helps to resist the effects of these Gifts, where applicable."}],Ranks:[{Rank:"•",Name:"Fever Dreams",Description:"Suffer a penalty on all Mental or Social rolls and Initiative equal to the Fire-Touched werewolf’s Primal Urge",Cost:"●",Book:"Pure 115",fullDescription:[{type:"paragraph",text:"The character passes along a spiritual infection to a target. Although this disease runs its course quickly, and rarely does any serious damage to the target, while he is infected he suffers cold sweats, headaches, fever and even mild hallucinations. Needless to say, fighting or even focusing his mind is extremely difficult while the disease holds him."},{type:"paragraph",text:"The character must touch her target’s flesh to use this Gift."}],fullCost:"1 Essence",dicePool:"Presence + Medicine + Wisdom versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf suffers the normal effects of the Gift himself. The Fire-Touched consider this a challenge from Gurim-Ur, and an opportunity, since visions often manifest themselves in the throes of fever."},{type:"line",label:"Failure",text:"No effect."},{type:"line",label:"Success",text:"The subject suffers as described above. For the remainder of the scene, he suffers a penalty on all Mental or Social rolls equal to the Fire-Touched werewolf’s Primal Urge. The same penalty is also levied against the target’s Initiative."},{type:"line",label:"Exceptional Success",text:"The disease takes a toll on the victim’s body as well as his senses, and he suffers lethal damage equal to the Gift user’s Primal Urge."}]},{Rank:"••",Name:"Virulent Rage",Description:"Infect another being with a portion of Fire-Touched Rage. Triggers Kuruth on werewolves. On humans, the Gift causes a terrible fit of contagious violent anger.",Cost:"○",Book:"Pure 115",fullDescription:[{type:"paragraph",text:["The Fire-Touched infects another being with a portion of her Rage. When used on a werewolf, this Gift usually triggers ",{text:"Kuruth",italic:!0},". When used a human being, the Gift causes a terrible fit of violent anger. Worse, this anger is contagious, meaning that if the Fire-Touched uses this Gift in a crowd, it will quickly spiral into a brutal, rioting mob."]},{type:"paragraph",text:"The werewolf must touch the target’s flesh to use this Gift."}],fullCost:"1 Willpower",dicePool:"Presence + Expression + Purity - Resolve + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Fire-Touched immediately enters Death Rage."},{type:"line",label:"Failure",text:"No effect."},{type:"line",label:"Success",text:["If Virulent Rage is used on a werewolf, she must immediately check for Death Rage. Even if she fails to resist ",{text:"Kuruth",italic:!0},", though, the player may roll Stamina + Resolve each turn (beginning on the turn following the one in which she was infected) reflexively to end the frenzy. During this time, her Rage is contagious (see below). The Death Rage lasts until the character can free herself from it, or until it runs its course.",{lineBreak:!0},"If Virulent Rage is used on a human being, she immediately attacks the nearest target other than the Fire-Touched. The attack is brutal and persistent, if not entirely focused. The infected human lashes out with fists, teeth, feet and anything that happens to be in her hands when the Rage takes over. She cannot use guns, Fighting Styles or any semblance of true strategy. Any attacks she makes are considered all-out attacks (see p. 157 of the ",{text:"World of Darkness Rulebook",bold:!0},"); she receives a +2 to her attack roll but loses her Defense. In addition, this state of frenzy is contagious. Anyone she touches (including in an attack) must succeed on a Stamina roll or succumb to the Gift’s effects.",{lineBreak:!0},"Human are subject to Lunacy in this state, but they don’t respond with fear. Instead, any werewolf engendering Lunacy in a human infected with Virulent Rage immediately becomes the target of the human’s frenzy.",{lineBreak:!0},"The Gift’s effects last for a number of turns equal to the Fire-Touched werewolf’s Primal Urge, but any victims can be re-infected. Therefore, in a large crowd of people, the Gift’s effects likely will end only when the rioters are separated and subdued (or dead)."]},{type:"line",label:"Exceptional Success",text:"The Rage is particularly strong. All rolls made to resist the frenzy are made at a -1 penalty."}]},{Rank:"•••",Name:"Glorious Agony",Description:"Sacrifice regeneration for rush of adrenaline, bestowing a +3 to all Strength- or Stamina-based rolls. Bite and claw attacks receive an additional +1 modifier",Cost:"●",Book:"Pure 115",fullDescription:[{type:"paragraph",text:["By activating this Gift, the werewolf taints his own Essence with a spiritual malady. This illness actually makes the werewolf stronger and deadlier, lending the pain of disease and contagion to his claws and fangs. The Fire-Touched must sacrifice his own regenerative powers to allow the disease to run its course, however, and many an ",{text:"Izidakh",italic:!0}," has perished under the effects."]},{type:"paragraph",text:"Once activated, Glorious Agony remains in effect for the remainder of the scene and cannot be terminated early."}],fullCost:"1 Essence",dicePool:"Strength + Survival + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf loses his regeneration for the scene, but gains no benefit. He suffers the symptoms described below during this time."},{type:"line",label:"Failure",text:"No effect (but the Essence point is not spent if the roll fails)."},{type:"line",label:"Success",text:["The werewolf experiences a rush of adrenaline, and tastes bile oozing from his gums. The disease bestows a +3 to all Strength- or Stamina-based rolls for the remainder of the scene. In addition, his bite and claw attacks receive an additional +1 modifier due to the caustic sludge from the werewolf’s mouth and fingernails. For the next two hours, however, the werewolf does ",{text:"not",italic:!0}," regenerate, and cannot spend Essence to heal lethal damage."]},{type:"line",label:"Exceptional Success",text:"The werewolf’s regeneration returns at the end of the scene, rather than after two hours."}]},{Rank:"••••",Name:"Lingering Bite",Description:"Bite attack inflicts damage as usual, but it cannot be healed by supernatural means",Cost:"●",Book:"Pure 116",fullDescription:[{type:"paragraph",text:"The werewolf’s bite leaves festering, odious wounds in his target’s flesh. These wounds heal extremely slowly, even for werewolves."},{type:"paragraph",text:"Lingering Bite can be used in any form (though when the werewolf is in Hishu form, the werewolf’s bite inflicts bashing damage and suffers a -1 modifier). A successful bite attack inflicts damage as usual, but the damage cannot be healed by supernatural means. Lethal damage heals at the normal human rate of one level per two days, and aggravated damage (should the Fire-Touched manage to inflict it with this Gift) heals at one point per week. The Rite of Healing cures this damage as usual, however."}],fullCost:"1 Essence per bite",dicePool:"None",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Wasting Sickness",Description:"The target sickens over a period of days, and, unless treated quickly and expertly, dies in less than week",Cost:"●●●",Book:"Pure 116",fullDescription:[{type:"paragraph",text:"This horrific Gift allows the Fire-Touched to infect a target with a slow disease. The target sickens over a period of days, and, unless treated quickly and expertly, dies in less than a week. Wasting Sickness can even be fatal to Uratha, though with their regenerative powers they are usually able to shake it off before death occurs. Though the disease is not normally transmittable, an exceptionally skillful or malicious Fire-Touched can make it so."}],fullCost:"3 Essence",dicePool:"Manipulation + Medicine + Cunning",action:"Extended; 10 successes required",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Fire-Touched contracts the non-transmittable version of the disease, and suffers as described below."},{type:"line",label:"Failure",text:"No successes are accumulated."},{type:"line",label:"Success",text:["Progress is made toward the goal. If the Fire-Touched reaches 10 successes, he becomes a carrier for the disease. The next person he bites becomes infected with the disease. Human beings cannot resist infection; they can only try to stave off the effects. Werewolves can resist with a contested action; the werewolf’s player rolls Stamina + Resolve, while the Storyteller rolls the Fire-Touched werewolf’s Primal Urge + 5 dice for the disease.",{lineBreak:!0},"Infected characters, Uratha or otherwise, suffer three points of lethal damage per day. A character may resist this damage by rolling Stamina + Resolve, but if the roll doesn’t result in three successes or more, the character suffers full damage (see “Disease” on p. 176 of the ",{text:"World of Darkness Rulebook",bold:!0},").",{lineBreak:!0},"While infected, characters suffer a -3 modifier to ",{text:"all",italic:!0}," actions. Damage from the disease can be overcome normally (which is why werewolves seldom die from it), but the modifier persists for as long as the disease does.",{lineBreak:!0},"Fighting off the disease requires an extended Stamina + Resolve roll. Uratha characters need 10 successes to fight off the disease, while humans require 20. One roll can be made per day, but the -3 modifier applies to this roll. If the character is under the care of a doctor or healer, successes from Intelligence + Medicine rolls (again, one roll per day) can be added to the total."]},{type:"line",label:"Exceptional Success",text:"The character makes considerable progress toward the goal. If the character reaches the goal with 15+ successes, the disease is contagious. It spreads like the common cold. Casual contact allows a Stamina + Resolve roll to avoid infection, but intimate contact (include prolonged physical contact, sex or a bite) means automatic infection for humans."}]}]},{Name:"Dominance",Description:"",Cost:"",Book:"WtF 109",Content:[{type:"paragraph",text:"The power to command others skillfully is an aptitude many desire but few possess. To sway another’s will requires courage and strength of mind, as well as a modicum of subtlety. Spirit teachers typically bestow these powers on Uratha (or on a lineage of werewolves) to whom they owe gratitude. Storm Lords and Rahu have affinity for Dominance; Elodoth and pack leaders often learn these Gifts as well. Teachers of Dominance Gifts are usually ancestor-spirits, girt with appropriate symbols of authority and command. Werewolves cannot use Dominance Gifts on targets who possess more dots in the same tribal primary Renown. A Storm Lord with Honor 3 (the primary Renown of the tribe) cannot use one of these Gifts on another of the Forsaken with Honor 4 or 5. That intended subject can be another Lord or simply a werewolf of another tribe with a higher Honor Renown."},{type:"paragraph",text:"Dominance Gifts do not function against other supernatural entities; they are Gifts that allow werewolves to establish dominance among themselves and their relatives. A werewolf can use a Dominance Gift only against other werewolves, the wolf-blooded, or ordinary humans."}],Ranks:[{Rank:"•",Name:"Warning Growl",Description:"Strike doubt into the heart of the target (+2 defense against target)",Cost:"○",Book:"WtF 109",fullDescription:[{type:"paragraph",text:"This Gift is the simplest of the secrets of Dominance, lending supernatural power to the sort of growl an alpha wolf uses to warn off a potential rival. The werewolf using this Gift growls deeply and loudly while focusing his gaze on a particular target, striking sudden doubt into her heart and affecting her ability to face her opponent. The target must be able to hear the growl to be affected."}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Glory versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails completely. The werewolf cannot use any Dominance Gifts on the subject for the rest of the scene."},{type:"line",label:"Failure",text:"Successes rolled tie or the subject gets the most. The target feels no particular dread of the werewolf."},{type:"line",label:"Success",text:"The most successes are rolled for the Gift user. This Gift affects a single target. The Gift user gains a +2 Defense bonus against any close-combat attacks made by the affected target for the duration of the scene — the target is literally too wary of the werewolf to attack with full vigor. This Gift can be used on multiple opponents during a scene, but the werewolf must use the Gift separately against each one (spending Willpower and making a contested roll each time)."},{type:"line",label:"Exceptional Success",text:"As success, but the Defense bonus against the Gift’s target rises to +3."}]},{Rank:"••",Name:"Luna's Dictum",Description:"Compel obedience on a simple command",Cost:"○",Book:"WtF 109",fullDescription:[{type:"paragraph",text:"With this Gift, the werewolf is able to articulate a command of no more than a few words and compel obedience. Some werewolves choose to speak these words in a soft, subtle whisper. Others prefer bellowing orders. This Gift cannot harm those who hear it, either directly or indirectly; it simply conveys a brief impulse to surrender to the werewolf’s authority."}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Glory versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails completely. The werewolf cannot use any Dominance Gifts on the subject for the rest of the scene."},{type:"line",label:"Failure",text:"Successes rolled tie or the subject gets the most. The target feels no compulsion to obey."},{type:"line",label:"Success",text:"The most successes are rolled for the Gift user. This Gift affects a single target, who must obey the command given. The words a character selects for his order must be specific and straightforward, and the command cannot take more than a minute to carry out. The user can’t direct a target to take any action that would conceivably bring harm to herself or others, or to do anything that would be drastically out of character. In particular, the Gift does not function at all if the subject is in combat or otherwise distracted by a very real danger to her safety. It’s a useful Gift, however, for telling a person to “step outside for a minute.” The target remembers that her will was not her own but might rationalize her obedience as a moment of weakness rather than supernatural coercion."},{type:"line",label:"Exceptional Success",text:"As success, but the target is sure to rationalize her obedience."}]},{Rank:"•••",Name:"Voice of Command",Description:"Intimidate targets to obey",Cost:"●",Book:"WtF 110",fullDescription:[{type:"paragraph",text:"At this level of Dominance, the werewolf learns to voice more complex and subtle decrees, in a tone that demands attention and respect. A thread of anger runs through the werewolf’s words, making everyone in earshot take notice of his declarations."},{type:"paragraph",text:"When activated, this Gift affects up to three targets, each of whom contests the roll separately. The player suffers a -1 penalty on the activation roll for each intended target after the first. Therefore, some subjects might obey while others resist."}],fullCost:"1 Essence",dicePool:"Manipulation + Intimidation + Honor versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails completely. The werewolf cannot use any Dominance Gifts on anyone for the rest of the scene."},{type:"line",label:"Failure",text:"An intended target feels no compulsion to obey."},{type:"line",label:"Success",text:"Affected targets react swiftly to the command. The werewolf’s orders can have two or three specific directions, but these orders can’t cause direct harm to the targets or to anyone else, and cannot defy the subjects’ identities or sense of self. A typical command might be, “Hide these bodies in the deep ravine near the river.” The subjects must obey the letter of the command, although twisting the spirit is possible. Targets obey for up to five minutes per success achieved on the activation roll. The Gift cannot be used again on the same subjects that day. If the targets suffer any harm as a result of obeying the command (such as being instructed to flee, only to be struck from behind by the Gift user’s packmate as they do so), the Gift effects immediately end, and the Gift cannot be used again on the targets that day."},{type:"line",label:"Exceptional Success",text:"As success, but the targets cannot twist the spirit of the command."}]},{Rank:"••••",Name:"Break the Defiant",Description:"Destroy opponent's will (loses 1 Willpower per success)",Cost:"●",Book:"WtF 110",fullDescription:[{type:"paragraph",text:"A werewolf with this level of power is able to project a force of presence that strips away a target’s desire to resist. The werewolf snarls in a tone full of menace, chilling the target to the marrow."}],fullCost:"1 Essence",dicePool:"Presence + Intimidation + Purity - subject’s Resolve",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails completely. The werewolf cannot use any Dominance Gifts for the rest of the scene."},{type:"line",label:"Failure",text:"The target is unaffected."},{type:"line",label:"Success",text:"The target immediately loses a number of Willpower points equal to the number of successes rolled for the Gift user. This Gift can be used only once on any given target in a day."},{type:"line",label:"Exceptional Success",text:"No additional bonus is levied apart from the crippling amount of Willpower lost."}]},{Rank:"•••••",Name:"Tug the Soul's String",Description:"Force target to act against his will",Cost:"●",Book:"WtF 110",fullDescription:[{type:"paragraph",text:"With this level of mastery, a werewolf understands genuine coercion, forcing others to do things even against their will. While the affected person doesn’t harm himself, the werewolf calling upon this Gift can incite her to perform deeds that defy her identity and to cause harm to others, even if the target is normally harmless and gentle."}],fullCost:"1 Essence",dicePool:"Manipulation + Persuasion + Cunning versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails completely. The werewolf cannot use any Dominance Gifts for the rest of the scene."},{type:"line",label:"Failure",text:"An equal number or more successes are rolled for the subject. She does not obey."},{type:"line",label:"Success",text:["The most successes are rolled for the character using this Gift, and he issues a single, straightforward command. The werewolf can force a target to do things she wouldn’t normally do, including hurting other people or placing herself in danger. If the command would place the victim in danger or force her to go against her moral code, however, three dice are added to the target’s Resolve + Primal Urge. If such danger or moral defiance is not evident when the Gift is activated, the victim gains a second contested roll with a +3 modifier if obeying orders does come into question. For example, a victim given the command “Remain in this building until I return” does not gain a bonus on the contested roll, but is allowed a second roll to break the Gift’s effects if the building catches fire before the werewolf’s return.",{lineBreak:!0},"The Gift’s effects last for 10 minutes per success achieved on the activation roll, or until the command is completed. It cannot be used on the same subject again that day."]},{type:"line",label:"Exceptional Success",text:"The most successes are rolled for the Gift user, and five or more are achieved. The target does not gain a second roll to break the compulsion if a situation involving danger or defying her moral code arises."}]}]},{Name:"Dreamer's Moon",Description:"",Cost:"",Book:"Lore 83",Content:[{type:"paragraph",text:"The Gifts of the Dreamer’s Moon draw on the spiritual power of Luna as a nocturnal spirit of sleep and dreams — whether gentle or nightmarish. Some can be used to heal, others to harm, but all touch the power of the dreaming mind."}],Ranks:[{Rank:"•",Name:"Sense Sleeper",Description:"Detect sleeping creatures",Cost:"-",Book:"Lore 83",fullDescription:[{type:"paragraph",text:"This peculiar Gift allows the Cahalith to open her senses to the world around her, getting a sense for the sleeping and perhaps dreaming minds that might be nearby. It is particularly handy for werewolves conducting a nocturnal hunt: if a Beshilu is hiding in the basement of a home, the Cahalith can tell if there are any family members still awake who might have to be accounted for."}],fullCost:"None",dicePool:"Wits + Empathy + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Cahalith receives an inaccurate, potentially even wildly inaccurate result."},{type:"line",label:"Failure",text:"The Cahalith is unable to tell whether anyone is sleeping in her vicinity. She may retry the Gift in one minute."},{type:"line",label:"Success",text:"The Cahalith gets an accurate count of the number of sleeping creatures larger than a cat within a range of 5 yards per success, and can sense the rough location and size of each. She is able to tell the difference between a sleeping animal and a sleeping human. The Cahalith may maintain the Gift’s effects for as long as she concentrates; however, she counts as distracted and suffers a -1 penalty to other die rolls during this time."},{type:"line",label:"Exceptional Success",text:"As above, but the Cahalith can also sense whether any individual sleeper is experiencing some unusual sleep condition — in the grip of a nightmare, comatose or the like."}]},{Rank:"••",Name:"Lover's Voice",Description:"Mimic a voice the target wants to hear the most for a scene",Cost:"●",Book:"Lore 84",fullDescription:[{type:"paragraph",text:"This Gift plays on both the Cahalith’s affinity for vocalization and the influence dreams can have on a person. With Lover’s Voice, a Cahalith can mimic the voice of someone important to the target, even if it’s a voice she’s never heard. The target hears the voice he most wants to hear, be it a family member, a friend or even someone he fantasizes about. Historically, this Gift was used to draw prey away from the herd and into an ambush — today, the same trick still works, but a creative Gibbous Moon can find other uses for the Gift as well."},{type:"paragraph",text:"This Gift can be used over a telephone or similar method of voice communication without establishing line of sight, but the Cahalith must know the full name of the target."}],fullCost:"1 Essence",dicePool:"Manipulation + Subterfuge + Cunning - subject’s Composure",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift draws the wrong voice from the subject’s daydreams: a security guard may hear the voice of a cartoon character rather than the pretty young thing who’s the last to leave the building."},{type:"line",label:"Failure",text:"The Gift fails to work. The Cahalith speaks with her own voice."},{type:"line",label:"Success",text:"The target hears the voice he most wants to hear in place of the Cahalith’s. The Cahalith may still need to fast-talk or otherwise convince the target of her identity, but the target wants to believe he’s hearing the person he is, and therefore may not be as suspicious as is logical. (For instance, using this Gift on the aforementioned security guard might duplicate the voice of his co-worker if he’s fantasizing about an after-hours sexual encounter with her, but also might duplicate the voice of his superior if he really wants to go home and is hoping he’ll be told to take the night off.). The Gift’s effects last for the duration of the scene; the Cahalith can alternate between being heard with her true voice or as the voice bestowed via the Gift."},{type:"line",label:"Exceptional Success",text:"The target is particularly susceptible to the Gift’s effects. Any efforts to manipulate the target while “in character” receive a +2 bonus to the dice pool."}]},{Rank:"•••",Name:"Nightmare Hunt",Description:"Harass the victim with nightmares",Cost:"●",Book:"Lore 84",fullDescription:[{type:"paragraph",text:"The gibbous moon swells with dreams and nightmares, and the Cahalith are prone to share both. Sometimes a Cahalith wakes from a nightmare with the face of the one hunting her in her mind. Some Cahalith choose to share this sensation with their prey. It may not be completely prudent to hound a foe in his nightmares before coming for him in the flesh, but the Cahalith find the concept glorious."},{type:"paragraph",text:"To use this Gift, the Cahalith must be able to see the target while he sleeps; watching remotely via live cameras will work, although in such a case the Cahalith must also know the target’s full name. As she invokes the Gift, she conjures up a terrible dream-wolf from her imagination and sets it loose in the sleeper’s dream."}],fullCost:"1 Essence",dicePool:"Intelligence + Intimidate + Honor - target’s Resolve",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The nightmare turns on the Cahalith, savaging her in her imagination in a terrible waking dream. The Cahalith loses a point of Willpower."},{type:"line",label:"Failure",text:"The sleeper’s dream is not altered in any significant way."},{type:"line",label:"Success",text:"The sleeper begins to dream of being hunted by a huge, savage wolf as much demon as animal. The wolf reflects the Cahalith’s imagination — a Blood Talon Cahalith might send a dream of Fenris-Ur with bloody muzzle, while an Iron Master’s sending might be a mongrel monstrosity that chases the target down blind alleys and empty streets. The target loses one point of Willpower upon waking, and suffers a -1 penalty to any rolls made to resist Uratha powers that inspire fear for the next 24 hours."},{type:"line",label:"Exceptional Success",text:"The target takes one lethal wound upon waking from the dream; a shadow of the wolf’s bite appears on his flesh as stigmata."}]},{Rank:"••••",Name:"Soul-Singing",Description:"Heal the target's mind with calming songs",Cost:"●",Book:"Lore 84",fullDescription:[{type:"paragraph",text:"The Cahalith’s art, the embodied howl, is capable of more than communication; the highest of the Gibbous Moons can not only communicate but commune. A soul-singer is able to draw on the power of the pregnant moon to soothe and heal, to wipe away a person’s trauma and nightmares and replace them with gentle sleep."}],fullCost:"1 Essence",dicePool:"Presence + Empathy + Purity",action:"Extended (25 successes; each roll represents one minute of song)",rollResults:[{type:"line",label:"Dramatic Failure",text:"The song goes gruesomely wrong, stirring up more terrible memories or visions and twisting them into sharp relief. The subject temporarily gains a derangement of the Storyteller’s choice; the derangement torments the subject until the next new moon, when the power of the gibbous moon has fully faded."},{type:"line",label:"Failure",text:"The song has no supernatural effect."},{type:"line",label:"Success",text:["Successes are gained; if the total reaches 25 successes or more, the song insinuates fully into the mind and memory of the subject. What the subject experiences is left to the Storyteller’s discretion, but usually the song either assuages the pain of a terrible memory or reminds the subject of a sweeter memory that has been recently repressed by more terrible experiences. The song cannot permanently heal mental scars, but it can soothe them for a time.",{lineBreak:!0},"The subject regains one Willpower point. Any derangements that the victim suffers will be temporarily relieved; the subject of the Gift will not be affected by the derangements for the rest of the story. The subject is likely to fall into a dreamless sleep at the conclusion of the Gift’s healing, unless he is deliberately attempting to remain awake for a specific purpose. Being exposed to this Gift may, at the Storyteller’s option, be a sufficiently profound experience that the subject may spend experience points to purchase another dot in Harmony (or Morality or the like) or Willpower."]},{type:"line",label:"Exceptional Success",text:"Successes are gained; if the total reaches 30 successes or more, the song is particularly potent. The subject regains all spent Willpower in addition to the benefits listed above."}]},{Rank:"•••••",Name:"Howl of Nightmares",Description:"Bring terror through a terrible howl. The target can make no action for 2 turns per success, after which may gain a derangement.",Cost:"●",Book:"Lore 85",fullDescription:[{type:"paragraph",text:"The most powerful of Cahalith can call down the night-terrors of the dreaming moon with a terrible howl. The Cahalith’s cry echoes into the soul of her prey, summoning up images of lunatic fright."},{type:"paragraph",text:"This Gift can be used only once per scene."}],fullCost:"1 Essence",dicePool:"Strength + Expression + Glory - target’s Composure",action:"Instant; contested and reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The howl goes awry, and the Cahalith glimpses a brief flash of the nightmares she’s called down. The Cahalith may only take a move action on her next turn as she regains her bearings."},{type:"line",label:"Failure",text:"The howl has no supernatural effect."},{type:"line",label:"Success",text:"The howl strikes into the target’s mind, twisting the sensory centers and triggering a rush of random hallucinations. For two turns per success, the target is overwhelmed with nightmarish visions, and can take no action. When the hallucinations pass, the target must make a successful Resolve + Composure check or gain a mild derangement of the Storyteller’s choice. The derangement is only temporary, lasting for one week (or technically, a complete change from one moon phase to the next)."},{type:"line",label:"Exceptional Success",text:"As above, save that if the target fails his Resolve + Composure check, the derangement gained is severe."}]}]},{Name:"Eclipse",Description:"",Cost:"",Book:"Blas 137",Content:[{type:"paragraph",text:"An eclipse is a few brief moments of darkness, the Earth hiding in the moon’s shadow or the moon obscured by the Earth. That, in a way, is a near-holy time to the Bale Hounds, when the moon is blinded by darkness. These Gifts are taught by spirits of darkness or some rare Lunes (particularly Irralunim)."},{type:"paragraph",text:"While these Gifts are quite appropriate for Bale Hounds, Storytellers may choose to make them available to other werewolves. The Bale Hounds don’t have a monopoly on the concept of darkness or shadows."}],Ranks:[{Rank:"•",Name:"Night-Eyes",Description:"The character can see perfectly well in natural darkness and suffers no penalties to vision-based rolls",Cost:"-",Book:"Blas 137",fullDescription:[{type:"paragraph",text:"Werewolves in Urhan form already have the sharpened senses of a true wolf, but this power allows the werewolf to see perfectly well in pitch darkness even in Hishu form. No natural darkness or shadow can defeat the werewolf’s vision, and he sees as keenly as though it were a night lit by the full face of Luna. The werewolf can still be blinded by supernatural means, or through natural means involving damage to his eyes. The Uratha’s enhanced sight can only pierce natural darkness without worry."}],fullCost:"None",dicePool:"Wits + Survival + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Uratha’s vision is troubled by flickering black shapes, rendering her near-blind for the rest of the scene. The werewolf suffers a -3 penalty to all rolls involving her vision for the remainder of the scene, or a whole hour, whichever is the soonest."},{type:"line",label:"Failure",text:"The Bale Hound’s perceptions do not shift."},{type:"line",label:"Success",text:"The character can see perfectly well in natural darkness and suffers no penalties to vision-based rolls."},{type:"line",label:"Exceptional Success",text:"The character’s sight becomes so attuned to the darkness that he gains a +2 bonus on all sight-based Wits rolls for the remainder of the scene."}]},{Rank:"••",Name:"The Shadow’s Secrets",Description:"Use targets' nearby shadows tactically to hear or speak",Cost:"●",Book:"Blas 137",fullDescription:[{type:"paragraph",text:"The Uratha can concentrate on any patch of shadow within her line of sight, and attune her senses so that she can hear and smell anything in the vicinity of the shadow. This is a useful Gift for a werewolf crouching on a rooftop or in an alleyway and who yet still needs to hear the conversation of her prey despite their distance down the street. The Gift works well in urban settings, when anyone standing in a city’s limits at night are constantly surrounded by the shadows of buildings, streetlights, alleys and so on."}],fullCost:"1 Essence",dicePool:"Wits + Occult + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The character hears the quiet whisperings of the shadow-spirits nearby instead of the targets’ voices. These are mellifluous, alien whisperings telling of every detail the shadows have seen that night, and the voices set nerves on edge and seem to make very little sense. The werewolf suffers a -4 to all hearing-based Wits rolls for the remainder of the scene."},{type:"line",label:"Failure",text:"Nothing happens."},{type:"line",label:"Success",text:"The character can make out the voices of the targets near the chosen shadow as if the werewolf was standing within the patch of darkness himself."},{type:"line",label:"Exceptional Success",text:"The werewolf’s senses become so amplified by the Gift that he can also scent the targets as if he were standing within the patch of shadow nearby."}]},{Rank:"•••",Name:"Shroud of the Blinded Moon",Description:"The spiritual reflection of an eclipse permeates the area, lengthening shadows and limiting vision drastically",Cost:"●",Book:"Blas 137",fullDescription:[{type:"paragraph",text:"The Uratha can call upon this Gift to summon his own eclipsing shadows. The darkness generated by this Gift is normal shadow, created to mirror the spiritual darkness of a lunar eclipse, and can be pierced by flashlights, sunlight and so on. When used subtly, such as in a dark alleyway or a forest at night, the summoned shadow can cloud the poor lighting completely and immerse the area in pitch darkness. Bale Hounds use this Gift in order to confound their foes or make last-minute escapes without the worry of being seen leaving the area."}],fullCost:"1 Essence",dicePool:"Manipulation + Occult + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf fails to summon the darkness of a lunar eclipse, and is unable to attempt another summoning until sunset the following evening."},{type:"line",label:"Failure",text:"Nothing happens."},{type:"line",label:"Success",text:"The spiritual reflection of an eclipse permeates the area, lengthening shadows and limiting vision drastically in an area of 20 square yards (or the entire room) for the rest of the scene."},{type:"line",label:"Exceptional Success",text:"The area affected doubles to a 40-square-yard area and further limits senses such as hearing and scent, inflicting -2 penalties to any rolls involving those senses while immersed in the summoned shadow."},{type:"table",title:"Suggested Modifiers",headers:["Situation","Modifier"],rows:[["Moonlight","+3"],["Dusk or poorly lit street","+2"],["Poorly lit room","+1"],["Well-lit room","—"],["Any sunlight present","-2"]]}]},{Rank:"••••",Name:"Darkened Moon",Description:"The target immediately loses all access to Auspice Gifts, and any Auspice Gifts that are currently in effect on the targetare canceled. The target also cannot use any auspice abilities and cannot add his Renown to any dice pools.",Cost:"●",Book:"Blas 137",fullDescription:[{type:"paragraph",text:"This Gift draws on the power of the lunar eclipse to blot out the werewolf’s victim’s access to the powers granted by Luna. The target loses access to all auspice abilities and even to the lunar marks of Renown. This Gift is presently unknown to the Pure, though the ramifications of it falling into their hands are very unpleasant."}],fullCost:"1 Essence",dicePool:"Intelligence + Occult + Honor versus Resolve + Primal Urge",action:"Instant and Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf is afflicted by the Gift’s effects as if Darkened Moon had been successfully used on her."},{type:"line",label:"Failure",text:"Nothing happens."},{type:"line",label:"Success",text:"The werewolf gains more successes than her target. The target immediately loses all access to Auspice Gifts, and any Auspice Gifts that are currently in effect on the target are canceled. The target also cannot use any auspice abilities and cannot add his Renown to any dice pools. The effects last for the duration of a scene."},{type:"line",label:"Exceptional Success",text:"The effects last for 24 hours."}]},{Rank:"•••••",Name:"Gauntlet Wraith",Description:"The werewolf can step into any shadow that is at least the same size as she is, and appear on the other side of the Gauntlet",Cost:"●",Book:"Blas 138",fullDescription:[{type:"paragraph",text:"The werewolf has developed such a command over shadows that she can use her power to push herself through the Gauntlet when she is immersed in darkness. The Gift only functions when the werewolf is hidden from Luna’s sight; the power fails to function if the Uratha can see the face of the moon from where she stands."},{type:"paragraph",text:"The werewolf can step into any shadow that is at least the same size as she is, and appear on the other side of the Gauntlet, either from spirit to substance or from the physical realm to the second world."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]}]},{Name:"Elemental",Description:"",Cost:"",Book:"WtF 111",Content:[{type:"paragraph",text:"Werewolves closest to the natural environment, among them the Hunters of Darkness, claim predominant affinity with these Gifts. Control of the elements and forces of nature, such as wind, fire, water and earth, are among the powers that werewolves may learn from Elemental Gifts. Logically, spirits somehow related to nature or specific elements teach these powers. The skill of the user depends on her physical might, as well as on her connection to the spiritual world."},{type:"paragraph",text:"While these Gifts as written reflect use of one specific element, Storytellers may optionally introduce four separate Elemental lists, substituting any of the four classical elements as needed. For example, Call Water could be Call Fire instead, with similar overall effects. Invoke the Wind could be Invoke the Earth, and so on."}],Ranks:[{Rank:"•",Name:"Call Water",Description:"Summon water in the werewolf's hand",Cost:"-",Book:"WtF 111",fullDescription:[{type:"paragraph",text:"Any animal knows that even a small pool of water can mean the difference between life and death. Such is the purpose behind this Gift, which can draw a few cups of water into the hands of a werewolf, even in a desert."},{type:"paragraph",text:["After invoking this Gift, the character creates the element of water between his hands seemingly from thin air, at least enough to stave off death from dehydration. (See “Deprivation,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 175) The character creates one cup of water for every success rolled — the excess overflowing his hands either into a container or just onto the ground. The Gift cannot be invoked more than once an hour."]}],fullCost:"None",dicePool:"Stamina + Survival + Purity",action:"Instant",rollResults:[]},{Rank:"••",Name:"Manipulate earth",Description:"Shape patch of earth",Cost:"●",Book:"WtF 111",fullDescription:[{type:"paragraph",text:"The dust of the earth becomes as malleable as clay in the werewolf’s hands. This Gift is useful for a variety of things, such as forming a protective earthen shelter or quickly concealing loved ones from enemies. The character touches the ground, and it seems to do her bidding."}],fullCost:"1 Essence",dicePool:"Dexterity + Crafts + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"Earth-spirits recoil at the werewolf’s fumbling. Any spirits of earth or stone become more hostile. Social rolls made toward those spirits suffer a -2 penalty, as do Gift-activation rolls or rite-activation rolls made within 24 hours that involve such spirits."},{type:"line",label:"Failure",text:"The Gift is unable to shape more than a few ounces of dirt."},{type:"line",label:"Success",text:"The werewolf can shape a surface area of roughly 100 square feet or a volume of roughly 40 cubic feet. The Gift is ideal for creating a quick foxhole or small escape tunnel. This power can sculpt earth, but not stone, concrete or metal. Changes made are permanent."},{type:"line",label:"Exceptional Success",text:"The werewolf can sculpt stone as well as earth, though not metal or man-made substances such as asphalt."}]},{Rank:"•••",Name:"Command Fire",Description:"Command flame's movement. May cause 1 lethal damage per success",Cost:"●",Book:"WtF 111",fullDescription:[{type:"paragraph",text:"Fire’s flames can both soothe the spirit and sear the flesh. This Gift shows the strong connection werewolves have with this element, even to the point of commanding fire to burn enemies or to cease its scorching wrath."},{type:"paragraph",text:["The character can’t summon fire from nothingness, but if open flames such as a nearby campfire or burning torch are within sight, she can command the flames at will, even having them arc through the air. The werewolf may cause one point of fire damage per success to a single target within line of sight. The target must be within 20 yards of an existing source of flame. The roll to attack someone with fire is penalized by the victim’s Defense and any cover or concealment involved. In addition, armor may offer some protection against the attack. (See “Fire” in the ",{text:"World of Darkness Rulebook",bold:!0},", p. 180.)"]},{type:"paragraph",text:"This Gift can also be used more simply, to spread an existing fire to a larger area (doubling the fire’s rate of growth) or to stop a fire from progressing toward a forest or settlement. This more exacting control lasts for as long as the werewolf concentrates. It is demanding, however, and imposes a -2 penalty on the activation roll."}],fullCost:"1 Essence",dicePool:"Strength + Survival + Glory",action:"Instant",rollResults:[]},{Rank:"••••",Name:"Invoke the Wind's Wrath",Description:"Summon and command a whirlwind. Inflicts 1 lethal damage per success and imposes a -4 to all rolls",Cost:"●●",Book:"WtF 111",fullDescription:[{type:"paragraph",text:["This Gift in many ways expresses the primal anger and inner turmoil of the werewolf’s spirit. The wind can be a fearsome ally, able to destroy flesh as well as metal, wood and stone. When a werewolf calls upon the wind, great destruction is sure to follow."]}],fullCost:"2 Essence",dicePool:"Strength + Empathy + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character stirs up a weather pattern beyond his control, such as a freak snowstorm or a bolt of lightning that strikes a random tree or building."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The local winds stir a bit with no real consequence."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," A whirlwind of terrible intensity forms immediately within 50 yards of the character. He can then set it moving in any direction he chooses (though he cannot make it change direction). The whirlwind’s radius of effect is approximately 10 feet, and it moves at the character’s unmodified base Speed. People or objects caught in that radius suffer one die of lethal damage per success rolled on the Gift’s activation roll. Anyone within the radius of effect also suffers a -4 penalty on all die rolls, and targets weighing 150 pounds or less may be lifted and thrown in a random direction. A character who is within the radius of effect can attempt to get out of harm’s way during the Gift-user’s place in the Initiative order if his action falls after that of the Gift user. His player rolls Dexterity + Athletics (though this roll suffers the -4 penalty). Even a single success allows the dodging character to get out of harm’s way, but doing so costs him his action at his own later place in the Initiative order that turn. The whirlwind dissipates after two turns. The Gift user himself can be affected by the wind if he comes in contact with it."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As success, but the whirlwind remains for an additional turn."]},{type:"heading",level:3,text:"Suggested Modifiers"},{type:"table",headers:["Modifier","Situation"],rows:[["-1","Calling a whirlwind on a blustery day"],["-3","Calling a whirlwind on a moderately windy day"],["-5","Calling a whirlwind on an utterly calm day"]]}]},{Rank:"•••••",Name:"Lament of the River",Description:"Summon and command a flood",Cost:"●●●",Book:"WtF 112",fullDescription:[{type:"paragraph",text:["Legends exist in almost every culture of great floods that have destroyed the known world. This powerful Gift is perhaps inspiration for those legends. The werewolf who calls upon the might of rivers and streams wields an awesome capacity for devastation and ruin."]}],fullCost:"3 Essence",dicePool:"Stamina + Intimidation + Wisdom",action:"Extended (50 successes; each roll represents one minute of uninterrupted concentration)",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," All accumulated successes are lost. The werewolf cannot try to use this Gift again in the same month."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No successes are gained this turn."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Successes are gathered for the turn. When 50 are accumulated, the waters within one square mile answer the werewolf’s call and burst forth from their shores with terrible might, as if they have been swollen by a month’s rains. Storytellers should probably think of this Gift in primarily qualitative terms. Immediate effects may include the indiscriminate death of local humans, the destruction of property and tremendous damage to flora and fauna. Some effects might even bleed into the Shadow."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No additional effects."]}]}]},{Name:"Ending",Description:"",Cost:"",Book:"Rage 114",Content:[{type:"paragraph",text:["Death Wolf walked the Pangaean landscape for many years, seeking out the answers at the end of every creature’s life. Through the Ending Gifts, her Bone Shadow children are able to explore the ending of lives as she once did, learning as their totem learned. Though the ",{text:"Hírfathra Hissu",italic:!0}," already have access to the Death Gifts, the Ending Gifts focus on aspects of death more tied in to Kamduis-Ur’s personal journey and the answers she worked for. As such, the Ending Gifts are often referred to as Death Wolf’s Gifts."]}],Ranks:[{Rank:"•",Name:"Fear of Death",Description:"The character learns the method of death that the subject most fears",Cost:"○",Book:"Rage 114",fullDescription:[{type:"paragraph",text:["The werewolf can look into the eyes of any living being and determine what type of death he most fears. The Gift can have some dark uses, revealing to a Bone Shadow just what method of death a subject fears the most, providing enough information for the character to arrange some grave threats or terrifying ambushes. Although the Gift was bestowed with a more insightful and cerebral intent in mind, there’s nothing stopping a cunning werewolf from using Fear of Death to scare his enemies or punish someone by killing her in the way she’s feared most since childhood."]}],fullCost:"1 Willpower",dicePool:"Wits + Empathy + Wisdom versus target’s Resolve + Primal Urge",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf garners an incorrect perception of the subject’s greatest fears regarding death. Whereas a person might fear being strangled after rape because of a similar incident in her life, the werewolf might sense a distinct fear of heights and falling that do not exist in the target’s mind."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf is unable to perceive the subject’s greatest fears regarding death."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character learns the method of death that the subject most fears, which is perhaps tied into a phobia or horrifying event in childhood."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The character also gains a faint impression of the reason the subject feels such fear, sensing images and fragments of thoughts detailing why that particular fear is so strong."]}]},{Rank:"••",Name:"Eyes of the Slain",Description:"Learn the most important thing that the soul is sorriest to leave behind. Sense the name and its relationship to the dead person, and a detailed description.",Cost:"●",Book:"Rage 115",fullDescription:[{type:"paragraph",text:["This Gift is a take on the apocryphal power to stare into the eyes of a corpse and discover how the victim was murdered. Though the Ending Gifts do not allow a werewolf access to such power, many Bone Shadows find Eyes of the Slain to be a fascinating opportunity nevertheless."]},{type:"paragraph",text:["The Gift only functions on the bodies of physical beings (not ghosts or spirits) that the werewolf has killed herself. In bringing about the death of the person, the character has bound herself to the path of the deceased soul’s destiny. By staring into the eyes of the corpse, the werewolf can focus her senses on that bond, determining what it was in life that the slain person most lived for. For some corpses, the images that shine in the eyes might be of their drug addiction, love for their children or an ambition regarding their career. It can be a difficult process to watch, for even the most hard-hearted of killers might have left behind something touching that they truly lived for, no matter how twisted their ideals. It goes almost without saying that some Bone Shadows use this Gift as a means of post-mortem interrogation as well as an aid to understanding mortal death."]}],fullCost:"1 Essence",dicePool:"Intelligence + Empathy + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The corpse’s eyes show nothing. Any local ghosts or death-spirits might become drawn to the location, sensing the killing and a potential new ghost."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character learns nothing from the glazed and motionless eyes."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character spends a full turn looking into the corpse’s eyes and learns the most important thing that the soul is sorriest to leave behind. In the cases of people, the Gift allows the character to sense the name of the face she sees and its relationship to the dead person, i.e., “Mary, his daughter” and a detailed description."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Per a success, but the character also learns another driving aspect that the deceased is sorrowful at leaving behind."]}]},{Rank:"•••",Name:"Death Masque",Description:"Deceive onlookers into believing that a glancing wound was lethal or that a near-miss became a mortal strike",Cost:"●",Book:"Rage 115",fullDescription:[{type:"paragraph",text:["It takes a bold werewolf to call on Death to protect himself, but some Bone Shadows do just that. This Gift allows the werewolf to wrap himself in the imagery of his own death, effectively deceiving onlookers into believing that a glancing wound was lethal or that a near-miss became a mortal strike. Once the foe believes the Bone Shadow dead, he may gain a few precious moments to heal — and to strike from behind."]}],fullCost:"1 Essence",dicePool:"Intelligence + Survival + Wisdom",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The death energies come to the werewolf, but do not act in his favor. The werewolf takes one point of bashing damage."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Gift fails to work; the werewolf’s wounds may appear a bit worse than usual, but not enough to convince anyone that they’re mortal."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The illusion takes effect. Any wounds that the werewolf has just suffered appear to be magnified. If the werewolf is unwounded but was previously in mortal danger, the illusion depicts that danger catching up to him. For instance, a recent claw rake across the back appears to be much deeper, with more blood and possibly deep cuts into the spine. If a person was shooting at the werewolf, Death Masque creates an illusion of bullets going into the heart, throat or head (or all three). As long as some plausible source of death has threatened the werewolf within the last six seconds, Death Masque can make it appear as though the danger has killed the werewolf."]},{type:"paragraph",text:["The illusory wounds granted by Death Masque last for the remainder of the scene, or until the werewolf chooses to end the Gift’s effects. The illusion extends to all five senses; the Bone Shadow smells dead, has no discernable pulse and cools to the touch. However, it will not conceal any movement more dramatic than breathing, regeneration or eye movement. If the werewolf gets up and keeps fighting (or doesn’t fall to the ground in the first place), others see him still moving and fighting, just with what would appear to be mortal wounds. This Gift can be used to gain the element of surprise on an attacker (see the World of Darkness Rulebook, p. 151)."]},{type:"paragraph",text:["This Gift automatically deceives any mundane observer. A supernatural power used to see through the illusion (such as the vampiric Discipline of Auspex) may see through the Death Masque; compare the observer’s successes on her activation roll to the werewolf’s successes gathered to activate this Gift."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As above, and any supernatural attempts to see through the Death Masque are at an additional -1 penalty."]}]},{Rank:"••••",Name:"Bone Hex",Description:"The target suffers a -4 penalty on his next three dice rolls, including Harmony, Morality or other degeneration rolls",Cost:"●",Book:"Rage 116",fullDescription:[{type:"paragraph",text:["Death Wolf learned to influence Fate in her travels, watching as creatures died under the twists of her machinations. This Gift allows her children to do the same, by weaving fate into a different pattern and altering the immediate destiny of a chosen subject. By killing in this manner, the werewolf does not avoid any Harmony loss she would otherwise experience if the death had been administered directly."]}],fullCost:"1 Essence",dicePool:"Presence + Occult + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The veins of fate refuse to be manipulated and the effects of the Gift backfire. The Bone Shadow suffers a -4 penalty on her next three dice rolls."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Fate remains the same, refusing to be twisted by outside interference."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character manipulated the fate of the subject by conscious thought. The target suffers a -4 penalty on his next three dice rolls, including Harmony, Morality or other degeneration rolls."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Per a success, though the Bone Shadow can choose when the effects of the Hex apply, as long as they occur within one month of the Gift’s use."]}]},{Rank:"•••••",Name:"Images of Death",Description:"Target witnesses his own death and suffers a -2 penalty to all dice rolls for the next week as he experiences recurring nightmares of the vision.",Cost:"●●",Book:"Rage 116",fullDescription:[{type:"paragraph",text:"Death Wolf learned all aspects of endings in her travels, even the ability to perceive a creature’s death from the moment of its birth. With this Gift, the werewolf can flood a target’s mind with images of his own death to come. This is a horrifying power, filling the subject’s mind with sensations that he unerringly knows represent the way he will die. Even relatively painless or quick deaths will hurt the target’s mind and eyes as he sees the literal end of his life."},{type:"paragraph",text:"Obviously, Storytellers will need to be careful when characters use this Gift, for it is supposed to show a person his exact death, not a possible one. Once a character has suffered this power’s effects, his fate is sealed. There is the belief among the Bone Shadows that if the power is used frivolously, such as on idly curious packmates, then the images shown detail a much harsher and earlier demise than would otherwise have happened."}],fullCost:"2 Essence",dicePool:"Wits + Intimidation + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The Gift fails and instead shows the werewolf conflicting visions of her own death. Unlike the images inflicted on others, these detail only possible deaths, appearing as eye-wracking visions that debilitate the character, reducing her dice pools by 2 for 10 – Stamina hours."},{type:"line",label:"Failure",text:"The Gift fails to show the target anything."},{type:"line",label:"Success",text:"Images of the target’s eventual death flash before his eyes, stealing all of his senses. If he dies in a car wreck, he feels himself standing on the road staring at the accident. If he dies in battle, he sees the death blow falling and his body breaking. If he dies in a hospital bed, he smells the disinfectant on the ward and the stale blankets bathed in his sweat. This is a traumatizing experience, to say the least. Anyone witnessing his own death in this way must suffer a –2 penalty to all dice rolls for the next week as he experiences recurring nightmares of the vision. No matter what steps the target takes to avoid his death, it will still occur in the ordained manner."},{type:"line",label:"Exceptional Success",text:"The visions turn into nightmares that last a month instead of a week."}]}]},{Name:"Endurance",Description:"",Cost:"",Book:"Rage 117",Content:[{type:"paragraph",text:"Werewolves are traditionally strong, fearsome beasts. Their shapechanging nature allows them to regenerate almost any wound, and folklore often remarks upon their incredible stamina — often, they will not stop or end their hunt, and mere food and tiredness mean nothing to them. These Gifts enhance that fortitude, allowing a werewolf to reap the most benefit from his regenerating body and shapeshifting metabolism. Endurance Gifts are taught by the spirits of animals noted for their stamina, such as camels, and the spirits of ancient forests and mountains."}],Ranks:[{Rank:"•",Name:"Vigil",Description:"Character doesn’t need to sleep for the next 12 hours, and does not suffer the normal symptoms of tiredness",Cost:"○",Book:"Rage 117",fullDescription:[{type:"paragraph",text:["A pack must keep constant watch over the pack’s territory and more besides. From spirits to ",{text:"shartha",italic:!0}," to humans who just don’t know when to stop, the world cries out for a werewolf’s attention. This Gift allows her to keep watching the world even when she’s about to drop from tiredness."]},{type:"paragraph",text:["Upon activating this Gift, the character doesn’t need to sleep for the next 12 hours, and does not suffer the normal symptoms of tiredness (lack of concentration, irritability and so on). Werewolves typically use this Gift when they’ve already been awake for 18 hours or more, and it leaves them feeling perked up and refreshed — a spiritual second wind. Once the period of extended wakefulness is up, the character feels a pressing urge to sleep for eight hours, and can sleep through any amount of noise or disturbance. She can use this Gift again before its effects wear off to get another 12 hours (and adding four hours to the time she must spend asleep), but once this Gift ends, she must sleep before she can use any other Gifts."]}],fullCost:"1 Willpower",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Long Running",Description:"Double Speed. This Gift’s effects last one hour per success. Does not work in combat (but may be prepared before, in which case it does work).",Cost:"-",Book:"Rage 117",fullDescription:[{type:"paragraph",text:["Sometimes, a werewolf must run as she never has before. Be it to take news to her packmates or seek out secrets deep within the spirit wilds, some things require that she not stop running until the message gets through. This Gift enhances her endurance, allowing nothing to stop her as long as all she does is run. Some Uratha have used this Gift to bring the secret of an ancient ritual back to their packs to save their territory, while others have ensured that they are far away from a new evil that will kill their pack."]}],fullCost:"None",dicePool:"Stamina + Athletics + Purity",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character tries to run, but features of the landscape that would normally present no problem to him tangle his feet and prevent him from getting a good start. He cannot use this Gift for the rest of the day."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character runs, but his feet are no more fleet than they normally are."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf is able to run all-out for as long as he needs. Double his Speed (as if sprinting) in order to work out how fast he travels when running. This Gift’s effects last one hour per success, but the character can cancel the Gift’s effects before that point, as long as he has spent at least five minutes running, as he has a spiritual need to cover distance that his muscles will not deny. The Gift cannot be used in combat as it requires preparation, though a character who is attacked while running still applies his Defense. After the Gift’s effects end, the character must sleep for at least four hours."]},{type:"paragraph",text:["The character can re-activate this Gift at any point before it ends; however the new duration takes effect from the point that the roll is made."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The character not only runs all-out, he is able to deftly overcome some obstacles that would normally get in his way. Add 2 to his Speed after doubling for a success. This bonus doesn’t last if the character re-activates the Gift."]}]},{Rank:"•••",Name:"Eternal Hunter",Description:"Does not have to roll for unconsciousness, and takes no extra damage when he has taken his Health in bashing or lethal damage. Lasts for one turn per success",Cost:"○",Book:"Rage 117",fullDescription:[{type:"paragraph",text:["A werewolf who possesses this Gift will keep on going almost forever. Neither hideous injury nor death will slow him down, as he focuses himself on his need to survive. While this Gift will not allow him to regenerate his way back from an obvious death, his spirit-enhanced endurance puts off the effects of his wounds until after his enemy is dead on his claws, or he has overcome the problems before him."]}],fullCost:"1 Willpower",dicePool:"Resolve + Survival + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character attempts to fight off the pain, but it overwhelms him. He falls immediately unconscious, and reverts to Hishu form."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character must roll for remaining conscious and bleeding out as normal."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Gift focuses the character’s will and resolve, making certain that he will not die. He does not have to roll for unconsciousness, and takes no extra damage when he has taken his Health in bashing or lethal damage. Only outright death will have an effect. The werewolf regenerates all damage as normal during this time, unless he takes enough damage to be dead. This Gift lasts for one turn per success, and the effects (unconsciousness rolls, bleeding out or death) occur immediately afterwards."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," In addition to the effects of a success, any member of the character’s pack seeing the use of this Gift immediately regains one Willpower point."]}]},{Rank:"••••",Name:"Rise Beyond",Description:"All wound penalties are instead applied as a bonus to applicable die rolls for the remainder of the scene.",Cost:"○",Book:"Rage 118",fullDescription:[{type:"paragraph",text:["Werewolves pride themselves on their endurance. The Storm Lords exemplify this, but that’s not to say that every other tribe doesn’t reward the ability for an Uratha to rise beyond adversity, stoically carrying on and even finding themselves working better under pressure. This Gift rewards that nature, giving the werewolf using it a greater chance to succeed if his body is broken than if he were uninjured."]}],fullCost:"1 Willpower",dicePool:"Stamina + Athletics + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf reaches deep inside, looking for a second wind, but instead comes face-to-face with her own lack of resources. All wound penalties are one higher (-1 becomes -2 and so on) until the end of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character has nothing more left to give."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf is flooded with renewed strength of purpose, and a desire to see her enemies hurt as much as they hurt her. All wound penalties are instead applied as a bonus to applicable die rolls for the remainder of the scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success, but the extra reserves are particularly potent. Increase each bonus by +1 (for example, +2 becomes +3)."]}]},{Rank:"•••••",Name:"Legacy",Description:"The werewolf spits one final curse at his killers in First Tongue, which usually applies within a year. It may be death or incapacity to all the killers.",Cost:"●●●○○",Book:"Rage 118",fullDescription:[{type:"paragraph",text:["The werewolf has learned how to endure even beyond death, with spirits ensuring that his dying wishes of revenge are carried out against his killer. Spirits that are near when the werewolf dies must carry out his dying wishes — often they must avenge his death by killing his killer. This Gift doesn’t allow an Uratha to bless his pack when he dies; the spirits only listen to curses of vengeance. As with all spirits, they will hunt down the werewolf’s killers and exact his revenge."]},{type:"paragraph",text:["This Gift can only be used if the werewolf is going to die on the turn that it is used, and he must pay the full cost of the Gift at the point of activation. The werewolf spits one final curse at his killers in First Tongue, empowered with spiritual Rage. This curse seeks out and finds everyone who has had a direct hand in the character’s death — the whole pack of Pure who ambushed him is a valid target, but the human who poisoned the pack’s water supply and weakened him does not suffer the effects."]},{type:"paragraph",text:["The curse can be effectively anything. It could be a simple “You will all die by the end of the year,” or something far more subtle — “You can never eat the flesh of beasts again.” Curses with a direct effect — death, incapacity — tend to take a year to manifest, and apply modifiers of up to three dice in a situation in which it looks likely that the character will fall prey to the curse. Non-direct curses, such as never eating the flesh of beasts, last until everyone cursed is dead and cause incredible pain if their restriction is broken. The precise mechanical effects of this Gift are left to the Storyteller, but should be suitably appropriate and powerful."]}],fullCost:"3 Essence and 2 Willpower",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]}]},{Name:"Evasion",Description:"",Cost:"",Book:"WtF 113",Content:[{type:"paragraph",text:"Cleverness and cunning are essential to survival, for both wolves and humans. Gifts of Evasion embody the shrewdness of the human mind with the instincts and natural intuition of a predatory animal. The Storm Lords have affinity with these Gifts; many Irraka also find them useful. Lunes and animal spirits, both taking the forms of creatures such as ravens, foxes and otters, teach Gifts of Evasion. The Gifts represent a blend of both keen intelligence and “gut feeling” that enables a werewolf to sneak, deceive and mislead with preternatural ease."}],Ranks:[{Rank:"•",Name:"Loose Tongue",Description:"Make the target speak (-2 to Empathy and Subterfuge against Gift user)",Cost:"-",Book:"WtF 113",fullDescription:[{type:"paragraph",text:["Some folks just have a knack for getting other people to blab incessantly. A werewolf with this Gift can take advantage of that strength, making people feel oddly chatty around her. The werewolf must engage a subject in conversation for at least 30 seconds before she can use this Gift. Success clouds a target’s better judgment, making it difficult to keep secrets from the werewolf."]},{type:"paragraph",text:["A contested roll is made for the intended subject with the highest Composure + Primal Urge dice pool. The Gift user need not be alone with the subject of this Gift for the Gift to work. She can isolate a particular subject in a crowd if she wants to. A contested roll is made for that subject alone."]},{type:"paragraph",text:["This Gift can be used successfully on only a single subject and only once per scene on that subject."]}],fullCost:"None",dicePool:"Manipulation + Socialize + Wisdom versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf is infected by the Gift’s effects instead of her targets, suffering a -3 penalty to all Empathy, Persuasion and Subterfuge rolls for the duration of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character fails to affect the target."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Up to one target in conversation with the werewolf is affected per success. You decide who is affected based on the total successes rolled. Targets under the Gift’s influence suffer a -2 penalty to Empathy and Subterfuge rolls for the duration of the scene, and only toward rolls made against the Gift user. A subject is not suddenly forthcoming with secrets to anyone else who comes along, but he becomes more susceptible to “friendly conversation.”"]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The targets suffer the listed penalties, as well as a -2 penalty to Composure rolls for the rest of the scene."]}]},{Rank:"••",Name:"Sand in the Eyes",Description:"Make the werewolf forgettable (-5 to Remember Gift user)",Cost:"-",Book:"WtF 113",fullDescription:[{type:"paragraph",text:["The genuinely cunning know the value of covering their tracks… not simply footprints, but also slips of the tongue or suspicious behavior. This Gift tends to make the questioner seem imminently forgettable to onlookers. The Gift doesn’t make the character any more innocuous at the time (a security guard will probably still ask to see her ID, for instance), but it becomes more difficult to remember her after the fact."]},{type:"paragraph",text:["A werewolf may use this Gift only once per scene per target (succeed or fail)."]}],fullCost:"None",dicePool:"Manipulation + Subterfuge + Honor versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Subjects instantly sense that something is dreadfully wrong about the werewolf, catching a glimpse of the predator within."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Subjects pay no more or less attention to the character than normal."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Anyone affected by the Gift who interacts with the werewolf while the Gift is in effect suffers a -5 penalty to any later Intelligence + Composure rolls for the purposes of remembering details about the werewolf (see ",{text:"World of Darkness Rulebook",bold:!0},", p. 44). They’re hard-pressed to pick the character out of a lineup, recall how long she hung around or even realize she was digging for information. If the werewolf takes any violent action against the subject, the Gift’s effects end where that subject is concerned. This Gift can only cloud memories of the scene in which the Gift was used; it does not erase all memories of the werewolf if the target and werewolf interacted previously."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Those affected must make an Intelligence + Composure roll at -5 to remember that the character was ever there at all."]}]},{Rank:"•••",Name:"Playing Possum",Description:"Feign death (also cancels regeneration while faking death)",Cost:"○",Book:"WtF 113",fullDescription:[{type:"paragraph",text:["Enemies often turn their backs on fallen foes. Imagine a victor’s shock when a supposedly dead werewolf rises to attack with complete surprise. To all but the most careful examination, a werewolf using this Gift appears quite dead. Her chest doesn’t rise and fall, her heart fails to beat and her body seems cooled to ambient temperature for as long as a day."]}],fullCost:"1 Willpower",dicePool:"Wits + Subterfuge + Cunning",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift’s effects take hold in the wrong way, increasing the werewolf’s heart rate and respiration in an unhealthy fashion. All Stamina rolls suffers a -1 penalty for the duration of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character may still play dead, but her pulse, breathing rate and regenerative abilities don’t change, possibly giving her away."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character appears to be freshly dead, displaying no discernible pulse or respiration, and she can remain in that state for up to one day. If she suffers from any wounds, they appear to have clotted with the slowing of blood, though the character receives no actual healing. (In fact, she doesn’t regenerate while this Gift is in effect.) She can revive herself at will as an instant action. A contested Intelligence + Medicine roll can be made for a persistent investigator if he spends at least one scene carefully checking over the werewolf, to recognize that the “death” isn’t genuine. While “dead,” the character knows what’s going on around her, but she can’t move without ending the effect of the Gift."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As success, but the character is able to regenerate her wounds at the usual rate without displaying any external sign of healing."]}]},{Rank:"••••",Name:"Double Back",Description:"Sense physical deception",Cost:"○",Book:"WtF 114",fullDescription:[{type:"paragraph",text:["While one facet of being clever and evasive is hiding your tracks, another aspect of wiliness is seeing when someone’s trying to pull the wool over your eyes. This Gift gives a werewolf a keen sense for deception, alerting her when things aren’t as they first appear. The effects of this power persist for the remainder of the scene."]}],fullCost:"1 Willpower",dicePool:"Intelligence + Investigation + Glory",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character perceives a hidden hand at work where none exists."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character gains no additional information."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character becomes immediately aware of all attempts at physical deception in her environment. She knows where a person has tried to hide evidence, conceal a trail or otherwise mislead a pursuer or investigator. She knows whether anyone in her area is disguised (although she cannot see ",{text:"through",italic:!0}," the disguises), and can tell where someone is physically hidden. This Gift doesn’t make the character aware of social deception (such as a person telling a lie) or of mystical disguises. She is, however, aware of a physical deception even if it’s mystically cloaked. For example, if a mage casts a spell of illusion to hide a wall safe, this Gift doesn’t reveal the presence of deception in the safe’s area. If the safe has also been physically hidden behind a painting, the character gets the extremely confusing sensation that something is hidden behind the picture, despite what his eyes tell him. If the safe is hidden behind a picture then the ",{text:"picture",italic:!0}," itself is hidden by a spell of illusion, however, this Gift doesn’t detect the physical hiding place."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As success, but the werewolf also becomes aware of any mystical tampering, deception or concealment. Again, she cannot see through such things, but [unclear]"]}]},{Rank:"•••••",Name:"Fog of War",Description:"Summon a veil of confusion (-3 to all rolls for selected targets)",Cost:"●",Book:"WtF 114",fullDescription:[{type:"paragraph",text:["A well-ordered battle plan seldom survives being put into action. Noise, smoke, darkness and fear lead to disorganization as confusion sets in. This Gift increases chaos in any situation. SWAT teams fire on each other, intruders get hopelessly lost, and emergency instructions are garbled."]},{type:"paragraph",text:["The werewolf howls, drums or sings a song against opponents (not necessarily enemies), throwing a veil of confusion over an area. All targets within extreme hearing range (whether they notice the sound or not) get a contested roll as a reflexive action."]}],fullCost:"1 Essence",dicePool:"Manipulation + Expression + Honor versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf’s howl falters and conjures no fear or confusion. Fog of War cannot be used again for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Successes rolled for the werewolf are less than or equal to those rolled for a listener. The listener goes about his business unaffected for the duration of the power."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The most successes are rolled for the werewolf. A listener suffers a -3 penalty to all actions while the Gift remains in effect. The effect lasts as long as the werewolf concentrates on the song; he cannot engage in other strenuous or distracting activity. Inflicting any wound on the performing werewolf terminates the effect."]},{type:"paragraph",text:["Penalties are not cumulative. If three werewolves all invoke the Fog of War at once, potential targets must make three separate contested rolls. Failure on any of the three imposes the -3 penalty, but it doesn’t increase to -6 or -9 if a target fails more than one contested roll."]},{type:"paragraph",text:["A user can designate subjects to go unaffected by the Gift in the turn in which the player makes the roll, but the user must designate them specifically and be able to see them when he does so. Otherwise, they are affected by default. A subject cannot be designated as immune if he hears the song once it’s already begun."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Five or more successes are rolled for the Gift user, and he wins the contested action. The song need not be sung continuously. Anyone who hears it in the first turn of performance and who loses the contested roll is affected for the remainder of the scene."]}]}]},{Name:"Father Wolf",Description:"",Cost:"",Book:"WtF 115",Content:[{type:"paragraph",text:"These Gifts represent the core strengths of the children of Father Wolf. Unlike other Gift lists, Father Wolf’s are accessible to Uratha of all tribes and auspices. They represent aspects of every werewolf, elements of the lineage that all werewolves share. Father Wolf’s Gifts comprise an “open” Gift list. Any werewolf character may purchase Gifts from this list at the same cost as purchasing Gifts from lists affiliated with auspice or tribe."},{type:"paragraph",text:"Father Wolf’s Gifts are taught by ancestor-spirits and war-spirits that take wolf form."}],Ranks:[{Rank:"•",Name:"Wolf-Blood's Lure",Description:"Communicate in any form with regular wolves and dogs",Cost:"-",Book:"WtF 115",fullDescription:[{type:"paragraph",text:["A werewolf is not simply a person with the power to transform into a wolf, he’s a person with a wolf’s soul. The simplest of Father Wolf’s Gifts to master, Wolf-Blood’s Lure allows one of the People to draw on his wolf soul, projecting it so that he seems more animal than human. While many mundane canines are naturally uncomfortable in the presence of the Uratha as predators, this Gift makes the werewolf seem more like one of the pack. While this Gift offers no additional control over mundane wolves or canids, the user finds it easier to earn a wolf pack’s trust or intimidate a guard dog."]},{type:"paragraph",text:["When activated, this Gift grants the character the ability to communicate with wolves and dogs, regardless of what form he’s in. In addition, a bonus die is gained on all Social rolls made involving wolves or other canids. The Gift’s effects last from moonrise to moonset, or from moonset to moonrise."]}],fullCost:"None",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Father Wolf's Speed",Description:"Increase speed (doubles speed and gives a -2 to all ranged attacks against Gift user)",Cost:"●",Book:"WtF 115",fullDescription:[{type:"paragraph",text:["Father Wolf was said to be as fleet as the wind, able to outrun the swiftest prey. Werewolves naturally share a measure of his great speed, but this Gift can increase their swiftness even further. A clever werewolf uses this Gift to run at the same pace as the rest of his pack then surprise prey with a sudden burst when the moment is right."]},{type:"paragraph",text:["This Gift cannot be used when the werewolf is in Hishu or Dalu form. The character’s Speed is doubled (after modifiers for his current form are determined). In addition, the character subtracts two dice from opponents’ Firearms dice pools. The effects last for a scene."]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"Primal Howl",Description:"Provoke Lunacy. Also affects supernaturals and cancels wolf-blooded Willpower bonus.",Cost:"●",Book:"WtF 115",fullDescription:[{type:"paragraph",text:["The werewolf howls with the voice of the first wolf, a voice that humans and animals instinctively recognize from millennia of ancestral memory. Those who hear the howl are overcome by their forebears’ fear of wolves hunting in the night, of predators that might yet come for them."]},{type:"paragraph",text:["The howl can be heard for miles, as any wolf howl, but the Gift takes effect on any targets within 10 yards per dot of the werewolf’s Primal Urge. The call has no effect over a telephone or other indirect communication. Affected subjects are overcome by fear as if affected by Lunacy (p. 175). If a listener’s Composure dots are equal to or higher than the number of successes earned, the subject may act normally, even though he feels a shiver of primal fear. The Gift user cannot select certain targets to be affected or unaffected — the howl affects anyone who hears."]},{type:"paragraph",text:["Shapeshifters and spirits are immune to the effects of the Primal Howl. Vampires, mages or other supernatural beings who were born human combine Composure + the appropriate resistance Trait (such as Blood Potency) to resist the effects of the Gift. Wolf-blooded and ghouls gain no bonus."]}],fullCost:"1 Essence",dicePool:"Presence + Expression + Purity versus Composure",action:"Contested; resistance is reflexive",rollResults:[]},{Rank:"••••",Name:"Savage Rending",Description:"Deal Aggravated damage with claws and bites. Sin when used against werewolves, with a threshold of 4",Cost:"●",Book:"WtF 115",fullDescription:[{type:"paragraph",text:["Father Wolf was more than a wolf-spirit. He was a spirit of war, tearing apart enemies with claws and fangs, more savage than any wolf born of flesh. His children have inherited many of his capabilities. The werewolf with this Gift can channel his fury through his claws and fangs, inflicting horrifying wounds on foes. It’s considered a sin against Harmony to use this Gift against other werewolves, equivalent to using a silver weapon (see p. 181)."]},{type:"paragraph",text:["The werewolf’s claw and bite attacks inflict aggravated damage. The amount of damage inflicted doesn’t change. Aggravated damage is caused for the duration of the scene unless the user terminates the Gift prematurely."]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Spirit Pack",Description:"Summons 1 wolf-brother per success",Cost:"●",Book:"WtF 115",fullDescription:[{type:"paragraph",text:["Even the Forsaken can call on ties of blood. A werewolf with this Gift is able to summon ancient spirit brethren, drawing a ghostly pack from the other world to assist him in battle. The werewolf howls a battle cry as he invokes the Gift. One Wolf-Brother spirit materializes per success achieved, and follows the general directions of the character. The spirits interpret the werewolf’s commands to the best of their ability, but they’re guided by their lupine nature. They fight in a pack rather than split in many directions at once, and they give chase to fleeing prey unless specifically commanded to halt. The spirits return to the depths of the Shadow once there are no more enemies to fight. If the Gift user is slain while the Wolf-Brethren are present, they fight until the one who slew their summoner is dead or until they’re defeated, and then leave. (For Wolf-Brother spirit statistics, see p. 244.)"]}],fullCost:"1 Essence",dicePool:"Manipulation + Animal Ken + Glory",action:"Instant",rollResults:[]}]},{Name:"Fervor",Description:"",Cost:"",Book:"Pure 116",Content:[{type:"paragraph",text:["An ",{text:"Izidakh",italic:!0}," is only as strong as his faith. Most Fire-Touched, then, are strong indeed. Fervor Gifts harness that faith, granting the werewolf who wields them knowledge, strength and perseverance."]},{type:"paragraph",text:"Fervor Gifts are taught by those that represent faith, sacrifice and loyalty. Dog-spirits, ideology-spirits, and even some disease-spirits can impart them."}],Ranks:[{Rank:"•",Name:"Eyes of Gurim",Description:"The character knows targets compulsions or derangements from losing Harmony and targets Vice",Cost:"-",Book:"Pure 116",fullDescription:[{type:"paragraph",text:["The Fire-Touched can judge the state of another werewolf’s soul. ",{text:"Izidakh",italic:!0}," use this Gift to judge whether an Uratha would be a good candidate for conversion. When used successfully, the Eyes of Gurim can give the Fire-Touched some information about the target’s weaknesses, which he can then exploit when attempting to convert her."]},{type:"paragraph",text:["This Gift works on any werewolf that the character can see directly (i.e., it does not work through video cameras or on photographs). The character can recognize members of his own tribe on sight."]}],fullCost:"None",dicePool:"Intelligence + Investigation + Purity",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character has a completely false idea of the target’s moral state. The character might mistake a ",{text:"Zi’ir",italic:!0}," for a paragon of Harmony, or might even mistake a Forsaken werewolf for a Fire-Touched."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character fails to uncover any information about the target."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character knows any compulsions or derangements she labors under from losing Harmony and her Vice."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No special effect."]}]},{Rank:"••",Name:"Gurim’s Comfort",Description:"The character regains a number of Willpower points equal to her Primal Urge",Cost:"-",Book:"Pure 117",fullDescription:[{type:"paragraph",text:["Gurim-Ur supports his children, even when times are dark and the enemies of truth are all about. The Fire-Touched with this Gift can call upon the succoring faith of Rabid Wolf to refresh her mental fortitude."]},{type:"paragraph",text:["This Gift can be used only when the Fire-Touched has spent her last Willpower point."]}],fullCost:"None",dicePool:"Resolve + Composure + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character suffers a crisis of faith. Gurim-Ur, the character feels, has abandoned her. The Fire-Touched must immediately check for degeneration if her Harmony is 7 or above (roll four dice)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character regains a number of Willpower points equal to her Primal Urge."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The character regains ",{text:"all",italic:!0}," spent Willpower points, just as if she had acted in accordance with her Virtue."]}]},{Rank:"•••",Name:"Trust in Gurim",Description:"Fire-Touched must make all-out attacks with +4 to all attacks. He does not get his Defense during this time",Cost:"○",Book:"Pure 117",fullDescription:[{type:"paragraph",text:["The Fire-Touched with this Gift fights as though he is immortal, secure in the knowledge that even if he should fall, Rabid Wolf will take the Fire-Touched to ",{text:"Taga Dan",italic:!0}," personally. He therefore fights with an unholy fury, tearing his enemies limb from limb, and never acknowledges pain or injury. If he survives the battle, he is grateful to his patron, but cannot help feeling a bit disappointed that he will not see paradise that day."]}],fullCost:"1 Willpower",dicePool:"Strength + Expression + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Fire-Touched succumbs to doubt and despair. He can take no action in combat during this scene except to dodge (see p. 156 of the ",{text:"World of Darkness Rulebook",bold:!0},"), as he fears for his life. After the combat ends, he must immediately check for degeneration if his Harmony is 7 or more (roll four dice)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Fire-Touched becomes infused with the strength of Gurim-Ur. For the remainder of the scene, the Fire-Touched must make all-out attacks (see p. 157 of the ",{text:"World of Darkness Rulebook",bold:!0},"), but instead of the usual +2 bonus, he receives a +4 to all attacks. The Fire-Touched does not get his Defense during this time, however."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," For one Willpower point, the Fire-Touched can use his Defense as usual while this Gift is active (though he cannot dodge). A Willpower point must be spent each turn to continue using Defense."]}]},{Rank:"••••",Name:"Gurim’s Might",Description:"Receive a +2 bonus on any roll involving Presence, Intelligence or Strength, Spend 1 Essence for each roll",Cost:"●○",Book:"Pure 117",fullDescription:[{type:"paragraph",text:["Gurim-Ur was, according to most stories, the smallest of the Firstborn, but he was fast and deadly when he hunted in earnest. This, the Fire-Touched say, is because he knew when he was in the right, and that righteousness made him mighty. The ",{text:"Izidakh",italic:!0}," can channel the might of their crazed totem, but can do so for any forceful endeavor — combat, indoctrination or even reasoning."]}],fullCost:"1 Willpower plus 1 Essence per roll",dicePool:"Resolve + Composure + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Fire-Touched realizes that Gurim-Ur does ",{text:"not",italic:!0}," approve of her current course of action. The Fire-Touched slips into a state of depression and suffers a -2 on all Mental or Social rolls until she can perform an act of penance."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Fire-Touched is secure in the knowledge that Gurim-Ur blesses her actions, and can use that surety to her advantage, as long as she is acting decisively and forcefully. In game terms, the Fire-Touched receives a +2 bonus on any roll involving Presence, Intelligence or Strength, provided that a point of Essence is spent for each roll. The benefits of this Gift last for one scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Essence only needs to be spent when bolstering Strength. All Presence- and Intelligence-based rolls receive the bonus for the remainder of the scene."]}]},{Rank:"•••••",Name:"Gurim’s Bite",Description:"Target is incapable of attacking the Gift user or anyone fighting alongside him",Cost:"●",Book:"Pure 117",fullDescription:[{type:"paragraph",text:["According to the Fire-Touched, Rabid Wolf’s madness wasn’t caused by an earthly disease or a malady of the mind but by his flawless honor trying to make sense of a dishonest world. Faith in the purity of honesty is what binds the Fire-Touched, and to his most faithful followers, Gurim-Ur grants the ability to spread that faith with a single bite. The victims of this Gift see, for a few brief moments before lies cloud their minds again, the freedom and the purity that the Fire-Touched truly possess. While the power of Gurim’s Bite isn’t normally sufficient to turn packmate against packmate, it does prevent the target from attacking the Fire-Touched, even in self-defense."]}],fullCost:"1 Essence",dicePool:"Presence + Persuasion + Cunning versus Resolve + Primal Urge",action:"Reflexive and contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Fire-Touched cannot summon the faith to make the Gift work. He loses access to this Gift and ",{text:"all",italic:!0}," Fervor Gifts until he performs an act of penance. He must also check for degeneration if his Harmony is 7 or more (roll four dice)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The target gains more successes than the Fire-Touched. The Gift has no effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Fire-Touched exceeds the victim’s successes. For the remainder of the scene, the target is incapable of attacking the Gift user or anyone fighting alongside him. The target is under no compulsion to fight at the ",{text:"Izidakh",italic:!0},"’s side, but cannot attempt to harm him in any way. Even thinking about doing so renders the target physically ill with remorse — the Fire-Touched simply seems too pure to touch, too holy to harm."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Fire-Touched exceeds the victim’s successes by five or more. The victim now feels compelled to aid the Fire-Touched, even to the point of attacking her family, friends or pack."]}]}]},{Name:"Fever",Description:"",Cost:"",Book:"Blas 82",Content:[{type:"paragraph",text:"These Gifts are the mainstay of the Fire-Touched in this lodge. Hosts of disease-, pain- and parasite-spirits teach these Gifts. These Fire-Touched would like to consider these Gifts as their personal property, but these dark spirits have made no bargain in exclusivity and may well teach them to others, especially Bale Hounds."}],Ranks:[{Rank:"•",Name:"Symptom",Description:"Disease makes the victim to suffer a -1 to all die rolls of one specific category of the user’s choice: Physical, Social or Mental.",Cost:"-",Book:"Blas 82",fullDescription:[{type:"paragraph",text:["Diseases most often start with tell-tale signs, such as a runny nose, sweaty brows, sneezing, blurry vision, minor aches and pains and so on. This Gift creates one of these symptoms in the target. Medical examination doesn’t reveal a reason for the symptom or any other associated sign of infection — no elevated white blood cell count, for example."]}],fullCost:"None",dicePool:"Cunning + Manipulation + Larceny versus Stamina + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift fails completely. The werewolf cannot use any Fever Gifts on the target for the rest of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Successes rolled tie, or the subject gets the most. The target displays no symptoms of disease."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The most successes are rolled for the Gift user. This Gift affects a single target. The target exhibits one or two outward symptoms of some disease — the effects may be discomforting, embarrassing or both, but are never life-threatening. The victim suffers a -1 to all die rolls of one specific category of the user’s choice: Physical, Social or Mental. The symptoms last for a number of hours equal to the successes rolled."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As success, but three to five symptoms can be inflicted at once. Also, the symptoms are so severe that the target suffers a -2 due to the discomfort."]}]},{Rank:"••",Name:"Touch of Fever",Description:"The victim contracts the disease. After one hour she begins showing symptoms and suffers a -1 to all rolls until she recovers, or passes away.",Cost:"●",Book:"Blas 82",fullDescription:[{type:"paragraph",text:["This Gift wills a potent fever into the hands of the Uratha. Anyone touched while the Gift is active must immediately make rolls to throw off the disease. The People’s regenerative capabilities make them immune to these effects, so the Pure use this Gift most often either as a warning by infecting those humans favored by a Forsaken pack, or as a means of appeasing disease-spirits for their favors."]}],fullCost:"1 Essence",dicePool:"Wisdom + Survival + Resolve versus Stamina + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The disease-spirits recoil at the werewolf’s fumbling. Social rolls made toward those spirits suffer a -2 penalty, as do Gift-activation rolls or rite-activation rolls made within 24 hours that involve such spirits."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Successes rolled tie, or the subject gets the most. The target displays no symptoms of disease."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The victim contracts the disease. The pathogen is akin to a virulent case of the flu, though the disease does not spread beyond the person touched. After one hour, the infected person begins showing symptoms and suffers a -1 to all rolls until she recovers, or passes away (a rarity). Each day, including the first, the target suffers one level of bashing damage. This damage does not naturally heal as normal bashing damage until the disease is beaten (although it can be healed magically). The target may make an additional Stamina + Resolve roll each day until she accumulates a number of successes equal to the Uratha’s initial roll to throw off the disease."]},{type:"paragraph",text:["The Uratha’s supernatural physiology makes them immune to this Gift. Other creatures that are immune to diseases, such as vampires, are likewise immune."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The disease causes lethal damage."]}]},{Rank:"•••",Name:"Fevered Visage",Description:"Successes rolled act as a negative modifier for all Skill and Combat rolls for a number of turns equal to the Primal Urge of the Uratha. The range of this attack is equal to the Gift user’s Primal Urge x2 yards.",Cost:"○",Book:"Blas 83",fullDescription:[{type:"paragraph",text:["Looking upon an Uratha with the Fevered Visage Gift is pain. The eyes of the Uratha become bloodshot and waves of heat seem to pass in front of his brow. When he fixes his gaze on his victim, the effect is transmitted to the target until he or she either fights off the supernatural fever or endures its consequences."]}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Purity - target’s Stamina",action:"Contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The disease- and pain-spirits that empower this Gift attack the Uratha foolish enough to dishonor them. The Uratha suffers a -2 pain modifier to all rolls for the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Gift does not function."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The victim feels a fever sweep over his brow and chill in the core of his body. The number of successes rolled acts as a negative modifier for all Skill and Combat rolls for a number of turns equal to the Primal Urge of the Uratha. The range of this attack is equal to the Gift user’s Primal Urge x2 yards."]},{type:"paragraph",text:["This can only affect a target that can meet the Uratha’s gaze. Anything that can conceal the Uratha’s face from the intended target may subtract from the Uratha’s roll. (See “Concealment,” ",{text:"World of Darkness",bold:!0},", p. 162.) The blind and the unliving are immune to the Gift’s effects."]}]},{Rank:"••••",Name:"Fevered Sending",Description:"Can observe victims dreams and manipulate dream events",Cost:"●○",Book:"Blas 83",fullDescription:[{type:"paragraph",text:["This power only works on sleeping victims. It allows the Uratha to enter into and tamper with the dreams of others. Due to the nature of dreams, the rite is actually very quick, though the dream may seem to have lasted much longer to its victim."]},{type:"paragraph",text:["The werewolf must be within one yard of the victim to attempt the Gift. During the time the Gift is active, the victim sweats, tosses and turns and lightly moans as if in the grips of a fever. The Uratha invoking the Gift can likewise take no other action."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Wits + Empathy + Honor versus Resolve + Primal Urge",action:"Instant and Contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The victim instantly wakes up, but the Uratha may remain trapped in a dream world that isn’t. He must make a Composure roll each round or be trapped in a Fugue state. One success is enough to free the Uratha, though he suffers a -1 to all Wits rolls for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Gift does not function."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," If the Uratha rolls more successes than his target, he appears within the victim’s dreamscape, much like a spirit in Twilight. With no effort, the Uratha may observe the dream and then depart — very useful if the target is a Cahalith. By expending more Essence, the Uratha can affect the dream by subtly changing events or rewriting the experience. The Storyteller must plot out the general events and characters of the dream. The Uratha can change one of the aspects (character, action or setting) per point of Essence spent, up to a number equal to his successes rolled."]},{type:"paragraph",text:["Exerting influence risks tipping the victim off to the Uratha’s manipulation. The Uratha must make a Disguise roll to hide his involvement (see the ",{text:"World of Darkness Rulebook",bold:!0},", p. 87). The Uratha’s control over the dreamscape gives him +2 to this roll, though some Uratha don’t care to hide their mastery of another’s dream."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No additional effect."]}]},{Rank:"•••••",Name:"Toxic Wrath",Description:"Toxic cloud, each success causes 1 point of lethal damage",Cost:"●○",Book:"Blas 84",fullDescription:[{type:"paragraph",text:["The most virulent forms of fever- and poison-spirits manifest in the breath of the Uratha who exhales a web-like cloud of putrescence. Any who contact the cloud must attempt to fight off the toxins therein."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Strength + Intimidation + Glory versus Stamina + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The disease-spirits recoil at the werewolf’s fumbling. No Gifts from this list may be used for 24 hours."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," A tie results, or the subject gets the most. The target displays no symptoms of disease."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Uratha breathes out a miasmic cloud with a diameter in yards equal to 2x Primal Urge. Those engulfed in the cloud who do not fight off its effects watch in horror as buboes, necrotic cysts and pox marks erupt on their skin. Each success causes a point of lethal damage. The cloud lasts for one turn."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The disease causes aggravated damage."]}]}]},{Name:"Firestick",Description:"",Cost:"",Book:"LodgS 59",Content:[],Ranks:[{Rank:"•",Name:"Yimidhirr’s Musket",Description:"Set flammable material on fire by pointing at it with a lit firestick.",Cost:"●",Book:"LodgS 59",fullDescription:[{type:"paragraph",text:["The Kooris met by Captain James Cook carried firestick “weapons” that Cook thought were muskets, and used fire to drive him back to his ship. Using this Gift, an Uratha can ignite fires almost anywhere with a common firestick. A lit firestick (Burri), a piece of wood or bark capable of ignition, is needed for the Gift to work, so that the Gaffling or even mote of Bushfire’s spirit can inhabit it. One or two brave werewolves have gotten this Gift to work using tobacco or pituri, but commercial cigarettes aren’t usually suitable. When the Uratha points the firestick and calls on Bushfire, the object at which the firestick is pointed will ignite, assuming that the object is flammable. (Humans don’t spontaneously combust, so this can’t be used to blow people up, unless they’re drenched in kerosene or something similar.) There is no limit on range, but the object must be clearly visible. Thus, beyond rifle range or thereabouts, this Gift is hard to use."]}],fullCost:"1 Essence per “shot”",dicePool:"Dexterity + Firearms + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," All fires on and around the Uratha’s person sputter out in pique. No more will ignite at her bidding that day."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The item indicated starts to burn. The fire will be normal: this Gift is deadly when a great deal of flammable material is about, but in a rainy city street, the fire is unlikely to last long enough to be a nuisance."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The object catches fire regardless of weather and wind, and will continue to burn unless some effort is made to douse it."]}]},{Rank:"••",Name:"Adder Smoke",Description:"Smoke fills immediate area, dealing 1 bashing damage per turn and -1 finesse rolls to non-pack members.",Cost:"●",Book:"LodgS 59",fullDescription:[{type:"paragraph",text:["Bandaiyan, which ",{text:"gubbas",italic:!0}," call Australia, is a land with more poisonous snakes than any other in the world. This Gift allows Uratha who use it to poison others with smoke, incapacitating or killing them. Adder Smoke requires a burning or smoldering object such as a firestick or candle."]}],fullCost:"1 Essence",dicePool:"Manipulation + Weaponry + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The user of the Gift chokes and strangles on the smoke, taking one bashing wound per turn until she can extinguish whatever is burning."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The fire goes out."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Smoke fills the immediate area, to a radius of two meters. The pack is unaffected, but anyone else within the smoke’s area chokes and coughs, taking one point of bashing damage per turn. In addition, anyone within the area (apart from the Gift-user and her pack) suffers one die to all Finesse-related rolls due to the obscuring nature of the smoke. The smoke continues to slowly fill the area until the fire is put out or until wind blows the smoke away. A wind of more than 10 mph will do this easily."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As above, but the penalty imposed by the smoke is increased to -2."]}]},{Rank:"•••",Name:"Smokestep",Description:"Walk on smoke or clouds.",Cost:"●",Book:"LodgS 60",fullDescription:[{type:"paragraph",text:["The perpetual burning of the Australian countryside by the local people caused the animals and plants to adapt to the presence of fire. This also meant that spirits such as Eucalyptus/Yaliwurru, Bushfire/Thurru and Spinifex became much more powerful than before. Wise ones, or wirringan, often spoke of “ascending” or “climbing” into the sky. Smoke is the obvious road. This Gift allows the Uratha to walk on smoke or clouds. There must be enough smoke to accommodate the feet of the Uratha’s current form, and it must be opaque smoke. A kitchen match won’t do."]}],fullCost:"1 Essence",dicePool:"Resolve + Athletics + Purity",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The smoke seems to hold together, but then fails to support the werewolf’s weight, likely after she’s already put her weight on it."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The smoke doesn’t bear the werewolf’s weight."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The user of the Gift can walk and run as normal on the smoke. If she reaches the end of the smoke plume or the edge of the cloud deck, she can’t go on. Wind can be a real problem."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Uratha can choose one other person to benefit from the Gift’s effects as long as the two remain in constant contact: hand-holding, tail in another’s mouth and so on."]}]},{Rank:"••••",Name:"Paths of the Ancestors",Description:"Smoke points towards a specified locus.",Cost:"●",Book:"LodgS 60",fullDescription:[{type:"paragraph",text:["The Paths of the Ancestors, the “songlines,” stretch across Bandiyan’s body, from the first places in the North to the far Bass Strait. Only one who knows the correct song can walk the songlines from one locus to another. The power that they contain is obvious, and well guarded: the songlines are very dangerous. This Gift allows a werewolf to seek the nearest Pathway by burning some sacred material, such as jarrah wood, and following the smoke. The Uratha must state to the spirits what exactly they seek: if the statement is imprecise, the goal found may not be the one intended. If the statement is too exact, then the goal may not be found at all. Simply saying that one wants to find the closest locus may lead to a great deal of trouble, as the locus might be a location where deadly monsters lurk."]},{type:"paragraph",text:["The Gift can work either in the mortal world or in the ",{text:"Hisil",italic:!0},". Note that a character may know the appropriate song for the songline where he is. If he knows it, and sings it, he gains a circumstance bonus of two dice to the roll."]}],fullCost:"1 Essence",dicePool:"Wits + Occult + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The smoke draws attention from hostile spirits."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The smoke points in no particular direction"]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The smoke points in the desired direction for up to one day per success. For obvious reasons, most werewolves with this Gift prefer to use it on a portable source of fire such as a firestick."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No additional effect."]}]},{Rank:"•••••",Name:"Wombat’s Curse",Description:"Curse target to remain in whatever form they currently occupy.",Cost:"●●●●●",Book:"LodgS 60",fullDescription:[{type:"paragraph",text:["Wombat, who is now a fat little burrowing plant-eater, was once handsome and tall. Long ago, he became fat by stealing food and goods from the Ancestors, and a wirringan, or clever one, cursed him with being unable to change his shape. This powerful curse, levied by blowing a handful of ash toward the target, freezes any being in the shape it currently occupies. An Uratha will remain in his current form, unable to change; a spirit will either remain in spirit form, or, if it’s materialized, won’t be able to disperse on its “death.” Hosts will be forced to keep whatever form they have made or stolen. Note that using this Gift inappropriately is a sin against Harmony 7. Given the massive Essence cost, using this Gift is also not done lightly."]}],fullCost:"5 Essence",dicePool:"Manipulation + Intimidation + Cunning - target’s Composure",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Enemies enter their most dangerous form and attack. Uratha at whom this is aimed will usually enter ",{text:"Kuruth",italic:!0}," at once."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The enemy is unable to change form for a number of days equal to the number of successes gained on the roll. Spirits that take lethal damage in excess of their Corpus will fall over “dead” instead of dispersing, Uratha cannot shapeshift and so on. If the Gift is used on a werewolf in Gauru form, the target will remain active until his time in Gauru would normally end, at which point he will collapse unconscious, still in Gauru. The victim will return to human form at the next sunrise, at which point he also awakens; the curse has no more effect on him at this point."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The enemy is frozen into her current form for an entire year."]}]}]},{Name:"Full Moon",Description:"",Cost:"",Book:"WtF 116",Content:[{type:"paragraph",text:"The Ralunim, the Lunes of the Full Moon Choir, expect adopted Forsaken to live up to and increase their Purity Renown, and to enforce the ideals for which it stands. The choir rewards the faithful with Gifts that display the unmistakable power of righteousness."},{type:"paragraph",text:"The following Gifts are available only to Rahu."}],Ranks:[{Rank:"•",Name:"Clarity",Description:"Increase initiative +5",Cost:"●",Book:"WtF 116",fullDescription:[{type:"paragraph",text:["The light of the full moon lends a peaceful insight into the dark of night, and the Ralunim can impart a similar sensitivity to a Rahu. But rather than cutting through literal darkness per se, this clarity cuts through the distracting haze that can cloud a warrior’s mind. Jarring himself mentally by touching the white-hot core of his soul, the werewolf burns away the fog of war and keeps his wits about him."]},{type:"paragraph",text:["By spending one Essence, the player increases his character’s Initiative modifier by five, greatly increasing the odds of seizing the critical first strike in any battle. The Storyteller may determine that some situations are inappropriate for this Gift (such as when the character is attacked by an invisible threat). If the power is used once combat is underway, the character’s new place in the Initiative order is applied in the next turn and in all subsequent turns for the remainder of the fight."]}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Attunement",Description:"Break opponent's defense (gives a penalty equal to Primal Urge to 1 target)",Cost:"○",Book:"WtF 116",fullDescription:[{type:"paragraph",text:["Violent conflict is ingrained deeply in every werewolf’s identity, and the Rahu auspice is the ultimate expression of that nature. Werewolves of the full moon thrive on combat, but even they must be careful not to let themselves get carried away. The Ralunim grant their chosen ones this Gift in the name of brutal efficiency. Using it, a werewolf can put an opponent down and end a fight quickly before it has a chance to provoke his rage."]},{type:"paragraph",text:["Coming into play once combat has begun, Attunement heightens a werewolf’s perceptions of his foe, making him aware of the subtlest telltale changes in expression and body posture. With this knowledge, he can move with his opponent and anticipate movements. In so doing, the user senses weaknesses in his opponent’s technique and can target them with unerring accuracy. After one full turn of combat with a foe, the werewolf using this Gift can ignore an amount of his opponent’s Defense modifier equal to half the user’s Primal Urge (rounded up) for the remainder of the scene. The Gift’s activation roll is made at the beginning of the user’s action in a turn, and if successful, the opponent’s Defense is reduced. If an opponent dodges, his Defense is reduced after being doubled. Therefore, a subject with Defense 2 gets Dodge 4. If the user of this Gift has Primal Urge 3, his opponent’s Dodge is reduced to 1. If the subject has the Brawling Dodge or Weaponry Dodge Merit (",{text:"World of Darkness Rulebook",bold:!0},", p. 110 and 114), Primal Urge is subtracted from the combined trait total. Attacks made in conjunction with this power don’t have to involve unarmed combat, even though Brawl is a part of the activation roll. Attacks can involve weapons (Weaponry), thrown attacks (Athletics) or even Firearms attacks made within close-combat distance."]},{type:"paragraph",text:["This Gift can be applied to only one opponent at a time. If the user wishes to apply it against another opponent in the same scene, the first use is cancelled by the second use. The first opponent’s Defense returns to normal."]},{type:"paragraph",text:["Only the Gift user enjoys an opponent’s reduced Defense. No other attackers gain this benefit."]}],fullCost:"1 Willpower",dicePool:"Wits + Brawl + Wisdom - opponent’s Resolve",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character misreads his opponent and gives away a weakness in his own technique. His Defense doesn’t apply to the opponent’s next attack."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character fails to find an obvious weakness in his opponent’s style."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character exploits a weakness and may ignore an amount of his opponent’s Defense equal to the Gift user’s Primal Urge dots for the remainder of the scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Add one to the Gift user’s Primal Urge for the purposes of this use."]}]},{Rank:"•••",Name:"Death Grip",Description:"Inflict horrific damage while in grapple (doubles bite damage)",Cost:"●",Book:"WtF 116",fullDescription:[{type:"paragraph",text:["The canine jaws and fangs of a Urhan-, Urshul- or Gauru-form werewolf are some of the most deadly weapons imaginable. Werewolf fighting styles take this power into account and can be adapted to lock a foe into close combat and enable a werewolf to bring his most vicious natural weaponry to bear. This Gift increases the power of a werewolf’s jaws dramatically."]},{type:"paragraph",text:["A werewolf in Gauru, Urshul or Urhan form can normally stage a bite attack without first initiating a grapple on a target (see p. 171). By use of this Gift ",{text:"and",italic:!0}," establishing a grapple on a target, however, a werewolf can inflict truly horrific harm. Once a hold is achieved and maintained, the character gains an additional six dice to rolls for overpowering maneuvers to bite the target are doubled. The victim’s ability to break the attacker’s hold is also diminished. The roll made for his next effort to break free or perform an overpowering maneuver of his own suffers a penalty equal to the last successes rolled for the werewolf. So, the victim in the previous example suffers a -3 penalty to break free or perform maneuvers of his own. A werewolf can use this Gift in only Urhan, Urshul or Gauru form. His jaws in Hishu and Dalu form are too small and imperfectly shaped to afford the proper purchase."]},{type:"paragraph",text:["See the ",{text:"World of Darkness Rulebook",bold:!0},", pp. 157-159, for rules on grappling."]}],fullCost:"1 Essence per bite attack",dicePool:"Strength + Brawl + Glory",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf wrenches his jaws in his enthusiasm to shed blood and inflicts a point of bashing damage upon himself."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf inflicts no damage at all upon his victim and does not adversely affect the victim’s efforts to break free or perform an overpowering maneuver of his own."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Damage is doubled and the victim suffers a penalty on his next effort to break free or perform a maneuver of his own."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The damage of the werewolf’s bite is doubled, and the shock automatically renders the victim immobile for his next action. All the victim can do is try to break free (no overpowering maneuvers of his own are possible), and he still suffers a penalty equal to the successes rolled in the bite. The werewolf need not actually maintain this immobilization. He can continue biting or performing other maneuvers."]}]},{Rank:"••••",Name:"Rage Armor",Description:"Gain armor (1 point per 2 success)",Cost:"●",Book:"WtF 117",fullDescription:[{type:"paragraph",text:["The natural resilience and rapid regeneration that the Forsaken have inherited makes werewolves daunting foes. Using this Gift, however, makes Full Moons even more fearsome than their brothers and sisters. With a blood-curdling howl to Luna, the werewolf tempers his flesh with the fire of his Rage and renders himself nigh indestructible for a short time. When he does so, his eyes glow the deep amber of the harvest moon, and a faint distortion makes the air around him waver as his inner fire burns close to the surface."]}],fullCost:"1 Essence",dicePool:"Stamina + Survival + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf mistakenly believes that he’s well protected, which makes him careless. Not only does he fail to gain the Armor, he loses his Defense for the first turn of combat."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf gains no Armor."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf gains a point of Armor for every two successes rolled, with remainders ignored. It protects against physical attacks and firearms equally, but not against silver. Attacks made with silver weapons or silver bullets ignore the effects of this Gift and still cause aggravated damage. The effect lasts for a number of turns equal to the character’s Primal Urge dots."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No special benefit other than a high Armor rating."]}]},{Rank:"•••••",Name:"Luna's Fury",Description:"Gain combat blessing from Luna (doubles defense and gives +2 to close combat)",Cost:"●/t",Book:"WtF 117",fullDescription:[{type:"paragraph",text:["A werewolf who Rages against his opponent is dangerous. A werewolf who loses himself in the heat of battle is even more fearsome. A werewolf who makes himself a vessel for Luna’s own fury, however, is truly a terror to behold. A shaft of pure white light lances down from the heavens to bathe the Forsaken in its radiance before the werewolf unleashes a whirlwind of destruction, his eyes, fangs and claws blazing with white fire."]}],fullCost:"1 Essence per turn",dicePool:"Dexterity + Empathy + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf receives no benefit, and instead loses his Defense modifier for the next turn of combat."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No benefit; no penalty."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Each success rolled keeps the Gift active for one turn, though the player must pay one point of Essence per turn as well. While the Gift is active, the werewolf receives the benefit of a dodge for purposes of protection, as well as the benefit of an all-out attack (see ",{text:"World of Darkness Rulebook",bold:!0},", pp. 156 and 157) for purposes of offense. That is, his Defense doubles against incoming close-combat attacks, ",{text:"and",italic:!0}," two dice are added to his own close-combat attacks. (Normally, dodging precludes all other actions in a turn, but this Gift allows attacks to be staged normally at the same time.) The werewolf can activate no other Gifts while this one is active."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Doubled Defense also applies against incoming Firearms attacks while the Gift is active."]}]}]},{Name:"Gibbous Moon",Description:"",Cost:"",Book:"Cahalith",Ranks:[{Rank:"•",Name:"Pack Awareness",Description:"Sense packmates' location and condition",Cost:"-",Book:"WtF 117",fullDescription:[{type:"paragraph",text:["When a pack goes into battle, its Rahu might lose himself in the fury of the fight, while the Irraka moves out to strike from the flanks, but the Cahalith must keep an eye on all her packmates. It’s her voice that sounds when a packmate is wounded, or that rallies members when they’re badly pressed. This Gift grants the Cahalith an intense sense of her pack’s welfare, so that she can make sure none are beyond the reach of her voice."]},{type:"paragraph",text:["When a werewolf invokes this Gift, she immediately gets a general sense of where her packmates are in relation to her, as well as a sense of their state of being. Allies might be “to the left about 30 yards” or “on the next floor of the building.” She also learns what form each packmate is in, as well as what general activity each is performing. Examples of the last include “fighting,” “waiting,” “moving,” “sleeping,” “fleeing,” “frenzying” or “having sex.” Finally, the Cahalith can tell when a packmate is suffering wound penalties or has fallen unconscious from wounds (which is different from simply being asleep for the purposes of this Gift)."]},{type:"paragraph",text:["All this knowledge comes to the werewolf subconsciously, without distracting her from whatever she’s doing at the moment. Packmates must be within a number of miles equal to the character’s Primal Urge for the awareness to apply. The effects of this Gift persist for one scene."]}],fullCost:"None",dicePool:"Wits + Empathy + Wisdom",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The awareness of her packmates’ situation overwhelms the Cahalith momentarily and proves distracting. Her actions incur a -1 penalty for one turn per packmate (not counting herself). She cannot invoke this Gift again until the penalty passes."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character gains no special awareness of her packmates."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character learns the listed information about her packmates."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," One pack member (not the character herself) regains a point of spent Willpower for knowing that his Cahalith is there to support him. The Cahalith’s player decides who gets this point."]}]},{Rank:"••",Name:"Resist Pain",Description:"Ignore wound penalties",Cost:"○",Book:"WtF 118",fullDescription:[{type:"paragraph",text:["Glory is the meat and drink of the Cahalunim, and few things are more glorious than a warrior who fights on despite grievous wounds. This Gift unleashes the raw passion of the Cahalith, filling her body with vigor such that normally crippling injuries do not deter her. Unfortunately, as the pain recedes, so does the Cahalith’s caution, and a glorious death might be her final act."]},{type:"paragraph",text:["When a werewolf activates this Gift, her awareness of the pain of her wounds recedes and ceases to impair her. As a result, she ignores the wound penalties that come from being badly injured, acting with a full dice pool until those last Health points are healed or she drops into blissful unconsciousness. The effects of this Gift persist for the remainder of the scene."]},{type:"paragraph",text:["A character with this Gift active is not threatened by Death Rage when injuries are imposed on her last three Health boxes. No roll to resist ",{text:"Kuruth",italic:!0}," is required because of those wounds. If the character is already in Death Rage, she still seeks to flee when injuries are marked in one of her last three Health boxes."]}],fullCost:"1 Willpower",dicePool:"Stamina + Survival + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character’s wound penalties increase by one for a single turn."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Wound penalties affect the character as normal."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Wound penalties do not affect the character, regardless of how badly hurt or near death she is."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success. Also, the character’s hardiness surprises enemies, granting a +1 bonus on the next attack roll made for her."]}]},{Rank:"•••",Name:"Rallying Cry",Description:"Grant willpower to packmate (each packmate regains a spent Willpower point)",Cost:"○",Book:"WtF 118",fullDescription:[{type:"paragraph",text:["By giving of herself and howling of past glories, a Cahalith can give her packmates hope even in their darkest hour. She channels the voices of the Cahalunim through her, lending their power to her words and inspiring packmates to greatness. The Cahalith stirs hearts with a tale (or howl or ballad or epic poem) of glory that’s thematically appropriate to some situation faced. This power cannot be used — successfully or not — on the same people more than once per day."]}],fullCost:"1 Willpower",dicePool:"Manipulation + Expression + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Cahalith shakes her packmates’ confidence and costs them each a Willpower point rather than awarding any. She loses a point as well, in addition to the one spent."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The message is strong, but it bears no supernatural inspiration."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Cahalith inspires her packmates to greatness. They each regain one spent Willpower point. A character’s Willpower cannot be raised above her total dots by this means. The Cahalith does not receive this bonus Willpower award herself, nor does she regain the Willpower point spent to activate the Gift."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Cahalith surprises herself with her own skill at inspiring her packmates, and their reactions motivate her in turn. She gains back the Willpower point spent to activate this Gift, and an additional one as well."]}]},{Rank:"••••",Name:"Unspoken Communication",Description:"Telepathic communication with packmates (+3 Initative, +1 to all rolls against enemies)",Cost:"●",Book:"WtF 118",fullDescription:[{type:"paragraph",text:["In the interests of greater communication, which leads to effective cooperation and glorious success, the Cahalunim grant Cahalith this Gift. With it, a Cahalith can keep packmates in constant contact, enabling them to act as one."]},{type:"paragraph",text:["Packmates within line of sight of the Cahalith can be joined in instantaneous mental communication for the rest of the scene. Allies need not necessarily see each other, they simply need to be seen by the Gift’s user. Packmates can “speak” mind to mind and hear each other perfectly clearly regardless of any ambient noise. Any speaker can communicate with one particular packmate of his choice, or with all of them simultaneously."]},{type:"paragraph",text:["Connected characters gain a +3 bonus to Initiative as they’re better able to coordinate their efforts. Connected characters also gain a +1 bonus to attack and use Gifts against enemies of the group as victims reel while trying to contend with combined and well-times assaults."]},{type:"paragraph",text:["The Cahalith can terminate the effect of this Gift at any point before the end of the scene, but doing so is an all-or-nothing proposition. She cannot selectively drop one packmate and keep others connected. She can, however, include a new packmate in the connection after the Gift is activated with the expenditure of an additional Essence point. If a packmate is within sight when the power is activated, and then moves to where he cannot be seen by the Cahalith, the link of communication is not severed."]},{type:"paragraph",text:["People who aren’t direct members of the Gift user’s pack cannot be included in this mental link. The power cannot be used to communicate across the Gauntlet."]}],fullCost:"1 Essence",dicePool:"Intelligence + Socialize + Purity",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The awareness of packmates’ thoughts overwhelms the Cahalith and proves distracting. Her actions incur a -1 penalty for one turn per packmate included (not counting herself). She cannot invoke this Gift again until the penalty passes."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," None of the packmates receives any extra awareness."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The packmates are connected mentally to each other and may “speak” mind to mind."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Connected characters each regain a point of spent Willpower for sharing a powerful pack bond. The Gift user doesn’t gain this bonus. Only one Willpower point can be regained by a character per day by this means."]}]},{Rank:"•••••",Name:"Call of Glory",Description:"Heal packmates (1 Health per success to packmates, from right to left. May heal even aggravated damage)",Cost:"○",Book:"WtF 119",fullDescription:[{type:"paragraph",text:["This Gift is similar to Rallying Cry in that it invokes the Cahalunim’s power to inspire a Cahalith’s packmates. Rather than projecting power through a Cahalith, though, the Lunes of the gibbous moon literally cry out in eldritch accompaniment as the Cahalith sings a battle hymn or howls a paean to Luna. When the werewolves of the Cahalith’s pack hear such a joyful noise, they can claw their way back from the gates of Hell."]},{type:"paragraph",text:["Each success achieved on the activation roll heals one point of damage for each of the Cahalith’s packmates (but not the Cahalith herself). These points are healed from right to left on characters’ Health charts. That is, if three successes are rolled, each character heals three points of damage. The type of damage healed doesn’t matter, whether bashing, lethal or aggravated. The Gift simply eliminates one wound per success from right to left on a character sheet."]},{type:"paragraph",text:["A packmate must hear the Cahalith’s howl directly for this power to apply. It doesn’t work over the phone, for example. All beneficiaries must also venerate the same pack totem. A character can benefit from the healing provided by Call of Glory only once per day."]}],fullCost:"1 Willpower",dicePool:"Presence + Expression + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Cahalith’s efforts offend the Lunes she calls on for help, drawing a backlash down on her entire pack. Rather than singing along, the Lunes screech in contempt and distract the Cahalith and her packmates, imposing a -2 penalty to all rolls for the next turn."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Cahalith puts on a good show, but not good enough."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Lunes join in the Cahalith’s effort and packmates are healed one Health point per success rolled."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Lunes are so impressed by the Cahalith that they include her in the healing."]}]}]},{Name:"Glory",Description:"",Cost:"",Book:"SotM 142",Content:[{type:"paragraph",text:"Without Glory, there would be no Cahalunim, and so it follows, there would be no Cahalith. Luna’s brilliant light falls strongest on the Cahalith who has learned not just how to follow her precepts, but how to follow them in the most memorable fashion possible. Of course, while a brave Cahalith seeks to live each day like it should be remembered for all time, a wise Cahalith leans to temper himself with the talent and knowledge to perform in spectacular ways."},{type:"paragraph",text:"Glory Gifts require that the Cahalith have Glory Renown equal to the Gift being learned, even if the werewolf would normally be able to learn the Gift without raising Glory."},{type:"paragraph",text:"Only Cahalith can learn these Gifts, taught by the members of the Cahalunim choir."}],Ranks:[{Rank:"•",Name:"Relentlessness",Description:"Add Glory as Temporary Health",Cost:"●",Book:"SotM 142",fullDescription:[{type:"paragraph",text:["Rare is the culture that does not have stories of great heroes who fought their enemies for days and days at a time. History and myth glorify the warrior who keeps on long after he should be dead, from the gladiator bleeding from the belly who fights on regardless of his inevitable death, to the gunslinging desperado who manages to shrug off bullets because he’s got ",{text:"revenge",italic:!0}," to satisfy. With this Gift, the Cahalith on the path to Glory can shrug off even the most determined attempts to make her sick or poison her. What’s more, she laughs in the face of danger thanks to her tenacity."]},{type:"paragraph",text:["For the remainder of the scene, the character adds his Glory score to his Health dots. See “Temporary Health Dots” in the ",{text:"World of Darkness Rulebook",bold:!0},", p. 173."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Instant",rollResults:[]},{Rank:"••",Name:"The Lesson Learned",Description:"After a loosing encounter, can gain Willpower equal to highest glory next time they encounter that enemy",Cost:"●",Book:"SotM 142",fullDescription:[{type:"paragraph",text:["It is not enough to remember the stories of the past or make a name for the future. A Cahalith performing in his role for the pack must be able to make use of his experience in a way that benefits all members of the pack. With this Gift, the Cahalith uses the hard lessons he and his pack have leaned and applies them to future confrontations, pointing out where the pack went wrong in such a way that they can do better next time."]},{type:"paragraph",text:["After a scene where a Cahalith or her pack has wounds while her enemy has gotten away, the Cahalith can activate this Gift. Activation requires the Cahalith to tell her pack a story about the failed encounter. The next time the pack encounters those opponents, they gain an advantage due to the lessons learned from the failure."]}],fullCost:"1 Essence",dicePool:"Intelligence + Expression + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Cahalith’s story is particularly uninspiring or teaches the wrong lessons. During the next encounter with the named opponents, the opponents gain a +2 bonus to their first actions against the pack, as the pack is left with the sense that they cannot win easily."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The story fails to inspire the pack. They gain no bonus."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The story is rousing and educational. During the next scene where the pack encounters the story’s opponents, each pack member gains temporary Willpower equal to the highest Glory rating in the pack. This gain ",{text:"can",italic:!0}," exceed her maximum. The pack must use these points on rolls against the opponents in question, and are lost if not used by the end of the scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The story is something of an epic. In addition to the effects of a success, the pack members each enjoy +1 to Defense against the named opponents for the next encounter, and cannot be ambushed by their foes."]}]},{Rank:"•••",Name:"Harvest of Glorious Fury",Description:"Everytime the character kills someone in Kuruth, gains cumulative boneses",Cost:"●",Book:"SotM 142",fullDescription:[{type:"paragraph",text:["What greater or more dramatic display of the People’s Glory is there than the Gauru form? As powerful, potent, and ultimately memorable as it is to take the war form, giving in to Death Rage is perilous. The Cahalith who make it to any great age or great understanding appreciate the need to balance purpose with focus and so the Cahalunim teach this Gift. With it, a Cahalith can take the Gauru form and utilize it as a war machine that brings him blood-soaked Glory."]},{type:"paragraph",text:["This Gift must be activated the moment the character enters Kuruth. Any time the character kills another living creature in the Gauru form of Death Rage, he gains a series of cumulative bonuses that build with each of her slain targets. He gains:"]},{type:"list",items:[["+1 to attack rolls"],["One point of Willpower (though not past the character’s maximum pool)"],["+1 to Defense"]]},{type:"paragraph",text:["So, if the character kills three individuals — be they guard dogs, mortal thugs, or other werewolves — he now has +3 to attack rolls, +3 to his Defense, and three new points of Willpower. What is reaped, is sown. The bonuses to attack and defend disappear after the character leaves Kuruth. The Willpower points remain, however, until spent or otherwise lost."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"••••",Name:"Glorious Empowerment",Description:"When the Cahalith spends Willpower, he adds his Glory instead of +3 or +2",Cost:"●",Book:"SotM 143",fullDescription:[{type:"paragraph",text:["A Cahalith need not be a power unto herself. Separate even from the comfort and confidence that comes of being a pack animal, a vetted Cahalith has a lifetime of accomplishments to draw upon. Whereas Uratha of other moons may face new challenges with uncertainty, a great Gibbous can look at her past successes and her future potential to draw on Glory itself to pull her through events she might not otherwise be able to handle."]},{type:"paragraph",text:["Whenever the Cahalith spends Willpower, she adds her Glory score to rolls instead of +3. In the case of resisted actions, it also adds Glory to resistance traits instead of the normal +2."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"The Legend Lives On",Description:"Tells a story of a fallen comrade, and can gain an XP discount on a skill or gift that comrade owned",Cost:"●●●",Book:"SotM 143",fullDescription:[{type:"paragraph",text:["When the Cahalith witnesses death, she can turn her eyes or she can make a story. During a scene where she sees another Uratha die, the Cahalith can activate this Gift and develops a story to tell in honor of the fallen. The death is not in vain, as the Cahalith takes the lesson, learns from it, and inspires others with it."]},{type:"paragraph",text:["When the Cahalith tells the story, she chooses one element of the tale to emphasize. Upon investing a bit of her soul into the story, she learns a single trait involved in the story. This can be a Skill or a Gift path possessed by the fallen. Afterwards, her story helps inspire others to learn the same edge."]},{type:"paragraph",text:["This Gift only works once per witnessed death, and only on fallen Uratha."]}],fullCost:"3 Essence",dicePool:"Intelligence + Expression + Glory, with a -1 penalty per dot of the trait the dying target possesses that the Cahalith wishes to acquire.",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The story is a disgrace to the memory of the fallen. Not only does the trait not manifest in the Cahalith, but for the next seven nights she is besieged by nightmares of the fallen Uratha. She gains no Willpower upon awakening during this time."]},{type:"line",label:"Failure",text:["With failure, the Cahalith’s story is not magnificent enough to transfer the trait."]},{type:"line",label:"Success",text:["The story is sufficiently moving. When she tells the story of the fallen, listeners subtract from the experience cost one point per success when trying to learn it themselves. This will not reduce the cost of a trait below half its original cost (rounded up), and the character can make only one attempt to help others acquire this knowledge. In addition, the character herself can automatically buy points in the chosen Skill or Gift path at half the normal experience cost. She can only tell the story of the fallen once per game session (i.e. “chapter”)."]},{type:"line",label:"Exceptional Success",text:["With exceptional success, the Cahalith’s story is so inspired that any time she tells it to help others, she gains one experience point herself."]}]}]},{Name:"Grotto",Description:"",Cost:"",Book:"LodgF 129",Content:[{type:"paragraph",text:"These Gifts are the blessings of those that tunnel and burrow, and assist werewolves in navigating the world underneath. These Gifts are taught by the spirits of burrowing things such as worms or moles. These Gifts can be learned by werewolves outside the Lodge of the Grotto, though only lodge members treat them as affinity Gifts."}],Ranks:[{Rank:"•",Name:"Ratsquirm",Description:"Renders the user's bones flexible, so they may move through tight spaces.",Cost:"-",Book:"LodgF 129",fullDescription:[{type:"paragraph",text:["If a werewolf with this Gift can get her head through an opening, she can wriggle the rest of her body through as well. The Ratsquirm Gift allows a werewolf to pop loose joints and temporarily collapse her ribcage in order to squeeze through spaces no other full-grown werewolf could pass."]}],fullCost:"None",dicePool:"Dexterity + Larceny + Cunning",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift fails to activate; the werewolf cannot attempt to use this Gift again for the remainder of the scene."]},{type:"line",label:"Failure",text:["The Gift fails to activate."]},{type:"line",label:"Success",text:["The Gift activates successfully. The werewolf is able to squirm through an opening no smaller than 10 inches in diameter as a standard action. If the werewolf has used this Gift as preparation to escape a grapple, she gains +2 dice to her escape attempt. This Gift may also allow a werewolf to escape handcuffs or rope or chain bonds with ease."]},{type:"line",label:"Exceptional Success",text:["The Gift activates particularly successfully. The werewolf may squeeze through an opening no smaller than eight inches in diameter as above, or gain a +4 bonus to her next roll to escape a grapple."]}]},{Rank:"••",Name:"Knocktale",Description:"Send an encoded message through pipes or stones, which may be understood by anyone who has this gift.",Cost:"-",Book:"LodgF 130",fullDescription:[{type:"paragraph",text:["Those who would hunt the Burrowers in their own tunnels find the hunting an intimidating experience. As the hunters press deeper into the darkness, they hear short bursts of staccato rapping and tapping, echoing around them like alien birdcalls. By means of the Knocktalk Gift, a werewolf can send coded messages to those around her by tapping on stone or metal pipes, thus enabling her and her kin to coordinate devastating attacks against intruders."]}],fullCost:"None",dicePool:"Wits + Expression + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift fails, and the werewolf is briefly confused as to why. For the remainder of the scene, she may not attempt the Gift again, and must make a roll to understand another werewolf’s knocktalk as if she did not know the Gift herself."]},{type:"line",label:"Failure",text:["The Gift fails; the tapping travels no further than the sound would without physical means, and no message is encoded."]},{type:"line",label:"Success",text:["The werewolf encodes a brief message of up to one word per success. The knocking or tapping can be heard for up to 100 yards along the tunnels per success. Any listener who knows the Knocktalk Gift automatically understands the message; others must make a Wits + Occult roll to understand the nature of the message. If the listener does not belong to the Lodge of the Grotto, the Wits + Occult roll is made at a -3 penalty."]},{type:"line",label:"Exceptional Success",text:["No additional effect."]}]},{Rank:"•••",Name:"Tunnelscent",Description:"Significantly enhances non-sight senses for the purposes of navigating underground.",Cost:"-",Book:"LodgF 130",fullDescription:[{type:"paragraph",text:["Most werewolves are able to adapt to subterranean darkness well enough, through a mix of arranging their own human-made light sources and shifting into forms with lupine senses. The truly dangerous, though, need neither of these things. The werewolf who has learned this Gift benefits from dramatically increased sense acuity while underground; even in pitch darkness she is able to navigate her surroundings by means of hearing and especially scent as accurately as if she were in broad daylight. She may fight without being subject to any of the normal penalties for fighting blind (see the World of Darkness Rulebook, p. 166)."]},{type:"paragraph",text:["This Gift functions only while the werewolf is underground; the Gift doesn’t work if the werewolf is above ground, whether in an enclosed area or under open sky. Sudden bright lights, loud noises or powerful odors will disorient a werewolf under the effects of this Gift. If exposed to such extreme stimuli, she must make a reflexive Wits + Survival roll to resist; such stimuli cause the werewolf to lose this Gift’s effects and take a -2 penalty to appropriate Perception rolls for five turns minus one turn per success on the Wits + Survival roll."]}],fullCost:"None",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"••••",Name:"Stoneburrow",Description:"Grows long mole-like claws that can shred through stone or concrete, but is of only limited combat use.",Cost:"●",Book:"LodgF 130",fullDescription:[{type:"paragraph",text:["Some werewolves use Elemental Gifts or mundane digging equipment to carve out underground dens. This Gift makes the process even easier. A werewolf in Dalu or Urshul form can use this Gift to grow long mole-like claws that tear easily through stone or concrete. The claws are unwieldy and not the finest for combat, but are virtually unbreakable."]}],fullCost:"1 Essence",dicePool:"Stamina + Athletics + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf’s nails become brittle and split painfully. She may not make any claw attacks for the duration of the scene."]},{type:"line",label:"Failure",text:["No change."]},{type:"line",label:"Success",text:["The werewolf’s claws become capable of digging through stone or concrete. She may excavate up to one cubic foot of stone or concrete per turn. She also gains a +1 damage claw attack if she did not have one previously (if in Dalu form), or may add +1 damage to existing claw attacks. The Gift’s effects last for the duration of the scene, or until the werewolf chooses to end the effects."]},{type:"line",label:"Exceptional Success",text:["The werewolf may excavate up to two cubic feet of stone or concrete per turn."]}]},{Rank:"•••••",Name:"Tunnelwrath",Description:"Triggers a tunnel to strike out at a target, causing significant damage.",Cost:"●●",Book:"LodgF 130",fullDescription:[{type:"paragraph",text:["This Gift calls on the wrath of the burrowed earth to strike down the werewolf’s enemies. Tunnels may crack and spray rocks or steam pipes may burst as the tunnel lashes out at intruders."]}],fullCost:"2 Essence",dicePool:"Intelligence + Crafts + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The tunnel rebels against the werewolf rather than her foes. The Gift user immediately takes one point of lethal damage from an appropriate source."]},{type:"line",label:"Failure",text:["The tunnel refuses to answer the werewolf’s call."]},{type:"line",label:"Success",text:["The tunnel strikes at the werewolf’s foes. The werewolf may distribute two points of lethal damage per success against anyone within 100 yards who shares the same tunnel as she. This takes the form of environmental damage, and can be used in either human-made or natural subterranean passages. For instance, if the user gained three successes in a mineshaft, she could choose to apply all six points of damage against one enemy (perhaps by causing a minor cave-in) or divide them among her five attackers, inflicting two points of lethal damage to one werewolf of her choice and one point of lethal damage to each of the five others. In a subway tunnel, the damage could take the form of an electrical short from the third rail, and so on."]},{type:"line",label:"Exceptional Success",text:["No additional effect apart from the large amounts of damage done."]}]}]},{Name:"Halcyon",Description:"",Cost:"",Book:"BotW 84",Content:[{type:"paragraph",text:["These weather-controlling Gifts call on the spirits of sky and wind to show mercy, appeasing them to quiet a storm or quell heat. Designed to keep the weather calm, placid, safe and, moreover, appropriate to wilderness travelers and survivalists, these Gifts are taught by sky-spirits or spirits that represent smaller species of birds. The Storm Lords have affinity with this Gift list, but few are interested in its ways — most ",{text:"Iminir",italic:!0}," feel a certain level of contempt for those who would seek to still the wind instead of standing proud amid the gales."]}],Ranks:[{Rank:"•",Name:"Scent Of The Wind",Description:"Know the weather in an area radius 5 miles per success, allowing the werewolf to predict the weather half an hour in advance.",Cost:"-",Book:"BotW 84",fullDescription:[{type:"paragraph",text:["Letting the air fill his nostrils, the werewolf tastes the condition of the local climate. He learns what the weather is like for miles around him and can safely predict what the weather will be in a short time."]}],fullCost:"None",dicePool:"Perception + Survival + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf develops an incorrect picture of the local weather. Attempts to divine the weather automatically fail until one full day has passed."]},{type:"line",label:"Failure",text:["The weather is unknowable."]},{type:"line",label:"Success",text:["The werewolf knows the weather of the region around him. Within a radius of five miles per success, he knows if it is sunny, cloudy, raining, hailing, assailed by fierce storms, beset by tornadoes or any other sort of weather. If there is a wind blowing toward him, double the distance for that direction. He can predict the weather that will affect him directly in advance, by one half-hour per success."]},{type:"line",label:"Exceptional Success",text:["Nothing, apart from increased distance."]}]},{Rank:"••",Name:"Cloud Cover",Description:"Spirits drag clouds overhead. If no clouds are found within 20 miles per point of Primal Urge, the essence cost is wasted.",Cost:"●",Book:"BotW 84",fullDescription:[{type:"paragraph",text:["The local spirits of wind communicate with their more-distant brethren to find clouds within several miles, sometimes beyond the visible horizon. If the spirits succeed, they collaborate to blow the clouds over the werewolf’s current location. This can serve simply as shadow from the sun or as protection from detection by high-flying planes and satellites."]},{type:"paragraph",text:["Cloud Cover remains as long as it normally would in prevailing wind conditions, though the werewolf can use the Gift repeatedly to call the clouds back. The spirits only look so far for the werewolf’s clouds, however: if there are no clouds whatsoever within 20 miles per dot of Primal Urge, the spirits find none and the Gift is wasted. If there are too few clouds to effectively cover the area surrounding the werewolf, the spirits bring what there is, and, if there are many clouds, the spirits bring only what is necessary. Use of this Gift can sometimes increase the chance of inclement weather in the region."]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Instant",rollResults:[]},{Rank:"•••",Name:"Raising Doldrums",Description:"Halves wind speed within one mile, stops winds within half a mile. Stops tornadoes within the area.",Cost:"●",Book:"BotW 84",fullDescription:[{type:"paragraph",text:["No wind can continue moving when one of the Forsaken levels this Gift upon the local weather. All local winds cease, abruptly and completely; the region becomes a zone of dead air. This Gift stops tornadoes completely and takes much of the sting out of rainstorms or snowstorms. Chill due to wind disappears completely."]}],fullCost:"1 Essence",dicePool:"Resolve + Survival",action:"Extended (25 successes; one turn passes per roll)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The wind-spirits are incited to a frenzy instead of lulled into sleep. Local winds increase in strength immensely, becoming half again as fast as they were before."]},{type:"line",label:"Failure",text:["The winds do not change."]},{type:"line",label:"Success",text:["All wind within one mile of the werewolf immediately slows by half, and all winds within one half-mile stop dead. Winds that blow in from outside the mile boundary begin to slow down, and wind that breezes into the half-mile boundary also stops. Areas downwind of the affected region are treated, for the duration, as though they were on the leeward side of a large, immobile object; they are sheltered from the wind. This condition continues as long as the werewolf concentrates on the effect. When the werewolf stops focusing on holding the wind steady, new winds that enter the area cease to be affected, and the local winds slowly begin to move again. Some strong localized winds, such as tornadoes, never regain their old momentum. It takes one half-hour per dot of Primal Urge for the effect to completely dissipate; until then, the wind will be sluggish within what was originally the null zone."]},{type:"line",label:"Exceptional Success",text:["Nothing, apart from gaining more successes."]}]},{Rank:"••••",Name:"Lightning Ward",Description:"For five hours, no lighting can strike withing 10 yards per Primal Urge of the targeted area.",Cost:"●",Book:"BotW 84",fullDescription:[{type:"paragraph",text:["The werewolf asks the spirits to provide respite from the danger of lightning strikes during a storm. Simply put, this Gift prevents lightning from striking anywhere within several dozen yards. Lightning Ward can also be learned as a Warding Gift from the spirits that teach those."]},{type:"paragraph",text:["For five hours, the spirits of wind, storm and lightning bend the strikes away from a point chosen by the werewolf. No lightning will strike any closer to that point than 10 yards per dot of Primal Urge."]}],fullCost:"1 Essence",dicePool:"None",action:"Instant",rollResults:[]},{Rank:"•••••",Name:"The Will Of The Winds",Description:"Causes all supernatural weather effects within one mile per Primal Urge to cease.",Cost:"●",Book:"BotW 85",fullDescription:[{type:"paragraph",text:["There are many times and many ways that the weather may be tampered with. This Gift empowers the local spirits to take charge of the winds and precipitation and restore them to the way they were before any supernatural powers came into play. The Will of the Winds causes all supernatural weather effects cease, and whatever weather pattern would have existed if not for their interference is put up in their place. Any being that has placed a supernatural weather effect on the region affected by this Gift makes a contested roll against the werewolf’s single roll; only the highest of his opponent’s rolls is considered."]}],fullCost:"1 Essence",dicePool:"Presence + Survival + Purity versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The weather-spirits rebuke the werewolf; he is unable to use Weather Gifts for one full day."]},{type:"line",label:"Failure",text:["If the user’s roll fails or the victim’s contested roll nets as many or more successes than the user’s, nothing changes. All present supernatural effects remain."]},{type:"line",label:"Success",text:["The most successes are rolled for the Gift user. All supernatural weather effects within one mile per point of Primal Urge cease immediately, replaced with the weather that would have been there if no one had interfered."]},{type:"line",label:"Exceptional Success",text:["The most successes are rolled for the Gift user, and five or more are achieved. The weather cannot be affected by supernatural means for a period of one hour per point of Primal Urge."]}]}]},{Name:"Half Moon",Description:"",Cost:"",Book:"WtF 120",Content:[{type:"paragraph",text:"The patrons of the Elodoth auspice, the Lunes of the Elunim Choir, expect werewolves to live in harmony and with honor. Their Gifts encourage honorable dealings among the People and between the worlds of flesh and spirit. While the Forsaken as a whole dedicate themselves to protecting the physical world from the ravages of the Shadow, Elodoth are expected to recognize spirits’ right to exist. Members of the auspice do what must be done to forestall spirit depredations, but they must recognize that the same cannot be inflicted upon the spirit world in return. Therefore, using these Gifts for abusive, treacherous or self-serving ends is a good way to incur the wrath of the Elunim."},{type:"paragraph",text:"The following Gifts are available only to Elodoth."}],Ranks:[{Rank:"•",Name:"Scent Beneath the Surface",Description:"Detect lies",Cost:"○",Book:"WtF 120",fullDescription:[{type:"paragraph",text:["Part of upholding the precepts of virtue, as Elodoth must, is being able to recognize dishonorable behavior even when it is disguised. The Elunim grant their chosen a decided advantage in such matters, though they still expect werewolves to do some of the work on their own."]},{type:"paragraph",text:["After paying close attention to someone for a single turn, the character gains a keen insight into not only what that person’s words and nonverbal behavior show, but also what his heart conceals. Unless the subject uses some supernatural means to hide his emotions and intent, the Elodoth can immediately tell whether he’s lying outright, lying by omission, speaking the truth in a deliberately misleading way or is intentionally evasive. The Elodoth can also piece together a general impression of the subject’s emotional state, regardless of how well the subject acts in order to conceal it."]},{type:"paragraph",text:["This Gift doesn’t reveal the whole truth behind a subject’s lies, but a clever Elodoth can usually deduce it from context. The Gift doesn’t act like sonar, vigilantly seeking out all forms of deception and alerting the werewolf to them. It applies to only one subject at a time and to intentional forms of expressed deception that are directed at the Elodoth specifically. Disguising oneself to look like an Elodoth’s father doesn’t automatically alert him to the deception. Calling him, “My son!” and generally acting like his father reveals the deception."]},{type:"paragraph",text:["Such awareness persists for the remainder of the scene."]}],fullCost:"1 Willpower",dicePool:"Wits + Empathy + Purity versus deceiver’s Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is convinced that what the speaker states is true. The Storyteller may make activation rolls on players’ behalf in case such a result could occur."]},{type:"line",label:"Failure",text:["An equal number or the most successes are rolled for the subject. The werewolf is on his own. He must rely on intuition and common sense."]},{type:"line",label:"Success",text:["The most successes are rolled for the Elodoth. He senses the presence or lack of deception in a subject’s actions and words, and deduces the subject’s general emotional state as it relates to the matter at hand."]},{type:"line",label:"Exceptional Success",text:["The most successes — five or more — are rolled for the Elodoth. If the subject is lying, he becomes so painfully aware that the Elodoth can tell that his veneer of confidence cracks and he gives away a specific clue about the truth he hides."]}]},{Rank:"••",Name:"Snarl of Command",Description:"Force target to tell the truth",Cost:"○",Book:"WtF 120",fullDescription:[{type:"paragraph",text:["Sometimes it’s enough just to know that someone is lying or holding something back. If the subject has any valor at all, simply being caught in a lie is enough to shame him into admitting the truth. When time is an issue, however, or when the subject of an inquiry clearly has no virtue, an Elodoth can rely on this Gift to cut to the chase."]},{type:"paragraph",text:["With an ugly snarl and a few harsh words, the Elodoth commands a subject to reveal the simple truth behind a topic of contention, and the subject is compelled to comply. Doing so usually entails answering a single question truthfully, but the subject can also be made to remove a disguise or reveal his magically concealed true form (provided the magical means of concealment is under his control). A subject cannot reveal a truth of which he is unaware, and this Gift cannot be used to simply issue random commands for a subject to follow. It works to reveal only the truth behind a particular deception or to force one true answer from a liar’s mouth."]},{type:"paragraph",text:["An Elodoth doesn’t have to use Scent Beneath the Surface before using this Gift, but doing so is a good idea. Using this Gift and contemptuously demanding that someone come clean when he’s actually telling the truth is shameful and can provoke violence."]},{type:"paragraph",text:["Snarl of Command can be used on a subject, whether successfully or not, only once per day. Werewolf and subject must be in face-to-face contact with one another."]}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Cunning versus subject’s Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character’s attempt to cow the subject fails so miserably that he cannot use the Gift against that subject again for 24 hours."]},{type:"line",label:"Failure",text:["An equal number or the most successes are rolled for the subject. He stubbornly refuses to reveal the truth."]},{type:"line",label:"Success",text:["The most successes are rolled for the werewolf. The subject grudgingly does as commanded but offers no more without further coercion."]},{type:"line",label:"Exceptional Success",text:["The most successes — five or more — are rolled for the werewolf. The subject offers complete information about the truth as best as he understands it, even providing details the Elodoth might not have guessed."]}]},{Rank:"•••",Name:"Aura of Truce",Description:"Stop hostility when not in combat (everyone willing to attack must spend 1 Willpower point)",Cost:"●",Book:"WtF 121",fullDescription:[{type:"paragraph",text:["Most Elodoth don’t need to turn to Gifts to fulfill the role of arbitrator, but sometimes speed is of the essence or matters are particularly delicate. When the Elodoth uses this power, a subtle half-moon halo appears in the air behind her, bathing everyone present in calming, soothing light. While it shines, tension dissipates and cool heads have a chance to prevail."]},{type:"paragraph",text:["This Gift lasts for one scene, and flaring tempers subside while it is in use. Opposing parties may disagree and voices may even be raised in anger, but the power of the Gift is such that outright hostilities are harder to perform than normal. In order to commit a violent act — be it an attack, an attempt to damage someone else’s property or an attempt to use a Gift against an unwilling subject — a Willpower point must be spent reflexively for the intended perpetrator. That participant has free reign thereafter. His aggressive actions do not necessarily discontinue the effect for everyone else, but if the Elodoth cannot get the malcontent under control she is wise to absolve everyone. If the character using the Gift attacks anyone under its influence, the power terminates automatically."]},{type:"paragraph",text:["The user may choose to terminate the Gift before the end of the scene, but she cannot do so selectively; the Gift ends with regard to all participants or to none. Those affected must be able to see and hear the user directly, and she must be able to do the same."]},{type:"paragraph",text:["This Gift works only ",{text:"before",italic:!0}," violence has broken out. Once a fight is underway, the power is useless on combatants."]}],fullCost:"1 Essence",dicePool:"Manipulation + Persuasion + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["There is little hope for a peaceful resolution to the proceedings. The Elodoth manages to offend all parties, and she cannot use this Gift on them again until the following moonrise."]},{type:"line",label:"Failure",text:["The Elodoth has only her wits and her charm to rely on, but she doesn’t start off on the wrong foot automatically."]},{type:"line",label:"Success",text:["The character suffuses the area with an aura of calm."]},{type:"line",label:"Exceptional Success",text:["Participants under the Gift’s effects must spend the requisite Willpower for every ",{text:"turn",italic:!0}," in which they try to act with hostility, rather than being able to break the spell with a single expenditure."]}]},{Rank:"••••",Name:"Fuel Rage",Description:"Increase Gauru duration (1 turn per success)",Cost:"●",Book:"WtF 121",fullDescription:[{type:"paragraph",text:["A werewolf can remain in the deadly Gauru form for only so long, based on his Stamina + Primal Urge. When that time is up, he loses the ability to maintain the delicate balance between flesh and spirit. The Elodoth, touched by duality, can learn a greater facility with maintaining that balance."]},{type:"paragraph",text:["Using this Gift before assuming Gauru form, the Elodoth increases the number of turns in which he can remain in Gauru form. The Gift must be performed in the turn immediately prior to that in which the character changes forms, or it can be used in the same turn if the change to Gauru occurs reflexively. (Just be sure that Essence spent in a single turn doesn’t exceed the limit set by the character’s Primal Urge — see p. 76.) If the form change doesn’t occur in the character’s same or next turn, the Essence spent on the Gift is lost and no special benefits are gained."]},{type:"paragraph",text:["Time spent in Gauru increases by a number of turns equal to the number of successes achieved on a Stamina + Occult + Purity roll. These extra turns begin after the number of turns based on the werewolf’s Stamina + Primal Urge have elapsed. A werewolf whose time in Gauru has been extended can still change out of that form at will. He’s not forced to remain in it, unless Death Rage is invoked (see p. 173). The power has no effect on a user in the Shadow. This power does not influence taking forms other than Gauru. Nor can it be applied successfully more than once per scene."]}],fullCost:"1 Essence",dicePool:"Stamina + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift interferes with the character’s effort to assume Gauru form, and he cannot do so for the remainder of the scene unless Death Rage is provoked in him."]},{type:"line",label:"Failure",text:["The Gift has no effect on the subject."]},{type:"line",label:"Success",text:["The Gift increases the user’s duration in Gauru form for one turn per success."]},{type:"line",label:"Exceptional Success",text:["The Gift not only has the intended effect, but it adds one extra turn."]}]},{Rank:"•••••",Name:"Bind or Sunder",Description:"Alter other's Gauru duration (1 turn per success)",Cost:"●",Book:"WtF 121",fullDescription:[{type:"paragraph",text:["Like the Fuel Rage Gift, this power influences time spent in Gauru form. Unlike that Gift, however, this one is used on other werewolves to extend or reduce their time spent in the war form."]},{type:"paragraph",text:["Using this Gift, the Elodoth can increase the number of turns that a werewolf of his choice remains in Gauru form. With the expenditure of one Essence, he can increase the number of turns the subject remains in Gauru by the number of successes achieved on a Stamina + Occult + Purity roll. These extra turns begin after the number of turns based on the werewolf’s Stamina + Primal Urge have elapsed. A werewolf whose time in Gauru has been extended can still change out of that form at will. He’s not forced to remain in that form, unless Death Rage is invoked (see p. 173)."]},{type:"paragraph",text:["An alternative use of this Gift can disrupt the balance required to maintain Gauru form by interfering with a subject’s connection to his spiritual self. An Essence point is spent and Manipulation + Occult + Cunning is rolled, with a dice-pool penalty equal to a resisting subject’s Resolve. (If a subject is compliant, no penalty is imposed.) Successes on this roll subtract from the number of turns the subject may remain in Gauru form. A subject forced out of Gauru reverts to Hishu form."]},{type:"paragraph",text:["Two Gift users can target the same subject with opposing versions of this power at the same time, with the resulting number based on the net successes rolled. So, if three are rolled to increase time in Gauru and one is rolled to diminish it, a total of two extra turns are gained. A single Elodoth cannot have more than one version of this Gift active at a time. He cannot empower each of his packmates on successive turns and then turn around in the next turn and weaken a rival. The Gift is considered active for as long as an affected werewolf remains in Gauru form."]},{type:"paragraph",text:["This power doesn’t influence taking forms other than Gauru, and doesn’t affect beings other than Uratha. It cannot be used to reduce the amount of time that a werewolf spends in Death Rage."]},{type:"paragraph",text:["The subject must be within line of sight of the Gift user. This power cannot be used on the Gift user himself."]}],fullCost:"1 Essence",dicePool:"Stamina + Occult + Purity (to extend time in Gauru); Manipulation + Occult + Cunning - resisting subject’s Resolve (to reduce time in Gauru)",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift has the opposite effect of what was intended. If it was meant to force a target out of Gauru, he may remain in Gauru for an additional turn. If it was meant to extend a target’s time in Gauru, he is automatically forced into Hishu instead."]},{type:"line",label:"Failure",text:["The Gift has no effect on the subject."]},{type:"line",label:"Success",text:["The Gift increases or decreases the subject’s duration in Gauru form by one turn per success."]},{type:"line",label:"Exceptional Success",text:["The Gift not only has the effect intended, but it adds or subtracts an extra turn of effect, as desired."]}]}]},{Name:"Honor",Description:"",Cost:"",Book:"SotM 102",Content:[{type:"paragraph",text:"The Elunim can grant many favors to a Walker Between, but only a few cut to the very core of the auspice’s role. Other werewolves often understand the importance of honor, but those who have received these Gifts embody it. The Elodoth must hold himself to high standards, but his rewards are great: he can turn his honor into a shield or a weapon, and can bind others to those same standards. The Elunim alone teach Honor Gifts, and only to those few Half Moons who manage to impress them."},{type:"paragraph",text:"These Gifts are exclusive to Elodoth characters, and are treated as affinity lists for the purposes of experience costs. A character cannot purchase an Honor Gift rated higher than his Honor Renown."}],Ranks:[{Rank:"•",Name:"Instant Measure",Description:"Gain 9again in Empathy, Persuasion, or Socialize against one target",Cost:"None",Book:"SotM 102",fullDescription:[{type:"paragraph",text:["An Elodoth with this Gift can gain the measure of another’s honor with only a few words. By measuring miniscule changes in body language and scent, the Elodoth knows how honorable his companion is, and can choose his words accordingly. This Gift doesn’t allow the werewolf to detect lies; instead he can play to his target’s sense of honor to bring him around to the werewolf’s viewpoint. The werewolf must engage the target in conversation, without threatening or bullying, to use this Gift."]}],fullCost:"None",dicePool:"Wits + Composure + Honor - target’s Composure.",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf misreads the person with whom he’s talking. Maybe he draws the wrong conclusions, or picks up on the body language of someone in the background. Whatever the case, the target gains a die on any rolls to hide information from the character."]},{type:"line",label:"Failure",text:["The werewolf doesn’t get a decent read of his target."]},{type:"line",label:"Success",text:["By interpreting changes of scent and body language, along with spiritual intuition, the werewolf knows how honorable his target is. By applying this knowledge, he knows how best to play his target in a social situation: each success gives the werewolf the 9-again quality to one Empathy, Persuasion, or Socialize roll made against the target until the end of the scene."]},{type:"line",label:"Exceptional Success",text:["The first roll enhanced with this Gift gains the 8-again quality. If that roll succeeds, the Elunim reward the werewolf with a point of Essence."]}]},{Rank:"••",Name:"Beyond Reproach",Description:"Add Honor to resist Mind Control or to act dishonorably",Cost:"None",Book:"SotM 102",fullDescription:[{type:"paragraph",text:["An Elodoth must act with honor in all things. This Gift makes the world aware of the werewolf’s deeds on a subconscious level. Those who would take away control of her actions must fight her honor, and even people who merely try to talk her into lies and dishonorable behavior face greater resistance. The protection of this Gift lasts only as long as the werewolf acts with a base amount of honor, if she ignores the basic tenets of honorable behavior then the Elunim remove their protection."]},{type:"paragraph",text:["The character can activate this Gift in two circumstances. Against supernatural powers that try to control her mind or directly influence her actions she adds her Honor to her Primal Urge for contested rolls, and adds her Honor to the Resistance trait for any Resisted powers."]},{type:"paragraph",text:["The second use for this Gift is in social situations. When anyone tries to convince your character to act in a dishonorable fashion, you can add your character’s Honor to the contested roll or to the Resistance trait as appropriate. For the purposes of this Gift, a dishonorable action is any action that would directly contravene the base expectations of Honor Renown (see “Contravening Honor” below)."]},{type:"paragraph",text:["If the werewolf takes an action that breaks the base expectations of Honor Renown, she cannot call on this Gift until the next moonrise. This includes actions that she is compelled to take by supernatural powers."]}],fullCost:"None",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"Forge Contract",Description:"Form a binding agreement between two parties",Cost:"●",Book:"SotM 103",fullDescription:[{type:"paragraph",text:["As the Half Moon is two-in-one, darkness and light that only exist as reflections of each other, so the Elodoth can reflect his honor in another. Some Half Moons use this Gift to arbitrate disputes, binding both parties to an oath with chains of honor as unbreakable as the werewolf’s will. Spirit envoys use this Gift to enforce the oaths they swear with spirits, and boundary walkers often need to make deals with otherwise untrustworthy people — and creatures."]},{type:"paragraph",text:["The Elodoth calls on the Elunim to witness a deal being struck. As both parties agree, he cuts the palm of his hand and touches the blood to all involved. Most usually, he does so by shaking hands with both parties, but hostile negotiations may require the werewolf touches his target (Touching an Opponent, World of Darkness Rulebook, p. 157). Shadows gather around one party, while moonlight suffuses the other; both are now parts of one greater whole. The werewolf can bind himself to a particular oath, but that oath cannot involve him breaking the base expectations of Honor Renown (see “Contravening Honor”, above)."]}],fullCost:"1 Essence",dicePool:"Manipulation + Persuasion + Honor versus Resolve + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf attempts to bind both parties to the deal into his own honor, but the Elunim are fickle and the bonds do not hold. The first time one of the parties breaks the terms of the contract, she gains a point of Willpower. At that point, the werewolf loses a point of Willpower."]},{type:"line",label:"Failure",text:["The werewolf cannot impose his own honor on the parties to the deal."]},{type:"line",label:"Success",text:["Each party to the contract is bound by the werewolf’s honor. If either one attempts to break the terms of the oath, she must fight against chains of honor and duty to do so. Any actions performed in service of breaking the oath suffer a negative modifier equal to the werewolf’s Honor Renown. The penalty represents the world putting obstacles in the oath-breaker’s way; circumstances conspire to make it easier to adhere to the contract. Two packs that vow to never step on each other’s territory might find cars and subway trains break down as they’re about to cross the boundary, or the roads are closed to fix the gas main or a sink-hole. A spirit who swears to never cross into the physical world finds the resonance of every locus opposes him, or might cross the path of a werewolf pack tracking another spirit foolish enough to attempt the crossing. The oaths’ supernatural protection lasts for a lunar month. Note that this Gift offers supernatural protection to the contract, and does not control or manipulate the minds of either party."]},{type:"line",label:"Exceptional Success",text:["The chains of honor bind both parties tight, enforcing the behavior of everyone who is a part of the oath. The first time a character attempts to contravene the oath, her action is automatically resolved by a chance roll."]}]},{Rank:"••••",Name:"Shining Example",Description:"Can change a resisted or contested action into an Instant action",Cost:"○",Book:"SotM 103",fullDescription:[{type:"paragraph",text:["An honorable werewolf can’t rest on her laurels. Others have to see her being honest and impartial, putting them ahead of herself, and doing her duty to her pack and her totem. Sometimes, that’s hard. Uncovering taint is never easy, but it’s worse when she discovers her own alpha is a Bale Hound. Negotiating with a powerful spirit is an exhausting ordeal, but all most people will ever know is that tomorrow is much the same as today. Carrying the flame of truth is hard, especially when it’s a truth most people would wish buried. Fortunately, just as the Elunim give Half Moons the ability to channel their honor backed with spiritual power, they empower particularly honorable behavior. A werewolf can use this Gift after performing a notable feat of honor (",{text:"Werewolf: The Forsaken",bold:!0},", p. 196)."]}],fullCost:"1 Willpower",dicePool:"Presence + Occult + Honor",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elunim turn their shadowed faces to the character. Whether they misunderstood her motives or see some flaw of which she is not yet aware, their displeasure is clear. The character loses a point of Essence."]},{type:"line",label:"Failure",text:["The character fails to impress the spirits."]},{type:"line",label:"Success",text:["The werewolf’s deeds impress the Elunim, showing that she is willing to put everything aside to do what is clearly right. For the rest of the scene, the werewolf can change a resisted or contested action into an instant action. She can do this a number of times equal to her Honor Renown."]},{type:"line",label:"Exceptional Success",text:["The character regains two points of Essence in addition to the effects of a success."]}]},{Rank:"•••••",Name:"Honor Incarnate",Description:"Anyone attacking the Elodoth's charge gains a penalty equal to her Honor. Half penalty if applied to self",Cost:"●●",Book:"SotM 103",fullDescription:[{type:"paragraph",text:["Sometimes, a werewolf must wear her reputation as a shield against those who would do her harm. This Gift channels her honor into an almost tangible form. She seems to stand taller than before, as if she has just discovered an extra six inches in height, and patches of light and shadow play across her body. Everyone who sees her knows deep down that she will do the right thing, make the right decision, no matter how unpleasant or painful. Guns pointed at someone under her protection start to waver, and nobody can hold a knife steady if it’s pointed in her direction. Deep down, in the primitive parts of the mind and the soul, everything knows that it’s not ",{text:"right",italic:!0}," to strike one that even Mother Luna knows as honorable."]}],fullCost:"2 Essence",dicePool:"Stamina + Expression + Honor versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character believes the world sees his honor, but he’s sadly mistaken. His overconfidence means he loses the benefits of his Defense for the first turn of combat."]},{type:"line",label:"Failure",text:["The werewolf gains no benefit."]},{type:"line",label:"Success",text:["Her foes are instinctively scared of actually striking a blow against the werewolf or someone she is defending. The most honorable use of this Gift is to protect another, though the werewolf can shield herself if she needs to. As long as she is in physical contact with the person she wishes to protect, anyone attacking the character’s charge suffers a penalty equal to the character’s Honor Renown (which has to be five dots). If the werewolf chooses to protect herself, attackers only suffer a penalty equal to half her Honor Renown, rounding down. This protection lasts for one turn per dot of Primal Urge, and the werewolf cannot attack while using this Gift."]},{type:"line",label:"Exceptional Success",text:["The werewolf’s selflessness impresses everyone. As long as she is protecting someone else, anyone attacking either character suffers the full penalty."]}]}]},{Name:"Information",Description:"",Cost:"",Book:"Rage 118",Content:[{type:"paragraph",text:"Some forward-thinking werewolves have taken to interrogating information-spirits — not just data-spirits but the far rarer spirits of concept and meaning. Wherever they hide, these werewolves hunt them for their knowledge. So far, only the following Gifts have come to light, and the Uratha who have learned them are not cohesive enough to form a lodge — though if they survive for long it is only a matter of time. Iron Masters and Bone Shadows are the most likely to find a spirit willing to teach Information Gifts, though that is mostly because of those tribes’ natural cunning. Only conceptual spirits of information can teach these Gifts."}],Ranks:[{Rank:"•",Name:"Sense the Flow",Description:"Can perceive the flow of information in an area, and can single out one particular stream",Cost:"-",Book:"Rage 118",fullDescription:[{type:"paragraph",text:["Information comes in many forms. A lot of the time the flow of information is obvious — information flows between two people in conversation, or from a book to its reader. Sometimes, it’s less obvious, such as a radio transmission or a coded message. This Gift allows the user to perceive the flow of information in an area, and can single out one particular stream. Radio broadcasts look like shining contrails that emit a faint high-pitched whine, while a coded message might make a passage of text smell wrong."]}],fullCost:"None",dicePool:"Resolve + Computer + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf sees codes and information where there are none, and misses obvious signs. His next Investigation or Computer roll has a -1 modifier."]},{type:"line",label:"Failure",text:["The Gift reveals nothing."]},{type:"line",label:"Success",text:["The character can sense information flows, to an extent. She can see a faint link between the source and the receiver of information, and the hue of the link gives her some idea of its nature. Information flows only manifest to this Gift when the information is received — a street sign generates a faint flow between itself and everyone who reads it, but only when someone reads it; and cell phones only create a flow when a call is in progress and one of the participants is listening. The character can see that a graffiti tag contains a hidden message only when someone is reading it, but she can tell that the message is hidden and who receives the message. In a crowded city street, these flows can quickly overwhelm the werewolf. Concentrating on one flow that she knows about — the flow from the wire a contact is wearing to the cops outside, or a radio broadcast that she is listening to — allows her to follow it to its destination. As the Gift works on information, the character is lead to the source of the broadcast. The Gift works for one minute per success and can be re-activated as a reflexive action if the character is actively following a trail."]},{type:"line",label:"Exceptional Success",text:["The Gift is as effective as for a success, plus the character can see the presence of information that isn’t currently in transit. By examining a computer, she can get a feel for what it’s used for from the types of files present, or she can determine whether a piece of text or art contains a coded message. Note that the presence of information doesn’t give her access to the information itself — there’s a whole world between knowing there’s a hidden message, and knowing what it means."]}]},{Rank:"••",Name:"Tongues",Description:"Translate text and also deeper subtext and other subtleties concealed in the words",Cost:"●",Book:"Rage 119",fullDescription:[{type:"paragraph",text:["This Gift allows a werewolf to extract the information from a source regardless of the form it comes in. This Gift allows him to understand something written or spoken in a foreign language without knowing the language in question, as the Gift extracts the information underlying the words. The Gift then processes that information at a spiritual level into a language that the character understands fluently. Thus, there is no chance for ambiguity or misunderstanding, and the character picks up on hidden meaning with ease."]}],fullCost:"1 Essence",dicePool:"Wits + Academics + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The translation is botched, appearing to convey the basic meaning of the text but with enough alterations to dramatically alter the actual meaning of the piece. All rolls relating to the translated information have a -1 modifier."]},{type:"line",label:"Failure",text:["The character gets nothing from the Gift."]},{type:"line",label:"Success",text:["The Gift effortlessly translates not only the text but also the deeper subtext and other subtleties concealed in the words. The Gift lasts for one piece of text roughly equal to a chapter of a book or one full conversation. Note that though the Gift gives the character a complete understanding of what was written or said, this Gift does not grant understanding of the language. Hence, in a conversation, she would have to speak the language used in order to reply. The Gift works on any information that is not being deliberately hidden, such as via a code or cipher."]},{type:"line",label:"Exceptional Success",text:["As a success, plus the Gift works in reverse, converting the character’s meaning back into the original language. If the language is verbal, this effect lasts for the whole conversation. If the language is written, the character can write a piece no longer than the original."]}]},{Rank:"•••",Name:"Babel Effect",Description:"Render a group of people (up to 5) entirely unable to understand one another",Cost:"●●●",Book:"Rage 119",fullDescription:[{type:"paragraph",text:["Language is a means of conveying structured information, a means of spreading ideas from one person to another. Language is a remarkably versatile form, and even a mild grasp of a tongue will allow someone to convey a wide range of basic ideas. This Gift shatters that. By crudely reorganizing the information that underlies a conversation, the werewolf can render a group of people entirely unable to understand one another. Without the ability to communicate using anything more than gestures, a group’s cohesion swiftly degrades until there’s nothing left but a lot of people getting in each other’s way. To those affected by the Gift, every other member of the group appears to be suffering from dysphasia."]}],fullCost:"3 Essence",dicePool:"Manipulation + Persuasion + Glory versus each target’s Composure + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf is unable to make herself understood to anyone using anything more complex than crude physical gestures for the rest of the scene."]},{type:"line",label:"Failure",text:["The targets of the Gift remain able to understand one another."]},{type:"line",label:"Success",text:["The character can target up to five people, all of whom must be part of one identifiable group (gang members, or a hunting party) within five times her Primal Urge in yards. Every target resists the Gift’s effects with the target’s own Composure + Primal Urge, and only those who roll fewer successes than the werewolf are affected by this Gift. Every affected member of the group becomes entirely unable to communicate with the others using any form of organized language — including sign language — and must rely on crude gestures to convey any meaning. While any member of the group who is not affected can be understood by those who are, those affected cannot make themselves understood to anyone else in the group. This effectively ruins the group’s co-ordination, making most tactics (including Pack Tactics, see p. 156) effectively impossible. The result of this is that each affected member suffers a -2 modifier to all rolls where communication with the other affected people is a factor. The Gift lasts for one scene."]},{type:"line",label:"Exceptional Success",text:["The werewolf poisons the underpinnings of his targets’ communication. Anyone suffering this level of effect cannot make himself understood by anyone, as opposed to just members of the same group."]}]},{Rank:"••••",Name:"Steganography",Description:"Add a hidden information-spirit to her words, encoding a hidden message or meaning that only someone of her choosing will understand",Cost:"●+",Book:"Rage 120",fullDescription:[{type:"paragraph",text:["Language is a carrier for information, a means of encoding thought and meaning — information — in a way that allows one person to transmit information to another person. This Gift allows the werewolf to add a hidden information-spirit to her words, encoding a hidden message or meaning that only someone of her choosing will understand. Anyone else reading or hearing her words will hear what she says, but her chosen recipient will also understand a message just for him. The few werewolves trying to unlock a Lodge of Information often use this Gift to communicate, but that is far from the only use."]}],fullCost:"Varies, see below",dicePool:"Intelligence + Subterfuge + Cunning",action:"Extended (10 successes; 10 minutes pass per roll)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf’s message is either warped as it is hidden so that it has a different meaning, or someone other than the desired target receives the hidden message."]},{type:"line",label:"Failure",text:["The message conveys no extra meaning."]},{type:"line",label:"Success",text:["The werewolf hides a message underneath what she is saying. Any individual she can identify, or members of a distinct group, will hear both messages, though the werewolf must spend one Essence per recipient. For example, in sending a message to her pack hidden in a message from a nightclub DJ, she must spend one Essence per packmate. If she instead selected “members of the Blackbird street gang” and spent three Essence, three members of the gang who are present at the rave will hear the message. If there aren’t enough people present, the extra Essence is wasted. If there are more present, the Storyteller decides who hears the message and who does not. The hidden message cannot be longer than the original message."]},{type:"line",label:"Exceptional Success",text:["As a success, but all members of a group hear the message for only one Essence. Any extra Essence spent is returned to the werewolf."]}]},{Rank:"•••••",Name:"Twisted Words",Description:"Convince the information-spirits of the speech to change depending on their audience, meaning that different people hear what he wants them to hear, rather than what was actually said",Cost:"●●(○)",Book:"Rage 120",fullDescription:[{type:"paragraph",text:["All too often, people hear what they want to hear. A speech on a controversial subject such as immigration or gay rights has the potential to warp in listener’s minds until they hear what they expected or wanted to hear. This Gift goes further than that. The werewolf convinces the information-spirits of the speech to change depending on their audience, meaning that different people hear what he wants them to hear, rather than what was actually said. While the new meaning must be on the same subject, it doesn’t have to bear any relation to the original. A group of Klansmen looking to lynch a speaker on race relations will get the impression that the speaker supports their views, even if the speech held a diametrically opposite viewpoint. Victims of this Gift can’t point to anything specific that gave them the impression that they came away with, but they are nonetheless certain about what they heard. This Gift only works for speeches, not written words."]}],fullCost:"2 Essence; optionally 1 Willpower",dicePool:"Wits + Persuasion + Wisdom - Composure",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["Everyone who would have been affected by the Gift hears exactly what the speaker says and nothing more, and knows that the werewolf is trying to pull the wool over her eyes."]},{type:"line",label:"Failure",text:["The character can’t alter anyone’s perceptions of what is said."]},{type:"line",label:"Success",text:["The werewolf can either wreck the meaning of the speech, making the speaker out to be a ranting lunatic incapable of holding a coherent subject, or can deliberately warp one group’s perceptions of the speech in a direction of her choosing. Wrecking a speech is easier than twisting it. The werewolf convinces the information-spirit to go crazy, mutating into wild yarns and insane conspiracy theories that are only vaguely related to the subject at hand. Listeners can make a reflexive Resolve + Persuasion roll to attempt to follow what sounds like a lunatic screed, but nobody else can take the speaker seriously. The Gift discredits the speaker in the minds of everyone present. Twisting the speech requires the werewolf to select a group among the listeners. The selection can be a wide group, up to and including “people who agree with the speech.” That group then hears a meaning to the speech that the werewolf decides. This change to the speech is general, and can be made at any point. For example, a werewolf present at a Fire-Touched sermon can twist the words of the preacher in the ears of all who would agree to hear a pro-Forsaken speech. Adding her own meaning to the speech costs one Willpower in addition to the Essence cost."]},{type:"line",label:"Exceptional Success",text:["When ruining a speech, none of the listeners may make a Resolve + Persuasion roll to determine the original meaning of the speech. When twisting the meaning, the werewolf can choose two groups, feeding both a different message."]}]}]},{Name:"Insight",Description:"",Cost:"",Book:"WtF 122",Content:[{type:"paragraph",text:"The supernatural is a reality that exists beyond ordinary human experience. To truly understand the realm of the occult, one must have senses that can delve further than the mortal. Gifts of Insight are ways of unlocking truly preternatural perception, teaching ways of “seeing with the third eye” or “perceiving the scents of the invisible world.” The Bone Shadows, bound as they are to learn the wisdom of other realms, have a particular affinity for Insight Gifts, although Ithaeur and Elodoth of all tribes find these Gifts useful."},{type:"paragraph",text:"Insight Gifts are taught by spirits associated with wisdom, and many have ties to the realm of Death as well. The dead perceive things that the living cannot. Spirits of owls and serpents are particularly appropriate teachers for these Gifts."}],Ranks:[{Rank:"•",Name:"Sense Malice",Description:"Sense negative emotions",Cost:"-",Book:"WtF 122",fullDescription:[{type:"paragraph",text:["Hatred has its own scent. The werewolf using this Gift is particularly sensitive to the malice that lurks in other people’s hearts, and he can smell a soul tainted with hatred, anger or envy as easily as a predator can catch the smell of prey. This Gift is frequently used on the hunt as a means of locating a potential threat to a werewolf’s family or territory, but it also has uses as a warning against potential danger."]},{type:"paragraph",text:["This Gift does not detect the presence of all negative emotions, only those that are powerful enough to have a grip on the mind of a subject. A man who is irritated that he’s been turned down by a girl doesn’t register. A man angry that his girlfriend left him might be barely noticeable, while a man who caught his wife cheating on him with his best friend certainly qualifies. A mass murderer or serial killer might not register to this Gift unless he actively experiences a flood of negative emotion. This Gift works only on targets that a werewolf is close enough to scent normally (usually within the same room). This Gift doesn’t require physical scent, and powerful odors do not obscure the ability to detect malice. This power does not ",{text:"usually",italic:!0}," tell the user what has actually happened to a subject or why he is incensed, simply that he is."]},{type:"paragraph",text:["If the subject’s Vice is Wrath or Envy, a +1 bonus is gained on the activation roll. The Gift user automatically senses the presence of anger or hatred in spirits that are the literal embodiments of such negative emotions (no roll is required). If a person or object is possessed by a spirit of anger, hatred or malice, a normal activation roll is required, but it gains a +3 bonus. At the Storyteller’s discretion, the strength of the emotion experienced may merit an additional bonus or penalty die, although not more than one."]}],fullCost:"None",dicePool:"Intelligence + Empathy + Wisdom versus subject’s Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character receives misleading information. She might sense intense anger in a subject who is only mildly annoyed, or she might be convinced that a would-be murderer is utterly without malice."]},{type:"line",label:"Failure",text:["An equal number or the most successes are rolled for the subject. The character distinguishes no information, though she is aware of her failure."]},{type:"line",label:"Success",text:["The most successes are rolled for the Gift user. She senses the presence of unusually strong aggression, hatred or anger. She can identify which specific person is the source of the emotion."]},{type:"line",label:"Exceptional success",text:["The most successes — five or more — are rolled for the Gift user. She intuitively understands the source of emotion and can determine the cause to some degree, though not with complete accuracy. She might perceive, “My mate betrayed me,” but not, “My wife cheated on me with the beat cop on our street.”"]}]},{Rank:"••",Name:"Scent of Taint",Description:"Sense supernatural creatures",Cost:"-",Book:"WtF 123",fullDescription:[{type:"paragraph",text:["The smell of supernatural influence emanates from beings that are beyond human and mundane. A werewolf who knows this Gift can detect the presence of supernatural beings. Specifically, the user can detect powers in his vicinity that defy the natural order of the physical and spirit worlds, so that vampires, ghouls, mages, acolytes and beings bestowed or imbued with unnatural capabilities are evident. Scent of Taint does not indicate or set apart — and cannot be used to recognize — any of the Uratha or the wolf-blooded. Nor can it be used to detect supernatural objects or places."]},{type:"paragraph",text:["Using this Gift to track (see p. 178) a supernatural being offers a +2 bonus to rolls made for the effort."]},{type:"paragraph",text:["The Storyteller is advised to make activation rolls on a player’s behalf so that the sense of mystery about nearby beings is maintained, based on whether success or failure occurs."]},{type:"paragraph",text:["If a supernatural being uses a power to hide its presence or true nature, a contested roll is required between the use of that power and the activation roll of this Gift. (The roll is reflexive for the subject.) If the rolls tie or the most successes are rolled for the hiding subject, he goes undetected. The power works only in the material world and cannot detect disembodied spirits or ghosts trapped in it. If such spirits or ghosts possess a host and grant her magical capabilities, the subject can be sniffed out."]}],fullCost:"None",dicePool:"Wits + Occult + Purity",action:"Instant (Subjects must be intentionally sought after; they are not detected simply for passing or being nearby.)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character receives misleading information. She might believe a supernatural being is nearby when it’s not, or she might believe none are near when they are."]},{type:"line",label:"Failure",text:["Nothing is detected."]},{type:"line",label:"Success",text:["The character recognizes the scent of some strange being in her proximity. The creature must be within 10 yards for each dot of Wits the user has to be detected at all. One roll can be made per turn to determine if the being remains present or has left the vicinity. The precise nature of the being cannot be determined. Nor can the specific identity of the being if the Gift user is in a crowd."]},{type:"line",label:"Exceptional success",text:["The specific individual who is “off” is recognizable, although his specific identity as a supernatural being — vampire, mage or something else — cannot be determined."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+1","Gift user has previously encountered this individual being (not supernatural type; i.e., “Jason Volk,” not “a vampire”)"],["-1","Outdoors; calm weather"],["-2","Outdoors; windy or drizzling"],["-3","Outdoors; snowing or raining"],["-3","Multiple supernatural beings (apart from Gift user) in area"],["-4","In a crowded area (nightclub, subway station, downtown lunch rush)"]]}]},{Rank:"•••",Name:"Echo Dream",Description:"Read spiritual resonance",Cost:"●",Book:"WtF 123",fullDescription:[{type:"paragraph",text:["Werewolves quickly learn that events in the physical world echo in the spirit world, leaving strange psychic impressions. A werewolf who has earned this Gift has gained the ability to sense these echoes, even ones long past. By holding or handling an object, or resting her hand against a wall or tree, the Forsaken can sense spirit echoes of the object or area’s recent past. These echoes are couched in the symbolic language of the spirit world but often convey sharper truth than any forensics report might."]},{type:"paragraph",text:["This Gift doesn’t work on sentient creatures, who generate their own spirit echoes. An attempt to use Echo Dream to read the recent past of a person results in contradictory, nonsensical images."]}],fullCost:"1 Essence",dicePool:"Wits + Investigation + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overwhelmed with violent and contradictory visions from the area and loses a point of Willpower."]},{type:"line",label:"Failure",text:["The character receives mere useless flickers or no vision at all."]},{type:"line",label:"Success",text:["The character receives some vision of the most significant thing that has involved the object or immediate area (no larger than a medium-sized room). Death usually leaves the most significant spirit echo, although powerful bursts of pain or negative emotion also register. Echoes rarely linger for more than a few years, although that depends on the intensity of the events involved. A knife that killed someone a hundred years ago might not possess an echo any longer, while a sacrificial dagger that cut out a thousand hearts five centuries ago might still trigger a powerful vision of blood and darkness. The vision is frequently couched in symbolic visual language, a side effect of the interconnectedness of many spirit concepts. For example, a gun that was used by a hunter to fire a silver bullet into a werewolf might project the sound of a gunshot and the image of the full moon cracking and bleeding. A successful Intelligence + Occult roll might be required to interpret a vision. This Gift cannot be used successfully more than once on any one object or place by the same character."]},{type:"line",label:"Exceptional Success",text:["The vision is exceptionally clear and provides additional information that the character might not expect. In the case of the gun used to shoot a werewolf, the character might receive an accurate vision of the hunter’s face."]}]},{Rank:"••••",Name:"Soul Read",Description:"Read the subject's heart (1 secret, fear or weakness per success)",Cost:"●",Book:"WtF 124",fullDescription:[{type:"paragraph",text:["At increasing levels of perception, a Gift of Insight can lay bare the darkest secrets of a person’s soul. The character can look directly into the heart of a subject, reading the worst fears, secrets and sins hidden there."]}],fullCost:"1 Essence",dicePool:"Intelligence + Empathy + Purity versus subject’s Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is inadequately prepared to look on the totality of a person’s being. She is temporarily overwhelmed and loses a point of Willpower."]},{type:"line",label:"Failure",text:["An equal number or the most successes are rolled for the subject. The Gift user fails to see far enough to uncover any secrets."]},{type:"line",label:"Success",text:["The most successes are rolled for the Gift user. She gains knowledge of one of the subject’s secrets, fears or weaknesses per success rolled. These are details that the subject doesn’t want to become public knowledge. A memory of committing an act of sexual abuse, an abiding fear of rejection or the location of something dear (such as a vampire’s haven) are all fair game. This Gift doesn’t provide information that the user already knows. If she’s already aware that her target is a warlock, the Gift doesn’t count that fact as a “secret” to be revealed. The Gift may, however, confirm a piece of information that the character had only guessed at before."]},{type:"line",label:"Exceptional Success",text:["The most successes — five or more — are rolled for the Gift user. The subject instinctively senses that the werewolf knows, and she suffers a -1 penalty to all Social rolls made to influence or resist her for the remainder of the scene."]}]},{Rank:"•••••",Name:"Omen gazing",Description:"Prophetic trance",Cost:"●",Book:"WtF 124",fullDescription:[{type:"paragraph",text:["With this Gift, the werewolf has developed an inner sight so powerful that it can actually catch glimpses of the future. The character enters a meditative trance, clearing her mind of everything but darkness in order to welcome the visions. She might receive warning of an impending attack, foretell the arrival of a potential ally or even watch a betrayal unfold before it happens. Viewing the future accurately is impossible, though. No vision is guaranteed to come true. Worse, visions gained are more often signs of ominous events than they are promises of good fortune. Whether this is because the Gift’s “eyesight” is through a dark lens, or simply a cold reflection of the hard truths of a werewolf’s existence, none can say."]},{type:"paragraph",text:["A character may not attempt Omen Gazing more than once in any 24-hour period."]},{type:"paragraph",text:["A seer is unaware of events surrounding her while she is in a trance. She is, however, aware of anything that touches or affects her body directly."]}],fullCost:"1 Essence",dicePool:"Resolve + Occult + Glory",action:"Extended (15 successes required; each roll represents one minute spent in a trance)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The vision fails automatically and the character cannot try again for 24 hours."]},{type:"line",label:"Failure",text:["No successes are gained for the minute. If no successes are gained in three consecutive rolls, no vision comes, although another attempt can be made."]},{type:"line",label:"Success",text:["The character catches a glimpse of a potential event in her near future — anywhere from 24 hours to one week. The vision lasts for roughly a turn’s worth of viewing — enough time to watch a man gun down a packmate, a car carrying a loved one swerve and crash or an elder hail a dangerous spirit. The vision is usually clear enough to make out details, though the details might be misleading. For example, a body face-down in the river, wearing a packmate’s jacket, might turn out be the corpse of a friend who borrowed the jacket. This Gift is a means of gaining a potential warning, nothing more."]},{type:"line",label:"Exceptional Success",text:["The vision lasts for up to a minute."]}]}]},{Name:"Inspiration",Description:"",Cost:"",Book:"WtF 125",Content:[{type:"paragraph",text:"Inspiration is the meat and drink of great heroes. It provides sustenance for flagging warriors, a fire in the heart fanned from mere embers. Werewolves who use these Gifts gain courage even in the face of extreme danger, and the spirit of Inspiration can entwine an entire pack in the unity of heroism. The Blood Talons possess particular affinity with Inspiration; it’s likewise a favorite of many Cahalith and Rahu. Teachers of these Gifts include various Lunes and ancestor-spirits."}],Ranks:[{Rank:"•",Name:"The Right Words",Description:"Positively affect morale (+2 to Social rolls to encourage or mollify)",Cost:"-",Book:"WtF 125",fullDescription:[{type:"paragraph",text:["Sometimes keeping a pack in line or a soldier’s morale up hinges on knowing just what to say. A stirring speech, a well-placed compliment or even just remembering the new guy’s name can bring confidence and a will to strive against adversity."]}],fullCost:"None",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[{type:"paragraph",text:["The character gains +2 to all Social rolls made to encourage or mollify. Social rolls to bully and threaten are not affected. The effects last for a scene."]}]},{Rank:"••",Name:"Camaraderie",Description:"Help working together (+1 to resist Death Rage, +1 to Teamwork)",Cost:"-",Book:"WtF 125",fullDescription:[{type:"paragraph",text:["There is strength in unity. Unfortunately, suspicion and personal agendas beget division. Easing tensions is a key step in binding comrades to a common purpose, even if that common purpose is simply not killing each other."]},{type:"paragraph",text:["To activate the Gift, the user speaks to his fellows about the need to set aside differences to work for a greater goal. Depending on the situation, this may be a few quiet words or a grand oratory. If successful, all listeners gain a +1 modifier to Resolve + Composure rolls to resist the Death Rage for the scene. In addition, if any of the subjects assist one another on a specific action during the scene (see “Teamwork,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 134), contributors each gain a +1 modifier to their rolls to help."]}],fullCost:"None",dicePool:"Manipulation + Persuasion + Wisdom",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"True Leader",Description:"Grant Willpower (1 point per success to all allies to be spent in the scene)",Cost:"●",Book:"WtF 125",fullDescription:[{type:"paragraph",text:["There is strength in unity. Unfortunately, suspicion and personal agendas beget division. Easing tensions is a key step in binding comrades to a common purpose, even if that common purpose is simply not killing each other."]}],fullCost:"None",dicePool:"Manipulation + Persuasion + Wisdom",action:"Reflexive",rollResults:[{type:"paragraph",text:["To activate the Gift, the user speaks to his fellows about the need to set aside differences to work for a greater goal. Depending on the situation, this may be a few quiet words or a grand oratory. If successful, all listeners gain a +1 modifier to Resolve + Composure rolls to resist the Death Rage for the scene. In addition, if any of the subjects assist one another on a specific action during the scene (see “Teamwork,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 134), contributors each gain a +1 modifier to their rolls to help."]}]},{Rank:"••••",Name:"Spirit Skin",Description:"Gain spiritual authority (dots of highest Renown are gained as modifier to Social rolls)",Cost:"●",Book:"WtF 125",fullDescription:[{type:"paragraph",text:["Werewolves are creatures of spirit and flesh, but using this Gift manifests that spirit side in the physical world for all to see. The werewolf exudes a perceptible cloak of authority and spiritual power. The appearance of this mantle varies by the werewolf’s nature. A wrathful warrior might glow with an inner fire and be shrouded with wisps of vapor, while a harmonious, introspective leader may exude an aura of dignity and calm. However it manifests, the werewolf can inspire awe or terror in those around him."]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Instant",rollResults:[{type:"paragraph",text:["The character’s dots in his highest Renown are gained as a modifier to Social rolls to impress, persuade, inspire or intimidate for the scene. This modifier does not stack with any Social pool modifiers gained from Renown (see p. 78). Opponents must succeed at a Composure + Primal Urge roll at a penalty equal to the character’s highest Renown in order to attack the werewolf, except in self-defense. The aura is manifest for the remainder of the scene."]},{type:"line",label:"Exceptional Success",text:["As success, and a human onlooker’s Willpower is considered three lower than normal for determining the effects of Lunacy (see p. 176)."]}]},{Rank:"•••••",Name:"Victor's Song",Description:"Grant Essence (1 point and +1 to all rolls for every allied)",Cost:"●",Book:"WtF 126",fullDescription:[{type:"paragraph",text:["All is lost when heart is lost. Yet even when hope has vanished, newfound courage can claim victory where there was only defeat. In the face of hopeless odds, whether surviving a suicide charge or bracing a crumbling levee, Victor’s Song doesn’t push allies beyond their limits, it pushes their limits beyond what they thought possible."]}],fullCost:"1 Essence",dicePool:"Presence + Expression + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The spirits are offended by the clumsy use of the Gift. The character loses the ability to use any Inspiration Gifts for the rest of the day."]},{type:"line",label:"Failure",text:["The Gift has no effect."]},{type:"line",label:"Success",text:["The user must howl, chant or sing a song extolling his comrades to valor and courage. Success rolled grants one Essence to all allied werewolves within earshot, save the Gift user. Furthermore, a one-die bonus is added to all allies’ dice pools. This Gift works only in the face of overwhelming odds (say, the imminent death of the pack or the loss of all territory). Against typical threats or evenly matched opponents, the Gift automatically fails; the spirits look askance at misuse of their power. This Gift may be used only once per day on a subject, and any unspent Essence gained is lost at the end of the scene. Die-pool bonuses stop at the end of the scene, too."]},{type:"line",label:"Exceptional Success",text:["As success, but all allied werewolves gain a point of Willpower for the scene, as well."]}]}]},{Name:"Judge's Moon",Description:"",Cost:"",Book:"Lore 86",Content:[{type:"paragraph",text:"These Gifts enhance the Elodoth’s ability to observe and pass judgment. A skilled Elodoth can gain a great understanding of a foe, enough to exploit a weakness personally or reveal it to his pack."}],Ranks:[{Rank:"•",Name:"See the Spirit Brands",Description:"See the spirit brands from renown from a target werewolf",Cost:"-",Book:"Lore 86",fullDescription:[{type:"paragraph",text:["The spirit brands that denote the Forsaken’s Renown are visible to any spirit, and burn with silver light when the Forsaken enter the Shadow Realm. This Gift allows the Elodoth to look with a spirit’s eyes, seeing the brands of Renown while he and his target are in the physical world. In this manner, he can determine how Renowned a werewolf is in general, whether she is Forsaken or Pure, or even if she has been initiated into either faction."]}],fullCost:"None",dicePool:"Composure + Politics + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elodoth’s vision clouds. He may not attempt to use this Gift again for the remainder of the scene."]},{type:"line",label:"Failure",text:["The Elodoth must rely on his physical senses."]},{type:"line",label:"Success",text:["The Elodoth is able to read the spirit brands of the subject, gauging roughly how much Renown the subject possesses and in what categories. The spirit brands of a Forsaken werewolf burn like silver, while the brands of a Pure werewolf appear to be massive scars that glow faintly with internal heat."]},{type:"line",label:"Exceptional Success",text:["The Gift remains in effect for a full minute, allowing the Elodoth to glance over multiple subjects or to make an accurate survey of a single subject’s Renown."]}]},{Rank:"••",Name:"Damning Tongue",Description:"Repeat all word spoken by the target, at a distance for a scene",Cost:"-",Book:"Lore 86",fullDescription:[{type:"paragraph",text:["The Elodoth has many tricks up his sleeve for judging and ensnaring prey, but this is arguably one of the most unusual. By invoking the Judge’s Moon, the Elodoth attempts to have his prey damn herself with her own words. Once the Half-Moon manages to establish a link with a target, whatever she says, he says; he recounts her half of a phone conversation even as she says it, or repeats the orders she gives to her underlings. The typical use for this Gift is to spy on a target, the Elodoth repeating her words to the pack as the Irraka advances to watch her actions. However, some Elodoth even use it as an intimidation tactic. When confronted with a person (or werewolf) seemingly able to read your thoughts, it puts a subject at a disadvantage for the conversation."]},{type:"paragraph",text:["The Elodoth must have line of sight to his target in order to invoke this Gift, but need not maintain line of sight in order to maintain the effects."]}],fullCost:"None",dicePool:"Wits + Empathy + Cunning versus target’s Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elodoth temporarily loses control of his own tongue. The character cannot speak for the next minute, and cannot attempt to use this Gift again for the remainder of the scene."]},{type:"line",label:"Failure",text:["The Gift fails to take effect."]},{type:"line",label:"Success",text:["The Elodoth establishes a link to the target. For the remainder of the scene, anything that the target says, the Elodoth repeats simultaneously. The character doesn’t actually “hear” the words in his mind and then choose to speak them; his mouth simply mimics the target’s speech. The Elodoth may speak normally, but if he chooses to say something of his own at the time the target is speaking, his own words take precedence, and he misses whatever she’s saying at that time. This Gift conveys no understanding of languages; if the target is speaking Portuguese, the Elodoth will repeat her words in Portuguese regardless of whether he understands the tongue or not. The Gift lasts for a scene, or until the Elodoth chooses to end the effects."]},{type:"line",label:"Exceptional Success",text:["The Elodoth actually “hears” the target’s speech in his mind an instant before he echoes it, and can therefore speak without fear of losing the conversation’s thread."]}]},{Rank:"•••",Name:"Pangs of Guilt",Description:"Make the target suffer from his sins, suffering 1 bashing damage per success and a -1 penalty for the next turn",Cost:"●",Book:"Lore 87",fullDescription:[{type:"paragraph",text:["Everyone is guilty of something. This Gift calls on the Judge’s Moon to set things “right” by revisiting a person’s cruelties on them; even tiny thefts and callous words can stab like knives. The more skeletons in the target’s closet, the more pain that is visited upon him."]},{type:"paragraph",text:["The Gift user subtracts the target’s Harmony (or Morality, Humanity or whatever trait fills that particular role) from his dice pool. This Gift cannot be used on animals, spirits, Hosts or other creatures that do not possess such a trait. Though a low Morality score reflects a character’s general comfort level with being increasingly cruel or callous to others, this Gift bypasses such mental defenses. It insinuates itself into a target’s mind and assails her with unfamiliar feelings of empathy for others. A solipsistic serial killer who ordinarily could not even conceive of other human beings as creatures with their own emotions can be brought low as he learns otherwise."]}],fullCost:"1 Essence",dicePool:"Presence + Investigation + Purity — target’s Harmony",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elodoth relives a flash of his own worst moments instead. The player must make an immediate Death Rage check."]},{type:"line",label:"Failure",text:["The target may feel a faint twinge of conscience, but nothing more."]},{type:"line",label:"Success",text:["The target takes one point of bashing damage per success, and is at a -1 penalty to all actions during her next turn as she re-orients herself. This Gift reveals no information about the target’s previous sins to the Elodoth; only that she appears to suffer lightly or greatly."]},{type:"line",label:"Exceptional Success",text:["The target’s disorientation lasts for the entire scene. In some cases, the target may desire to critically re-examine her life if she survives the encounter."]}]},{Rank:"••••",Name:"Anticipation",Description:"Predict an opponent's future action (+4 Defense for next turn, or +2 if he warns a packmate)",Cost:"●",Book:"Lore 87",fullDescription:[{type:"paragraph",text:["This Gift heightens the Elodoth’s powers of observation and understanding to the point that he can predict his target’s actions with uncanny accuracy. He can half-glimpse a strike before his opponent makes it, guess which way his target is going to run, even guess a password as his target moves to type it in."]}],fullCost:"1 Essence",dicePool:"Wits + Empathy + Wisdom - subject’s Resolve",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elodoth greatly misinterprets his foe’s actions. The character may take no action during his next turn save to defend himself, as he waits for a move that isn’t going to happen."]},{type:"line",label:"Failure",text:["The Elodoth is unable to perceive his opponent’s actions in sufficient advance to gain any benefit."]},{type:"line",label:"Success",text:["The Elodoth manages to accurately predict his opponent’s action. The Storyteller describes the next action that the opponent plans to take to the player, in moderate detail: for example, “She’s going to try to hamstring David with a bite, unless he moves beyond her reach or her packmate takes him down.” The Elodoth gains a +4 bonus to Defense against the target of this Gift during the target’s next turn only. If the Elodoth is linked to the pack via the Gift: Unspoken Communication (",{text:"Werewolf: The Forsaken",bold:!0},", p. 118), all other packmates share in the Defense bonus against the target. If he is able to warn his packmate vocally, a packmate may gain a +2 Defense bonus against the target’s next action. Again, the bonus lasts only during the target’s next action. If used out of combat, this Gift can reveal certain key bits of information to the Elodoth; he may anticipate the number that the target punches into a keypad or guess the next sentence out of her mouth."]},{type:"line",label:"Exceptional Success",text:["The Elodoth is able to anticipate the target’s next two actions, and gain the Defense bonus against each. The Storyteller announces the first of the opponent’s actions on the Elodoth’s turn, and then announces the second of the target’s planned actions on the Elodoth’s next turn."]}]},{Rank:"•••••",Name:"Curse of Talion",Description:"Curse a target according to his past sins",Cost:"●●",Book:"Lore 88",fullDescription:[{type:"paragraph",text:["An eye for an eye; a tooth for a tooth. This is the law of Talion. The greatest Gift of the Judge’s Moon grants the Elodoth the ability to curse a target with a punishment reflecting the suffering visited on the target’s victims. A rapist may be mutilated, a murderer may die on the spot. The Elodoth has no control over what form the Curse of Talion may take — he simply opens the floodgates and lets the half-moon’s idea of punishment flow out."]},{type:"paragraph",text:["This Gift can be used only once against any given target, even if it fails. The Gift may also only be used on the night of the half-moon."]}],fullCost:"2 Essence",dicePool:"Intelligence + Politics + Honor versus target’s Resolve + Primal Urge",action:"Standard",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Elodoth improperly calls on the Judge’s Moon, and is rebuffed. The Elodoth may not use any more Judge’s Moon Gifts until the next half-moon, or until he performs the Rite of Contrition."]},{type:"line",label:"Failure",text:["The target feels a brief moment of unease, but is spared."]},{type:"line",label:"Success",text:["The Curse of Talion is levied. The Curse takes a form determined by the Storyteller, and is personalized to the target’s level of crimes. If the Curse is levied against a person guilty of no more than petty theft, the target may wind up misplacing something important to him but not vital. On the other hand, if the target is a murderer, wounds may open up on his body. A soldier who has killed only in wartime might be less vulnerable than a civilian who killed someone for vengeance. As a general rule, humans are the most vulnerable to the Curse; a human murderer may die from this Gift. Supernatural entities are harder to affect. At the most, the Curse of Talion might do six points of bashing damage, four points of lethal damage or two points of aggravated damage to a supernatural target. The Curse may also manifest as a debilitating but temporary curse; a slanderer may lose her voice for a month, for instance."]},{type:"line",label:"Exceptional Success",text:["The severity of the Curse is increased, even for supernatural targets."]}]}]},{Name:"Knowledge",Description:"",Cost:"",Book:"WtF 126",Content:[{type:"paragraph",text:"Few things are more useful than knowledge, and some spirits know secret shortcuts to learning interesting things. Where Gifts of Insight allow a werewolf to see the world through a different set of eyes, Gifts of Knowledge involve simply reaching out, plucking a fact or piece of data from the greater weave of the world and putting it to use. Iron Masters, with their desire to learn as much as they can about the changing world, are particularly drawn to Knowledge Gifts, but any werewolf can find them useful."},{type:"paragraph",text:"Gifts of Knowledge are typically taught by spirits that represent wisdom or information, and are frequently urban. Spirits of computers are one source, as are rat- and cockroach-spirits."}],Ranks:[{Rank:"•",Name:"Know Name",Description:"Learn anyone's name",Cost:"-",Book:"WtF 126",fullDescription:[{type:"paragraph",text:["To understand something, one must first know its name. This Gift is a simple trick, but one with potentially wide-ranging applications. With a glance, the werewolf can learn the name of someone she sees in person. The name learned is always one that the person would answer to and consider his own. The character cannot use this Gift on a person that she sees indirectly (through a video camera or in a photograph)."]}],fullCost:"None",dicePool:"Intelligence + Investigation + Cunning versus subject’s Resolve + Primal Urge (see below)",action:"Instant or contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf picks up a different and wholly inappropriate name. She might learn the name of someone else in the room or of the target’s fourth-grade teacher and assume it belongs to the target."]},{type:"line",label:"Failure",text:["The werewolf fails to learn the target’s name. She cannot try to use this Gift on the same target again this scene."]},{type:"line",label:"Success",text:["The character learns the target’s name as the target defines it. Using this Gift on a werewolf produces the target’s name among the People, unless the target thinks of himself primarily by his human name. If the target has some reason to hide his name, such as a vampire who avoids people he knew in life or an undercover cop, then a reflexive, contested Resolve + Primal Urge roll may be made for the target. The target remains unaware of the Gift being used, and of his resistance."]},{type:"line",label:"Exceptional Success",text:["The character learns all the names to which the target answers (assuming the subject doesn’t successfully contest the roll). For example, she may learn the birth name, Uratha deed name and current nickname of a subject werewolf."]}]},{Rank:"••",Name:"Traveler's Blessing",Description:"Learn anywhere language and way of life",Cost:"○/s",Book:"WtF 126",fullDescription:[{type:"paragraph",text:["A werewolf’s road can take her a long way from home, but spirits can guide her as she goes. This Gift teaches the werewolf the basics of what she needs to know about whatever human culture in which she finds herself. As she calls on her spirit-wisdom, the local language settles into her mouth and knowledge of local customs wraps around her mind. Though still a stranger wherever she goes, she need never be an ignorant one."]}],fullCost:"1 Willpower per scene",dicePool:"Wits + Streetwise + Wisdom",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character receives a dangerous mix of misinformation and true information. She gains only basic fluency in the local language, and her faulty information imposes a -1 penalty to all Social rolls for the remainder of the scene."]},{type:"line",label:"Failure",text:["The werewolf learns nothing she didn’t already know."]},{type:"line",label:"Success",text:["The werewolf gains competent fluency in the most commonly spoken language of the area that she doesn’t already know. A werewolf in Texas who already speaks English but not Spanish gains fluency in Spanish, despite the greater proportion of English-speakers. In addition, she becomes aware of local customs to some degree, granting her a +1 modifier to all Social rolls made to influence locals. Traveler’s Blessing cannot be used to learn non-human languages. For example, the werewolf could not enter the Shadow and use the Gift to gain full fluency in the First Tongue."]},{type:"line",label:"Exceptional Success",text:["The werewolf’s bonus to Social rolls made to influence locals rises to +2."]}]},{Rank:"•••",Name:"Sagacity",Description:"Learn skills (1 dot per success for 1 minute per success)",Cost:"●",Book:"WtF 127",fullDescription:[{type:"paragraph",text:["Though a true devotee of knowledge spends years learning Skills and facts as thoroughly as possible, sometimes a shortcut is necessary. This Gift allows a werewolf to become an instant expert in the field of choice. Knowledge floods her mind and leaves just as rapidly, but she can accomplish things in the interim that it would take years of study to do."]}],fullCost:"1 Essence",dicePool:"Wits + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character taps into inaccurate and misleading information. She suffers a -1 penalty on all attempts to use the nominated Skill for the rest of the scene. This is cumulative with any -1 or -3 penalty for untrained Skill use."]},{type:"line",label:"Failure",text:["The character gains no additional knowledge."]},{type:"line",label:"Success",text:["The character temporarily gains dots in the Skill of choice equal to the number of successes rolled. The result cannot raise any Skill above five dots. The Skill bonus lasts for one minute per success rolled. The only thing that Skills gained from this Gift cannot do is be used to activate other Gifts. Instant expertise in Stealth does not convey the kind of covert understanding needed to properly use an Evasion Gift, for example. The character’s standard dots in the Skill in question (if any) are rolled to activate a Gift. No more than one Skill can be elevated at a time, and the character may increase only her own trait dots, not those of others."]},{type:"line",label:"Exceptional Success",text:["The duration of the Gift’s effects increases to five minutes per success rolled."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["-1","Social Skills"],["-3","Physical Skills"]]}]},{Rank:"••••",Name:"Know the Path",Description:"Know the best path to his destination",Cost:"●",Book:"WtF 127",fullDescription:[{type:"paragraph",text:["Not all werewolves hunt by scent. The werewolf with this Gift draws forth knowledge of the quickest path to wherever she wants to go, be it the safe house of an allied pack or the heart of a Beshilu infestation. The quickest and most efficient path isn’t always the safest, but so it goes."]}],fullCost:"1 Essence",dicePool:"Wits + Survival + Glory (versus subject’s Resolve + Primal Urge)",action:"Instant or contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character perceives an improper path, one that leads someplace considerably less useful and potentially more dangerous."]},{type:"line",label:"Failure",text:["The character fails to discern the proper path and cannot use this Gift again until after the next moonrise."]},{type:"line",label:"Success",text:["The character visualizes the closest and most efficient route to the location she wishes. The information is stored in her head as a precise set of directions, allowing her to spend minimal time checking for landmarks. This Gift does not reveal the presence of dangers or obstacles along the way, unless they are specific landmarks. (“Turn left at the open chemical vats.”) If the location in question is kept secret by its owner (such as a vampire’s haven), the roll is contested. Roll Resolve + Primal Urge for the subject. If the place is shared by multiple people, roll the lowest Resolve + Primal Urge pool among them. The Gift user must be in the physical presence of someone whose secret lair is discerned. If a subject ties or wins the roll, he cannot be subjected to this Gift again for 24 hours. This Gift cannot locate the path to a place that is magically veiled or that exists on another plane of existence. The character can, however, use the Gift in the Shadow Realm to find the way to another location in the spirit world. The Gift effects last for a scene. If the character doesn’t reach her destination in that time, she must use the Gift again, or Intelligence + Composure can be rolled to remember the details (",{text:"World of Darkness Rulebook",bold:!0},", p. 44)."]},{type:"line",label:"Exceptional Success",text:["The character learns not only the most efficient route to the desired location, but also the safest. She might not choose the safest, but the option is there."]}]},{Rank:"•••••",Name:"Communion with the Land",Description:"Gain knowledge of everything around him (+2 to Defense and Initiative)",Cost:"●",Book:"WtF 127",fullDescription:[{type:"paragraph",text:["In war, knowledge of the terrain is key to victory. This Gift is an expression of that maxim. The werewolf opens her mind to her environment and gains knowledge of the terrain around her — where enemies are, where she can hide, where the best avenues of attack lie. When used on the home territory of an enemy, the werewolf might find she knows more about her foe’s home ground than he does."]}],fullCost:"1 Essence",dicePool:"Intelligence + Streetwise + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character gains conflicting messages about her surroundings. She suffers a -1 penalty to Initiative until the scene ends or she leaves the area."]},{type:"line",label:"Failure",text:["The character gains no knowledge of her surroundings."]},{type:"line",label:"Success",text:["The character immediately gains full knowledge of her surroundings with regard to potential entrances and exits, the number of creatures larger than a rat present and general terrain features. While she remains in the area, a +2 bonus to Defense and Initiative is gained. The area to which she can attune herself is roughly equal to one acre per success. The Gift effects last for a scene."]},{type:"line",label:"Exceptional Success",text:["As success, but the bonus to Defense and Initiative is +3."]}]}]},{Name:"Mother Luna",Description:"",Cost:"",Book:"WtF 128",Content:[{type:"paragraph",text:"The ability to change form was a gift to the Forsaken from Luna herself, and assuming the five forms comes as naturally to werewolves as breathing. There are nuances to the art, however, that can be mastered only with experience and instruction. This is an open Gift list; any werewolf character can possess Mother Luna’s Gifts as if they had auspice or tribal affinity with them. Werewolves most often learn Mother Luna’s Gifts from the Lunar Choirs, but they can be taught by various spirits associated with trickery, such as coyote- or monkey-spirits."}],Ranks:[{Rank:"•",Name:"Partial Change",Description:"Shapeshift only part of his body",Cost:"(●)",Book:"WtF 128",fullDescription:[{type:"paragraph",text:["This subtle Gift allows a werewolf to transform only the parts of himself that he needs in order to complete a task at hand. For example, a werewolf in Hishu form might transform only his nose in order to track someone through the city streets by scent, without drawing the attention to himself that transforming into Urhan would attract. Conversely, a werewolf in Urhan form might transform his eyes to human to gain sharper color vision."]}],fullCost:"None (or 1 Essence)",dicePool:"Stamina + Survival + Primal Urge. The player has the option of rolling this dice pool, with the intended change occurring if even one success is achieved. In this case, the change is an instant action. Or, he may spend one Essence for his character to change automatically as a reflexive action.",action:"Instant or reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["Another feature of a different form is assumed instead of the one intended (the Storyteller decides which). Human onlookers are subject to Lunacy as if their Willpower is two dots higher than normal."]},{type:"line",label:"Failure",text:["No change occurs."]},{type:"line",label:"Success",text:["The werewolf chooses which parts of himself he transforms. The result might allow him to use certain abilities normally restricted to other forms (such as tracking by scent or using claws in Hishu; the Storyteller decides what modifiers transfer over). Though he may change as much or as little as he wishes, the choice is final. To add or subtract any feature requires another use of the Gift (so “undoing” features also requires another application of the power). The Storyteller decides if and how any human onlookers might spot the character’s features and potentially suffer Lunacy. If it is triggered, normal rules apply and subjects’ Willpower is considered one higher than normal."]},{type:"line",label:"Exceptional Success",text:["The change occurs as a reflexive action without the expenditure of an Essence point."]}]},{Rank:"••",Name:"Anybeast",Description:"Change into any animal",Cost:"●",Book:"WtF 129",fullDescription:[{type:"paragraph",text:["The boundary between spirit and flesh is no less threatened in portions of the land where wolves don’t roam. This Gift allows a werewolf to temporarily camouflage itself in the skin of another carnivorous beast. Urhan form might come to resemble a hyena, while a werewolf might use the skin of a grizzly bear to disguise his Urshul form."]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Instant",rollResults:[{type:"paragraph",text:["This Gift can affect the character’s Dalu, Gauru, Urshul and Urhan forms, within reason. The animal form to be mimicked must have the same general size and build for the werewolf to duplicate it in Urshul or Urhan form. A werewolf couldn’t appear to be a bear in Urhan form, as a bear is simply too large, and taking the form of an eagle or wolverine is outright impossible. Traits don’t change, nor do modifiers to attacks or actions. The character retains the capabilities of his own form."]},{type:"paragraph",text:["The Gift effects last even if the character shapeshifts into Dalu or Gauru form, although disguise is no longer a possibility. Instead, the werewolf appears to be a hybrid of human and the appropriate carnivore. A werewolf mimicking a tiger in Urshul form might appear to be a monstrous tiger-man if he takes Gauru form before the Gift effect ends."]},{type:"paragraph",text:["The Gift lasts for the duration of the scene, or until the character chooses to end its effects."]}]},{Rank:"•••",Name:"Silver Jaws",Description:"Claws and fangs become silver",Cost:"●",Book:"WtF 129",fullDescription:[{type:"paragraph",text:["The Lunes, particularly those of the Elunim choir, can teach a werewolf to become his own nightmare. Use of this Gift transforms the werewolf’s teeth and claws into an array of terrible silver weaponry. Use of this Gift is a clear sin against Harmony, which has led may werewolves to wonder precisely why it is that Elunim are willing to lead Uratha astray in such a fashion. Is it some sort of test or simply the caprice of Mother Luna at work?"]}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Instant",rollResults:[{type:"paragraph",text:["This Gift changes a werewolf’s teeth and nails into pure silver. Once transformed, they inflict aggravated rather than lethal damage against werewolves. This Gift doesn’t function in Hishu form unless the character also uses Partial Change to give himself claws or wolf-like fangs. The character is not adversely affected by the silver parts of his own body. They also add a bonus die to attempts to use Intimidation on those vulnerable to silver."]},{type:"paragraph",text:["This Gift lasts for one scene. Using this Gift against another werewolf requires a roll to resist degeneration if the character’s Harmony is 4 or higher (see page 181)."]}]},{Rank:"••••",Name:"Skin-Stealing",Description:"Change into any human",Cost:"●",Book:"WtF 129",fullDescription:[{type:"paragraph",text:["Old human legends describe werewolves as creatures that learned the art of shapeshifting by dressing in the skins of wolves. This Gift lends some credence to those stories, for the werewolf who has learned its secret can garb himself in the skin of almost any human whose blood he has tasted. The disguise created is almost perfect — disturbingly so."]}],fullCost:"1 Essence",dicePool:"This power requires no roll to activate.",action:"Instant",rollResults:[{type:"paragraph",text:["When activated, the Gift sheathes the werewolf in a brand-new skin. The new skin is not part of the character’s body; it’s more like a full-body glove. It fits perfectly, though, and the Gift transforms the character’s body to fit the dimensions of the imitated individual. Therefore, the character’s Hishu form shrinks if he’s impersonating a particularly small person or swells if he’s wearing the stolen skin of an obese person. Although the werewolf “wears” the skin, the skin is warm to the touch, sweats and bleeds in perfect imitation of living tissue. The new skin doesn’t cover the eyes or orifices, however, and the werewolf may still be given away by different eye color or dental work. This Gift can duplicate the skin of a mage or an ordinary human, but not that of a vampire or other undead creature. This Gift can also duplicate the skin of a werewolf, and it is retained throughout all five forms, although the cost increases to two Essence."]},{type:"paragraph",text:["The new skin grants four bonus successes to any disguise rolls (",{text:"World of Darkness Rulebook",bold:!0},", p. 87) made to impersonate the subject in question. The stolen skin gives off the same scent as the impersonated being and masks the werewolf’s own scent. The character’s Attributes are unmodified. Even if the skin seems to grant an additional 250 pounds of fat, the character loses none of his Dexterity."]},{type:"paragraph",text:["The character must remain in Hishu form to use this Gift. If the character shapeshifts while still wearing a false skin, the skin tears apart and is shed. (The exception is if the character “borrows” a werewolf’s skin. In this case, an additional Essence keeps the skin intact when shapeshifting, mimicking the subject’s appearance in all forms.)"]},{type:"paragraph",text:["The effects of the Gift last for a scene, although the character may end them sooner by tearing off the skin or shapeshifting. Once the skin has been discarded, it quickly breaks down into dust of indeterminate origin. Although the skin is perfect enough that DNA testing could reveal it to be that of the person mimicked (rather than that of the character using the Gift), it breaks down too quickly to be of any use afterward."]}]},{Rank:"•••••",Name:"Primal Form",Description:"Shapeshift into a gigantic wolf form for 1 turn per success",Cost:"●",Book:"WtF 129",fullDescription:[{type:"paragraph",text:["The werewolf who learns this Gift goes beyond the already terrifying power and savagery of the children of Luna and becomes something truly monstrous. This Gift calls on the power of a time when Luna looked down upon Pangaea, transforming the user into a creature that’s one part prehistoric beast and one part pure nightmare. Werewolves among the Forsaken use this Gift only in times of dire need, because they fear it will drive them to acts of violence unspeakable even to them, and because the form has another, more sinister reputation. The greatest among the Pure Tribes known as the Predator Kings have long learned this Gift for a very specific purpose — to them, Primal Form is meant specifically for hunting the Forsaken."]}],fullCost:"1 Essence",dicePool:"Stamina + Survival + Primal Urge (The dice pool normally rolled to change shape applies, as opposed to one involving a Renown trait.)",action:"Instant (Unlike a conventional shapechange, one Essence cannot be spent to make this one reflexive.)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character fails to assume Primal Form, and the strain of the effort exhausts him. He may not attempt to change to ",{text:"any",italic:!0}," other form or use any of Mother Luna’s Gifts for five turns."]},{type:"line",label:"Failure",text:["The character fails to assume Primal Form."]},{type:"line",label:"Success",text:["The character shifts into a form that resembles Urshul, but that is even larger. Primal Form stands six to eight feet tall at the shoulder. It’s treated as Urshul in most respects, including the general inability to speak (see p. 172), with the following exceptions:"]},{type:"list",items:[["The form’s dot modifiers are: Strength +4, Dexterity +2, Stamina +4, Manipulation -3, Size +3, Health +7, Initiative +2, Speed +9. The character is treated as having 2/1 armor due to the form’s thick hide."],["The character causes Lunacy as if he were in Gauru."],["The character heals one point of lethal damage per turn, at the beginning of his turn. This replaces the one point of bashing damage that werewolves normally heal per turn unless the character has suffered only bashing damage. (If the player spends a point of Essence to heal — see p. 168 — the character regenerates an additional point of lethal damage.)"],["All Resolve + Composure rolls to resist Death Rage are at -3."]]},{type:"paragraph",text:["The character can remain in Primal Form for one turn per success achieved on the power’s activation roll. Unlike other Mother Luna’s Gifts, the character ",{text:"cannot",italic:!0}," voluntarily choose to end this Gift’s effects prematurely unless a successful Resolve + Composure roll is made at a -3 penalty."]},{type:"line",label:"Exceptional Success",text:["The glorious fury that accompanies Primal Form rushes through the character without forcing him to lose control… yet. The character also regains a Willpower point."]}]}]},{Name:"Nature",Description:"",Cost:"",Book:"WtF 130",Content:[{type:"paragraph",text:"The Gifts of Nature are similar to Elemental Gifts in that both deal with the environment and the surroundings of the world. Nature Gifts, however, focus not on the elements but on the specific flora and fauna of the wild. The Hunters in Darkness in particular have affinity with these Gifts, and any werewolves who have frequent dealings with animals and growing things find the Gifts useful. Spirits of animals, trees and plants teach these Gifts."}],Ranks:[{Rank:"•",Name:"Speak with Beasts",Description:"Communicate with animals",Cost:"-",Book:"WtF 130",fullDescription:[{type:"paragraph",text:["Werewolves must often talk with other animals to gather information or make bargains. This Gift allows them to communicate with both voice and body language to speak and listen to animals, though an animal is under no obligation to listen to or agree with what a werewolf says."]}],fullCost:"None",dicePool:"Manipulation + Animal Ken + Purity",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The animal is spooked and attempts to flee or fight."]},{type:"line",label:"Failure",text:["The character cannot achieve communication."]},{type:"line",label:"Success",text:["The character can speak so as to be understood by any known animal, as well as understand what the animal might “say.” The creature in question is still fearful, and it might not listen to the werewolf. The effects last for one minute."]},{type:"line",label:"Exceptional Success",text:["The character is able to make himself particularly clear, gaining a +1 bonus to any Social rolls made to influence animals for that application of the power."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+2","The animal is a wolf"],["+0","The animal is another predator"],["-1","The animal is a “prey animal,” something that fears wolves"],["-3","The animal is an insect or fish"]]}]},{Rank:"••",Name:"Plant Growth",Description:"Increase and direct plant growth",Cost:"○",Book:"WtF 130",fullDescription:[{type:"paragraph",text:["The werewolf can cause any living plant to grow at a phenomenal rate, shaping the growth to her whim. Some Hunter in Darkness packs have thick thorn hedges surrounding their territorial borders, or live in literal tree houses."]}],fullCost:"1 Willpower",dicePool:"Wits + Survival + Honor",action:"Instant",rollResults:[{type:"paragraph",text:["Each success rolled increases the size of a plant or group of plants by a cubic yard, at a rate of one minute per cubic yard. The vegetation can grow in whatever shape desired. The effects of the growth are permanent, though the plants can be trimmed or destroyed as usual. One or two successes are required to create a simple shelter for an individual. Five successes can turn a sapling into a 20-foot-tall tree."]}]},{Rank:"•••",Name:"Forest Communion",Description:"Gain information from natural landscape",Cost:"●",Book:"WtF 130",fullDescription:[{type:"paragraph",text:["The forest is alive, and much can be gleaned by those who know how to listen. With this Gift, a werewolf can sense much about the life around her: the tread of boots on the earth, fleeting images through the eyes of an owl or fox, or the scent of recent visitors."]}],fullCost:"1 Essence",dicePool:"Manipulation + Survival + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overwhelmed by the amount of information, suffering a -1 penalty to Wits rolls for the remainder of the scene."]},{type:"line",label:"Failure",text:["The character cannot establish communication."]},{type:"line",label:"Success",text:["The user slips into a trancelike state. Successful activation of this Gift allows basic information (presence of intruders, potential threats such as fires) up to 500 yards from the werewolf. Each additional success increases the radius by an additional 100 yards and increases the detail of information learned. One success could tell the presence of intruders, while three successes could reveal the species and gender of those intruders. The Gift lasts as long as the user remains in the trance, but she is unaware of and cannot react to the outside world, nor can she relay her findings while the Gift is active. This Gift doesn’t function in an urban environment."]},{type:"line",label:"Exceptional Success",text:["No additional effect apart from greater range and increased information."]}]},{Rank:"••••",Name:"Beast Ride",Description:"Possess animals",Cost:"●",Book:"WtF 131",fullDescription:[{type:"paragraph",text:["With this Gift, the werewolf can enter the mind of a mammal or bird, exerting some influence over where it goes and sensing what it does. The Gift works only on mundane mammals or birds, not on werewolves or other supernatural beings in animal form, or on animals that are Spirit-Ridden."]}],fullCost:"1 Essence",dicePool:"Wits + Animal Ken + Wisdom - animal’s Resolve",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["Mannerisms and thought patterns of the animal intended to be ridden haunt the character, instead. All Social rolls made for the next 24 hours suffer a -2 penalty."]},{type:"line",label:"Failure",text:["The werewolf’s spirit doesn’t take possession of the animal."]},{type:"line",label:"Success",text:["The werewolf must be able to see the animal to bond with it. Once joined, the character’s body is comatose and cannot be roused. The character is aware of any contact or harm that befalls his body, however, and can return instantly at any time. The werewolf is normally simply a “passenger” in the animal, though he may exert control if this Gift is successfully activated at a -2 penalty. The ride lasts one hour for each success rolled, and he may travel as far from his body as he wishes. While the werewolf possesses an animal, any injuries inflicted on the animal also appear on the [unclear]"]}]},{Rank:"•••••",Name:"Nature's Vengeance",Description:"Vegetation attacks the target (-2 to Speed, -1 to all rolls, 1 - 3 points of bashing damage per turn)",Cost:"●",Book:"WtF 131",fullDescription:[{type:"paragraph",text:["For countless millennia, humans have exploited the forest. This Gift lets the forest fight back. Branches smash, vines constrict and grass entangles those that the werewolf marks as enemies."]}],fullCost:"1 Essence",dicePool:"Intelligence + Survival + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The forest animates, but not under the werewolf’s control — plants attack packmates as well as enemies."]},{type:"line",label:"Failure",text:["The character cannot rouse the spirits of the land."]},{type:"line",label:"Success",text:["Each success animates roughly 25 square yards worth of vegetation. The Gift user can be amid the area affected, or he needs to be able to see the area he intends to affect. Generally speaking, the vegetation can do little more than hit, trip, grab and squeeze. A patch of ivy has the equivalent of Strength 2, while an old oak might have a Strength of 10 or more. Each victim suffers a -2 reduction to Speed due to grasses and weeds pulling at its feet. Victims might also suffer a -1 penalty to other rolls while being accosted, depending on the action and how much vegetation is present. For example, an intruder in an animated wheat field would not suffer a penalty to a Firearms roll, as his arms would be free of the plants’ reach, while a person in a patch of kudzu might suffer a penalty to any roll that involves physical action. In addition, each victim may be the subject of one attack from nearby vegetation each turn. Anywhere from one to three bashing damage (as determined by the Storyteller) may be inflicted automatically, based on how dense the local foliage is. This damage ignores armor and a subject’s Defense. The plants settle down at the end of the scene."]},{type:"line",label:"Exceptional Success",text:["The plants manifest unusual vigor and cause one extra penalty point (Speed is reduced by -3 instead of -2, for example). Damage increases by one point per turn."]}]}]},{Name:"New Moon",Description:"",Cost:"",Book:"WtF 132",Content:[{type:"paragraph",text:"The Irralunim Lunes of the New Moon Choir are the recorders and arbiters of Cunning Renown, and the patrons of the Irraka auspice. The Gifts they grant remove minor obstacles that stand in the way of greater, brilliant feats."},{type:"paragraph",text:"The following Gifts are available only to Irraka."}],Ranks:[{Rank:"•",Name:"Sense Weakness",Description:"Learn target's weaknesses (Vice, derangements or Flaws)",Cost:"-",Book:"WtF 132",fullDescription:[{type:"paragraph",text:["One of the clearest indicators of a person’s ingenuity is his ability to use his enemies’ weaknesses to his advantage. The Irralunim respect such efforts, and they offer this Gift to their chosen werewolves to make those efforts a little easier."]},{type:"paragraph",text:["If the character spends even a little time (one turn) observing his intended target, he can draw on the supernatural perception of this Gift to analyze the potential flaws in his target’s mind and body. This Gift reveals weaknesses that aren’t common to the subject’s kind. It doesn’t reveal a vampire’s weakness to sunlight (which is not a personal weakness), but it does reveal that the vampire suffers from a particular psychological ailment."]}],fullCost:"None",dicePool:"Intelligence + Empathy + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf garners a false impression about the subject’s weaknesses. The Storyteller might want to make activation rolls on the player’s behalf for this reason."]},{type:"line",label:"Failure",text:["The werewolf gains no particular hidden insight into the subject."]},{type:"line",label:"Success",text:["The werewolf learns a target’s weakness in one of three specific areas: his target’s Vice, the presence and nature of any derangements from which the target suffers, or any physical liabilities (Flaws) the character suffers (such as a bad leg or poor eyesight). Already known weaknesses are not revealed. The Storyteller decides which is discovered. The Gift can be used successfully on a single subject only once a day. Subsequent uses in the same day reveal no further flaws."]},{type:"line",label:"Exceptional Success",text:["In one use, the werewolf learns two of the three possible types of weakness he could discover."]}]},{Rank:"••",Name:"Slip Away",Description:"Escape any physical binding",Cost:"○",Book:"WtF 132",fullDescription:[{type:"paragraph",text:["If an Irraka doesn’t enter a dangerous situation, he isn’t doing his job. When he does find trouble, it’s up to him to use cunning to get out of it again. Even the clever werewolf gets caught from time to time, however. The Irralunim provide this Gift as a first step toward helping Irraka get out of the dicey situations."]}],fullCost:"1 Willpower",dicePool:"No roll is required to escape ropes, chains et cetera.",action:"Reflexive",rollResults:[{type:"paragraph",text:["With the expenditure of one Willpower point, an Irraka can use this Gift to escape any mundane bond or to wriggle free of an attacker’s arms with little apparent effort. If the werewolf is bound physically (be it with handcuffs, rope, chain, a straitjacket, duct tape or even a dollop of industrial-strength adhesive), this Gift frees him automatically. The bonds remain sound and unbroken (as well as locked, buckled or even sticky, depending on its nature), but the werewolf slips out effortlessly — often leaving would-be captors wondering how in the world he did it."]},{type:"paragraph",text:["If the werewolf is locked in a grapple by another person and tries to break free he automatically succeeds. This benefit does not apply to performing overpowering maneuvers of the werewolf’s own, only on efforts to escape a hold."]},{type:"paragraph",text:["This Gift does not allow the Irraka to slip out of bindings that have active magical effects working on them."]}]},{Rank:"•••",Name:"Distractions",Description:"Create a distracting hallucination (-2 to all rolls)",Cost:"●",Book:"WtF 132",fullDescription:[{type:"paragraph",text:["Being werewolves, Irraka are no slouches in a fight, but their true strengths lie in cleverness and misdirection. The heat of desperation can make it difficult to think originally on demand, so this Gift buys a werewolf time to improvise."]},{type:"paragraph",text:["As the character spits out whispering yips and hisses, half-perceived visions much like the Irralunim themselves flit in and out of a chosen subject’s range of perception, distracting him. Only the chosen target can perceive these spirit echoes, but they cause such a distraction that the victim suffers a -2 modifier to all rolls in every turn in which the Irraka keeps up his antics. This effect works especially well in combat, but an Irraka can also use it to distract a security guard he’s trying to sneak past or to distract the driver of a car in order to cause a diversionary traffic accident. The Irraka must be able to see his chosen victim directly in order to distract him, but the victim need not be able to see or hear the Irraka. A character may maintain the effect of this Gift and move normally, but he may not attack or run in the same turn and maintain the effect. His Defense modifier still applies as normal."]},{type:"paragraph",text:["Only one use of this Gift may be in effect at one time, and only one subject can be made to see the visions."]}],fullCost:"1 Essence",dicePool:"Manipulation + Subterfuge + Glory versus subject’s Resolve + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The victim is unperturbed by the character’s efforts, and further uses of this Gift are powerless against him until the next moonrise."]},{type:"line",label:"Failure",text:["The victim is unperturbed by this Gift for the moment."]},{type:"line",label:"Success",text:["The victim is distracted by the character’s efforts, incurring a -2 penalty on all actions."]},{type:"line",label:"Exceptional Success",text:["As a success, but the victim also loses his Defense against incoming close-combat attacks in the turn after the Gift is activated."]}]},{Rank:"••••",Name:"Blend In",Description:"Disappear into crowds",Cost:"●",Book:"WtF 133",fullDescription:[{type:"paragraph",text:["This Gift makes a werewolf appear as if he belongs in whatever environment into which he steals. He doesn’t disappear from view or match ambient color patterns like a chameleon does, but neither does his presence attract especial attention. He appears to be nothing more than a face in the crowd, even to traditional, digital or fiber-optic cameras. Regardless of his attire or attention to personal hygiene, the werewolf doesn’t appear to be at all out of place. Even if he’s in blood-stained sweats and a duster walking through the headquarters of a Wall Street brokerage firm, his mere presence doesn’t make others sit up and take notice."]},{type:"paragraph",text:["The protective anonymity that this Gift provides protects the werewolf only so far, though. If he goes out of his way to draw attention to himself by doing anything notable (say, by starting a fight, changing forms in front of someone, kicking open an emergency fire door or tackling an oblivious pedestrian who’s about to be hit by a car), the effect ends. Otherwise, the Gift lasts for a scene. The effects remain active if the Irraka talks to the people around him or otherwise interacts with them unobtrusively (such as chatting in an elevator or waving nonchalantly to a security guard behind a bank of monitors). The Gift cannot fool security devices such as hand-scanners, retina-scanners, voice-recognition systems or number pads that require a key-code or password, but it can evade facial-recognition software that someone is using it to try to pick the werewolf out of a crowd. A security measure as simple as needing to sign a logbook at a security station, or handing over a ticket at the door of a bus or plane can be problematic unless the Irraka takes an opportunity to mingle discreetly at the scene. Finally, this Gift cannot protect the Irraka if there’s a lack of genuine bystanders with which to blend. He could not, for example, infiltrate a corporation’s Board of Directors meeting, where an extra head would quickly be noted. He might, however, be able to crash a small, invitation-only affair by mingling with the caterers rather than the guests."]},{type:"paragraph",text:["Supernatural forms of awareness might be able to see through the effect, but only if they are of an equal or greater level. If the level is greater, the user of that power sees the truth behind the Irraka’s efforts automatically. If its level is equal, the number of successes achieved to activate Blend In must exceed those rolled for the detecting character’s power."]},{type:"paragraph",text:["The Gift user must be in Hishu form to use this power; it doesn’t work when he’s in any other form."]}],fullCost:"1 Essence",dicePool:"Wits + Subterfuge + Cunning versus the highest Wits among observers",action:"Instant and contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character accidentally draws immediate attention to himself and cannot use Blend In again for the rest of the scene."]},{type:"line",label:"Failure",text:["An equal or the most successes are rolled for observers. The character must rely on his mundane abilities to not draw attention to himself."]},{type:"line",label:"Success",text:["The most successes are rolled for the character, and he blends into the environment that surrounds him for the rest of the scene."]},{type:"line",label:"Exceptional Success",text:["The most successes — five or more — are rolled for the character. He blends in so well that witnesses have trouble even remembering that he was present at all. They incur a -1 penalty to any rolls made to remember anything about the werewolf or what he was up to."]}]},{Rank:"•••••",Name:"Ghost Step",Description:"Steps in Twilight (-5 to perception rolls to detect him. She cannot affect physical world)",Cost:"●",Book:"WtF 133",fullDescription:[{type:"paragraph",text:["Some Irraka can miraculously escape from danger unscathed, even when trouble waits for them on both sides of the Gauntlet. And some can find out damning information that, by all rights, should have long since been buried or forgotten. The trick of the Ghost Step allows a werewolf to become immaterial, his body transformed to spirit matter yet not conveyed across the Gauntlet."]},{type:"paragraph",text:["The character becomes an insubstantial, ghostly form, only barely perceptible as translucent mist. He cannot be affected by any physical attack while using this ability; he has no scent, and cannot make any sound even if he wishes. It is particularly difficult to detect the ephemeral Irraka via sight, and any perception rolls made to detect him incur a -5 penalty. He is effectively in Twilight, much as an unmaterialized spirit in the physical world is (see p. 252)."]},{type:"paragraph",text:["While insubstantial, the Irraka cannot affect the physical world in any way, not even with Gifts. He doesn’t fall unhindered through floors or sink into the poured foundations of the structures that surround him if he doesn’t want to — the generally accepted laws of physics apply. With a little effort, though, he can leap up into the ceiling of a room, catch hold, and pull himself up through the roof or floor above him."]},{type:"paragraph",text:["While the Irraka remains in this ephemeral state, he can walk and use Gifts that affect himself rather than the physical world, and can change forms as usual, but he cannot remain ephemeral indefinitely. After a number of turns equal to his Harmony score, the werewolf begins to experience a sensation of being stretched thin. The Irraka begins to suffer a -1 penalty to all rolls for each turn that he spends ephemeral beyond the limit based on Harmony. He may choose to end the Gift’s effects at any time. The Gift also ends if he’s somehow rendered unconscious, such as if overcome by spirits also in Twilight."]},{type:"paragraph",text:["The personal possessions worn by a werewolf change with him when he becomes ephemeral. He cannot carry large items such as shotguns or crates and have them transform with him, although a fetish weapon does make the transfer."]},{type:"paragraph",text:["The ephemeral state is also shared by disembodied spirits that have entered the physical world as well as human ghosts, who can see and hear the displaced Irraka."]},{type:"paragraph",text:["An ephemeral spirit or ghost can affect the Irraka, and vice versa, as if they were both solid. Spirits, of course, are likely to take the presence of an ephemeral werewolf very badly, as it’s a predator that can bodily injure or kill them. Ghosts run the same gamut of emotions, predispositions and prejudices as the living do, so there’s no telling how one might react to a werewolf passing through, but ghosts don’t suffer Lunacy like the living do. Some guard what territory they’ve staked out, going so far as to attack a werewolf in hopes of driving him away. Others mindlessly repeat some task that absorbed them in life, remaining unaware of a werewolf no matter what happens. Still others are just so happy to encounter another intelligent soul that they do what they can to keep the werewolf from leaving. Some adventurous ghosts might even follow a werewolf around and manifest in the living world for as long as they can, starving for the contact and social interaction of which their deaths have bereaved them."]},{type:"paragraph",text:["For more information on ghosts, see the ",{text:"World of Darkness Rulebook",bold:!0},", p. 208."]}],fullCost:"1 Essence",dicePool:"Wits + Survival + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf slips into the spectral state as intended, but finds himself surrounded by angry ghosts who mean him harm. Also, he can stay in this place for one less turn than he would have been able to normally before the penalties begin to kick in."]},{type:"line",label:"Failure",text:["The character is unable to become ephemeral, but the Essence point is still spent."]},{type:"line",label:"Success",text:["The character becomes ephemeral as described."]},{type:"line",label:"Exceptional Success",text:["The character may remain in ephemeral form without penalty for one extra turn."]}]}]},{Name:"Opening",Description:"",Cost:"",Book:"LodgF 50",Content:[{type:"paragraph",text:["Doors, minds, pathways — all of these things function best when open. The Lodge of Doors dedicates itself to opening the gates of knowledge, and the Opening Gifts provide the means to do so. What they do not provide, though, is a way to ",{text:"detect",italic:!0}," secrets or knowledge. The Lurker in Doorways and its spiritual brethren can provide the means to open a door, once the Uratha has found it. Spirits of creatures that excel in bypassing barriers, such as raccoons and rodents, often teach Opening Gifts."]}],Ranks:[{Rank:"•",Name:"Word of Opening",Description:"Any barrier to information opens, provided it is not locked.",Cost:"-",Book:"LodgF 50",fullDescription:[{type:"paragraph",text:["A common saying in the lodge is, “Try every door. You never know what’s unlocked.” Indeed, many Lurkers are surprised to find how easy it is to gain access merely by trying the most obvious methods. This Gift allows the Uratha to open an unlocked door, turn on a computer or even flip a rock with a gesture."]},{type:"paragraph",text:["A werewolf can use Clear the Way either on a deliberate target or simply to see what opens. In either case, the character simply makes a fist and then opens it, focusing either on his immediate area or on the object he wishes to open. The Gift only functions on objects within a 15-foot radius of the character and only on objects that might lead to knowledge or information (computers, filing cabinets, doors and books are just a few examples). If the object is locked or barred in any way, the Gift does not function. A book lying closed on a table can be opened with this Gift, but a book on a shelf wedged between other books cannot."]}],fullCost:"None",dicePool:"Dexterity + Larceny + Honor",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["All objects with the capacity to lock within the area of effect immediately do so. Computers require a password, doors lock to whatever degree they are able and even books won’t open unless someone reads the title aloud."]},{type:"line",label:"Failure",text:["Nothing happens."]},{type:"line",label:"Success",text:["If the werewolf is using the Gift on a specific target, it opens, provided it was not locked or barred in any way. If the Uratha was merely using the Gift on an area, one applicable object opens. The Storyteller decides what this object is. It might not be anything useful to the character."]},{type:"line",label:"Exceptional Success",text:["No special effect if the character is targeting a specific object. If the character is using the Gift on an area, the object that opens is in some way directly useful (or leads to something directly useful) to him."]}]},{Rank:"••",Name:"Lurker’s Key",Description:"Attempts to open a barrier, be it physical or digital, with a bonus.",Cost:"●",Book:"LodgF 50",fullDescription:[{type:"paragraph",text:["Bypassing barriers and locks is an important part of ferreting out secrets. Many Lurkers are capable of picking locks, hacking computers and simply smashing or tearing away the impediments to their goals, but sometimes a more subtle approach is necessary. This Gift allows the werewolf to bypass physical locks with a simple knock."]},{type:"paragraph",text:["Lurker’s Key works on electronic locks and can even be used to bypass computer security. In keeping with the lodge’s insistence on earning knowledge, however, the character must rely on her own skills to do so. Using this Gift on a mechanical or electronic lock uses the Larceny Skill. Bypassing computer security uses the Computer Skill. In any case, if the character attempts to use this Gift without any dots in the proper Skill, she suffers the usual unskilled penalty. The character must be able to touch the lock (or the computer’s monitor, in the case of computer security) to use this Gift. Most Bone Shadows knock, but a gentle touch works just as well."]}],fullCost:"1 Essence",dicePool:"Wits + Larceny or Computer + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The lock refuses to open, and in fact becomes damaged beyond repair. Computers freeze up, tumbler locks crack and electronic locks short. The only way through the lock now is by force."]},{type:"line",label:"Failure",text:["The lock remains intact."]},{type:"line",label:"Success",text:["The lock opens."]},{type:"line",label:"Exceptional Success",text:["No special effect."]}]},{Rank:"•••",Name:"Create Opening",Description:"Creates a small, clean opening in a physical object.",Cost:"●○",Book:"LodgF 51",fullDescription:[{type:"paragraph",text:["The initial Opening Gifts deal with already extant apertures. This Gift, however, creates new ones. The werewolf focuses on a seamless object, be it a steel plate, a brick wall or a living being, and wills the object to open. A single, smooth tear appears in the object, beginning as hairline fracture and widening as it goes. Used on a physical object, this Gift can render something useless, create a small portal through which the character can escape or even allow the character to peek through a wall. Used on a living being, of course, the effects are far more painful (and usually messy)."]},{type:"paragraph",text:["The character need not touch the target for the Gift to function, but using the Gift at a distance imposes a -3 penalty to the roll. The maximum range for the Gift is one foot per dot of Primal Urge the character possesses, in any event."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Resolve + Intimidation + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift reverses itself. The werewolf’s skin splits open, and she suffers lethal damage equal to her own Resolve rating."]},{type:"line",label:"Failure",text:["Nothing happens."]},{type:"line",label:"Success",text:["The target, inanimate or not, suffers lethal damage equal to the character’s successes. Armor does not stop this damage (though the werewolf can target the armor rather than the person, if she so desires). The object or person simply splits open. See p. 136 of the ",{text:"World of Darkness Rulebook",bold:!0}," for rules on breaking objects."]},{type:"line",label:"Exceptional Success",text:["No extra effect beyond the increased damage."]}]},{Rank:"••••",Name:"The Open Mind",Description:"Disorients a target with massive quantities of information, inflicting a penalty to all actions equal to the greater of activation successes or Primal Urge.",Cost:"-",Book:"LodgF 51",fullDescription:[{type:"paragraph",text:["The world is a constant rush of information, and only by filtering out most of it are we able to function. This Gift opens the target’s mind to not only the physical world, but all of the sensation of the Hisil. The target is inundated by a swirling onslaught of sensation, which normally leaves him incapacitated and terrified. Those who manage to cope with this madness, however, can draw strength from it."]},{type:"paragraph",text:["The Bone Shadow must make eye contact with the target or touch his skin. She then wills his mind open. The results vary based on how strong-willed the target is; see below."]}],fullCost:"None",dicePool:"Manipulation + Subterfuge + Wisdom versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The target’s mind remains closed. The character’s own mind receives much of the chaos she was trying to foist on the target and loses 1 Willpower point."]},{type:"line",label:"Failure",text:["If the character’s player rolls no successes, nothing happens. If both the character and the target succeed and the target gains more successes, however, the target experiences the effects of the Gift but is able to find peace and clarity amid the chaos, regaining 1 Willpower point."]},{type:"line",label:"Success",text:["The target becomes overwhelmed by the chaos. For one turn per success on the character’s roll, the target is effectively blinded and deafened by the maddening rush of sensation. Any actions attempted receive a negative modifier equal to the character’s successes, or the character’s Primal Urge, whichever is greater."]},{type:"line",label:"Exceptional Success",text:["No effect beyond the greater duration and intensity of the Gift."]}]},{Rank:"•••••",Name:"Gauntlet Key",Description:"Allows the user to cross back and forth across the Gauntlet; must be completely alone and unobserved to use, and it cannot be used for purposes of assassination or violence.",Cost:"●●●",Book:"LodgF 51",fullDescription:[{type:"paragraph",text:["The most experienced and wise members of the Lodge of Doors are granted a great secret — how to bypass the Gauntlet without a locus or a rite. Only the Lurker in the Doorway teaches this Gift, and only to Uratha whom the spirit believes will use the Gift responsibly and within the principles of the lodge."]},{type:"paragraph",text:["To activate the Gift, the character must be completely alone. If the character is observed by anyone on his side of the Gauntlet, the Gift does not function. The character must find a gateway — a doorway, two trees spaced a few feet apart, even a crude sketch in the dirt will do. The character steps through the gateway and, provided the Gift works, finds himself on the other side of the Gauntlet. The character ",{text:"cannot",italic:!0}," act as a pathfinder (see p. 251 of ",{text:"Werewolf: The Forsaken",bold:!0},") while using this Gift. When stepping into the physical world from the spirit wilds, the character must again step into a location where he is unobserved. The Lurker in the Doorway does not approve of using this Gift for purposes of assassination or surprise attacks (as the spirit is rather squeamish about violence) and revokes the Gift as well as the fifth dot of Renown that allowed the character to learn it if the Uratha attempts such a thing. Spying, however, is a perfectly acceptable use of the Gift."]},{type:"paragraph",text:["The experience cost of this Gift is doubled if the character does not already possess the other four Opening Gifts."]}],fullCost:"3 Essence",dicePool:"Wits + Stealth + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:["All roll results are exactly the same as those described for stepping sideways on p. 251 of ",{text:"Werewolf: The Forsaken",bold:!0},"."]}]}]},{Name:"Pack",Description:"",Cost:"",Book:"Rage 121",Content:[{type:"paragraph",text:"Despite the instincts toward pack life that surge through every werewolf, many Gifts ignore their users’ packmates. Gifts of the Pack go some way to redressing that balance, being the reward granted by a group of wolf-spirits to a pack that braved the spirit wilds to find the one spirit that could heal a Wound in the pack’s territory. The pack showed incredible teamwork and behaved as a true pack should. History doesn’t say what became of the pack, or whether the packmembers remained the perfect example of a werewolf pack for long. The spirits of creatures that hunt in packs teach these Gifts, including wolves, ants and dolphins."}],Ranks:[{Rank:"•",Name:"Web of Scent",Description:"Borrow any sense of a packmate within half of Primal Urge in miles, losing her own.",Cost:"-",Book:"Rage 121",fullDescription:[{type:"paragraph",text:["A pack can only work together so well, even with the bonds of the totem joining each packmate. The spirits that grant the werewolf this Gift want him to work closer with his packmates, and to that end they let him share their senses. He can’t communicate with his packmate or control where she looks; he is very much a passenger behind her eyes and nose."]}],fullCost:"None",dicePool:"This power requires no roll.",action:"Instant",rollResults:[{type:"paragraph",text:["The character can borrow the senses of any of his packmates within half his Primal Urge in miles. He has to know where the chosen packmate is, whether through his normal senses or Gifts such as Pack Awareness (see ",{text:"Werewolf: The Forsaken",bold:!0},", p. 117)."]},{type:"paragraph",text:["When borrowing his packmate’s senses, the werewolf must choose which senses remain his own and which come from his packmate, and these choices remain for the duration of the Gift. He gains the full benefit of her natural senses, but doesn’t benefit from any Gifts or other supernatural sensory effects that affect her. He also can’t use the borrowed senses of his own body, so would not be able to hear an attacker sneaking up behind him if he were relying on his packmate’s ears. The packmate knows when she is sharing her senses, and can spend a point of Essence to ‘fog’ them for a minute. The Gift-user doesn’t gain his original senses back, but gets nothing useful from his packmate for that time, and can do nothing about this interference. The Gift lasts for five minutes, or until the Gift-user cancels it."]}]},{Rank:"••",Name:"Warning Howl",Description:"Howl for help. All packmates in pack's territory hear it and cannot be misinterpreted.",Cost:"●",Book:"Rage 121",fullDescription:[{type:"paragraph",text:["A pack cannot travel as one all the time. Uratha have territory that they must watch over. The entire pack traveling as one would not only make the werewolves easy to ambush, it would leave most of their territory unattended. Without the Forsaken watching, all manner of spirits and other creatures would wreak havoc. The spirits that teach this Gift show the packmembers that they are as one even when physical distance separates them. The Gift allows a werewolf to howl a warning to his packmates, calling their aid from anywhere within the pack’s territory."]}],fullCost:"1 Essence",dicePool:"Wits + Expression + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf howls, but his packmates aren’t the ones who hear him. Spirits, ",{text:"shartha",italic:!0}," or the Pure could hear the howl, and find themselves aware of a lone Forsaken in trouble."]},{type:"line",label:"Failure",text:["The character’s howl doesn’t have the spiritual might it needs to reach his packmates."]},{type:"line",label:"Success",text:["The character howls, calling for his packmates to assist him. The howl pierces the Shadow and reverberates across his pack’s territory. Each packmember who is in the pack’s territory (including any disputed areas) hears the howl regardless of distance, though to anyone who is not part of the pack who hears it will just hear a normal wolf howl (or a human trying — badly — to mimic a wolf howl). The character’s packmates know instinctively where he is and why he is calling on them for aid — the Gift allows no misrepresentation, so werewolves who attempt to use it to summon their pack for trivial reasons will be disappointed. In an urban area that isn’t part of the pack’s territory, the howl can be heard for the user’s Primal Urge in city blocks, whereas in rural areas the howl carries for the user’s Primal Urge in miles."]},{type:"line",label:"Exceptional Success",text:["The packmates rushing to the aid of their fellow double their Speed until they reach him, but only if they head toward the howl. This effect ends when they arrive at the Gift-user."]}]},{Rank:"•••",Name:"Brother’s Strength",Description:"Can solve a problem that would normally only allow one werewolf to work on it as a pack, and makes them better at working together normally",Cost:"○",Book:"Rage 122",fullDescription:[{type:"paragraph",text:["A true pack works together, each member contributing to whole that is definitely greater than the sum of its parts. The spirits that teach this Gift show the pack that this is so, allowing the packmembers to solve a problem that would normally only allow one werewolf to work on it as a pack, and making them better at working together normally. Of course, if the werewolf who possesses this Gift is not the pack alpha, some may question his right to be organizing so much of the pack’s efforts."]}],fullCost:"1 Willpower",dicePool:"Composure + Empathy + Glory",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character’s concentration is shredded by the conflicting urges of his packmates. The attempt at teamwork fails, and the character suffers a -2 modifier on the action his pack was attempting."]},{type:"line",label:"Failure",text:["The character can summon no more assistance from his packmates."]},{type:"line",label:"Success",text:["The Gift channels the character’s packmates, giving him greater strength and ability. The werewolf using this Gift must be the primary actor, the character doing the most toward the action. If the action would normally allow teamwork, each secondary actor in the character’s pack can use “9 again” on their roll. If the action would not normally allow teamwork, the character can allow one packmate to assist as a secondary actor. Additional packmates cost one Willpower to add as secondary actors. This Gift can only be used once for a single action."]},{type:"line",label:"Exceptional Success",text:["In addition to the effects of a success, the dice pool penalty from a secondary actor rolling a dramatic failure is reduced to -2."]}]},{Rank:"••••",Name:"Synergy",Description:"Can transfer skills between pack members, even his own. The character can't be the beneficiary.",Cost:"●●",Book:"Rage 122",fullDescription:[{type:"paragraph",text:["A pack that works together well will always have specialists. Sometimes, a problem needs the same specialist to be in two places at once, and this Gift allows that. A werewolf can donate her skills in an area to another member of the pack, a transfer facilitated by the user of this Gift. The spirits that grant this Gift want each packmate to look beyond what she can do individually to what the pack can do as a whole."]}],fullCost:"2 Essence",dicePool:"Manipulation + Larceny + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The werewolf botches the transfer. The packmember with the highest rating instead takes on the rating of the other packmate for the remainder of the scene."]},{type:"line",label:"Failure",text:["The character cannot transfer anything."]},{type:"line",label:"Success",text:["The werewolf transfers a Skill from one packmate to another, effectively swapping both character’s ratings in that Skill. Both packmates must agree to the transfer, and the werewolf using the Gift must touch both parties to the transfer. The Gift-user can give a Skill but not receive. The two characters swap ratings and any Specialties in the named Skill, unless the lower rating is 0, in which case the donating character retains one dot in the Skill. The switch lasts until the character “borrowing” the Skill chooses to end the effect, or the next moonrise/moonset (whichever is sooner)."]},{type:"line",label:"Example",text:[{text:"Johnny “Gearshift” Blaine donates his skills behind the wheel to Thunderbolt Hamilton, knowing that while she will chase their prey into the ambush, he’s going to have the job of actually out-driving the bastard. Gearshift has Drive 4 with the specialty of Stick-Shift, Thunderbolt has Drive 2. Gearshift uses the Gift and succeeds at the roll. Thunderbolt now has Drive 4, specializing in Stick-Shift, while Gearshift has Drive 2 until Thunderbolt ends the exchange. If Thunderbolt’s Drive had been 0, Gearshift would have retained Drive 1. After all, it’s what he does.",italic:!0}]},{type:"line",label:"Exceptional Success",text:["As a success, but the donator of the Skill gains a +1 modifier to all rolls using that Skill from past experience. This bonus stops as soon as the Gift’s effects end."]}]},{Rank:"•••••",Name:"Unity",Description:"Any packmate can spend Willpower or Essence toward a roll of a mate. She can also take one Health point of damage for packmate.",Cost:"●●●○",Book:"Rage 123",fullDescription:[{type:"paragraph",text:["The pack is a being greater than the sum of its parts. Each member contributes something toward the whole, be they werewolf or totem spirit, but the pack performs great deeds and binds powerful spirits. The pack is the basic unit of werewolf life, and this Gift proves it, allowing members to pool their mental, physical and spiritual resources. Spirits teach other Pack Gifts in order to make a point to a pack, showing the packmembers an area where they are deficient. This Gift shows that the pack have nothing left to learn."]}],fullCost:"3 Essence and 1 Willpower",dicePool:"This power requires no roll.",action:"Instant",rollResults:[{type:"paragraph",text:["This Gift lasts for a scene, and only affects other members of the user’s pack within twice his Primal Urge in yards. Until the end of the scene, each packmate present can choose to spend Willpower to affect the roll of any other packmate, can spend Essence toward a Gift or other ability used by another packmate or can take one Health point of damage that would have hurt another packmate. In the case of Health, the type of damage doesn’t change even if a Gift or other supernatural power would normally have changed the severity of the damage. Each packmate can only make one transfer per turn of either Willpower, Health or Essence, and unconscious packmembers are entirely unaffected by the Gift — they can neither give nor receive. A character can make her transfer at any point in the Initiative order."]}]}]},{Name:"Predator",Description:"",Cost:"",Book:"Rage 123",Content:[{type:"paragraph",text:"Werewolves are consummate predators. The Forsaken ideally use this ability to carry on in the footsteps of Father Wolf, but many also carry out their own hunts, whether to avenge slights against their pack or pursue personal vendettas. The Pure enlist the aid of spirits in the Pure’s quest to slaughter the Forsaken, hunting the werewolves who attempt to carry on in Father Wolf’s footsteps. These Gifts were originally the sole purview of the Predator Kings, knowledge gained from spirits that hated the kinslayers. A hundred years ago, a pack of Bone Shadows decided to do something about that. Questing deep into the spirit wilds, they surmounted incredible challenges and trapped the original spirits with their own bans. Striking a deal with the spirits, these Bone Shadows ensured that the Forsaken can learn these Gifts for themselves. The spirits of predatory animals, including wolves and big cats, now teach these Gifts."}],Ranks:[{Rank:"•",Name:"Bestial Fellowship",Description:"Gain four extra dice on all Animal Ken rolls made to influence predators",Cost:"●",Book:"Rage 123",fullDescription:[{type:"paragraph",text:["The werewolf gains a kinship with other predatory beasts. While even the most savage animals normally register the half-spirit children of Father Wolf as higher predators than themselves, a werewolf using Bestial Fellowship overrides this instinct. The animals get a sense that the werewolf does not see them as prey, and will let her be. In addition, she can talk with other predators, possibly learning valuable information, though she cannot convince them to do anything that is against their nature. Suppressing the wolf-side of her spirit is an uncomfortable thing for a werewolf to do, and Uratha especially try to avoid using this Gift more than is necessary. One positive side of the Gift is that it works for all predators up to and including predatory animals kept as pets, such as most pet cats. Using this Gift is a sin with a Harmony Threshold of 8, and over-reliance on this Gift may make it harder for the user to gain Purity Renown."]}],fullCost:"1 Essence",dicePool:"None",action:"Reflexive",rollResults:[{type:"paragraph",text:["Upon activating this Gift, the werewolf gains four extra dice on all Animal Ken rolls made to influence predators. This Gift lasts until the moon next rises or sets."]}]},{Rank:"••",Name:"Hunter’s Fortitude",Description:"Can lie in wait or track prey for days on end without the common distractions of normal life",Cost:"●",Book:"Rage 123",fullDescription:[{type:"paragraph",text:["Wolves are not unique among predatory animals in eating only rarely. However skilled a creature is at hunting, there are many days when the creature will go without food. This Gift allows a werewolf in any form to mimic this fortitude, allowing her to lie in wait or track prey for days on end without the common distractions of normal life."]}],fullCost:"1 Essence",dicePool:"Stamina + Survival + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overcome by hunger, and even after he has eaten his fill finds it hard to avoid little distractions. All Resolve rolls suffer a -1 modifier until the end of the scene."]},{type:"line",label:"Failure",text:["The character has no extra reserves to tap."]},{type:"line",label:"Success",text:["The werewolf can survive without food and needs only a small amount of water to keep in perfect condition. His mind is attuned to the task of hunting prey, be that an extended hunt or a stakeout lasting several days. While he still needs sleep, he feels as though he has slept for twice the amount of time he actually has. The Gift’s effects last for three hours per success, after which time the werewolf must eat a hearty meal and rest for at least 12 hours."]},{type:"line",label:"Exceptional Success",text:["The werewolf’s mind is so focused on his task that any roll to distract him suffers a -1 penalty."]}]},{Rank:"•••",Name:"Savage Hunt",Description:"All rolls to find or track her target have a +1 bonus. Bite and claw attacks deal aggravated damage against her chosen prey only.",Cost:"●●●○",Book:"Rage 124",fullDescription:[{type:"paragraph",text:["The apex predator understands the importance of the hunt to her own survival. Tracking prey to eat is only one aspect of the overarching thing that is the hunt. With this Gift, the character embodies every part of the hunt, losing herself to the need to run prey to the ground, giving up a piece of herself to the hunt in order to embody it. While some Forsaken apply the concept of hunting liberally, referring to everything from Internet searches to gunfights, a character embodying the Savage Hunt knows that they are wrong. Hunting pits the hunter’s senses, reflexes and claws against the prey. Only the truly worthy among the prey survive. Using this Gift against other werewolves is a sin against Harmony equivalent to using a silver weapon (see ",{text:"Werewolf: The Forsaken",bold:!0},", p. 181)."]}],fullCost:"3 Essence + 1 Willpower",dicePool:"Dexterity + Athletics + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character becomes an avatar of the hunt, but her prey is not whom she chose. Her new prey could be anyone, including a packmate or a wolf-blooded ally, and is chosen by the Storyteller."]},{type:"line",label:"Failure",text:["The character fails to invoke the spirit of the hunt."]},{type:"line",label:"Success",text:["The werewolf feels a surge of energy as she dedicates herself to the ancient hunt. Naming her prey, she gains a number of advantages. First, her senses are sharper, better isolating the scent and sound of her chosen target. All rolls to find or track her target have a +1 bonus. Also, her bite and claw attacks deal aggravated damage against her chosen prey only. The Savage Hunt lasts until the moon next rises or sets (whichever is next), or until the werewolf catches and kills her prey, whichever happens first."]},{type:"line",label:"Exceptional Success",text:["The character gains a better understanding of her prey while she tracks it. When she encounters her prey, roll Initiative as normal. If the hunter rolls lower than her prey, the hunter’s Initiative is instead equal to that of her prey."]}]},{Rank:"••••",Name:"Harry",Description:"Prey’s rolls suffer a -2 modifier for the duration of the confrontation.",Cost:"●",Book:"Rage 124",fullDescription:[{type:"paragraph",text:["Predators either strike from concealment, stalking their prey and then attacking swiftly, or they run it down until the prey is exhausted. Their prey knows what is coming, but still runs. The prey has a hope, however feeble, that it can escape. Sometimes it does. More often, it collapses from physical and mental exhaustion. While not resigned to its fate, there is certainly no chance that it can run any farther. This Gift gives the werewolf’s prey that fear. They know from glimpsed shadows and occasional scents created by spirits of the hunt that something is toying with them, waiting for them to drop, but they never know where the werewolf is or when she will strike. This is a very unnerving feeling, and someone who survives being under the influence of this Gift will remember it for the rest of his days."]}],fullCost:"1 Essence",dicePool:"Wits + Intimidation + Glory versus Resolve + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character’s prey is filled with resolve, determined to face her fate and seize any opportunity to best his hunter. The target of the Gift receives one bonus Willpower point that can only be spent to support actions taken against his hunter. This extra point can bring the prey above his normal Willpower maximum."]},{type:"line",label:"Failure",text:["The character attempts to run her prey to the ground, but has no spiritual assistance in doing so."]},{type:"line",label:"Success",text:["Spirits aid the werewolf as she runs her prey (one person or creature) to the ground, spooking him and generally making sure he is never sure of what is happening or where an attack will come from. Her prey’s rolls suffer a -2 modifier for the duration of the confrontation. The prey can roll Resolve each turn after the first to reduce this modifier to -1. The effects of this Gift last until the end of the scene."]},{type:"line",label:"Exceptional Success",text:["As a success, and the werewolf’s Initiative is doubled for the conflict."]}]},{Rank:"•••••",Name:"Predator’s Kin",Description:"Summon every predatory creature within the user’s Primal Urge in miles to attack the target as one",Cost:"●●",Book:"Rage 125",fullDescription:[{type:"paragraph",text:["There are some things that no hunter can tackle alone. Some are massive creatures that could easily crush one hunter; others are groups of prey animals that would overwhelm a lone hunter. Even solitary predators understand the benefits of assistance. This Gift summons nearby predators to the character’s aid. Depending on the area, this assistance can come from unlikely quarters — coyotes and badgers will respond to this Gift in a city. Wolves and dogs will respond to the call, but they will be on edge. This Gift taps into their predatory nature without paying any respect to Father Wolf, and canine animals can sense the difference."]}],fullCost:"2 Essence",dicePool:"Presence + Animal Ken + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["Local predators respond to the call, but are as much a nuisance to the werewolf as her prey."]},{type:"line",label:"Failure",text:["Nothing answers the character’s call for assistance."]},{type:"line",label:"Success",text:["This Gift summons every predatory creature within the user’s Primal Urge in miles, though wolves and dogs respond as if the user’s Primal Urge were two lower than it is. The majority of predators found in an urban area will do little more than distract the prey, but large creatures such as wolves or big cats will do more damage. The animals that respond are treated as one creature that makes one attack, with a number of dice equal to the largest Size in the group. This group of creatures deals lethal damage. Larger creatures (Size 4 or above) can either be handled individually as Storyteller characters, or add one attack to the general mass per three animals present. A group of miscellaneous small predators assisted by a cougar and two wolves would thus make two attacks with a dice pool of 4."]},{type:"line",label:"Exceptional Success",text:["The creatures attack with such ferocity that they add one die to their attack pool."]}]}]},{Name:"Purity",Description:"",Cost:"",Book:"SotM 179",Content:[{type:"paragraph",text:["Ralunim are uncompromising, brutal and honest. They might take the forms of proud, powerful warriors, shining silver-furred wolves, or blinding shafts of moonlight. In addition to the Full Moon Gifts found on pp. 116–117 of ",{text:"Werewolf: The Forsaken",bold:!0},", the Lunes of the Fury Choir can teach Purity Gifts."]},{type:"paragraph",text:"Purity Gifts require that the Rahu in question have Purity Renown equal to the Gift being learned, even if the werewolf would normally be able to learn the Gift without raising Purity. For instance, a Bone Shadow Rahu uses Purity and Wisdom as his primary Renown categories. When he reaches Wisdom 3, he is eligible to learn three-dot Gifts, regardless of his Purity rating. However, for him to learn The Illuminated Battlefield, he would need to increase his Purity rating to three."},{type:"paragraph",text:"Only Rahu can learn these Gifts."}],Ranks:[{Rank:"•",Name:"Moonlight",Description:"Adds Purity to Social Rolls involving Spirits",Cost:"●",Book:"SotM 179",fullDescription:[{type:"paragraph",text:["The silver Renown markings that all werewolves bear are marks of pride and accomplishment, but Purity markings have the added benefit of being badges of moral merit. Ralunim recognize them and the mere presence of such a Lune is often enough to make Purity markings glow slightly, even in the physical world. A Rahu with this Gift can cause his Purity tattoos to shine with full moonlight. This has the effect of providing illumination, which can be useful on its own, but it also cows any spirit that sees the light."]},{type:"paragraph",text:["Once this Gift is activated, the player adds the character’s Purity rating to any Social rolls made against spirits for the rest of the scene. If the full moon is visible, the player adds an additional die to such rolls."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Righteous Rage",Description:"Can instinctively ignore pack in a Death Rage",Cost:"●",Book:"SotM 179",fullDescription:[{type:"paragraph",text:["Death Rage is one of the most terrifying possibilities for a Rahu, because in Kuruth, the werewolf can’t tell the difference between friend and foe. And yet, Death Rage has its own purity, a complete focus on violence and killing that the Ralunim respect."]},{type:"paragraph",text:["This Gift allows the werewolf to instinctively ignore his own pack while in Death Rage. He can’t take part in pack tactics or do anything else normally prohibited during this state of frenzy, but he never attacks werewolves with whom he shares a pack bond."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"The Illuminated Battlefield",Description:"Illuminates anyone using underhanded or sneaky tactics, including traitors to the pack",Cost:"●",Book:"SotM 179",fullDescription:[{type:"paragraph",text:["Ralunim can appreciate clever tactics, but they don’t tend to use them. To the Fury Choir, the perfect tactic is meeting on the field of battle and ",{text:"winning",italic:!0}," through superior strength and skill, not sneaking up behind an opponent and planting a knife in his back. Anyone can do that. A true warrior wins or loses on her own merits."]},{type:"paragraph",text:["The Ralunim do recognize, however, that others don’t think this way, and this Gift helps to keep everyone honest. Once the werewolf activates this Gift, the site of the battle is immediately bathed in brilliant, white moonlight, as though taking place on a clear night during a full moon. If the werewolf activates the Gift during the day or in an otherwise illuminated place, the existing light takes on this moonlight-like quality."]},{type:"paragraph",text:["Anyone in the fight who attempts an underhanded tactic — sneak attacks, taking hostages, mind control, etc. — reflects the light, appearing to glow. This doesn’t prevent the tactic from happening, necessarily, but it ensures that the Gift’s user knows about it."]},{type:"paragraph",text:["If the werewolf’s pack contains a traitor, he glows under this Gift’s effects as well. A “traitor,” here, is any werewolf actively working against the pack’s goals, currently breaking the pack totem’s ban, or helping enemies of the pack in any way. As with so many matters involving Ralunim, this Gift doesn’t take into account certain nuances, such as double agents, and it illuminates the Rahu’s packmates dirty tricks just as much as their enemies. The Rahu is advised to use this Gift with caution."]}],fullCost:"1 Essence",dicePool:"Wits + Survival + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift gets the attention of a Ralunim, but not in the way the werewolf intended. The Lune takes offense and blinds the werewolf — ",{text:"all",italic:!0}," she sees is the bright moonlight for the rest of the scene."]},{type:"line",label:"Failure",text:["The Gift fails to activate, though the werewolf can try again."]},{type:"line",label:"Success",text:["As described above, anyone involved in the current fight using any tactic that involves deception, trickery, ambush or forcing opponents to act against their own side glows brightly. In addition, any werewolf belonging to the Gift user’s pack who is involved in actions against that pack, even if those actions make sense in a greater context, glow as well. In addition, the Rahu using the Gift adds his Purity rating to all Perception rolls made during the scene."]},{type:"line",label:"Exceptional Success",text:["All members of the werewolf’s pack (except for any “traitors” identified) add the Rahu’s Purity rating to their initiative modifiers for the scene, as they take best advantage of the Illuminated Battlefield."]}]},{Rank:"••••",Name:"Harmony's Reward",Description:"Add Harmony to any dice pool, but any call of Degeneration for the scene is at -1",Cost:"○",Book:"SotM 179",fullDescription:[{type:"paragraph",text:["Observing the Oath of the Moon can have tangible rewards. A werewolf who lives in balance can use that Harmony to amplify almost any endeavor. Obviously, this Gift is of greatest benefit to werewolves that studiously cultivate Harmony and avoid violations of the Oath — but that’s what Rahu are supposed to do anyway."]},{type:"paragraph",text:["This Gift adds the werewolf’s Harmony rating to any one dice pool. It can be used only once per turn, and no limits are imposed upon the action itself, regardless of whether or not the attempted action is in violation of the Oath of the Moon. However, using Harmony’s Reward to take an action that could lead to degeneration is risky, in that it puts the werewolf in a fragile spiritual state, making degeneration more likely."]},{type:"paragraph",text:["In game terms, if a player is called upon to make a degeneration roll during a scene in which the character has used this Gift, subtract one die from the degeneration roll for each use. Note that it is not possible to roll a dramatic failure on a degeneration roll, so even if the dice pool is reduced below one, a roll of 8 or above on the die is still a success."]}],fullCost:"1 Willpower",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"•••••",Name:"Intractable Warrior",Description:"Can auto track a target, and gain other bonuses once facing them",Cost:"●",Book:"SotM 180",fullDescription:[{type:"paragraph",text:["Once a Ralunim has chosen a foe, nothing can stop it from meting out its fury. Werewolves, likewise, are the greatest hunters in the world — a single taste of blood is enough to allow a werewolf to track her target. A Rahu of impeccable Purity can learn to refine this hunting prowess, so that no force on Earth can stop him from chasing down her foe."]},{type:"paragraph",text:["The werewolf must be able to see her target, or else have previously tasted his blood, obtained some other piece of him or acquired an item of great personal significance to him. Once the character activates the Gift, the werewolf can unerringly track the foe. The player gets a bonus to tracking the target equal to the werewolf’s Purity rating (five dice)."]},{type:"paragraph",text:["Once the werewolf has found the target, the true horror of the Gift begins. Nothing can stand in the character’s way. Other opponents fall aside with a casual shove (in game terms, the Rahu can make a reflexive attempt to touch (not strike) opponents other than his target; if it connects, the target is subject to a Knockdown effect), doors unlock themselves, and other barriers break or part for the hunter. If the target is protected by some supernatural means (magic that hides him, a supernaturally sealed door) the werewolf’s Purity rating acts as a modifier to any rolls made to maintain this means, positive or negative in the werewolf’s favor. For example, if the werewolf’s player would normally roll Wits + Composure to detect a hidden character, she adds the character’s Purity rating to the roll. If the target would roll Composure + Stealth to use an invisibility power of some kind, the target’s player ",{text:"subtracts",italic:!0}," the werewolf’s Purity rating."]},{type:"paragraph",text:["This Gift lasts from when it is activated until the next sunrise, whereupon the werewolf can, if she wishes, use it again. Once combat with the target begins, the Gift has no further effect."]}],fullCost:"1 Essence",dicePool:"Resolve + Survival + Purity",action:"Instant",rollResults:[]}]},{Name:"Rage",Description:"",Cost:"",Book:"WtF 134",Content:[{type:"paragraph",text:"The spirits recognize the power that Rage grants werewolves, and they respect that power even if they resent how the Uratha came by it. In an effort to appease the Uratha and hopefully convince them to direct their Rage elsewhere, spirits offer these Gifts. The list helps a werewolf derive more power from his Rage, and even manipulate the power that Rage gives rivals and enemies."}],Ranks:[{Rank:"•",Name:"Mask of Rage",Description:"Increase Lunacy",Cost:"●",Book:"WtF 134",fullDescription:[{type:"paragraph",text:["The character makes himself seem preternaturally terrifying by exposing onlookers to Lunacy and intensifying its effects. If the character does so in Dalu or Urshul form, Lunacy is as intense as it would be if he were in Gauru form. If he does so in Hishu or Urhan form, he emanates a Lunacy-inducing effect as if he were in either Dalu or Urshul form (respectively). This Gift cannot be activated in Gauru form. The effect lasts for as long as the werewolf remains in the form in which he activates it, for as long as he chooses, or for the rest of the scene (whichever comes first)."]}],fullCost:"1 Essence",dicePool:"No roll is required",action:"Instant",rollResults:[]},{Rank:"••",Name:"Hone Rage",Description:"Concentrate Gauru ability (the player may sacrifice Gauru duration for +1 to Strength or Dexterity per turn sacrificed)",Cost:"●",Book:"WtF 134",fullDescription:[{type:"paragraph",text:["A character with this Gift can channel the power of his Rage more efficiently than the average character, sacrificing the time he can spend in Gauru form for increased physical prowess. For each success rolled, a player can exchange one turn of Gauru form for one additional, temporary dot of either Strength or Dexterity. If the player scores two successes, he may sacrifice two turns in Gauru form for two additional dots of Strength, two additional dots of Dexterity, or an additional dot of Strength and an additional dot of Dexterity. These extra dots apply only while the werewolf is in his Gauru form, and they last for as long as he remains in that form."]},{type:"paragraph",text:["This Gift can be activated when a character assumes Gauru form, or it can be activated after he’s already in that form, as long as turns in Gauru are still available to be sacrificed. If no more turns are left to exchange, the Gift cannot be used. As the action to activate this Gift is reflexive, the bonus dots received apply to any action taken in the same turn in which this Gift is activated. Activating the Gift doesn’t count as a distraction from attacking while in Gauru, and doesn’t threaten Death Rage. If a character enters Death Rage while using this Gift, the Gift’s effects immediately end, and the character will be subject to Death Rage for the usual duration."]},{type:"paragraph",text:["Trait maximums based on a character’s Primal Urge do not apply against these bonus Attribute dots. Note also that a character’s Speed, Defense and Initiative are subject to temporary modification based on changes to his Dexterity and/or Strength."]}],fullCost:"1 Essence",dicePool:"Stamina + Survival + Purity",action:"Reflexive",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character loses one turn from Gauru duration, but no additional Attribute dots are gained."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character neither loses any time in Gauru form nor gains any additional Attribute dots."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," For every success rolled, the player may sacrifice one turn of Gauru Rage. For each turn so sacrificed, the player may apply a temporary bonus dot to either Strength or Dexterity. Trait maximums due to Primal Urge do not apply, and the bonus dots disappear when the character changes out of his Gauru form. Extra successes beyond the number of turns of Gauru form remaining confer no benefit."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The player adds Stamina to the Attributes that may gain dots. Remember that Health increases as a result, though the time he may spend in Gauru form (Stamina + Primal Urge) does not benefit."]}]},{Rank:"•••",Name:"Leech Rage",Description:"Drain Gauru duration (1 turn per success)",Cost:"●",Book:"WtF 135",fullDescription:[{type:"paragraph",text:["Facing a werewolf with this Gift is a dangerous proposition indeed. A werewolf literally steals the power of a rival’s Rage and adds it to his own. With a hissing inhalation, the Gift-user draws off his opponent’s power in a wash of energy that distorts the air between them. The victim loses a number of turns that could be spent in Gauru form, and the Gift user gains those turns in addition to his own."]},{type:"paragraph",text:["A werewolf can use this Gift only on another werewolf, and only on a werewolf who is currently in Gauru form. Furthermore, the victim must still have turns available to spend in Gauru form. When a user activates this Gift, he reflexively assumes his own Gauru form as a result, provided he hasn’t already done so in the same scene. (Assuming Gauru in conjunction with using this power requires a separate Essence point; no Stamina + Survival + Primal Urge roll is allowed to change form when this Gift is used.) If the Gift user has already assumed Gauru form in the same scene prior to activating this power, he may still use it on a subject. Should he activate the Gift successfully, he robs the victim of turns in war form, but doesn’t gain those extra turns himself. If this Gift is used against a subject currently undergoing the Death Rage, the target may make a Resolve + Composure check to stop ",{text:"Kuruth",italic:!0},"; however, the Gift user must make a check to resist Death Rage or enter ",{text:"Kuruth",italic:!0}," himself."]},{type:"paragraph",text:["A werewolf can use this Gift successfully once a scene and on only one victim before assuming Gauru form himself. A victim can, however, be targeted by multiple applications of this Gift by separate users at the same time."]},{type:"paragraph",text:["A character who is currently in Gauru form can use this power on another Raging werewolf. Activating the Gift does not count as a distraction from attacking foes in the turn."]}],fullCost:"1 Essence",dicePool:"Presence + Empathy + Cunning - subject’s Composure",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The intended victim loses no turns spent in Gauru form. Roll Resolve + Composure to see if the Gift user resists entering Death Rage. (If he succeeds, he doesn’t assume Gauru form.) The character cannot use this Gift again in the same scene. If the Gift user has already changed into and out of Gauru form in this scene, he enters Death Rage automatically as a result of a dramatic failure."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The user reflexively enters Gauru form in a controlled Rage (provided he hasn’t already used up his Rage turns for this scene). For every success on the roll, the victim loses one turn in Rage and the user gains it as an additional turn in his own Rage. If successes rolled exceed the number of turns that the subject has left in Gauru form, the Gift user gains the lower number in extra turns of Rage. So, if four successes are rolled but a subject has only two turns left to spend in Gauru, the Gift user takes away only those two turns and adds them to his own duration. If the Gift user has changed into and out of Gauru form this scene, a roll to resist Death Rage is made and the victim still loses turns available in Gauru form."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success. The extra turns are the exceptional reward."]}]},{Rank:"••••",Name:"Rekindled Rage",Description:"Additional Gauru shapeshifting (normal duration -2)",Cost:"○",Book:"WtF 136",fullDescription:[{type:"paragraph",text:["Normally a werewolf character can enter Gauru form only once per scene (with the exception of Death Rage), but a werewolf who has mastered this Gift is not so limited. With a successful Stamina + Expression + Glory roll and the expenditure of one Willpower point, the werewolf can enter Gauru an additional time in the same scene, though the second transformation will not last as long."]},{type:"paragraph",text:["A character can use this Gift only after he has entered and let lapse his first Gauru Rage in a scene."]},{type:"paragraph",text:["A character may use the Hone Rage Gift in a Rekindled Rage, and he is equally susceptible to the Leach Rage Gift. Or he can use the Rekindled Rage Gift in one turn and then use Leach Rage on a Raging victim in a subsequent turn."]}],fullCost:"1 Willpower",dicePool:"Stamina + Expression + Glory",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character enters Death Rage automatically, with no chance to forestall it by spending Willpower."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character fails to rekindle his Rage and is unable to use the Gift again in the same scene."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character rekindles his Rage. The player makes a new shapeshifting roll (or spends a point of Essence) to assume Gauru form and enter a controlled Rage in a scene in which he has already done so. The character can remain in Gauru form for a number of turns equal to Stamina + Primal Urge -2."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success, except that the duration of the second Rage is normal."]}]},{Rank:"•••••",Name:"Soured Rage",Description:"Inflict Kuruth",Cost:"●",Book:"WtF 136",fullDescription:[{type:"paragraph",text:["A werewolf in Rage is a powerful warrior and ally. A werewolf with this Gift, however, can turn that warrior’s power into a liability by souring that Rage and taking control of it out of an unsuspecting victim’s hands. With an ugly First-Tongue curse, the Gift user poisons a victim’s Rage such that it is overridden by the instinct for self-preservation."]},{type:"paragraph",text:["With the expenditure of one Essence point and a successful Manipulation + Intimidation + Purity roll, the Gift user turns a victim’s controlled Rage into the self-preservation instinct of a badly wounded werewolf in the thrall of ",{text:"Kuruth",italic:!0},". The victim suffers no actual damage, but if his contested Composure + Primal Urge roll does not net him as many or more successes than rolled for the user, he loses control of himself and flees for the rest of the scene in a mindless Death Rage of self-preservation."]},{type:"paragraph",text:["This Gift works only on a subject who is already in Gauru form, but it doesn’t matter if he’s been in it long enough to accrue wound penalties. If the subject is already suffering from wound penalties when this Gift is used, he seeks to escape automatically. A werewolf cannot use this Gift if he’s currently in his own Gauru form. Nor does the Gift affect a werewolf who is already in a Death Rage."]}],fullCost:"1 Essence",dicePool:"Manipulation + Intimidation + Purity versus Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The victim enters a Death Rage of mindless destruction rather than self-preservation."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," If the user’s roll fails or the victim’s contested roll nets as many or more successes than the user’s, nothing happens. The user cannot use this Gift again on the same victim for the remainder of the scene."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The most successes are rolled for the Gift user. The victim enters a mindless Death Rage of self-preservation, just as he would if he were already in ",{text:"Kuruth",italic:!0}," and had suffered enough damage to accrue wound penalties and flee the scene. He remains in that state for the rest of the scene and runs for his life with no regard for anything or anyone around him."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success, and the victim loses a Willpower point."]}]}]},{Name:"Retribution",Description:"",Cost:"",Book:"LodgF 115",Content:[{type:"paragraph",text:["Werewolves are not at any loss for skill in battle or in ways to track down their enemy, and so a being that wrongs a werewolf (or, worse, a pack) is probably in for a savage lesson in pain. Members of the Lodge of Wrath, dedicated as they are to seeking out and punishing those who would trespass on or despoil ",{text:"Meninna",italic:!0}," territory, have special blessings from Shrike-Bloody-Beak to aid them in their work."]},{type:"paragraph",text:"Retribution Gifts only function against targets that have directly wronged or harmed the Gift’s user, her pack or the Lodge of Wrath in general. Against innocent targets or offenders that have never committed any offense to the werewolf or her people, these Gifts are useless. The player should be ready to justify the use of these Gifts against a given target, and the Storyteller is, of course, the final arbiter of whether the use is justified."}],Ranks:[{Rank:"•",Name:"Shrike’s Vengeance",Description:"Makes a prayer to the Lodge of Wrath's totem spirit, who grants the ability to inflict lethal damage with any attack to a specific target for one scene.",Cost:"-",Book:"LodgF 115",fullDescription:[{type:"paragraph",text:["Shrike-Bloody-Beak teaches its followers how to strike with spirit talons, making even their Hishu-form fists deadly weapons. A werewolf using this Gift can split open an opponent’s flesh with a slap and disembowel him with a solid kick — provided that he can first convince Shrike of the opponent’s guilt."]},{type:"paragraph",text:["The character utters an entreaty to Shrike in the First Tongue, asking for the spirit’s blessing in punishing a given target. If the entreaty is accepted, that character inflicts lethal damage with any attack against that ",{text:"specific target",italic:!0}," for the rest of the scene, whether or not the attack would normally cause lethal damage. Fists, feet or blunt weapons can kill a target in the same way claws and blades would. The Gift lasts for one scene once activated, and can only be used against one opponent per scene."]}],fullCost:"None",dicePool:"Manipulation + Expression + Honor versus Composure + Primal Urge",action:"Instant; resisted",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Shrike hears the character’s entreaty, but does not find the target worthy of punishment, and chastises the werewolf for wasting the spirit’s time. The character suffers a point of lethal damage, and both of his cheeks begin to bleed as if slashed."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Shrike does not hear or attend to the character’s plea. Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Shrike agrees that the target needs to be hurt, and the character inflicts lethal damage with all attacks against that target for one scene. In addition, any attacks he makes against that target receive a +1 modifier. If the character subsequently makes an attack that would inflict aggravated damage (a silver weapon against a werewolf, or the Gift: Savage Rending), the more powerful Gift takes precedence (but the +1 still applies)."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Shrike is outraged by the target’s obvious guilt and aids the werewolf even further by distracting his foe. The werewolf’s opponent feels tiny stings as Shrike’s servants bombard him, reducing his Defense by 1 against the Gift user for the scene."]}]},{Rank:"••",Name:"Sinful Thoughts",Description:"Sends a spirit to attack a perceived sinner, sapping their willpower.",Cost:"●",Book:"LodgF 115",fullDescription:[{type:"paragraph",text:["Used when someone has offended one of the ",{text:"Serthaha",italic:!0}," in a minor way or with a decent explanation, this Gift works to prevent a recurrence. Shrike-Bloody-Beak sends one of its flock to follow the target of the Gift, watching carefully for any intent to inflict harm upon the werewolf’s pack, trespass on his territory or otherwise repeat his crime. If he so much as considers doing so again, the tiny bird-spirit pecks at him, causing him extreme pain for a few seconds. While this spiritual attack usually doesn’t cause any damage to the target’s body, it’s normally enough to make him think twice about crossing the Lodge of Wrath again."]},{type:"paragraph",text:["Sinful Thoughts requires the werewolf to stare at the target for a full turn. If the target is capable of ridding himself of the shrike-spirit, he may do so (werewolves and some mages often can, for instance, though normal mortals are usually stuck with their watchful hanger-on)."]}],fullCost:"1 Essence",dicePool:"Presence + Occult + Cunning",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The shrike appears, but is confused as to whom to afflict and when to strike. It chooses a random person (perhaps a packmate of the character) and attacks whenever it feels appropriate. It leaves after a day if not shooed away earlier."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No spirit responds."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The shrike-spirit appears and stays near the target for one day per success. Whenever the target considers committing whatever crime caught the ",{text:"Serthaha’s",italic:!0}," ire in the first place, the shrike-spirit pecks at the target fiercely. This causes no physical damage, but strips one point of Willpower. The target perceives this as feelings of depression, guilt and humiliation. The spirit isn’t powerful enough to defend itself against a concerted attack, so if the target is able to enter the ",{text:"Hiril",italic:!0}," and confront the spirit directly, or if someone does so on the target’s behalf, the spirit flies off. The target’s intent must be clearly a repeat of the offensive behavior; if a werewolf used this Gift on a person in her territory with the intent of stopping him from “trespassing,” the target could trespass on other people’s property with impunity. Only considering trespassing on the werewolf’s territory would trigger the Gift effects."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As above, but in addition to the Willpower/Essence loss, roll the spirit’s Power (2) as bashing damage whenever the spirit attacks. This damage manifests as splitting headaches and nosebleeds."]}]},{Rank:"•••",Name:"Shrike’s Larder",Description:`Curses a target, such that they cannot die until the end of the scene or the user of the gift allows them to do so. Only works if the victim's "fatal" damage was inflicted by the user or their pack-mates.`,Cost:"○",Book:"LodgF 116",fullDescription:[{type:"paragraph",text:["The ",{text:"Serthaha",italic:!0}," believe that the soul carries pain after the body dies, and that it serves as a reminder in future lives. Therefore, they sometimes wish to stretch out the pain an offender feels so that, in future incarnations, he will instinctively know to avoid the same crimes. This Gift, named for Shrike-Bloody-Beak’s habit of impaling still-living prey on thorns for later consumption, facilitates that by forestalling the moment of death. The target may (and probably will) wish to die, but cannot until the Gift’s effects end."]},{type:"paragraph",text:["Traditionally, Shrike’s Larder is used to prolong the agony of serious offenders to the Lodge of Wrath. Some ",{text:"Serthaha",italic:!0}," use this Gift on a given target before entering combat, allowing them the surety of at least one survivor to interrogate or leave writhing in pain as an example. Using this Gift as a method of torture requires a roll to resist degeneration if the character’s Harmony is 3 or more (see p. 181 of ",{text:"Werewolf: The Forsaken",bold:!0},")."]}],fullCost:"1 Willpower",dicePool:"Resolve + Medicine + Purity",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift functions too well. The Gift user cannot directly cause physical harm to the target for the rest of the scene; her claws will not cut, her guns will not fire."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The target cannot die until the werewolf allows it, no matter how much damage he suffers. He suffers penalties from taking damage in his last three Health boxes as usual, and if the target is a werewolf he can regenerate this damage (whereupon the ",{text:"Serthaha",italic:!0}," typically injures him further). The Gift’s effects end when the scene ends, at which point the werewolf can choose to reactivate the Gift by spending another point of Willpower. If the target has suffered enough damage to kill him when the Gift’s effects end, he immediately dies. The werewolf can end the Gift at any time before the end of the scene."]},{type:"paragraph",text:["This Gift applies only to damage caused by the target or the Gift user and her pack. For full effect, the target must usually be confined lest he find some way of ending the pain; if he tried to blow his brains out, the Gift would keep him alive, but if he leapt in front of a bus, the damage caused by the bus could well finish him."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No extra effect."]}]},{Rank:"••••",Name:"Guilt’s Lure",Description:"Inspires a target with a desire to return to a place they sinned.",Cost:"●",Book:"LodgF 116",fullDescription:[{type:"paragraph",text:["The Uratha are superlative trackers, but the myriad antiseptic scents in the modern world often make hunting down an unknown trespasser very difficult. This Gift, however, draws the offender back to the scene of the crime, allowing the werewolf and her pack to lay an ambush."]},{type:"paragraph",text:["The Gift must be activated within 24 hours of the crime. The werewolf paces around the crime scene (which might where a body was found, the site of vandalism in the werewolf’s territory, etc.) and emits low growls and snarls. The target, wherever he is, feels a strong pull to return to the area. The desire to return makes sense to the target. A murderer might feel compelled to return and make sure that no one has discovered his crime, while a vandal might want to go back and do more damage."]}],fullCost:"1 Essence",dicePool:"Presence + Persuasion + Cunning versus Resolve + Primal Urge",action:"Contested and extended (15 successes; each roll represents one minute); resistance is reflexive and unconscious",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The target knows that he is in mortal danger if he ever returns to the scene, and furthermore can recognize the Uratha on sight as being a threat (but not necessarily as a werewolf)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The defender reaches 15 successes first and shakes off the desire to return to the area. The target cannot be affected by this Gift again for that particular crime, and has no idea that any attempt to influence her behavior was made."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character’s player reaches 15 successes first. The target feels compelled to return to the scene of the crime as described above. Since he concocts his own reason for wanting to return, he might simply drive by the area, or might return and take more involved action. As such, it behooves the werewolf’s pack to keep an eye out in the surrounding area."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Significant progress is made toward the goal. If the character’s player manages 20 successes, the target feels compelled to walk to the center of the “crime scene” rather than skirt the edges or look in from a distance."]}]},{Rank:"•••••",Name:"Shrike’s Feast",Description:"Touch a target, and inflict lethal damage, while simultaneously draining Essence or Willpower.",Cost:"●",Book:"LodgF 116",fullDescription:[{type:"paragraph",text:["Shrike-Bloody-Beak is known to impale its prey on sharp objects and eat it one piece at a time. The ultimate expression of this spirit’s vengeance is similar — the werewolf can separate the target’s soul and mind from his body, picking away at flesh, spirit and mental strength."]},{type:"paragraph",text:["This Gift requires the werewolf to touch the target. Doing so in combat requires a single success on a roll of Dexterity + Brawl - target’s Defense."]}],fullCost:"1 Essence",dicePool:"Strength + Intimidation + Purity",action:"Reflexive",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Shrike-Bloody-Beak doesn’t see the target as guilty and lashes out at the werewolf for wasting the spirit’s time. The werewolf suffers two points of lethal damage, loses 2 Essence or 1 Willpower (player’s choice)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," One of Shrike-Bloody-Beak’s flocks attacks the target, stripping away first flesh, then spirit, then mind. Each success inflicts a level of lethal damage and then strips a point of Essence (if applicable) or Willpower. These effects occur in order, and more than three successes “resets” the effects. For instance, if the werewolf’s player rolls four successes, the target suffers a point of lethal damage, loses a point of Essence and Willpower and then suffers another point of lethal damage (if the target is a werewolf or another being with Essence; if the target is human, he skips the Essence stage and suffers two points of lethal damage and loses 2 Willpower)."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No extra effect beyond the greater intensity of the assault."]}]}]},{Name:"Savagery",Description:"",Cost:"",Book:"Pure 118",Content:[{type:"paragraph",text:["As those who hunt even the hunters, the Predator Kings are masters at controlling their feral instincts and manipulating such savagery in others. Above all, these Gifts are used by the ",{text:"Ninna Farakh",italic:!0}," to make them even more capable killers and even more dangerous to others. Savagery Gifts are taught by spirits that understand what it is to be a true hunter — bears, lions, birds of prey and so on."]}],Ranks:[{Rank:"•",Name:"Predator’s Presence",Description:"The werewolf’s Social penalties inflicted by her Primal Urge modifier are shared with any human who interacts with her",Cost:"○",Book:"Pure 118",fullDescription:[{type:"paragraph",text:["A werewolf’s innate Primal Urge betrays her to nearby humans, letting the mortals know on a subconscious level that a predator is nearby. This can make people uncomfortable and reluctant to respond favorably to a werewolf in her human form. This Gift allows a ",{text:"Ninna Farakh",italic:!0}," to turn that discomfort to her favor, generating a sense of palpable threat that unnerves and frightens nearby humans into awkwardness and placid obedience."]}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Purity",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf fails to project her predatory aura with any subtlety, instead sending subconscious threats to all nearby. The werewolf suffers the social penalty effects of double her usual Primal Urge rating for the rest of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf masters her hunter’s aura and focuses it upon nearby humans. The werewolf’s Social penalties inflicted by her Primal Urge modifier are shared with any human who interacts with her for the rest of the scene. People react to the werewolf with obedience, placidity, even a little fear, as each human character suffers negative modifiers to their Social rolls until the werewolf leaves their presence."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The werewolf further heightens her domination over the prey creatures, and any human interacting with her suffers an additional -1 to all Social rolls for the remainder of the scene."]}]},{Rank:"••",Name:"Unending Fury",Description:"This Gift suppresses the hunter’s fight or flight instincts",Cost:"●",Book:"Pure 118",fullDescription:[{type:"paragraph",text:["To fall into ",{text:"Kuruth",italic:!0}," is to abandon all reason for the purest instinct of all — to survive at any cost. Some Predator Kings have learned not to fear the touch of Death Rage, but to welcome it as the epitome of the hunter’s arsenal against his prey. This Gift suppresses the hunter’s fight or flight instincts, so that characters down to their last three health boxes do not feel the instinctive urge to preserve their life. Instead, they lose themselves to mindless Rage, ripping flesh and lashing out with no desire beyond killing their enemies. Predator Kings who are blinded by hate for the enemies, who simply wish to take down as many of their foes as possible before their own death or who are certain victory can come with a final-breath effort, use this Gift with devastating effects."]}],fullCost:"1 Essence",dicePool:"None",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"Challenger’s Instinct",Description:"The werewolf can tell how many turns his opponent can spend in the Gauru form",Cost:"●",Book:"Pure 118",fullDescription:[{type:"paragraph",text:["The Predator King with this Gift can sense the depths of Rage boiling within another werewolf, but only when the enemy is immersed in his purest fury. ",{text:"Anshega",italic:!0}," with this ability use it on foes that have shifted into the Gauru form, to read the telltale signs in body language, spirit brands and the aura of a fellow predator to determine how deep the hunter’s fury runs in their opponent’s psyche. It is a bald, open study of another hunter, often employed to locate and face down the most-skilled combatant in an enemy pack. This Gift only works on Uratha in Gauru form that the character can see directly."]}],fullCost:"1 Essence",dicePool:"Wits + Investigation + Cunning",action:"Reflexive",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf completely misinterprets the target of the Gift. The werewolf learns how many turns the target can spend in Gauru form, but the number is either significantly higher or lower than the true figure."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf is unable to sense anything about the target’s Rage at all."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf perceives the target’s inner fury and can tell how many turns his opponent can spend in the Gauru form before he must change back. The werewolf also perceives whether the target has any Gifts or fetishes that could potentially alter the number of turns, such as Rage Gifts or the Elodoth Gift: Fuel Rage."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As a success, but the Predator King becomes deeply attuned to the target’s fury, and can predict the ebb and flow of his foe’s anger. In combat against the target, the character receives +1 Brawl and +1 Defense as he predicts and interprets his attacker’s wild, Rage-driven strikes."]}]},{Rank:"••••",Name:"Embrace the Beast",Description:"A werewolf has to roll to resist Death Rage every time she takes lethal damage and marks a health box",Cost:"",Book:"Pure 119",fullDescription:[{type:"paragraph",text:["Werewolves who use this Gift are often feared by their packmates because of their instability in battle, but no one can deny the incredible killing Rage that pulses in their bones and allows them to tear their enemies apart. This Gift is popular among Predator King elders and lone wolves who walk away from their ",{text:"Anshega",italic:!0}," brethren to live alone. Although any single werewolf is capable of tremendous physical prowess, this ability infuses an ",{text:"Uratha",italic:!0}," with unmatched, unreasoning killing power from her proclivity to fall into Death Rage."]},{type:"paragraph",text:["This Gift alters the criteria for succumbing to ",{text:"Kuruth",italic:!0},". A werewolf has to roll to resist Death Rage every time she takes lethal damage and marks a health box, rather than only when suffering aggravated damage."]}],fullCost:"None. The Gift is innate once learned.",dicePool:"",action:"",rollResults:[]},{Rank:"•••••",Name:"Baresark",Description:"Provoke Death Rage in humans and werewolves",Cost:"●",Book:"Pure 119",fullDescription:[{type:"paragraph",text:["With this power, the Predator King has mastered his own savagery and anger to the point where he can fiercely project it onto others, making them experience the depths of his potential for viciousness. More than that, he can focus his anger so powerfully that it can steal the rational thoughts of humans and other werewolves, causing humans to act like savage animals, and pushing ",{text:"Uratha",italic:!0}," close to ",{text:"Kuruth",italic:!0},"."]}],fullCost:"1 Essence per target the Gift user wishes to affect",dicePool:"Manipulation + Expression + Purity versus Composure + Primal Urge among the affected targets.",action:"Contested; resistance is considered reflexive",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The attempted projection of the character’s killing urges backfires, and he must test for Death Rage."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Gift has no effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The minds of the targets are clouded in animalist fury, making people act on their most savage instincts. Each individual targeted suffers the following effects depending on their nature. Werewolves must test for Death Rage as if they had taken an aggravated wound, and suffer -1 on all Harmony rolls for the rest of the scene. Humans become violently angry with the closest person to them (including the Gift user if appropriate), requiring the expenditure of a Willpower point every turn for the rest of the scene to prevent themselves from attacking. Humans also suffer -2 to all rolls involving Mental attributes and suffer -1 on all Morality rolls for the rest of the scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As with a success, though the effects of the Gift apply to twice the number of people originally targeted."]}]}]},{Name:"Scheherazade's",Description:"",Cost:"",Book:"SotM 140",Content:[{type:"paragraph",text:["The fictitious storyteller, Scheherazade, was not a werewolf. However, since the earliest printings of ",{text:"1,001 Arabian Nights",italic:!0},", many Cahalith have looked to the doomed bride as one of the foremost storytellers and see her as an ideal even if she never existed."]},{type:"paragraph",text:"Spirits of memory and inspiration teach these Gifts so that most Visionaries tie to the heritage of Scheherazade. Only Cahalith can purchase this Gift path."}],Ranks:[{Rank:"•",Name:"The Unending Story",Description:"Tell a story that cannot be interrupted",Cost:"None",Book:"SotM 140",fullDescription:[{type:"paragraph",text:["With a good enough yarn, a Cahalith can hold her audience captivated indefinitely, so long as she maintains the story. Upon activating this Gift, anyone with hearing distance of the story will sit down and listen for its duration, even spirits that might not normally understand or grasp the meaning of the tale."]},{type:"paragraph",text:["To enact this Gift, the Cahalith must be able to tell a story in song or words. While lyrical tales happen in other art forms, this Gift requires spoken words."]}],fullCost:"None",dicePool:"Presence + Expression + Glory, minus the highest Composure of the gathered listeners (or the highest Resistance if those are spirits)",action:"Extended and resisted, each roll represents one minute, and the Gift can last for up to one full scene.",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The story stirs something vile and brutal within listeners. They become angry, and are likely to attack (this is especially true of spirits)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No successes are added. During that minute, listeners are free to act as they see fit."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," During a minute where the Cahalith achieves any successes, listeners must spend a point of Willpower ",{text:"and",italic:!0}," must succeed on a Composure + Primal Urge roll in order to take any action that might interrupt the storytelling."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The story is so potent, at its end the Cahalith feels truly triumphant, gaining a point of lost Willpower at the culmination of the tale."]}]},{Rank:"••",Name:"The Storyteller's Indulgence",Description:"Tell a story that makes a small request of the listeners they are compelled to agree too",Cost:"●",Book:"SotM 140",fullDescription:[{type:"paragraph",text:["Since time immemorial, a storyteller sitting down to pass along a tale by the fireside has been granted certain indulgences. A man comes to town with a tale; someone will bring him a pint. If an aunt sits at the table to talk the old family yarns, someone is bound to bring her a slice of cake and some tea."]},{type:"paragraph",text:["So it is with the Cahalith. With a successful performance of this Gift, the storyteller begins an engrossing tale meant to keep his audience attention distracted from his goal. He may involve the people listening, or call up local history. Regardless, as he’s telling the story, he can make a small request of the listeners and they are compelled to agree."]}],fullCost:"1 Essence",dicePool:"Manipulation + Persuasion + Cunning, contested by the listener’s Composure + Primal Urge",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The target sees the story for what it is, an attempt to manipulate those listening. This may cause the target to respond with hostility. Regardless, the Cahalith suffers a -1 to all social actions against anyone who heard the story for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," There is no compulsion for the listener to obey the Cahalith."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," During the course of his story, the Cahalith can give a single command to one listener. If successful, the target will perform one task for the Cahalith without being aware of the manipulation. The command must be within the confines of the tale told, and must not put the target in direct danger. The task must be something that can be completed within the given scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The listener obeys the compulsion with greater fervor. On future rolls involving the listener, the Cahalith gains +2 to all pertinent Social rolls."]}]},{Rank:"•••",Name:"Perchance to Dream",Description:"Can give target the Prophetic Dream Auspice Ability",Cost:"●",Book:"SotM 141",fullDescription:[{type:"paragraph",text:["Stories told at bedtime can help a child sleep, guiding her toward restful slumber with pleasant dreams. Here, the Cahalith harnesses that core idea not to necessarily provide ",{text:"restful",italic:!0}," sleep, but to grant a listener a ",{text:"meaningful",italic:!0}," sleep."]}],fullCost:"1 Essence",dicePool:"Wits + Expression + Purity",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The story told before the target sleeps is inadvertently haunting and harrowing. The target suffers terrible nightmares — upon the target’s next awakening, she doesn’t gain a Willpower point."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The bedtime story has no effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Cahalith effectively grants the listener the Prophetic Dreams auspice ability — the target sleeps and has a meaningful dream cast in prophetic symbols. Interpretation can be made with a Wits + Occult roll — if the target is not a Uratha, however, that roll suffers -3 dice."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As above, and the target feels very refreshed and clear-headed upon waking, gaining +1 to all Mental rolls for the remainder of the day."]}]},{Rank:"••••",Name:"Drawing the Curtain",Description:"Tell a story that the next time the target spends willpower it automatically a dramatic failure",Cost:"●",Book:"SotM 141",fullDescription:[{type:"paragraph",text:["A wise storyteller knows that when an enemy must be dealt with, the best story is a tragedy. Striking an enemy from any history the Cahalith might create is surely satisfying, but a dramatic end in a story long remembered may be more fitting, and ultimately serve as a good warning to others who would cross the Cahalith. Cahalith with this Gift can tell a tale of woe so terrible that the subject of the tale is marked by fate for an awful end."]}],fullCost:"1 Essence",dicePool:"Manipulation + Expression + Wisdom versus the subject’s Composure + Primal Urge",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Not only does the story not stir fate to turn on the listener, but the listener is aware that the Cahalith was toying with his destiny."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Cahalith finishes her story, but nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The story influences the listener in a dark way. The next time the listener’s player (or Storyteller) chooses to spend Willpower to add dice to a roll, tragedy strikes and the roll is automatically considered a dramatic failure. The Willpower is not actually spent, however."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As above, but the Willpower stays spent."]}]},{Rank:"•••••",Name:"Magnum Opus",Description:"Tell a story that the next time the target spends willpower it automatically adds 3 success instead of dice",Cost:"●○",Book:"SotM 141",fullDescription:[{type:"paragraph",text:["Stories serve a number of functions for a pack: to remind them of past glories, educate, or inspire to future greatness."]},{type:"paragraph",text:["The inspirational potential of the story is demonstrated at its full potential with this Gift. The storyteller weaves an epic tale of how spectacular their successes will be in the near future, and the listeners are so inspired they are able to perform acts with success beyond their wildest dreams."]}],fullCost:"1 Willpower and 1 Essence",dicePool:"Presence + Expression + Glory",action:"Instant",rollResults:[{type:"heading",text:["Roll Results"]},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The story’s effect is counter to the intention. The next time the listener spends Willpower to enhance a roll, no dice are added to the roll, and the listener still loses the point."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The story rouses greatness in its listener. The next time the listener spends Willpower to enhance an action, instead of adding three dice to the roll, add three ",{text:"successes",italic:!0}," to the total rolled. Note that the Cahalith can use this Gift to affect several listeners — up to her Primal Urge score."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The next time the listener spends a point of Willpower to enhance an action, that action is ",{text:"automatically",italic:!0}," an exceptional success."]}]}]},{Name:"Shaping",Description:"",Cost:"",Book:"WtF 137",Content:[{type:"paragraph",text:"It is with these Gifts that the Iron Masters first earned their name, as well as how Luna expresses her ever-changing nature through her Ithaeur. Werewolves use these powers to craft fetishes, perform repairs, embellish mundane objects or even sabotage the items of their enemies."},{type:"paragraph",text:"To use these Gifts, a character must be in either Hishu or Dalu form, and he must touch the item or substance he’s trying to affect. He need not be in total control of the object (especially if he’s trying to affect a select portion of a large object). If someone else is in control of the item, however — such as if he attempts to use Ruin on a sword someone else is swinging — the Gift’s activation roll is contested reflexively by the opponent’s Resolve + Primal-Urge."},{type:"paragraph",text:"These Gifts affect only non-living substances that are already whole. A character could use Sculpt on a large chunk of stone or dried asphalt, for example, but not a pile of gravel. He could also use these Gifts on bone or wood that is no longer part of the living organism from which it was created. Other substances that are susceptible to these Gifts include glass, any metal, plastic, brick, cardboard, concrete, ice (but not liquid water) and rubber. Silver items cannot be affected by this Gift. Nor can ones of supernatural quality, such as enchanted items or undead flesh. An existing fetish or talen cannot be altered or destroyed with these Gifts, for example."}],Ranks:[{Rank:"•",Name:"Straighten",Description:"Repair object (recover half Structure points lost) or ruin it without damage, leaving it useless",Cost:"●",Book:"WtF 137",fullDescription:[{type:"paragraph",text:"This Gift delivers what it promises, straightening out kinks, warps, folds or natural imperfections in a physical object. It could straighten a crooked walking staff into a long pole, uncoil a spring into a stiff wire, smooth out a crumpled piece of sheet metal, make a pitted chunk of concrete as smooth as a river stone, or flatten a bent and crooked blade to its original shape. Even a cast-off stick one finds on the ground could be shaped into a perfectly straight arrow shaft."},{type:"paragraph",text:"This Gift does not, however, repair damage caused by rust, decay, breakage or the removal of part of an object. If one were to punch a hole in a metal door, this Gift would straighten the surface back to its original shape, but the seams of the break would not magically reseal themselves. Nor does the Gift reinforce the strength of an object."},{type:"paragraph",text:"This Gift affects up to one square yard of material per turn. A werewolf could use it to completely repair the badly dented hood of a car in one turn, for example, but it takes multiple turns (and multiple points of Essence) to repair the car’s entire chassis. A werewolf cannot use this Gift on an item on which Ruin has been used successfully."},{type:"paragraph",text:["Used on an object that has suffered Structure damage (see ",{text:"World of Darkness Rulebook",bold:!0},", p. 135), this Gift might restore up to half the points suffered (rounded up). For example, a car that has lost eight of its 12 Structure in a wreck can be the focus of this Gift and regain four Structure points, leaving four non-repaired. The Storyteller decides how applicable such repair is to the object in question, and decides how many applications of the Gift are required to accomplish the repairs. Straighten can be used on an object only once for the current damage that it suffers. Any remainder must be repaired by conventional means (see the Crafts Skill in the ",{text:"World of Darkness Rulebook",bold:!0},", p. 57)."]},{type:"paragraph",text:"Alternatively, Straighten could ruin an object based on its original purpose, without inflicting a single point of Structure damage. A drill bit used to crack safes becomes a useless steel rod, for example."}],fullCost:"1 Essence",dicePool:"No roll is required",action:"Instant",rollResults:[]},{Rank:"••",Name:"Ruin",Description:"Make an object unusable",Cost:"●",Book:"WtF 137",fullDescription:[{type:"paragraph",text:"This Gift has the opposite effect of the preceding one. With a harsh bark and a flare of energy, the character causes an object to warp, twist and crumple up into a useless, gnarled mass. The Gift affects up to about one square yard of material, and the object must be single and discrete. A werewolf could ruin the radiator of a car or the car’s vacuum tube, for example, but he couldn’t ruin the entire engine with one use of the Gift. He could use Ruin to wreck a door, but he couldn’t use it to wreck a load-bearing wall. He could wreck a single ceiling beam, but he couldn’t ruin the entire ceiling."},{type:"paragraph",text:"A werewolf can use this Gift on an object on which Straighten has been used, but a werewolf cannot use Straighten to fix an object on which this Gift has been used."},{type:"paragraph",text:"No actual Structure damage is done to the object in question. Glass doesn’t break. Wood doesn’t splinter. Steel doesn’t crack. It merely changes shape."}],fullCost:"1 Essence",dicePool:"Wits + Crafts + Cunning",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The item is unaffected, but the user of the Gift suffers two points of bashing damage as something writhes and warps in his guts."},{type:"line",label:"Failure",text:"Nothing happens."},{type:"line",label:"Success",text:"A discrete item up to one square yard in area warps and crumples uncontrollably, more than likely rendering it useless."},{type:"line",label:"Exceptional Success",text:"The user regains the Essence spent to activate this Gift."}]},{Rank:"•••",Name:"Sculpt",Description:"Shape matter, making an object malleable (then must roll Dexterity + Crafts to sculpture the object)",Cost:"●+",Book:"WtF 137",fullDescription:[{type:"paragraph",text:"With this Gift, a physical object becomes as malleable and workable as clay. A character can sculpt and re-form the object into any shape he desires, as long as he has the manual dexterity to do so, of course. He can perform quick, indelicate changes, such as snatching a gem out of its setting, or he can perform non-intuitive transformations such as flattening out a bowling ball and shaping it into a stout club."},{type:"paragraph",text:"The character can manipulate up to one cubic yard of material per use of this Gift, and he can continue to work and shape it for half an hour per Essence spent (as long as he continues to touch it). The Essence need not be spent up front; it can be spent throughout the process as it proves necessary. Also, a character can use a tool such as a knife to sculpt the object as long as some other part of his body is touching the substance."},{type:"paragraph",text:"An Intelligence + Crafts + Wisdom roll activates the Gift and makes the substance in question malleable enough to work with, but a Dexterity + Crafts roll (along with any tool bonuses) is necessary to determine the quality of the item he sculpts. When the work is done (either the half-hour time limit runs out without further Essence expenditures, or the character breaks contact with the object), the material returns to its original consistency and physical properties. For example, a character could use this Gift to wad a glass bottle up into a ball and then sculpt a pair of wrist manacles out of it, but when the work is done it’s as easy to smash the manacles as it would be to smash a bottle. The sculpted item has the same Durability of its original form, though it may no longer have the same Size and therefore Structure."},{type:"paragraph",text:"This Gift can affect only one substance at a time, but that substance can be part of a complex object. A werewolf could use this Gift to twist apart the barrel and cylinder of a revolver, for example, since both parts are made of the same material, but the bullets in the cylinder would not be affected, nor would the pistol’s wooden handle. If a character sculpts an empty wine bottle into a glass rose for use as a fetish, the label on the bottle would be unaffected by the Gift (though it would be torn up as the character sculpts the glass to which it is attached)."},{type:"paragraph",text:"Substances that have been affected by this Gift cannot then be affected by Straighten or Ruin, but uses of Sculpt, Shatter, or Condense or Expand (by the same character or different ones) have normal effect."}],fullCost:"1 Essence per half an hour of work",dicePool:"Intelligence + Crafts + Wisdom",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The object or substance in question is affected as if by Ruin, and the character cannot use Sculpt on it again until the next moonrise."},{type:"line",label:"Failure",text:"The object or substance is unaffected."},{type:"line",label:"Success",text:"The object or substance in question becomes malleable and workable for half an hour per Essence point spent, as long as the character remains in physical contact with it. The player may then make normal Dexterity + Crafts rolls to determine how well his sculpture comes out."},{type:"line",label:"Exceptional Success",text:"The character’s efforts earn a +2 bonus on Dexterity + Crafts rolls to shape the material."}]},{Rank:"••••",Name:"Shatter",Description:"Destroy an object (1 Structure point damage per success)",Cost:"○",Book:"WtF 138",fullDescription:[{type:"paragraph",text:"The character howls and breaks down an object just by touching it, more than likely destroying it. It might crumble to dust in his hands or fracture like desert hardpan. It might even explode, depending on what other stress it’s under at the time. For every success achieved on the Presence + Expression + Glory roll, the object loses one point of Structure; Durability is ignored. The object could then be repaired using a Crafts roll and the proper tools, or the character could use Sculpt to magically reassemble the pieces."},{type:"paragraph",text:"A character cannot use Shatter on more than one object simultaneously, but one object can be the target of multiple uses of Shatter by different characters simultaneously. Also, a character can target up to one cubic yard of large objects and concentrate the effects of this Gift in that region. For instance, he could use Shatter on the engine block of a car, but not the entire car. He could use Shatter on the cornerstone of a building but not the entire building. If more than one character uses Shatter on the same object at the same time, they can concentrate their efforts on the same region to dramatically increase the damage done, or spread the damage out over a wider area."}],fullCost:"1 Willpower",dicePool:"Presence + Expression + Glory",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The object loses no Structure points and the character cannot use Shatter on that same object again for 24 hours."},{type:"line",label:"Failure",text:"Nothing happens."},{type:"line",label:"Success",text:"For every success, up to one cubic yard of an object or substance loses a point of Structure."},{type:"line",label:"Exceptional Success",text:"As a success; the extra points are the exceptional reward."}]},{Rank:"•••••",Name:"Condense or Expand",Description:"Alter an object's size (gains or loses 1 Size point and loses or gains 2 points of Durability, respectively)",Cost:"○",Book:"WtF 139",fullDescription:[{type:"paragraph",text:["This bizarre Gift either shrinks or enlarges an object while keeping its mass the same. Making an object larger causes it to become lighter and easier to break, for example, while making it smaller causes it to become heavier and much harder to break. The object maintains its original consistency — woven fibers, for instance, remain flexible — but both its Size and Durability change. If the character condenses an object, its Size decreases by one while its Durability increases by two. If the character expands the object, its Size increases by one while its Durability decreases by two. (Size and Durability combine to form an object’s Structure — effectively its Health — as shown on p. 135 of the ",{text:"World of Darkness Rulebook",bold:!0},", so a change in either calls for a change in Structure.) The character must touch the object in question."]},{type:"paragraph",text:"If two characters try to use opposing versions of this Gift on the same object at the same time, the side with the greater number of successes achieves the desired effect. If they try to achieve the same effect, their efforts combine. If they try to do the same thing but either suffers a dramatic failure, the opposite effect occurs. Objects that are either condensed or expanded cannot then be affected by Straighten or Ruin, although Sculpt and Shatter are still permitted under their normal circumstances. A character can use this Gift multiple times on the same object over successive turns as long as the player pays the Willpower cost and continues to make successful rolls."},{type:"paragraph",text:"If the effects of this Gift reduce an object’s Size or Durability to zero, the object either disappears as a gas or collapses under its own weight (respectively). Also, the subject in question must be a discrete object taking up no more than one cubic yard of space. Undifferentiated sections of larger objects cannot be targeted."},{type:"paragraph",text:"The changes made to an object are permanent."}],fullCost:"1 Willpower",dicePool:"Intelligence + Crafts + Purity",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The effect the character seeks is reversed."},{type:"line",label:"Failure",text:"The object undergoes no change whatsoever."},{type:"line",label:"Success",text:"If the character tries to condense the object, it loses one point of Size and gains two points of Durability (resulting in a net gain of one point of Structure. If the character tries to enlarge the object, it gains one point of Size and loses two points of Durability (resulting in a net loss of one point of Structure). If the object could cause damage to a person or other object from being shrunk (such as a worn pair of handcuffs or a briefcase containing a laptop), both the condensed object and the person or object take four points of lethal damage. If this is not sufficient damage to destroy or sever whatever is within the condensed object, the condensation stops. A necklace so affected would shrink enough to inflict four points of damage to its wearer but would not keep shrinking enough to sever the wearer’s head."},{type:"line",label:"Exceptional Success",text:"The change in the object’s Durability increases by one additional point. That is, if the character tries to enlarge the object, it loses three points of Durability. If the character tries to shrink the object, it gains three points of Durability."}]}]},{Name:"Scourging",Description:"",Cost:"",Book:"Pure 119",Content:[{type:"paragraph",text:"The Scouring list is considered an affinity Gift list for the Ivory Claws. It represents their relationship to the Purity Renown and the benediction of Silver Wolf. The core idea of purity is that un-alike things should not mix. Silver Wolf and his servants demand adherence to that principle. These Gifts are most commonly taught by eagle-spirits."}],Ranks:[{Rank:"•",Name:"Sense the Impure",Description:"Determine the purity of a subject’s werewolf blood by scent",Cost:"",Book:"Pure 119",fullDescription:[{type:"paragraph",text:"Silver Wolf insists on the highest standards of pure blood for his subjects. This Gift allows the Ivory Claws to determine the purity of a subject’s blood — or a substance — merely by scent."},{type:"paragraph",text:"If the target is a liquid, gas or a living creature, the werewolf must be within a few feet of the target of the Gift in order to activate it. If the target is a solid, the Uratha must touch it to activate this Gift."}],fullCost:"None",dicePool:"Wits + Animal Ken + Wisdom",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Ivory Claw believes the opposite of the truth — either that a target with pure blood or pure substance is impure, or the other way around."},{type:"line",label:"Failure",text:"The Ivory Claw does not learn anything about the target."},{type:"line",label:"Success",text:["The Ivory Claw learns whether the target is a werewolf; the Gift user can also discern whether the target has any Uratha ancestors within the past three generations or has the Wolf-Blooded Merit. If the target is inanimate, the Gift user gets an idea of the target’s level of Purity in general terms. The Gift does ",{text:"not",italic:!0}," permit the Ivory Claw to detect pre-Change werewolves; however, it does give the user an idea of even wolf-blooded humans’ ancestry, as above."]},{type:"line",label:"Dramatic Success",text:"Per success; additionally, if the target is a werewolf or has the Wolf-Blooded Merit, the Uratha can tell whether the target is a Pure werewolf or one of the Forsaken, and whether the target’s ancestors were Pure or Forsaken."}]},{Rank:"••",Name:"Relentless Focus",Description:"For every two successes achieved on the roll, the Uratha regains a point of Willpower",Cost:"○",Book:"Pure 120",fullDescription:[{type:"paragraph",text:"Purity begins in the soul. The Uratha using this Gift gains intense focus on whatever actions are most important to him, and only the greatest of temptations or distractions can gain his attention. This Gift can be used only once per day."}],fullCost:"1 Willpower",dicePool:"Resolve + Empathy + Honor",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"Something is too distracting to ignore. The Uratha loses an additional point of Willpower."},{type:"line",label:"Failure",text:"The Uratha cannot gain the desired level of focus."},{type:"line",label:"Success",text:"For every two successes achieved on the roll, the Uratha regains a point of Willpower (up to his normal maximum)."},{type:"line",label:"Dramatic Success",text:"Per success, and the Uratha also gets one bonus die to all Resolve, Composure or Stamina rolls for the remainder of the scene."}]},{Rank:"•••",Name:"Purify",Description:"Purify substance",Cost:"●",Book:"Pure 120",fullDescription:[{type:"paragraph",text:"This Gift separates different substances out from a small, mostly pure mixture. The mixture cannot be living or recently dead material, but can be solid, liquid or gas. The Gift can affect no more than one liter of liquid or solid, or a small room’s worth of gas. This Gift can ensure that there is no poison in a drink, change 14kt gold into 24kt gold or drive dangerous gases from a room. Purify does not split a mixture into all of its components separately. Instead, whatever substance comprises the majority of a mixture is left alone, and anything that isn’t that substance is extracted in a single, visible mass."},{type:"paragraph",text:["Although the Gift is magical in nature, Purify obeys the laws of chemistry: Purify ",{text:"will not",bold:!0}," break a molecular compound apart, but only perform a physical change. For example, Purify cannot break alcohol down into carbon, hydrogen and oxygen — but the Gift could pull water and other substances out of an alcoholic drink, leaving behind 100% pure alcohol."]},{type:"paragraph",text:"At the character’s discretion, the impurities in the substance may be pushed a few inches away from the newly pure substance — enough to leave a clean, full container of the pure material and a puddle of other material outside of that container."},{type:"paragraph",text:"Purify renders poisoned or contaminated food or drink safe to eat. Purified explosives probably won’t work. Purified gems shatter; purified precious metals become more valuable per ounce. This Gift can be used on fetishes — however, the fetish gains a resistance roll equal to its spirit’s Resistance Trait."}],fullCost:"1 Essence",dicePool:"Intelligence + Science + Purity",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The character cannot purify the substance with this Gift until 24 hours have passed."},{type:"line",label:"Failure",text:"The Gift fails to work"},{type:"line",label:"Success",text:"The substance is purified, as described above."},{type:"line",label:"Exceptional Success",text:"The substance is purified, as described, and the character does not lose the Essence you would ordinarily spend to activate this Gift."}]},{Rank:"••••",Name:"Expel",Description:"This Gift pushes all parasitic or symbiotic life forms out of a living creature",Cost:"○",Book:"Pure 120",fullDescription:[{type:"paragraph",text:"This Gift pushes all parasitic or symbiotic life forms out of a living creature (including animals, humans and Uratha). Expel cleans infected wounds perfectly, heals bacterial disease completely and expels any parasites. Microorganisms are destroyed invisibly; any visible parasite is killed and forcibly expelled through the nearest suitable opening."},{type:"paragraph",text:"Unfortunately, this Gift does not discriminate between beneficial symbiote and parasite. Most creatures’ digestive tracts contain extensive quantities of microorganisms to help them digest food. Expel eliminates those as well. This can lead to a few days of intestinal distress for the subject of the Gift, until he has eaten enough local food to re-establish the balance of his digestive systems. This distress causes a one-die penalty on Composure rolls for the next three days."},{type:"paragraph",text:"Expel does not work on magical diseases, viruses or prion-based diseases. It cannot expel a spirit from a host body, though the Gift can force out a supernatural parasite with a material form."}],fullCost:"1 Willpower",dicePool:"Intelligence + Medicine + Cunning",action:"Extended (each roll represents one turn spent in a trance over the subject; the number of successes needed is the same as the Stamina + Resolve roll difficulty on p. 176 of The World of Darkness).",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The infection is worse than previously thought; Expel will not work on it, and the target’s Stamina + Resistance roll requires five more successes than previously thought."},{type:"line",label:"Failure",text:"No successes are gained for this turn. If the character fails three successive rolls, the character cannot use Expel again on this target until the next day."},{type:"line",label:"Success",text:"Successes are accumulated. If enough successes are gained, the infection, disease or parasite is eliminated. This Gift does not heal damage already done by that influence."},{type:"line",label:"Exceptional Success",text:"A greater number of successes are accumulated. If five extra successes over the target are achieved on that final roll, the target’s immune system is supercharged for the next three days, providing an additional two dice to any Stamina + Resistance rolls to avoid disease."}]},{Rank:"•••••",Name:"Cast Out",Description:"The spirit is driven from its host and takes one point of Corpus damage; the spirit suffers a one-die penalty due to pain for a day and a night afterwards",Cost:"●",Book:"Pure 121",fullDescription:[{type:"paragraph",text:"Purity of spirit is as important to Silver Wolf as purity of body. Cast Out drives a possessing spirit from its subject. While many Uratha know the rite Banish Spirit, Cast Out works much more quickly. However, Cast Out is also incredibly painful — for the Uratha who uses it, the spirit the Uratha targets with the Gift and the person possessed by the spirit. The use of Cast Out is a sure way for an Ivory Claw to make a long-term enemy out of the spirit she targets."},{type:"paragraph",text:["To use Cast Out, the Uratha must cut her hand and place (smear, flick or fling) her blood on the possessed person or thing. The wound causes great pain and heals slowly (it is an ",{text:"aggravated",italic:!0}," wound). After being expelled, the spirit suffers a one-die penalty from pain."]},{type:"paragraph",text:"Cast Out works on possessed animals or things as well as humans."}],fullCost:"1 Essence + 1 point of aggravated damage",dicePool:"Resolve + Occult + Glory versus the spirit’s Resistance",action:"Contested",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The spirit is not driven from its host and takes no damage. The host body suffers one point of aggravated damage."},{type:"line",label:"Failure",text:"The spirit is not driven from its host and takes no damage."},{type:"line",label:"Success",text:"The spirit is driven from its host and takes one point of Corpus damage; the spirit suffers a one-die penalty due to pain for a day and a night afterwards."},{type:"line",label:"Dramatic Success",text:"Per success, but the wound that the Uratha suffers is only a lethal wound point rather than aggravated."}]}]},{Name:"Silver Road",Description:"",Cost:"",Book:"WAtP 144",Content:[{type:"paragraph",text:["This Gift list is only open to those who have been initiated into a crusade by the Rite of the Silver Road. This list further bolsters the power of Forsaken, making them implacable foes of Luna’s enemies, granting them increased powers related to the Moon and the ",{text:"Hisil",italic:!0},"."]}],Ranks:[{Rank:"•",Name:"Luna’s Grace",Description:"+2 Primal Urge for resisting magical deception or coercion purposes",Cost:"●",Book:"WAtP 144",fullDescription:[{type:"paragraph",text:"Uratha on the Silver Road may ask for Luna’s help to resist the effects of others who would turn the Uratha from the Silver Road. By offering her a sacrifice of Essence, the Uratha strengthens Luna’s bonds to himself for a short time, intensifying his resolve in her cause."},{type:"paragraph",text:"During this period of grace, the Forsaken’s Primal Urge score is considered two higher for the purposes of resisting any magical attempt at deception or coercion. The Gift’s effects last for the scene."}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Lunar Martyr",Description:"Suppress flight instinct when in Death Rage",Cost:"○",Book:"WAtP 145",fullDescription:[{type:"paragraph",text:["Use of this Gift suppresses the automatic flight instinct when in Death Rage. The Uratha who falls into Death Rage while under the effects of this Gift only flees when she has one (instead of three) wounds left (see ",{text:"Werewolf: The Forsaken",bold:!0},", p. 174). This Gift is dangerous to both the Uratha and her allies, but is often used in instances when the Uratha fears overwhelming odds and wishes to do as much damage as possible."]},{type:"paragraph",text:"This Gift lasts for a scene."}],fullCost:"1 Willpower",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"•••",Name:"Leap the Moon",Description:"Tunnel through the Shadow",Cost:"●●○○",Book:"WAtP 145",fullDescription:[{type:"paragraph",text:["This powerful Gift calls upon the Lunes to create a tunnel through the Gauntlet and ",{text:"Hisil",italic:!0},". The Forsaken can suddenly disappear and reappear nearby, getting the drop on his opponents or moving through solid walls. The Uratha seemingly walks into nothing and steps out somewhere else. (The target of an attack surprised by this Gift normally loses his or her Defense.)"]},{type:"paragraph",text:["The Uratha’s travel is limited by the nature of the Shadow, rather than physical obstacles in this world. A wall that exists in the ",{text:"Hisil",italic:!0}," may block the Forsaken’s progress, while a bank vault in this world, with no spirit reflection, offers no impediment whatsoever."]},{type:"paragraph",text:["Use the modifiers for stepping sideways (see ",{text:"Werewolf: The Forsaken",bold:!0},", p. 250) per normal."]}],fullCost:"2 Essence + 2 Willpower",dicePool:"Dexterity + Athletics + Cunning",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Uratha is deposited in the ",{text:"Hisil",italic:!0}," by the offended Lunes and left high and dry."]},{type:"line",label:"Failure",text:"The Gift fails."},{type:"line",label:"Success",text:["The length of the tunnel is equal to the number of successes times two in yards ",{text:"or",italic:!0}," the Forsaken’s Speed, whichever is lower."]},{type:"line",label:"Dramatic Success",text:"The length of the tunnel is equal to the number of successes times two in yards plus the Uratha’s Speed."}]},{Rank:"••••",Name:"Silverpelt",Description:"Turn fur into silver",Cost:"●",Book:"WAtP 145",fullDescription:[{type:"paragraph",text:"This potent Gift turns the tips of many individual strands of hair in the Uratha’s pelt into silver needles. The more powerful the Uratha, the more hair is transformed. Uratha who touch the character suffer an automatic attack. The damage counts as silver (aggravated to werewolves). Any attacker making Brawl or Weaponry attacks, or locked in a grapple with the character, suffers this attack."},{type:"paragraph",text:"This is only useful in Gauru, Urshul and Urhan forms."}],fullCost:"1 Essence",dicePool:"Stamina + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The silver fur grows inward for an instant. The Uratha suffers an aggravated wound."},{type:"line",label:"Failure",text:"The Gift fails."},{type:"line",label:"Success",text:"Random strands of hair are transformed into silver needles. The effect lasts for one turn per success. Roll the character’s Primal Urge as silver damage against any werewolf making bodily contact with the Gift user. The attacker (the person doing the touching) gains the effect of armor against this damage, but not Defense."},{type:"line",label:"Dramatic Success",text:"The needles gain Armor Piercing 2."}]},{Rank:"•••••",Name:"Five Faces of Luna",Description:"All werewolves count as being in their auspice moon phase in an area",Cost:"●○",Book:"WAtP 146",fullDescription:[{type:"paragraph",text:"This Gift bathes the Uratha in the area with the light of her auspice, allowing her to function as if the moon is in her auspice phase for the scene. Anyone viewing the moon behind an Uratha using this Gift sees the moon as a rosette of each of its five phases."}],fullCost:"1 Willpower, 1 Essence",dicePool:"Presence + Expression + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"Luna turns her back on the Uratha; any and all allies within 10 yards lose any benefit of the moon’s phase for the scene."},{type:"line",label:"Failure",text:"The Gift fails."},{type:"line",label:"Success",text:"All allies within a number of yards equal to the successes rolled are affected by this Gift. This radiance moves with the Gift user for the duration."},{type:"line",label:"Dramatic Success",text:"The area is doubled."}]}]},{Name:"Spirit’s Silence, The",Description:"",Cost:"",Book:"",Content:[],Ranks:[{Rank:"• - •••••",Name:"",Description:"Each level can make the sound of activating gifts of the same level completely silent",Cost:"●",Book:"LodgS 129",fullDescription:[{type:"paragraph",text:"This rite, nicknamed the “Silent Treatment” by a few Thin Men, allows the werewolf to defer the noise created by a rite, Gift or fetish activation to another time. There are actually five versions of this Gift, ranked one to five. Each version affects Gifts or fetish activation of the same level; for example, the two-dot version of The Spirits’ Silence can affect two-dot rites, Gifts and fetishes, and so on. Note that the Gift effects are not cumulative; a Thin Man who knows the four-dot version of this Gift but not the three-dot version cannot silence a three-dot Gift."}],fullCost:"1 Essence",dicePool:"Wits + Stealth + Cunning",action:"Instant (although mimicking the action of the rite, Gift or fetish activation may take longer)",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"Not only are the desired sounds not captured, but the Spirits’ Silence cannot be used with that Gift, rite or fetish for one lunar cycle."},{type:"line",label:"Failure",text:"The sounds of the accompanying Gift, rite or fetish are not captured."},{type:"line",label:"Success",text:["When performing The Spirits’ Silence, the Uratha declares another of his Gifts, rites or fetishes at the same time. He then mimics the sounds and actions of the Gift, rite or fetish. Those sounds are “captured” by a mynah-spirit, who flies with the information deep into the ",{text:"Hisil",italic:!0},". When the Uratha goes to activate the ability associated with The Spirits’ Silence, the mynah releases the sound (presumably far, far away from the werewolf). The result is that any Gift, rite or fetish can be silenced, making absolutely no noise — not just for the required activation, but for the entire Gift or rite! If a fetish, rite or Gift requires a response or noise to be created by a target, then the target must either be present for this Gift’s usage and be willing and able to make the required noise, or the target will still make the same audible noises at the time of the Gift or rite’s activation (although the rest of the action will be silent). Only direct effects of the Gift or rite are silenced; for example, if a Shadow used the Rank 5 of this gift on the Rank 4 Gift Invoke the Wind’s Wrath, the sound of the whirlwind would be silenced, but a target knocked into a building would still be audible."]},{type:"line",label:"Exceptional Success",text:"The Uratha feels especially attuned in the mimicry he performs; in addition to the benefits of success, he gains a +1 bonus to the usage or activation of the Gift or rite when he decides to use it."}]}]},{Name:"Stalker's Moon",Description:"",Cost:"",Book:"Lore 88",Content:[{type:"paragraph",text:"The lightless Stalker’s Moon grants Gifts of stealth and tracking, ways for an Irraka to disguise his own presence even as he moves in for the kill."}],Ranks:[{Rank:"•",Name:"Soundless Strike",Description:"Invoke a brief silence. An Irraka's turn happens in complete silence.",Cost:"●",Book:"Lore 88",fullDescription:[{type:"paragraph",text:"Using this Gift, the Irraka can strike in a single moment of blessed silence. Claws tear through flesh without a sound, a victim’s mouth strains to form a scream that will not come. Though the moment of silence is fleeting, a cunning Irraka can turn it into a great opportunity."},{type:"paragraph",text:"This Gift must be invoked during the Irraka’s turn."}],fullCost:"1 Essence",dicePool:"Dexterity + Stealth + Purity",action:"Reflexive",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Gift fails, and the Irraka is rattled by its failure. The Irraka suffers a -1 penalty to the action in question."},{type:"line",label:"Failure",text:"The Gift has no effect."},{type:"line",label:"Success",text:"The Irraka’s turn happens in complete silence. If he tears the leg off a victim, the victim’s scream is without sound. If he fires a gun at point-blank range, the report is inaudible."},{type:"line",label:"Exceptional Success",text:"If the Irraka’s target survives, her next turn is also spent in complete silence, preventing her from crying for help."}]},{Rank:"••",Name:"See Heat",Description:"Thermal vision for a scene",Cost:"-",Book:"Lore 88",fullDescription:[{type:"paragraph",text:"There’s more than one way to follow a trail, and this Gift opens the Irraka’s eyes to an entirely new realm of experience. The Irraka becomes able to see his surroundings as patterns of heat — living creatures are warm, fire almost blindingly bright, landscape features much cooler."}],fullCost:"None",dicePool:"Wits + Survival + Wisdom",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Gift fails to work; the Irraka cannot use the Gift again for the remainder of the scene."},{type:"line",label:"Failure",text:"The Gift doesn’t take effect."},{type:"line",label:"Success",text:"The Irraka shifts his visual perception to pick up heat rather than visible light. While this Gift is in effect, his eyes reflect a deep red-orange when light falls on them. While using this Gift, certain details may be hard or impossible to distinguish; the Irraka won’t be able to read a book, for instance. However, lingering heat traces can be detected — if a footprint is still warm, the Irraka will know with a glance. The Gift lasts for the scene, or until the Irraka chooses to cancel its effects."},{type:"line",label:"Exceptional Success",text:"The outlines of objects or people become more clearly defined, although certain details remain impossible to distinguish. An Irraka might be able to tell what clothes a person has on, for instance, though not what color they are."}]},{Rank:"•••",Name:"Liar's Brand",Description:"Change renown brand for a scene",Cost:"●",Book:"Lore 88",fullDescription:[{type:"paragraph",text:"One of the difficulties in deceiving other werewolves or spirits is that the spirit brands that mark Renown can give an Irraka away. The Irraka who learns this Gift can cheat a little in this regard, masking his brands and the Renown that they convey with illusion. Some are even skilled enough to alter their brands so that they can pass for a member of the Pure Tribes rather than appearing to be marked by Luna."},{type:"paragraph",text:"Though this deception is far from what’s considered honorable, nonetheless it is accepted as part of the Irraka’s arsenal. An Irraka who uses this Gift too frequently to appear as more Renowned than he is might have difficulty gaining Honor Renown in the future, but no single use of this Gift (particularly to appear more humble than he actually is) carries dishonor by its very nature."}],fullCost:"1 Essence",dicePool:"Manipulation + Subterfuge + Cunning",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Irraka’s spirit brands flare and then grow dull, although they remain visible. The Irraka suffers a -2 modifier to all dice pools involving Renown, including rolls made to activate Gifts, for the duration of the scene."},{type:"line",label:"Failure",text:"The Irraka is unable to disguise the patterns of his spirit brands."},{type:"line",label:"Success",text:["The Irraka is able to conceal and even faintly alter the patterns of the spirit brands that shine on his coat. If the character mutes the patterns of his Renown, the werewolf may lower his visible Renown in one category per success achieved on the roll. The Irraka may leave his Renown in any given category where it is, or even conceal it entirely; an Irraka who conceals any sign of his spirit brands can pass for a werewolf who has not yet been initiated or even for an ordinary human.",{type:"lineBreak"},"If the Irraka is attempting to add to his brands temporarily, he may add one point of mock Renown, plus one additional point of false Renown for every two successes after the first. This may allow him rise in equivalency to the spirits’ Rank, or to more effectively masquerade as a member of a different auspice or tribe. Note that although this mock Renown might convince a spirit that he is capable of learning a more potent Gift than he can actually master, the Liar’s Brand Gift ceases working the moment a spirit begins trying to teach the Irraka a Gift. It would seem the Irralunim believe that such a deception can be allowed only so far.",{type:"lineBreak"},"The Irraka can attempt to disguise his Renown so that it resembles the very different scar brands of the Pure Tribes. If he is successful with this Gift, he may add his Purity Renown to any Social dice pools made to influence the Pure, as described on p. 78 of ",{text:"Werewolf: The Forsaken",bold:!0},". However, this Gift conveys no knowledge of Pure customs and rituals, so the Irraka’s disguise is only as good as his wits.",{type:"lineBreak"},"The effects of the disguise last for the scene, or until dispelled as described above."]},{type:"line",label:"Exceptional Success",text:"The effects of the disguise last until the next moonrise, or until dispelled as described above."},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["-1","Attempting to appear of higher Renown."],["-2","Attempting to emulate the spirit brands of Pure Renown."]]}]},{Rank:"••••",Name:"Stolen Scent",Description:"Mimic a target's scent he is familiar with for 1 hour per success",Cost:"●",Book:"Lore 89",fullDescription:[{type:"paragraph",text:["It’s one thing to leave no scent. It’s quite another to leave a misleading one. The Irraka with this Gift can alter his scent however he likes, even going so far as leaving the scent of a rival at the scene of a murder. Given how many ",{text:"werewolves",bold:!0}," trust their noses before their eyes, this is no small thing."]}],fullCost:"1 Essence",dicePool:"Manipulation + Survival + Glory",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Irraka only enhances his own scent, smelling more pungent than usual for the duration of the scene."},{type:"line",label:"Failure",text:"The Gift fails to work."},{type:"line",label:"Success",text:"The Irraka leaves the scent of the target of his choice behind wherever he walks. He may duplicate any scent he is familiar with (that is to say, any scent he’s reliably observed in Urshul or Urhan form) — human or animal, of any gender, even mimicking the scent of a wounded or sick creature. He may change his scent as many times as he likes while the Gift remains in effect. When coupled with the Stealth Gift: Feet of Mist, the Irraka can lay trails that even the most skilled Predator King would have difficulty unraveling. The Gift lasts for one hour per success, although the Irraka may cancel its effects at any time as a reflexive action."},{type:"line",label:"Exceptional Success",text:"No additional effect."}]},{Rank:"•••••",Name:"Strike Blind",Description:"Remove a target's sense of vision, audition or smell for 24 hours",Cost:"●●",Book:"Lore 89",fullDescription:[{type:"paragraph",text:"The Irraka strives to deceive the senses of others, but isn’t above removing them entirely. This Gift enables the Irraka to strike a foe blind, to make her go deaf or to rob her of her sense of smell. Any one of the three is a terrible punishment for a werewolf, but human prey are particularly vulnerable to losing their sight."}],fullCost:"2 Essence",dicePool:"Wits + Medicine + Honor versus target’s Composure + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The Irraka catches a bit of backlash from the Gift. For the rest of the scene, the Irraka suffers a -1 penalty to all perception-related rolls."},{type:"line",label:"Failure",text:"The Gift fails to work."},{type:"line",label:"Success",text:"The victim is struck blind, deaf or scent-blind; the Irraka chooses which sense is affected. The sensory loss lasts for 24 hours."},{type:"line",label:"Exceptional Success",text:"The sensory loss lasts for an entire lunar month, although certain supernatural means may be able to restore the victim."}]}]},{Name:"Stalking",Description:"",Cost:"",Book:"Rage 125",Content:[{type:"paragraph",text:"Stalking Gifts reflect Hikaon-Ur’s own hunting style, combining the essence of her stealth, skill and predatory mastery within her own hunting ground."},{type:"paragraph",text:"They are sometimes referred to as Black Wolf Gifts, though whether this is in honor of the totem or because she was the first to bestow them onto the Forsaken is a matter of debate."},{type:"paragraph",text:["Stalking Gifts are treated as tribal Gifts for the Hunters in Darkness, who learn these Gifts from spirits of darkness, night and shadow. ",{text:"Meninna",italic:!0}," characters can choose to begin play with one of these Gifts as their tribal selections or learn the Gifts through the course of the chronicle as with experience points."]},{type:"paragraph",text:"A curious aspect to these powers is that they function only at night."}],Ranks:[{Rank:"•",Name:"Night Sight",Description:"Suffer no penalties for blindness in darkened or pitch-black areas",Cost:"-",Book:"Rage 125",fullDescription:[{type:"paragraph",text:"Wolves have an incredibly powerful sense of smell and keen hearing to go with it. Werewolves can take advantage of this aspect of their nature just by shapeshifting to their wolf forms, but for Hunters in Darkness who claim city territories, that’s not always an easy option. Just as Hikaon-Ur hunted in pitch blackness by using her supernatural senses, so too do her children learn to see in utter darkness as if the moon’s bright light illuminated all around them."}],fullCost:"None",dicePool:"Intelligence + Survival + Honor",action:"Reflexive",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The werewolf is temporarily blinded for a turn as her eyes fail to register anything."},{type:"line",label:"Failure",text:"The werewolf’s vision is unchanged."},{type:"line",label:"Success",text:"The character suffers no penalties for blindness in darkened or pitch-black areas for the duration of the scene or until sunrise, whichever comes first. Supernatural darkness hinders the werewolf as normal."},{type:"line",label:"Exceptional Success",text:"The werewolf is able to see even in supernatural darkness."}]},{Rank:"••",Name:"Heaven’s Guidance",Description:"Pinpoint roughly where she is, giving her a perfect sense of direction and an eidetic recollection of the ways and distances she has traveled since sunset",Cost:"○",Book:"Rage 126",fullDescription:[{type:"paragraph",text:"A true hunter is never lost in the wilderness, whether it’s the deep wild, the back alleys of cities or the distorted chaos of the Shadow. This Gift allows the werewolf to pinpoint roughly where she is, giving her a perfect sense of direction and an eidetic recollection of the ways and distances she has traveled since sunset."},{type:"paragraph",text:"The character needs only look up at the night sky to activate the Gift. Whether the sky is a star-filled expanse or a dark and cloudy shroud, the werewolf feels the Gift’s benefits."}],fullCost:"1 Willpower",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"•••",Name:"Scent the Supernatural",Description:"Can “smell” the presence of any supernatural creature or active supernatural effect within 30 feet",Cost:"○",Book:"Rage 126",fullDescription:[{type:"paragraph",text:"The best hunters develop an almost sixth sense for danger and being watched. This Gift allows a Hunter in Darkness to detect the scent of any unnatural or supernatural presence in the area, and determine the presence’s type. Supernatural presences include manifested spirits, Ridden, Hosts, vampires, mages, werewolves, ghosts and any Gifts or rites being performed nearby. Scent the Supernatural only reveals presences of supernatural entities on the same side of the Gauntlet as the character using the Gift."}],fullCost:"1 Willpower",dicePool:"Wits + Empathy + Wisdom",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The werewolf believes she can sense the presence of something supernatural nearby, but is either incorrect or grossly misjudges the type of being detected."},{type:"line",label:"Failure",text:"The character detects nothing nearby."},{type:"line",label:"Success",text:"For every success on the Gift roll, the werewolf can “smell” the presence of any supernatural creature or active supernatural effect within 30 feet. The scent varies by the nature of the presence, although some imprecision is still possible. The Hunter will instantly recognize another werewolf’s scent or the scent of a familiar Gift’s effect, but other supernatural presences may become less obvious based on the character’s familiarity with them. A vampire would probably register as “something dead” or “a stink of blood,” depending on its current status, scents that could be confused with other undead or entities that feed on or bathe in blood."},{type:"line",label:"Exceptional Success",text:"The details offered are more precise. A vampire might be described as “a stench of dead, polluted blood,” for instance."}]},{Rank:"••••",Name:"Shadow Strike",Description:"For every success on the roll, the character may emerge from a patch of darkness up to 20 yards away",Cost:"●",Book:"Rage 126",fullDescription:[{type:"paragraph",text:"Night is the time when the Hunters in Darkness are in their element. This Gift allows the werewolf to literally blend in with the darkness around her as she hunts, with shadows and the night itself wrapping around her as she stalks her prey."},{type:"paragraph",text:"Characters using this Gift are able to melt into a shadow or other patch of natural darkness and emerge from another elsewhere to make the killing strike. The only consideration is that the shadow where the character emerges from must be of a size to allow the werewolf to “fit” as if emerging from a portal or hole."}],fullCost:"1 Essence",dicePool:"Manipulation + Stealth + Cunning",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The character not only fails to emerge from the patch of darkness as desired, but she is trapped in absolute blackness for three turns, unable to escape back to the real world or the Shadow."},{type:"line",label:"Failure",text:"The character fails to enter the shadow."},{type:"line",label:"Success",text:"For every success on the roll, the character may emerge from a patch of darkness up to 20 yards away."},{type:"line",label:"Exceptional Success",text:"No effect beyond the bonuses of additional successes."}]},{Rank:"•••••",Name:"Shadow Pack",Description:"Summon 1 Shadow wolf per essence spent for 1 turn per success. They have the same statistics that the character in Urhan.",Cost:"●+",Book:"Rage 126",fullDescription:[{type:"paragraph",text:"Hikaon-Ur was a lone wolf, and though her children run in packs with their brethren, there will be times in a werewolf’s life when she finds herself alone in the darkness, hunting alone as her totem hunted. This Gift is an echo of the great powers Black Wolf used in the depths of the Pangaean wilderness, summoning a pack of dark and shadowy wolves to assist in bringing down prey. The Shadow Pack appear as flickering wolf-shapes composed of pure darkness, flashing in and out of sight as they move. These shadow-wolves are Hikaon’s own servants and allies, born before the world split. They hunt in eerie silence, moving in perfect unison with the summoner, returning to Hikaon’s dark wilderness realm in the Shadow once their hunt is completed."},{type:"paragraph",text:"To call the shadow-wolves, the character must raise her head and howl silently to the night sky as she spends the Essence, going through the motions of howling but making no sound. Upon manifestation (either in the physical world or the Shadow) the shadow-wolves use the character’s Attribute and Ability scores, and possess the same Health scores as the werewolf in Urhan form."}],fullCost:"1 Essence per shadow-wolf summoned",dicePool:"Presence + Animal Ken + Purity",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The silent summons fails to call any of Black Wolf’s spirit brood to the character’s side, and the shadow-wolves ridicule her attempt. She may not use the Gift again for another cycle of the moon."},{type:"line",label:"Failure",text:"The silent howl fails to summon any of Hikaon-Ur’s shadow-wolves."},{type:"line",label:"Success",text:"The shadow-wolves begin to manifest from any shadowed areas within 10 yards of the character, and will be able to hunt with her at the beginning of her next turn. The summoning lasts for a number of turns equal to the number of successes rolled."},{type:"line",label:"Exceptional Success",text:"No additional bonus beyond the extra successes."}]}]},{Name:"Stealth",Description:"",Cost:"",Book:"WtF 139",Content:[{type:"paragraph",text:"Werewolves frequently find great advantage in leaving no footprints or traces of their presence. Likewise, moving silently and swiftly is of benefit in both hunting prey and stalking an enemy. These Gifts represent the preternatural abilities of werewolves to remain hidden from prying eyes. The Hunters in Darkness in particular possess affinity with these Gifts, and any who find a need for furtiveness and secrecy find them highly beneficial. The spirits of nocturnal animals or entities are the primary teachers of these Gifts."}],Ranks:[{Rank:"•",Name:"Feet of Mist",Description:"Leave no scent (-1 to tracking or -3 if 1 Willpower point is spent)",Cost:"● (○)",Book:"WtF 139",fullDescription:[{type:"paragraph",text:"Sight and sound are not the hardest senses for a werewolf to defeat, but even a bloodhound would wear its nose out trailing a werewolf with Feet of Mist. The werewolf’s scent fades to near-imperceptibility."},{type:"paragraph",text:"All attempts to track or detect the werewolf by scent are automatically at a -1 penalty (see “Tracking,” p. 178), even when this Gift is not active. By expending a Willpower point, the werewolf intensifies the penalty to track or detect her to -3. The character may consciously suppress this power if she wishes to lay a normal scent."}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Blending",Description:"Hide in plain sight while motionless",Cost:"-",Book:"WtF 139",fullDescription:[{type:"paragraph",text:"An expert hunter knows the value of not being seen. A werewolf with this Gift can blend with the landscape by simply remaining still — overlooked even in the open."}],fullCost:"None",dicePool:"Wits + Stealth + Cunning versus Wits + Composure (see below)",action:"Instant or contested",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The character actually attracts attention to herself. Observers in the area can’t help but notice her."},{type:"line",label:"Failure",text:"The werewolf isn’t particularly hidden beyond what cover and physical obstructions suggest. The character doesn’t know how well hidden she is until she is found out or overlooked."},{type:"line",label:"Success",text:"The character may “hide in plain sight,” blending into her surroundings by remaining motionless, even if she isn’t directly behind any cover. Casual observers roll Wits to contest the character’s roll as a reflexive action; active searchers contest with Wits + Composure as an instant action. If the werewolf wins the roll, she cannot be distinguished as anything other than a landscape feature. (If a supernatural power of observation is used to find the werewolf, successes rolled to activate that effect must exceed those rolled for this Gift.) Even the slightest movement is recognized by an observer, negating the Gift."},{type:"line",label:"Exceptional Success",text:"Nothing beyond what high successes indicate."}]},{Rank:"•••",Name:"Running Shadow",Description:"Leave no sound (-3 to hearing the character)",Cost:"●",Book:"WtF 140",fullDescription:[{type:"paragraph",text:"Sometimes, one must choose between moving silently and moving quickly. This Gift makes the choice unnecessary. The werewolf can trot over dry leaves as quietly as tiptoeing carefully."},{type:"paragraph",text:"For the duration of the scene, the werewolf can sneak as well at a dead run as he can at a walk. In effect, mundane Stealth tasks become reflexive actions for the character; they can be performed almost recklessly without worry of making noise. Potential observers suffer a -3 penalty to contested rolls to notice the quiet character. But if sound isn’t a significant factor in detecting the werewolf, no modifiers apply for silent movement."}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[]},{Rank:"••••",Name:"Shadow Flesh",Description:"Become a physical shadow (+3 to Stealth and Defense. Suffers a -2 to affect her surroundings)",Cost:"●",Book:"WtF 140",fullDescription:[{type:"paragraph",text:"This Gift actually affects the werewolf’s form, making her a living shadow. While her flesh is transformed to shadowy matter, she can slip through areas with great ease, even sliding under doors or through cracks."}],fullCost:"1 Essence",dicePool:"Wits + Stealth + Cunning",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The character fails to assume shadow form, and cannot try again for the remainder of the scene. In addition, her own shadow is adversely affected. For the remainder of the scene, she casts a shadow of a form different from the one she currently wears. If the character is in Hishu, she might cast a Gauru or Urhan shadow. If she shifted to Gauru, her shadow might reflect an Urshul or Hishu form."},{type:"line",label:"Failure",text:"The character fails to assume shadow form."},{type:"line",label:"Success",text:["This Gift can be used in situations only where shadows can exist. If the character is surrounded by bright lights such that no shadows can be cast, or if she is in total darkness, she cannot transform into shadow form. If a character in shadow form suddenly finds herself in a situation where no shadows can exist (such as being trapped in a basement with no light during a blackout), she is forced back into normal form.",{type:"lineBreak"},"The character’s body becomes a two-dimensional shadow of the same height and width that lies flat against the ground, walls, trees and other surfaces. The shadow form appears to be the character’s own shadow, and thus reflects whatever form she was in when she activated the Gift. The shadow form, is still a physical thing, though. The character can be injured, and the shadow bleeds real blood if wounded.",{type:"lineBreak"},"While in shadow form, the character gains a +3 bonus to Stealth rolls and a +3 bonus to Defense. She may still affect things around her (and retains all of her usual Attributes, as appropriate for the form she is in), but the limitations of her shadow substance make it more difficult. Any roll made to affect her surroundings (such as attack a foe or type on a computer keyboard) incurs a -2 penalty, due to the necessity of remaining flat against an appropriate surface. To attack an enemy, for example, the character has to slide across the ground toward him and even slide partly up his body before her shadowy claws can dig in.",{type:"lineBreak"},"The character can also fit through small openings and slither under doors as long as there is sufficient light and contrast for her to remain in that form. She may move up walls only if she could normally climb them, and cannot move across the surface of water or other liquids. She may also shapeshift normally when composed of shadow. When the Gift’s effects end, she returns to normal in whatever form she had taken.",{type:"lineBreak"},"The character may remain in shadow form for one minute per success rolled. Or she may choose to end the Gift’s effects prematurely.",{type:"lineBreak"},"Any clothing or personal possessions worn change into shadow along with the character, but large objects held in hand such as a shotgun do not change. (Although a fetish weapon does.)"]},{type:"line",label:"Exceptional Success",text:"The character may remain in shadow form for the duration of the scene."}]},{Rank:"•••••",Name:"Vanish",Description:"Become invisible (-5 to detect the character. Rules of Fighting Blind apply)",Cost:"●●",Book:"WtF 140",fullDescription:[{type:"paragraph",text:"The ultimate in visual stealth, the werewolf can instantly fade from sight, even in full view. Cameras, heat sensors — no form of visual detection can perceive the hidden werewolf, although this Gift conveys no protection from other senses."}],fullCost:"2 Essence",dicePool:"Wits + Stealth + Purity",action:"Instant",rollResults:[{type:"heading",text:"Roll Results"},{type:"line",label:"Dramatic Failure",text:"The power fails and cannot be called upon again for 24 hours."},{type:"line",label:"Failure",text:"The Gift fails to take effect."},{type:"line",label:"Success",text:["The user may move and fight as normal. Perception and detection rolls to recognize or spot her suffer a -5 penalty, except those based strictly on smell or sound.",{type:"lineBreak"},"Opponents fight blindly and must rely on cunning and their other senses to hit. (See “Fighting Blind,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 166.) Every time the werewolf is struck, a number of successes must be achieved on a reflexive Wits + Resolve roll in excess of the number of Health points suffered in order to maintain the Gift. Unconsciousness negates the Gift. The Gift lasts for the duration of the scene, although the character may choose to end the effects early."]},{type:"line",label:"Exceptional Success",text:"Wits + Resolve rolls to maintain the effects of the Gift receive a +1 bonus."}]}]},{Name:"Strength",Description:"",Cost:"",Book:"WtF 141",Content:[{type:"paragraph",text:["From folklore’s King Lycaon to Hollywood’s ",{text:"Wolf Man",italic:!0},", one thing all tales of werewolves seem to agree on is that those cursed with lycanthropy are possessed of superhuman might. While not all aspects of werewolf legend are true where the Uratha are concerned, this fact most certainly is. The average Uratha in Gauru form is easily capable of ripping a man to shreds or overturning an automobile, but with the aid of certain Gifts, he is capable of feats that neither Ovid nor Universal Studios ever imagined."]},{type:"paragraph",text:"Strength Gifts are taught by myriad animal spirits, usually those associated with might, and by some earth-spirits or spirits of war."}],Ranks:[{Rank:"•",Name:"Crushing Blow",Description:"Inflict Lethal damage with unarmed strike or melee weapon (instead of bashing damage)",Cost:"○",Book:"WtF 141",fullDescription:[{type:"paragraph",text:"Sometimes a werewolf chooses to kill without using his claws or fangs — perhaps to elude hunters searching for a “rabid man-eating animal,” perhaps simply as a gesture of scorn for his prey. Crushing Blow allows a character to deliver strikes with bone-shattering force. Few things in nature (or out) can stand against such power."}],fullCost:"1 Willpower",dicePool:"No roll is necessary.",action:"Reflexive",rollResults:[{type:"paragraph",text:"This Gift’s effects last for a scene. During that time, any bashing damage the werewolf normally inflicts, whether with his bare hands or with a blunt instrument, is converted to lethal damage."}]},{Rank:"••",Name:"Mighty Bound",Description:"Make incredible jump (+6 to Jumping)",Cost:"-",Book:"WtF 141",fullDescription:[{type:"paragraph",text:"The power of this Gift allows werewolves to leap across distances that would seem impossible for creatures of their size. An Uratha who has learned this Gift may spring effortlessly from rooftop to rooftop in pursuit of his prey."}],fullCost:"None",dicePool:"None",action:"None",rollResults:[{type:"paragraph",text:["A character who has learned this Gift automatically gains six dice to any jumping roll (see “Jumping” on p. 66 of the ",{text:"World of Darkness Rulebook",bold:!0},"). The Gift’s effects are permanent once learned."]}]},{Rank:"•••",Name:"Iron Rending",Description:"Damage objects (cancels 1 point of Durability or Armor per success)",Cost:"●",Book:"WtF 141",fullDescription:[{type:"paragraph",text:"Werewolves tap into a source of strength that is older than all the works of man. Iron-Rending infuses a werewolf’s claws with such destructive power that iron, steel and concrete cannot withstand his might. A character with this Gift can tear apart steel like cardboard and claw stone as easily as clay. This Gift is usable only in Dalu, Gauru or Urshul form."}],fullCost:"1 Essence",dicePool:"Strength + Crafts + Glory",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift fails and the werewolf’s claws actually soften and break off. The result inflicts one point of bashing damage."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf gains no particular advantage."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," When attempting to damage an inanimate object with his bare claws, the character may ignore a number of points of Durability (see the ",{text:"World of Darkness Rulebook",bold:!0},", p. 135) equal to the number of successes achieved on this power’s activation roll. The Gift’s effects last for one turn per success rolled. If the werewolf attacks a target protected by worn armor, this Gift allows a number of Armor points to be ignored equal to successes achieved on the power’s activation roll. This Gift cannot penetrate Durability or Armor gained by mystical means, such as through the Gift: Rage Armor."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Not only does the character ignore a portion of an object’s Durability or a target’s Armor, but he gains a +1 bonus to unarmed close-combat attacks for the duration of the effect."]}]},{Rank:"••••",Name:"Legendary Arm",Description:"Throw to amazing distance (allows throwing an object with a size double her Strength without usual penalty due to object's size)",Cost:"●",Book:"WtF 141",fullDescription:[{type:"paragraph",text:"With this Gift, a werewolf can hurl even tremendous and unwieldy objects great distances. Whether this means throwing a boulder as a projectile at enemies or tossing a packmate over high flames depends on circumstance."}],fullCost:"1 Essence",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[{type:"paragraph",text:["This Gift allows a werewolf to throw an object while disregarding its Size (see “Throwing,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 67). The character’s short range for throwing a non-aerodynamic target increases from (Strength + Dexterity + Athletics - object’s Size) yards to (Strength + Dexterity + Athletics) yards. An aerodynamic object may be thrown double these distances, as usual. In addition, this Gift allows a character to throw an object with a Size up to twice his Strength. So, a character with Strength 4 can throw an object up to Size 8. The character’s Strength is determined by his current form, whether Hishu, Dalu or Gauru. Accuracy is determined as normal (Dexterity + Athletics + equipment). This Gift works for a single action. Hero’s Arm may be used to hurl an object lifted through the application of Savage Might (and also adjusts the potential maximum Size of an object to be thrown). Without the combination of Gifts, the Size of an item thrown with Savage Might alone is subtracted from the base distance that it can cover."]}]},{Rank:"•••••",Name:"Savage Might",Description:"Gain inhuman strength (+3 to Strength per Essence point spent)",Cost:"●+",Book:"WtF 142",fullDescription:[{type:"paragraph",text:"Though already capable of incredible feats of might, there are times when even Uratha need to perform not the incredible, but the impossible. Calling on the indomitable strength of Father Wolf himself in every muscle, bone and sinew, the character channels a fraction of his progenitor’s might into a single extraordinary display of physical power."}],fullCost:"1 Essence per three Strength gained",dicePool:"This power requires no roll.",action:"Reflexive",rollResults:[{type:"paragraph",text:"Each point of Essence invested when this Gift is activated increases the character’s original Strength by three dots, even above the normal limitations of Primal Urge. For example, a character with Strength 4 for whom one Essence is spent has an effective Strength of 7, and a Strength of 10 if two Essence are spent. The player may make a Strength + Stamina roll, using the Strength modified for this Gift, for his character to lift even more weight as normal. This power lasts for only a single turn."}]}]},{Name:"Tainted Moon",Description:"",Cost:"",Book:"Blas 138",Content:[{type:"paragraph",text:"Some of the more dramatically twisted weapons in the arsenal of the Bale Hounds are perversions of Luna’s own blessings. The Tainted Moon Gift list is a fine example of the auspice choirs turned against Mother Luna in a sickly sweet violation of the natural order. The werewolf must have access to one of the Flayed Ones, a Lune that has been bound and tortured, in order to learn these Gifts. For more information, see the “Merit: Flayed Lune,” p. 136, and “the Rite of Dead Light,” p. 145."}],Ranks:[{Rank:"•",Name:"Bloody Moon",Description:"Suffer a -2 penalty on all rolls to avoid entering Death Rage. Gain an additional +1 to Strength, Dexterity and Stamina, above and beyond the normal bonuses associated with Gauru form",Cost:"-",Book:"Blas 138",fullDescription:[{type:"paragraph",text:["Under the full moon, the corrupted Lunes teach the Bale Hounds to tap the full potential of their Rage. For a Hound, entering Death Rage is not a struggle for control or a surrender to murderous urges. Death Rage is the only time that the ",{text:"Asah Gadar",italic:!0}," truly feels like herself."]},{type:"paragraph",text:"This Gift is permanent once learned. It does not need to be activated and requires no expenditure or dice roll. Bale Hounds with this Gift suffer a -2 penalty on all rolls to avoid entering Death Rage, but are all the more dangerous when Death Rage comes. The werewolf with this Gift gains an additional +1 to Strength, Dexterity and Stamina, above and beyond the normal bonuses associated with Gauru form."}],fullCost:"None",dicePool:"No roll is necessary.",action:"N/A",rollResults:[]},{Rank:"••",Name:"Gravid Moon",Description:"Grants an extra die per success on all Social interactions for the remainder of the scene and drains Willpower from any ordinary humans within a radius equal to 10 yards per dot of the Bale Hound’s Primal Urge",Cost:"●",Book:"Blas 138",fullDescription:[{type:"paragraph",text:"The Bale Hound who uses this Gift appears more vital, more alive and more human — at the expense of those around him. Using this Gift steals the vitality from others, changing their spark of life into a mask for the Hound. The people whom this Gift afflicts don’t realize the effect the Bale Hound has on them. Passersby become weak, bitter and depressed, sick people or infants die and even the Hound’s packmates feel out of sorts and restless. Meanwhile, the Bale Hound appears normal, trustworthy and even happy."}],fullCost:"1 Essence",dicePool:"Manipulation + Subterfuge + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character becomes suffused with the positive energy in the area, but instead of reflecting the energy, she absorbs it. The character must immediately check for Death Rage; even if she keeps herself under control, she feels nauseated for the remainder of the scene (-1 on all rolls unless she subsequently enters Death Rage)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character siphons off the positive and life-affirming energies and feelings from those in the immediate area. This grants him an extra die per success on all Social interactions for the remainder of the scene, but also drains Willpower from any ordinary humans within a radius equal to 10 yards per dot of the Bale Hound’s Primal Urge. The Willpower drain affects those with the lowest Willpower ratings first (so if the Bale Hound has two successes for the Gift and there are three people within the radius with Willpower 3, 5 and 8, the first two lose a point of Willpower). If the drain would afflict someone who is currently out of Willpower, the Gift inflicts a point of bashing damage instead. The werewolf gains no Willpower or Health by using this Gift. The drain is merely a by-product of the Gift’s effect. The werewolf cannot gain more dice to Social rolls than he drains Willpower; if he uses this Gift in an area where only one human is within range, he gains only one die to his Social pools."]},{type:"paragraph",text:"Supernatural entities are not affected by the draining effect of this Gift. The Gift may be used only once in any 24-hour period."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No effect beyond a greater Social bonus."]}]},{Rank:"•••",Name:"Broken Moon",Description:"The target automatically enters Death Rage, changes to Gauru form and attacks the first thing at hand",Cost:"●",Book:"Blas 139",fullDescription:[{type:"paragraph",text:["The Elunim police the Uratha for violations of Honor, seeking balance between human and wolf, Rage and temperance. After the flaying rites of the Bale Hounds, the Lunes look at the broken moon as just further evidence that balance is unnatural, and they are quite happy to teach the ",{text:"Asah Gadar",italic:!0}," how to upset it."]},{type:"paragraph",text:"Successful use of this Gift forces other werewolves into Death Rage. The Bale Hound need only glance at the target to activate the Gift."}],fullCost:"1 Essence",dicePool:"Presence + Expression + Honor versus Resolve + Primal Urge",action:"Contested; resistance is reflexive and unconscious.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Bale Hound immediately enters Death Rage."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The target automatically enters Death Rage, changes to Gauru form and attacks the first thing at hand."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No extra effect."]}]},{Rank:"••••",Name:"Sickle Moon",Description:"The spirit suffers one point of damage per success on the Bale Hound’s attack",Cost:"○",Book:"Blas 139",fullDescription:[{type:"paragraph",text:["Under the crescent moon, the ",{text:"Asah Gadar",italic:!0},"’s warped Lune servants show them how to silence any spirits that might ally with their prey. Use of this Gift requires that the werewolf see the spirit, either by peeking into the ",{text:"Hisil",italic:!0}," or using the Two-World Eyes Gift (a manifested spirit is also vulnerable). A spirit’s Defense does not apply to this attack."]}],fullCost:"1 Willpower",dicePool:"Strength + Occult + Wisdom - spirit’s Resistance",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Bale Hound’s attack on the target spirit not only fails, but alerts every spirit in the area as to what just happened. Even in areas populated by spirits that despise the Forsaken, the Hound won’t remain masked for long."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens. The spirit notices the attempted attack with a successful Finesse roll."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The spirit is wracked with searing pain as its Corpus sloughs away like diseased flesh. The spirit suffers one point of damage per success on the Bale Hound’s attack."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Damage is applied to the spirit’s Corpus ",{text:"and",italic:!0}," Essence, making it possible for a Bale Hound to completely destroy a spirit with this Gift."]}]},{Rank:"•••••",Name:"Dark Moon",Description:"The target loses all sensory input, becoming blind, deaf and unable to smell or feel the world around him. Werewolves must immediately check for Death Rage",Cost:"●○",Book:"Blas 139",fullDescription:[{type:"paragraph",text:["The Irralunim help the Forsaken to surmount minor obstacles, but many Irraka suspect that these Lunes are much more powerful than they let on. The no-moons would be distraught, then, to find out the Gift that their patron choir grants to the Bale Hounds. With a touch and a single word in a language no Forsaken understands, the Bale Hound can strike an Uratha blind, deaf and insensate. Locked in a world of silence and darkness, completely cut off from any sensory information whatsoever, the victim must struggle to maintain his sanity and his control. Death Rage offers release, because in ",{text:"Kuruth",italic:!0}," the victim’s conscious mind takes leave — but the victim has no way to know who he might kill during this frenzy."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Wits + Subterfuge + Cunning versus Composure + Primal Urge",action:"Contested; resistance is reflexive and unconscious.",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Bale Hound falls unconscious as the Gift reverses itself upon her."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The target loses all sensory input, becoming blind, deaf and unable to smell or feel the world around him. This is disturbing enough for human beings, who typically flail and scream incomprehensibly when afflicted by the Dark Moon. Werewolves, though, must immediately check for Death Rage and continue doing so every minute. These rolls incur a cumulative -1 penalty, meaning that in five minutes the Uratha has a -5 penalty to avoid Death Rage. The sensory deprivation lasts for one minute per success on the Bale Hound’s roll."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," When the Gift’s effects wear off, the target must immediately check for a derangement (Resolve + Composure; failure means the target develops a new derangement, probably involving fear of the dark)."]}]}]},{Name:"Technology",Description:"",Cost:"",Book:"WtF 142",Content:[{type:"paragraph",text:"Technology, in the broadest sense, is the way people use discoveries and inventions. It is interdependent and often highly specialized. Technology is the forte of the Iron Masters, who possess affinity with these Gifts. Still, many other werewolves find knowledge of how to thwart high-tech computers and other devices extremely useful, especially in dealing with urban and human affairs. These Gifts also represent how to use existing technology to best advantage. Urban spirits and spirits of various metals and forms of energy such as electricity are the most frequent teachers of these Gifts."}],Ranks:[{Rank:"•",Name:"Left-Handed Spanner",Description:"Disable a device for 1 turn per success",Cost:"○",Book:"WtF 142",fullDescription:[{type:"paragraph",text:"This Gift temporarily disables a specific technological object, such as a cell phone, computer or automobile engine, within arm’s reach. The malfunction has no apparent external cause. In truth, the werewolf using the Gift has interrupted the flow of spirit energy into the object, thus causing its breakdown."}],fullCost:"1 Willpower",dicePool:"Wits + Crafts + Purity",action:"Instant",rollResults:[{type:"paragraph",text:["The player must specifically state which object her character wishes to disable, and the werewolf must touch it. The object ceases to work for a number of turns equal to the successes rolled. If the object is carried by another who seeks to avoid the werewolf’s touch, a roll is required to make contact (see “Touching an Opponent,” ",{text:"World of Darkness Rulebook",bold:!0},", p. 157). Valid pieces of technology that can be overcome include anything manufactured by industrial means with at least three separate parts; a gun is valid, but a hinge or syringe is not. The object cannot be larger than the werewolf himself in Hishu form. A werewolf can affect the engine of a car, but not the entire automobile."]}]},{Rank:"••",Name:"Nightfall",Description:"Extinguish all artificial light in the vicinity",Cost:"○",Book:"WtF 143",fullDescription:[{type:"paragraph",text:"Humans and werewolves alike rely on the power of light for innumerable tasks. This Gift allows the user to extinguish all electric light (i.e., electric lamps, battery-powered flashlights, streetlights) in a specific area."}],fullCost:"1 Willpower",dicePool:"Wits + Larceny + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The failed Gift alerts local technological spirits. Any spirits in the area associated with technology become increasingly hostile toward the character for one lunar month."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Nothing happens."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The character must target a specific area within unaided visual range; the Gift does not work on areas viewed remotely via binoculars, security systems or the like. Success extinguishes the light within a home of about 2,000 square feet, with each additional success doubling the size of the area. Three successes, for example, kill the lights on an entire floor of a large office building. This Gift does not simply turn the lights off — it prevents them from functioning at all. The effects last for one scene, or until the character chooses to end the Gift’s effects."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The character gains selective control over the technological light sources in the area, and may select one source to still function if she chooses."]}]},{Rank:"•••",Name:"Iron Treachery",Description:"Make a device turn against its user (reduces dice polls for using the object to a chance die for 1 turn per success)",Cost:"●",Book:"WtF 143",fullDescription:[{type:"paragraph",text:"With a gesture and snarl, the werewolf temporarily awakens the spirit of a machine, driving it into a brief fit of angry independence. A pistol jerks in the hand of its owner, refusing to be aimed; a steering wheel twists madly."}],fullCost:"1 Essence",dicePool:"Wits + Crafts + Glory - Resolve",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift temporarily awakens the spirit, but it is compliant rather than rebellious. The spirit grants an additional die to any attempts to use the object for the rest of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The machine’s spirit does not awaken."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Gift user must point at the mechanical device in question, which must be within 10 yards per point of Primal Urge, and must comprise at least two separate moving parts. If someone is currently attempting to use the device, he resists with Resolve. If the Gift user succeeds, the device’s spirit becomes essentially uncontrollable for one turn per success. Any attempts to use the machine while the Gift effects last are reduced to a chance die."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The spirit is exceptionally angry, and rebels for the duration of the scene."]}]},{Rank:"••••",Name:"Machinegeist",Description:"Possess a machine (gains perception and information, but cannot control it)",Cost:"●",Book:"WtF 143",fullDescription:[{type:"paragraph",text:"A werewolf calling on this Gift merges his being with the spirit of a particular machine or electronic device, such as a computer or a school bus. He sees what the machine sees and feels what the machine feels, taking advantage of any hidden knowledge or extra sensory awareness therein. To those not skilled or familiar with Technology Gifts, this Gift is a little frightening, as the werewolf using Maschingeist becomes “one” with his subject, temporarily leaving his body and singular consciousness behind."}],fullCost:"1 Essence",dicePool:"Wits + Computer + Wisdom",action:"Instant or extended (10 to 20 successes required; each roll represents a minute’s time)",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The object’s spirit is offended by the character’s intended intrusion and cannot be communed with at all for 24 hours."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No contact is made."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The player succeeds at a Wits + Computer + Wisdom roll for his character to create a bond with a mechanical or electrical device within reach. The werewolf is in a trance as he communes with the subject’s spirit. He cannot perceive the world around him, except as the machine’s spirit does. Communing with a car’s spirit, for example, he “feels” that which touches the car and “sees” through the car’s headlights, windshield or mirrors, but he cannot see what a passenger leaning out a window might. No Gifts can be used while out of body."]},{type:"paragraph",text:"The machine need not be active (though it must be physically intact, or at least enough so to be in working order) for this Gift to work. The werewolf can commune with a television that isn’t currently on or a car that isn’t currently running. Only one werewolf can communicate with an object via this Gift at a time."},{type:"paragraph",text:"If the spirit of the machine is already awake, communion takes a single turn — an instant action. If it slumbers, communion takes time, depending on the intricacy of the machine in question; communion does not actually wake the spirit. An extended action is required to connect with it. A simple machine such as a lawn mower might require 10 successes, while a large or complicated one such as a computer might require 20. The werewolf is in a trance throughout the extended communion process."},{type:"paragraph",text:"Forging a bond, the werewolf gains access to any knowledge or information the machine’s spirit possesses, as decided by the Storyteller. Merging with a television set in a seedy motel room may reveal who has been in the room recently and what they did there, though a television set’s “memory” won’t reach as far back as a computer’s. Joining with a mainframe computer may give the character reams of information, more than he can even absorb. The character retains information for one minute after leaving the gestalt"},{type:"paragraph",text:"A werewolf can remain bound to a machine’s spirit for a number of turns equal to his Harmony, or he may break contact as an instant action earlier if all information sought is acquired."},{type:"paragraph",text:"If the object to which a character’s psyche is connected is destroyed, the character’s identity is thrown back to his body immediately. Any Structure damage inflicted on the object is also inflicted as points of Health to the character’s body. If the werewolf’s body is attacked, he is aware of it immediately. If his body is knocked unconscious, his spirit returns. If his body is killed, his psyche is trapped in the object for the duration of the power and is then lost forever."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The character can remain in contact with the object’s spirit for a number of hours equal to his Harmony dots."]}]},{Rank:"•••••",Name:"Create Technology",Description:"Craft a device",Cost:"●○",Book:"WtF 144",fullDescription:[{type:"paragraph",text:"To a master of technological animism, complicated devices are simply another element to be conjured up at will. This Gift allows a werewolf to create sophisticated technology from the basest materials."}],fullCost:"1 Essence + 1 Willpower",dicePool:"Intelligence + Crafts + Cunning",action:"Extended (5 to 50 successes required; one turn passes per roll)",rollResults:[{type:"paragraph",text:"The character must have some foundation materials, such as metal or plastic, roughly equivalent in mass to the item she wishes to create. She must also either know how to build the item in question or have access to instructions on how to construct such a thing. A character cannot create a complicated bomb without either extensive knowledge of explosives or a manual or other set of instructions on how to create the object in question. Within these limitations, this Gift can quickly and efficiently replicate almost any technology imaginable. With a few pounds of scrap metal and sand, for example, she can create a rudimentary computer. Or a handful of glass could be transformed into a magnifying glass. The more complex the item is, the more successes are required. A dozen bullets may be formed with as few as five successes, a pistol 15, while a car or computer would take a total of 50."}]}]},{Name:"Territory",Description:"",Cost:"",Book:"Terr 48",Content:[{type:"paragraph",text:"Uratha instinctively know that they must claim territory as their own. These Gifts aid werewolves in protecting their own territory and assessing the strength of rivals who control territory nearby. These Gifts are open to Pure Ones as well as the Forsaken. Territory is critical to a werewolf: this is an open list, and any werewolf can possess these Gifts as if they had tribal or auspice affinity for them."},{type:"paragraph",text:"Each of these Gifts relates to a pack’s territory in some fashion. Generally speaking, a section of territory is considered “claimed” by a pack only if the packmembers have taken some pains to make it so; packmembers who say they control a street they haven’t ever set foot on doesn’t “claim” that street for purposes of this Gift. Only land that’s been patrolled, fought over, laid stake to via the Howl of Ownership (see p. 50) or otherwise seen a genuine werewolf presence counts."}],Ranks:[{Rank:"•",Name:"Lay of the Land",Description:"Learn the population of a Territory, as well as seeing the totem of the pack that claims it",Cost:"-",Book:"Terr 48",fullDescription:[{type:"paragraph",text:"This Gift gives the werewolf who uses it an instant sense of how many people and spirits are in the immediate area, as well as which werewolf pack (if any) claims it. For purposes of this Gift, “the immediate area” means “the territory feature,” as described in this book."}],fullCost:"None",dicePool:"Wits + Politics + Purity",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf receives faulty or misleading information about the local area. The exact nature of the character’s mistake is up to the Storyteller — the werewolf should learn half-truths so that it is not obvious what she is wrong about."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf gains no information. She cannot use this Gift again in this immediate area, until the next moonrise or moonset."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf gets a rough impression of what the total population of the area is, though the Gift does not differentiate among humans, werewolves, spirits or other supernatural beings. The character also sees the symbol and totem spirit of the pack that claims the area — if she has encountered the pack in the past she recognizes them immediately."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The werewolf gets a more precise impression of the territory feature’s overall population. She also sees the symbol and totem spirit of the pack (if any) that claims the area, and if she does not know them, she hears the pack’s name as a howl."]}]},{Rank:"••",Name:"Minor Sending",Description:"Send a whispered message to a packmate while on your territory",Cost:"●",Book:"Terr 48",fullDescription:[{type:"paragraph",text:"Minor Essence flows crisscross every werewolf pack’s territory. With this Gift, the werewolf may infuse one or more Essence onto one of these minor Essence flows and whisper a message for a packmate. The packmate can be any distance away, so long as both are within the pack’s territory, and will still hear the Gift user’s message as if whispered directly into her ear. This message cannot be tapped or intercepted."}],fullCost:"1 Essence",dicePool:"Presence + Expression + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The message fails to arrive at all."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The message arrives, but is garbled beyond understanding."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Gift user is able to transmit a whispered message up to 30 seconds in length. The message travels at about 200 miles per hour, or about half a mile per turn, so if the packmate is two miles away, the message needs four turns to arrive."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," As with an ordinary success, but the Gift’s recipient actually receives the spent point of Essence as it chases the message."]}]},{Rank:"•••",Name:"Sense of the Territory",Description:"Learn the location of all Loci, Werewolves and spirits Rank 3 or higher",Cost:"●",Book:"Terr 48",fullDescription:[{type:"paragraph",text:"A werewolf can use this Gift to read the local Essence currents, instantly gaining an idea of where all noteworthy disturbances are. He can learn the location of any loci in the territory, as well as the presence of any spirits of Rank 3 or higher or werewolves. This Gift only works within the werewolf’s own territory."}],fullCost:"1 Essence",dicePool:"Wits + Politics + Wisdom",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Every werewolf and spirit in the pack’s territory instantly learns the Gift user’s location. The Gift user receives no information in return."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect; the Essence spent is lost."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf learns the location of all loci higher than • in rating and all werewolves and all spirits of Rank 3 or higher within his pack’s territory. The Gift reveals only the presence of potential intruders on the same side of the Gauntlet as the user; if the Gift user is in the Shadow, the Gift will reveal only the location of spirits and werewolves who are likewise in the spirit world."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Gift reveals the presence of significant intruders on both sides of the Gauntlet."]}]},{Rank:"••••",Name:"Animate the Land",Description:"A chosen skill either receives bonuses for packmates or penalties for enemies",Cost:"●●",Book:"Terr 49",fullDescription:[{type:"paragraph",text:"At the werewolf’s command, the land of his pack’s territory itself rises up in defense of the pack and its power."}],fullCost:"2 Essence",dicePool:"Manipulation + Intimidation + Glory",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The land rises up in rage against the Gift user; the werewolf suffers a -2 to all Physical dice pools for the next three turns."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect; the Essence spent is lost."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Within the immediate area (the present territory feature), the player may apply the successes rolled as either bonus dice to the character and his packmates or penalties to his opponents’ dice pools, for the next four turns. The player defines the way that the local terrain rises up to assist the werewolf; shopping carts may hurl themselves into the path of onrushing foes, or a peaceful stream may become a roiling river. At that time, the player must also define which Skill will be affected by the dice — for example, the pack may receive bonus dice to Athletics as the ground tilts and eases to help them, or the pack’s enemies suffer a penalty to Firearms as barriers spring up in their way. The Storyteller has final judgment over whether a particular Skill use is appropriate; a pack cannot expect to gain bonuses to Politics rolls in the middle of a forest, for instance. Once the Gift user has defined the specific bonus or penalty that the terrain will impose, the modifier continues to work in that fashion throughout the duration of this Gift."]},{type:"paragraph",text:"This Gift can naturally be used only within the werewolf’s own territory. The local area cannot benefit from more than one use of this Gift at the same time. This Gift may be used only once per scene."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The duration of the Gift is extended to six turns."]}]},{Rank:"•••••",Name:"Disrupt Essence",Description:"All powers cost twice as much essence for non-pack members",Cost:"●●●",Book:"Terr 50",fullDescription:[{type:"paragraph",text:"Within your pack’s territory, you can cause spirits and werewolves to waste Essence in powering their supernatural abilities. This may make them resort to physical tactics, or stay out of your territory entirely."}],fullCost:"3 Essence",dicePool:"Presence + Occult + Honor",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift effects rebound on the user. The user cannot use any more Territory Gifts until a day and a night has passed."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No effect; the Essence spent is lost."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," For a number of turns equal to the number of successes rolled, any creature that is not a member of the Gift user’s pack must spend twice as much Essence as would normally be indicated to power a given ability for as long as the creature remains within the Gift user’s territory. For purposes of this Gift, a pack totem is considered to be part of a pack (and therefore does not suffer that penalty)."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Gift user may also designate up to five entities that are not members of his pack who do ",{text:"not",italic:!0}," suffer this penalty."]}]}]},{Name:"War",Description:"",Cost:"",Book:"WAtP 46",Content:[{type:"paragraph",text:"These Gifts focus on the most important commodity in war: information. Skill in battle and powerful weapons are valuable, but knowledge is king. Because so many spirits operate on a personal, local level, it can be exceedingly difficult to find those that teach War Gifts. Moreover, because large-scale, organized war is so faint in werewolves’ memories, few know these Gifts exist or think to seek them out."},{type:"paragraph",text:"Most commonly, a werewolf can learn these Gifts from the military-spirits that hover about military bases. Regimented creatures, usually insects such as army ants or wasp colonies, also have a nature that would allow their spirits to teach a War Gift or two. Some famous battle-sites, such as Gettysburg, Waterloo or Normandy Beach have powerful spirits that linger still and might share their secrets. Finally, hot combat zones spawn hundreds of the active (but short-lived) war- and battle-spirits that know these Gifts, if a werewolf can only get close before they dissipate."}],Ranks:[{Rank:"•",Name:"Find Conflict",Description:"Find the biggest and most fierce conflict in an area",Cost:"-",Book:"WAtP 46",fullDescription:[{type:"paragraph",text:"In the middle of a massive battle, a general can easily lose track of his troops. With this Gift, a war leader can instantly locate the hottest fighting and focus his efforts there, or he can detect incoming enemy action before the scouts reach him."}],fullCost:"None",dicePool:"Composure + Investigation + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The power fails, and the werewolf cannot activate any War Gifts for one hour."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf does not learn the location of any battles."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf becomes aware of the fiercest and most escalated conflict within one mile, plus one mile per success. In calm areas, this Gift can pick up something as innocent as a heated argument. When there are multiple conflicts underway within the Gift’s range, the werewolf always pinpoints the more dangerous. A conflict with weapons bared always trumps one that is not, and open violence always has precedence over a situation without exchanged blows. If two battles are at about the same level of escalation, the one with more participants wins."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," In addition to learning the location of the most violent conflict, the werewolf gains a rough estimate of how many are fighting on each side."]}]},{Rank:"••",Name:"Notice Defeat",Description:"Reflexively notice that a group of allies is in trouble",Cost:"○",Book:"WAtP 47",fullDescription:[{type:"paragraph",text:"When several groups of Forsaken soldiers are fighting the enemy, knowing when one requires reinforcements or other assistance is important. Using this Gift allows a war leader to know when any werewolf or pack under her command is losing a battle."}],fullCost:"1 Willpower",dicePool:"Wits + Empathy + Wisdom",action:"Reflexive",rollResults:[{type:"paragraph",text:"Once she has learned this Gift, a character never activates it consciously. Instead, any time a soldier or company (usually a werewolf or pack) under the werewolf’s effective command is in battle against the joint enemy and in need of support, something tickles at the back of her mind. By reflexively spending a Willpower point, the werewolf turns that irritation into solid information on which she can act."},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf misinterprets the information, making it dangerously nonsensical and contradictory. She becomes temporarily dizzy, losing one die from all physical actions. She also becomes unable to use any War Gifts for one hour."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," Despite the werewolf’s attention, the vague unease fades without revealing anything."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf learns which of her units is in trouble, based on its most common appellation (the name of the werewolf or pack, the title of her special task force, etc.). More successes reveal more information: three successes means the leader learns approximately where the subjects are (within about one square mile). With five successes, the werewolf also knows what sort of the support the troubled unit most desires (which is not always the best support to give)."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Increased knowledge (as described above) becomes known to the werewolf."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["-1","More than 1 mile away"],["-2","More than 10 miles away"],["-3","More than 100 miles away"]]}]},{Rank:"•••",Name:"Whispers on the Wind",Description:"Send a message to any number of people in an area",Cost:"●",Book:"WAtP 47",fullDescription:[{type:"paragraph",text:"Possessing good intelligence is not the same as being able to use it. Before knowledge can become action, a general must command his troops. Using this Gift allows a werewolf to direct the action from afar, remaining central to an engagement while ensuring that his subordinates hear his instructions."}],fullCost:"1 Essence",dicePool:"No roll is necessary.",action:"Instant",rollResults:[{type:"paragraph",text:"Activating this Gift lets the werewolf speak directly into the wind, which carries his words as much as three miles to people he commands. He can convey as much as three short or two longer sentences before the effect ends, and the werewolf can target an individual, select group or indiscriminately let the words reach all who serve under him. Targets of the Gift hear the statements about one minute later. They all recognize the source of the commands as their superior, but they are in no way compelled to obey any instructions given."}]},{Rank:"••••",Name:"Echoes of Opposing Brilliance",Description:"Learn the tactics of the opposing commander",Cost:"●",Book:"WAtP 47",fullDescription:[{type:"paragraph",text:"Every military commander in history has wanted to know what her enemy counterparts are doing. This Gift steals the words of opposing commanders and carries them to the werewolf. Being able to hear their orders gives the war leader a definite edge."}],fullCost:"1 Essence",dicePool:"Wits + Investigation + Wisdom - highest Resolve",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," Unable to discern useful from dross, the wind-spirits whisper hundreds of babbled words in the werewolf’s ear. She suffers a -2 dice penalty to all Perception rolls relating to hearing and a -1 die penalty to anything that requires concentration for the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf fails to eavesdrop on her enemies."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf hears words spoken by her enemy commanders, carried to her by fleet spirits. She does not hear everything they say, but she usually gets enough to construct an overall picture of the tactics they employ. In most cases, the Storyteller should give the werewolf an idea of what her opponents plan and allow her to counter their strategies. When a battle is being played out more abstractly with dice rolls, the werewolf gains a +2 bonus on all tactical rolls."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Wind-spirits are particularly thorough. Nearly every word the opposing commanders utter, the werewolf hears. With this much information, she should be able to construct a nearly unbeatable counter-tactic. In dice terms, she gets a +3 dice bonus to relevant rolls."]}]},{Rank:"•••••",Name:"Shared Battle Mind",Description:"Give soldiers a subtle instinctive push to act in according to the tactics the commander chooses",Cost:"●●",Book:"WAtP 48",fullDescription:[{type:"paragraph",text:"Many wars suffer because the general is too far removed from his rank-and-file soldiers. They cannot see the plans he has made because they’re too close to the action. This Gift gives a small portion of the war leader’s awareness to all his werewolf allies, keeping a battle moving in the right direction."}],fullCost:"2 Essence",dicePool:"Presence + Socialize + Purity",action:"Extended (five successes + one success per werewolf affected; each roll represents one minute)",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The werewolf’s attempt to infuse his allies with a portion of his strategy ends catastrophically. Instead of receiving a subconscious understanding of the battle, they develop false ideas about what they should do. For 10 minutes until the confusion clears, all werewolves targeted with the Gift suffer a -1 die penalty to all actions as they charge enemies who are somewhere else and expect reinforcements that are miles away."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No successes accumulate."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Successes accumulate. When the werewolf achieves a number of successes equal to the number of targeted werewolves plus five, he manages to imbue those allies with a small piece of his knowledge. It manifests as a subtle instinct to head in a certain direction, stand fast, recover the wounded or other broad and immediate tactics. These instincts depend on the Gift-user’s tactics, so a war leader with out-of-date information can still lead his soldiers astray."]},{type:"paragraph",text:["Shared Battle Mind conveys no ",{text:"clear",italic:!0}," information. This Gift does not replace Whispers on the Wind or having runners in battle to carry orders and information back and forth. There is only an itch in the back of the head, a gut feeling that this is the right thing to do at the moment, and nothing compels a werewolf to obey. It is often hard for werewolves to obey, since it is a quieter instinct than ",{text:"chase",italic:!0}," and ",{text:"kill!",italic:!0}," and less stirring; war leaders must keep their urges under control to wisely manage a battle."]},{type:"paragraph",text:"Battles commanded with the help of this Gift typically run much more smoothly, as the war leader’s followers know better what he needs them to do and do it. The Storyteller should help make this happen when a players’ character is running the war. Mechanically, werewolves affected by the Gift may make Composure + Empathy to sense what the Gift-user desires. Penalties on the roll come from distraction or competing instincts. Success indicates that the werewolf gets a general idea (“stay where you are,” “rout them!” “help another pack”); exceptional success provides somewhat more detailed information (“stay in place to protect supplies,” “finish off that Hallowed Jungle pack,” “be reinforcements to your west”)."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," More successes accumulate. If the werewolf ends the Gift exceeding the necessary number of successes by five or more, the subconscious directions become stronger. Werewolves roll Composure + Empathy + Primal Urge to feel out their Gift-given instincts."]}]}]},{Name:"Warding",Description:"",Cost:"",Book:"WtF 144",Content:[{type:"paragraph",text:"Protecting the sanctity of the Uratha’s many holy sites is the reason various wards were originally developed. Over time, however, the People have found myriad ways to put wards to use outside loci, though they are still primarily used to guard those locations. These Gifts are typically taught by wolf- or ancestor-spirits."}],Ranks:[{Rank:"•",Name:"Ward Versus Predator",Description:"Protect a territory against predatory animals (requires Resolve + Composure to enter the territory)",Cost:"-",Book:"WtF 144",fullDescription:[{type:"paragraph",text:"The simplest of protections, this Gift lets other predators know that a tract of land has been claimed by a werewolf. All such predatory animals instinctually realize that to intrude into the territory is an invitation to be attacked or killed, and most are cowed by such knowledge, avoiding the warded ground religiously thereafter to avoid a potentially fatal confrontation."}],fullCost:"None",dicePool:"Presence + Intimidation + Honor",action:"Extended (5 successes per square mile required; one hour per roll)",rollResults:[{type:"paragraph",text:"The werewolf marks the extent of her territory (a maximum area equal to one square mile per point of the character’s Primal Urge) by urinating on objects along its boundaries. If the ward is set up around an area that already contains more than ten types of predatory animals per square mile (such as a zoo), the Gift cannot take effect. Animals that are already in the ward’s area of effect when the Gift is invoked aren’t affected by the ward."},{type:"paragraph",text:"A number of successes must be achieved for an intruder on a Resolve + Composure roll in excess of those achieved on the werewolf’s Presence + Intimidation + Honor roll for a predatory animal to enter the warded area voluntarily. An equal number or less and the animal turns away at the boundary. The ward lasts for one lunar cycle. No penalties are imposed on an animal that is involuntarily dragged into the area. A ward doesn’t prevent other werewolves, other supernatural beings or humans from entering one’s territory. It works only against mundane predatory reptiles, birds and mammals. Other werewolves and supernatural beings with the senses to recognize the ward notice it, however. Crossing into the territory is, therefore, a conscious choice and an invitation for harm."}]},{Rank:"••",Name:"Ward Versus Humans",Description:"Protect a territory against humans (requires Resolve + Composure to enter the territory)",Cost:"○",Book:"WtF 144",fullDescription:[{type:"paragraph",text:"Many times, the biggest danger to a locus comes not from werewolves’ supernatural rivals, but from humanity’s teeming ignorant masses, ever eager to transform the world around them and never suspecting the troubles this calls down from the Shadow. Entering, much less clearing, woods warded by this Gift calls forth feelings of unparalleled dread from the depths of the hindbrain. “Something lives in there that’s mightier than you,” the mind screams. “Something hungry that will eat you up.” Someone intent on entering the warded area might convince himself to do so, but a casual hiker or other such indifferent walks away."}],fullCost:"1 Willpower",dicePool:"Presence + Intimidation + Wisdom",action:"Extended (5 successes per square mile required; one hour per roll)",rollResults:[{type:"paragraph",text:"The werewolf marks the extent of her territory (a maximum area equal to one square mile per point of the character’s Primal Urge) by urinating on objects along its boundaries. For a human being to enter the warded area requires a successful Resolve + Composure roll. A human who fails the Resolve + Composure roll but is somehow forced to enter the territory seeks to flee it at top speed as soon as possible, or if impossible to do so collapses into a quivering heap unable to do more than rock quietly back and forth."},{type:"paragraph",text:"This Gift does not work in areas normally teeming with humans, such as a few city blocks. The very mass of people in the area is more than the power can contend with. Uratha who use the Gift in such a place need to localize the area affected to a building, back alley or parking lot that isn’t intensely populated or active. The warded area can keep people at bay thereafter. This Gift does not keep other supernatural beings, such as mages or ghouls, at bay. It does work on wolf-blooded, however. The ward persists for one lunar cycle."}]},{Rank:"•••",Name:"Technology Ward",Description:"Disable all devices in the vicinity (mechanical devices reduce all rolls to a chance roll)",Cost:"●",Book:"WtF 145",fullDescription:[{type:"paragraph",text:"Werewolves are creatures born of a primal time. They rely on their teeth and claws first, the powers won from the spirit world second, and human technology as a distant third. Naturally, they favor stacking the battlefield in their favor by doing what they can to ensure that their prey must rely on similar advantages instead of advanced tools. This Gift is an effective means of removing any technological advantage, thus giving werewolves the edge."}],fullCost:"1 Essence",dicePool:"Presence + Crafts + Cunning",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The character attracts hostile attention from local spirits of technological nature. These spirits do not act instantly, but wait for the right moment to make the character’s life hell."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The character fails to invoke the ward."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The werewolf howls up a spiritual barrier that wreaks havoc on any electronic item and any mechanical device more complex than a simple lever or bow within the warded area (a radius equal to five feet per success rolled). Electronic devices are rendered completely useless within the zone, and complex mechanical devices such as automobiles and firearms are disabled. Cars governed by onboard computers stand no chance of working. All purely mechanical devices, including most firearms and older model cars, stand a good chance of suffering a mechanical failure; all efforts to use such devices are reduced to a chance roll. The effects of this Gift last for one scene."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The radius of effect extends to five yards per success rolled."]}]},{Rank:"••••",Name:"Shadow Ward",Description:"Strengthen the Gauntlet (-1 to crossing or seeing through the Gauntlet)",Cost:"●",Book:"WtF 145",fullDescription:[{type:"paragraph",text:"This Gift is invoked on rare occasions, as it denies werewolves access to one of their major strengths — the ability to access the spirit world. Shadow Ward actually strengthens the Gauntlet in the warded area. The werewolf using the ward outlines its boundaries with intricate designs and patterns. She then calls on the power of the physical side of her being while denying her spiritual side. The ripples of that renunciation intensify the barrier to the spirit world even in areas one would normally consider spiritually sacrosanct. (In fact, repeated use of this Gift may permanently damage an area’s spiritual connection and create a Barren, at the Storyteller’s discretion.)"},{type:"paragraph",text:"The Gift is considered important to offset damage to the Gauntlet often done in urban settings by Beshlilu and other creatures that seek to collapse the wall between the material and spirit worlds. And yet, some Uratha are wary of werewolves who know this Gift for fear that it will be turned on the holy sites of the People."}],fullCost:"1 Essence",dicePool:"Presence + Occult + Glory",action:"Extended (30 successes; one hour per roll)",rollResults:[{type:"paragraph",text:"Success increases the penalty for crossing or seeing through the Gauntlet in the warded area by one. The maximum area that may be warded by this Gift is equal to the character’s Primal Urge in tens of square yards. This Gift’s effects linger for one lunar cycle, although the character may reverse the ritual by spending one Essence and enacting the ward in reverse; this works only to undo the effects of a previous use of this Gift, and cannot reduce an unmodified Gauntlet. This Gift even works at a locus, although it’s sure to draw the ire of any spirits in the vicinity."},{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The opposite effect of reinforcing or thinning the Gauntlet is had. Its rating changes by one in the wrong direction. All accumulated successes are lost."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," No successes are gained at this time."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," Progress is made toward weakening or strengthening the Gauntlet."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," Considerable progress is made toward weakening or strengthening the Gauntlet."]}]},{Rank:"•••••",Name:"Ward of Spirit Slumber",Description:"Put all spirits in the vicinity to sleep",Cost:"●",Book:"WtF 145",fullDescription:[{type:"paragraph",text:"Singing a lullaby attributed as Luna’s song to her offspring by Father Wolf, the werewolf’s voice pierces the Gauntlet, where the soothing melody continues to echo. Spirits crossing into the warded area hear the song’s haunting strains and are lulled into a deep enchanted slumber. Werewolves frequently use this Gift to protect an area from hostile spirits without actively injuring or offending the spirits."}],fullCost:"1 Essence",dicePool:"Manipulation + Occult + Purity versus Resistance",action:"Instant, can be contested",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The song incites the local spirits, who receive a +1 bonus to resist any Gifts the character uses against them for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The song has no effect on the local spirits."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The ward lasts for one turn per success rolled and affects an area with a radius of five yards per success, centered on the character. The ward works on both sides of the Gauntlet, affecting spirits both in the physical world and in the Shadow reflection of the target area. Spirits within the ward’s area (those that were already present or those that enter the area while the ward is still in effect) immediately fall into a deep slumber which can last for days unless they succeed on a Resistance roll to remain awake. Even awake, the drowsiness induced by the song imposes a -1 penalty on every action that spirits attempt. Most spirits who don’t succumb immediately to the ward’s effect recognize their peril and leave the warded area as quickly as possible."]},{type:"paragraph",text:"Spirits falling into slumber from this ward do not wake unless physically assaulted. Once the ward effects end, any spirit put to sleep via this ward may wake up after a reflexive Resistance roll. Further rolls may be made once per day until the spirit does wake."},{type:"paragraph",text:"Werewolves, Ridden, Hosts or other creatures of part spirit and part flesh who are in the Shadow Realm are affected by the ward as if they were spirits, except Resolve + Primal Urge is rolled for them to resist, and at a +3 bonus. Other creatures in the Shadow Realm that aren’t part spirit (such as mages) are not subject to the ward’s effects; nor are spirits that are bound into fetishes or otherwise not independently active (with the exception of those possessing living hosts)."},{type:"paragraph",text:"A werewolf may attempt to use this Gift only once per day."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The ward lasts an additional two turns."]}]}]},{Name:"Warrior's Moon",Description:"",Cost:"",Book:"Lore 90",Content:[{type:"paragraph",text:"The blessings of the Warrior’s Moon, of course, have to do with battle. They focus the Rahu on his ability to overcome foes, as well as his ability to determine which battles shouldn’t be fought."}],Ranks:[{Rank:"•",Name:"Warrior's Insight",Description:"Unlimited use of the Warrior's Eye",Cost:"●",Book:"Lore 90",fullDescription:[{type:"paragraph",text:"All Rahu are gifted with the ability to look an opponent square in the eye and estimate his strength. This Gift strengthens that ability, allowing the Rahu to see the measure of a person even if he’s already drawn on the power recently."}],fullCost:"1 Essence",dicePool:"This Gift requires no roll.",action:"Reflexive",rollResults:[{type:"paragraph",text:"By spending a point of Essence, the character can use the warrior’s eye auspice ability even if he has already used that ability during the session. There is no limit to the number of times that this Gift can be used per session, other than the Essence cost."}]},{Rank:"••",Name:"Battle Mind",Description:"Resist mental influence",Cost:"●",Book:"Lore 90",fullDescription:[{type:"paragraph",text:"On the battlefield, it is a grievous breach of discipline to be swayed into abandoning the fight. This Gift allows a Rahu to focus tightly on the task at hand, entering a mental state of disciplined near-Rage. While the Rahu is in the grips of Battle Mind, he becomes particularly difficult to influence with powers that would affect his mental control over his actions, such as Gifts that cause fear or vampiric Disciplines that attempt to control a victim mentally. But this is not a kind and forgiving state of mind, and a werewolf who enters this state finds it difficult to turn his attention to anything other than bloody conflict."}],fullCost:"1 Essence",dicePool:"Resolve + Empathy + Purity",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Rahu’s urge to destroy is heightened beyond his ability to control it. The character must immediately make a Death Rage check (",{text:"Werewolf: The Forsaken",bold:!0},", p. 173)."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The werewolf’s mindset is unchanged. The player may attempt to use this Gift again next turn."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The Rahu tempers his bloodthirst with discipline, and indulges both in full. For the duration of the scene, the Rahu gains +2 to all dice pools made to resist any powers that would directly affect his control over his actions, such as Dominance Gifts. He also suffers a -1 penalty to any dice pools that do not directly relate to fighting and overcoming enemies."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Rahu’s purpose is forged even stronger. The bonus to resist mental control or influence is raised to +3."]}]},{Rank:"•••",Name:"Hobbling Gaze",Description:"Slow a fleeing opponent",Cost:"●",Book:"Lore 91",fullDescription:[{type:"paragraph",text:"Rahu have no time for cowards. This Gift helps them keep a fight to a one-on-one basis by hampering their opponent’s ability to flee. Of course, some Rahu have been known to use this Gift to promote their own cowardice, by hobbling a foe and then fleeing. The target must be within five yards of the Rahu, and the Rahu must have clear line of sight."}],fullCost:"1 Essence",dicePool:"Dexterity + Athletics + Honor - target’s Resolve",action:"Instant",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Gift goes badly awry. The Rahu’s Speed is reduced by 2 for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The Gift has no effect."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," As the Rahu glares at his target, the strength drains from the target’s legs. The target’s Speed is reduced by 1 per success. A target can be affected by this Gift only once per scene. The Gift’s effects last for one minute per success."]},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," The Gift’s effects last for the entire scene."]}]},{Rank:"••••",Name:"Bloodletting",Description:"Inflict an hemoragy",Cost:"●",Book:"Lore 91",fullDescription:[{type:"paragraph",text:"A Rahu with this Gift has learned a truly savage trick from the warrior’s moon. By invoking this Gift as he tears into an opponent, he curses the wound to hemorrhage greatly, sapping his opponent’s strength as her blood drains from her body."},{type:"paragraph",text:"This Gift must be used on the same turn as a successful bite or claw attack."}],fullCost:"1 Essence",dicePool:"Strength + Medicine + Cunning - opponent’s Stamina",action:"Reflexive",rollResults:[{type:"paragraph",text:[{text:"Dramatic Failure:",bold:!0}," The Rahu cannot use this Gift for the remainder of the scene."]},{type:"paragraph",text:[{text:"Failure:",bold:!0}," The target suffers no additional ill effects."]},{type:"paragraph",text:[{text:"Success:",bold:!0}," The target’s wound begins to bleed rapidly. The target takes one additional level of bashing damage per turn, for a number of turns equal to the successes on the Gift’s activation roll."]},{type:"paragraph",text:"This Gift has no effect on creatures that do not “bleed” per se, such as vampires, spirits and certain types of Claimed. The Rahu may use this Gift against a given target only once per scene."},{type:"paragraph",text:[{text:"Exceptional Success:",bold:!0}," No additional effect apart from the severity of the wound."]}]},{Rank:"•••••",Name:"Might of the Full Moon",Description:"Wear gauru form as long as wished",Cost:"●●",Book:"Lore 91",fullDescription:[{type:"paragraph",text:"Under the full moon, the warrior reaches his peak. With its blessing, he can wear the war form for as long as he chooses, tearing into his foes relentlessly."},{type:"paragraph",text:"When this Gift is activated, the Rahu shifts into Gauru form as a reflexive action. He may remain in Gauru form for the duration of the scene. He is still subject to Rage, however, and all the drawbacks of Gauru that come with it. If he shifts out of Gauru form, the Gift’s effects end, and he cannot resume Gauru form without the assistance of some supernatural means such as the Rekindled Rage Gift."},{type:"paragraph",text:"This Gift can be used once per scene, and functions only under a full moon."}],fullCost:"2 Essence",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]}]},{Name:"Weakness",Description:"",Cost:"",Book:"Rage 127",Content:[{type:"paragraph",text:"While the Storm Lords exemplify the traditional attitude a werewolf holds toward weakness — that is to say, they hate it with the core of their being — all tribes find weakness to be a hindrance even if it’s not physically repulsive. Gifts of Weakness allow a werewolf to dampen his own weakness while exploiting it in others. The Storm Lords don’t favor this Gift list because too many see it as a cheap get-out clause that disgraces their ties to Winter Wolf. Spirits of animals with hidden strengths teach these Gifts, including a wide variety of poisonous spirits. The Gifts are also taught by some spirits aligned with the Maeljin."}],Ranks:[{Rank:"•",Name:"Reflection",Description:"Change a Chance roll to one die",Cost:"-",Book:"Rage 127",fullDescription:[{type:"paragraph",text:["In order to know weakness, the werewolf first seeks it out in the one place she knows it resides — herself. While other Gifts allow her to manipulate the weaknesses of others or hide her own failures, this Gift allows her to know her own limitations far better than she could without spiritual understanding. She knows what is holding her back, allowing her to work around that problem."]}],fullCost:"None",dicePool:"Wits + Empathy + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character believes one of her strengths is really a weakness. She suffers a -1 penalty on the next roll she makes with her highest Attribute or Skill."]},{type:"line",label:"Failure",text:["The werewolf understands no more about herself than normal."]},{type:"line",label:"Success",text:["The werewolf realizes how her own weakness is holding her back. If she has to make a Chance roll before the end of the scene, she instead makes the roll as if she had one die."]},{type:"line",label:"Exceptional Success",text:["The werewolf gets more insight into how she can work around her weakness. She can reduce the penalty applied to one roll that affects her current situation by 1 (so a -3 penalty becomes -2)."]}]},{Rank:"••",Name:"Shallow Heart",Description:"Select a new Vice for the subject that replaces the old one for a scene",Cost:"●",Book:"Rage 128",fullDescription:[{type:"paragraph",text:["Focusing on weakness includes inspecting the dark corners of one’s own mind. Many Uratha don’t like what they see there, reliving the moments of shame and wrath that have made them who they are. For a short time, this Gift allows the werewolf to show another — or herself — what she would be like if those little twists had taken a different turn and she had become a different person entirely, with a different core of weakness whispering into her heart. The werewolf can use this Gift upon herself or another, but using it on another werewolf is a sin with a Harmony Threshold of 6."]}],fullCost:"1 Essence",dicePool:"Composure + Larceny + Cunning versus Composure + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The target changes Vice as for a success, but entirely outside of the character’s control. The Storyteller should choose a new Vice for the subject of the Gift, and the player of the subject should play it out fully."]},{type:"line",label:"Failure",text:["The subject sees no other weakness but his own."]},{type:"line",label:"Success",text:["The werewolf plays around with his subject’s secret weaknesses and triggers, exposing a different set of negative values to the world. The player can select a new Vice for the subject, which lasts until the end of the scene and should be roleplayed appropriately. The new Vice entirely replaces the old one; though, if the subject has already indulged himself, this scene he can do so again."]},{type:"line",label:"Exceptional Success",text:["The subject finds triggers he didn’t know about, leading him to question who he is. This new understanding is akin to his committing a sin with Morality Threshold (Harmony Threshold for werewolves) of 6."]}]},{Rank:"•••",Name:"Coward’s Soul",Description:"Inflicts feelings of guilt and depression in the victim. She cannot gain Willpower until she sleeps well.",Cost:"●●●",Book:"Rage 128",fullDescription:[{type:"paragraph",text:["The weak accept tawdry untruths about free will and nobility. They act as though a moment’s grace, defying their basic weakness just once, will redeem them for the countless little sins of a week or a month. Their actions — however noble — are a pitiful reflection of their own weakness, trying to make up for their guilt over being such a worthless human being most of the time. This Gift enhances that feeling, inducing a depression that robs even the most selfless actions of all meaning besides assuaging the actor’s guilt."]}],fullCost:"3 Essence",dicePool:"Resolve + Empathy + Purity versus subject’s Resolve + Primal Urge",action:"Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overcome by the guilt and depression she had intended to inflict. For the remainder of the scene, any action that would trigger her Virtue does not do so."]},{type:"line",label:"Failure",text:["The werewolf cannot capitalize on the subject’s weakness."]},{type:"line",label:"Success",text:["The werewolf inflicts feelings of guilt and depression in the victim that last until the next time the subject gets a good night’s sleep. If the subject’s Virtue would have restored her Willpower before she awakes, she regains no Willpower."]},{type:"line",label:"Exceptional Success",text:["The subject is consumed by self-loathing. In addition to the effects of a success, the next action that the subject would consider noble is at a -2 penalty."]}]},{Rank:"••••",Name:"Hidden Self",Description:"Hide weakness from onlookers (Vice, low attribute, low harmony or derangement), making them effectively of average statistics for game mechanics.",Cost:"○",Book:"Rage 128",fullDescription:[{type:"paragraph",text:["A werewolf who masters weakness must accept that it lies within his heart as much as any other’s. The claims of some Uratha that they are beyond weakness are nothing but lies. They hide their weakness, but it still lurks within them. This Gift allows a werewolf to hide his weakness from the world. To those who care, he is without the weakness that defines everyone. While this can be a useful tool to bluff or bluster an opponent, the use of this Gift is never perfect. People can tell that something is wrong, something is missing, and may come to suspect the character because of that."]}],fullCost:"1 Willpower",dicePool:"Composure + Subterfuge + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overcome by the very weakness she was trying to hide. She must find an opportunity to indulge her Vice before the end of the scene, but gains no Willpower for doing so."]},{type:"line",label:"Failure",text:["The character’s attempt to hide her weakness fails."]},{type:"line",label:"Success",text:["The werewolf successfully hides her weakness from onlookers. This weakness can be her Vice but it could be something else; a low Attribute, low Harmony or a derangement may all be considered weakness by the character. She does not suffer the effects of her most obvious weakness for one scene. If her weakness is a Vice, she regains one Willpower in a situation in which she is strongly tempted to indulge but does not, derangements don’t have any effect, a low Attribute is rolled as if it were average (two dice) and so on. Supernatural powers that attempt to discern her weakness automatically fail.",{type:"lineBreak"},"This effect only works when people are watching the werewolf, and anyone observing a situation in which the werewolf’s weakness would normally affect her can make a straight Resolve + Empathy roll. Success indicates that the observer knows something is wrong, though only an exceptional success indicates to the observer that the werewolf is hiding her weakness from the world. Storm Lords who make use of this Gift (and are caught) are guaranteed to have a very hard time gaining Honor Renown."]},{type:"line",label:"Exceptional Success",text:["The effects of the Gift extend until the next moonrise or moonset (whichever is sooner). Observers who try to see through the Gift do so at a -2 penalty."]}]},{Rank:"•••••",Name:"Wrack",Description:"Make target suffer severe depression and self-loathing for 2 turns per success. She may take actions only spending Willpower and her defense is 0. After recovering, she must do a degeneration roll.",Cost:"●●○",Book:"Rage 129",fullDescription:[{type:"paragraph",text:["All the physical power of a werewolf is sometimes no match for the darkness within a person’s heart. Using this Gift, a werewolf inflicts a person with spirits of weakness that make sure that every little moment of shame plays out a thousandfold in the subject’s head. Every moment of weakness comes back to haunt the target of this Gift, and, in extreme cases, can lead to self-harm and even suicide as the subject tries any means possible to make up for leading such a wretched existence. Even if the target doesn’t harm herself, she certainly has no recourse to defend herself against anyone who would free her from her pit of weakness, though many werewolves find the psychological damage that this Gift produces just as effective as their own teeth and claws. There’s no doubt that this is a cruel Gift, but those who have gained the secret knowledge behind it believe that in some instances it is the only way forward that has any justice behind it."]}],fullCost:"2 Essence and 1 Willpower",dicePool:"Wits + Larceny + Honor - target’s Resolve",action:"Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The subject of the Gift is flooded with confidence in herself and her actions. For the next day, any attempt to exploit her weaknesses suffers a -3 penalty."]},{type:"line",label:"Failure",text:["The subject is no more depressed than anyone else in the World of Darkness."]},{type:"line",label:"Success",text:["The subject of the Gift finds herself suffering severe depression and self-loathing as every little moment of weakness plays back behind her eyes. She can take no actions beyond moving half her Speed each turn without spending a Willpower point (which does not grant the usual three-dice bonus). If attacked, her Defense counts as zero. The Gift’s effects last for two turns per success, and if the target survives she must make a degeneration roll as if she had committed a sin with a Morality Threshold equal to her current Morality trait (so if she had Morality 6, she would roll three dice)."]},{type:"line",label:"Exceptional Success",text:["The subject of the Gift starts self-harming, gouging long wounds in her arms with any vaguely sharp instrument nearby, or her own nails if no tool presents itself. The subject takes her Strength in lethal damage in addition to the other effects of this Gift."]}]}]},{Name:"Weather",Description:"",Cost:"",Book:"WtF 146",Content:[{type:"paragraph",text:"By their very nature, the Forsaken are closely tied to the spirits of the natural world. By exploiting this connection, knowledgeable werewolves can influence the very heavens. One of the most visible and useful ways of doing so is by commanding various forms of weather."},{type:"paragraph",text:"These Gifts are typically taught to the Forsaken by storm- or powerful bird-spirits."}],Ranks:[{Rank:"•",Name:"Call the Breeze",Description:"Summon light wind (-1 to Perception rolls)",Cost:"-",Book:"WtF 146",fullDescription:[{type:"paragraph",text:["A werewolf may summon a brisk wind (approximately 25 miles per hour) and direct it as he wills. This wind is useful both for dispersing or redirecting a fire or flying insects, or as a distraction."]},{type:"paragraph",text:["Though it requires no roll to actually summon the wind, a successful Manipulation + Occult roll is necessary to direct it to any specific task, such as to disperse tear gas. Because of the distraction of the sudden breeze, perception task rolls (",{text:"World of Darkness Rulebook",bold:!0},", p. 45) made in the area suffer a -1 penalty. The Gift lasts for one turn per dot of Primal Urge that the summoner has. The breeze can be conjured indoors or out."]}],fullCost:"None",dicePool:"This power requires no roll.",action:"Instant",rollResults:[]},{Rank:"••",Name:"Silent Fog",Description:"Summon a patch of fog (-2 to Perception rolls)",Cost:"●",Book:"WtF 146",fullDescription:[{type:"paragraph",text:["Though fierce fighters and savage predators, even werewolves recognize the need for stealth and guile. This Gift is a prime example of how werewolves operate strategically and with a mind toward hewing to the Oath’s prohibition against human discovery. With it, a werewolf may summon a thick blanket of fog to obscure an area, allowing a pack to move unseen in whatever form its members choose. This fog bank moves as the werewolf who summoned it wills it to, and it makes an excellent vehicle for ambush or a way of avoiding combat entirely."]}],fullCost:"1 Essence",dicePool:"Manipulation + Survival + Cunning",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The fog appears, but it obscures the vision of the summoner and his pack as much as anyone else."]},{type:"line",label:"Failure",text:["The weather does not change."]},{type:"line",label:"Success",text:["Over the course of a turn, the cloud-spirit summoned with this Gift congeals from the air, and a dense fog covers an area equal to the werewolf’s Primal Urge x 20 square yards. It may thereafter be directed to move in any direction at a rate of (Primal Urge x 10) yards per turn. While within the fog, a perception check at -2 is required for observers to spot someone more than one yard distant. Even if spotted, ranged attacks are treated as if those within the bank are substantially concealed (see “Concealment” on pp. 162-164 of the ",{text:"World of Darkness Rulebook",bold:!0},"). Silent Fog lasts for an entire scene or until the spirit is dismissed by the Forsaken who commanded it."]},{type:"line",label:"Exceptional Success",text:["The fog is particularly thick, levying a -3 penalty to perception checks instead of -2."]}]},{Rank:"•••",Name:"Deluge",Description:"Summon a heavy rain (-2 to Perception and ranged combat rolls)",Cost:"●",Book:"WtF 146",fullDescription:[{type:"paragraph",text:["With this Gift, a werewolf summons a rain-spirit to bring a torrential downpour to an area. No gentle shower, this torrent has myriad uses, from ruining crops to starting flash floods to erasing evidence of a pack’s passage. This Gift can only be used outdoors."]}],fullCost:"1 Essence",dicePool:"Manipulation + Survival + Honor",action:"Extended (20 successes; one turn passes per roll)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The weather alters in a manner other than the character’s choosing. It may shift from rain to snow to hail to high wind, usually in some fashion horribly inconvenient to the Gift user. The aberrant and troublesome weather persists for the duration of the scene."]},{type:"line",label:"Failure",text:["The weather doesn’t change."]},{type:"line",label:"Success",text:["The area affected is equal to one square mile per success achieved. Common sense must be applied to applications of this Gift. The deluge could flood low-lying areas or cause a river to swell its banks, but no one standing on even reasonably high ground is going to drown. The Gift isn’t designed to directly damage an individual, but it can sure as hell do so indirectly, causing thousands of dollars in property damage alone. In times of drought, the power of this Gift can be a great boon. The downpour lasts for a scene.",{type:"lineBreak"},"Those caught in heavy rain suffer a -2 penalty to perception rolls and ranged combat."]},{type:"line",label:"Exceptional Success",text:["The character can select an area that receives less or no rain, effectively creating an eye of the storm."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+2","The weather is already raining or drizzling"],["+1","A heavily clouded day"],["-3","A cloudless day"],["-5","Desert or other similarly arid area"]]}]},{Rank:"••••",Name:"Killing frost",Description:"Summon a hard frost wave (2 points of bashing damage, -2 to Strength and Dexterity rolls)",Cost:"●",Book:"WtF 147",fullDescription:[{type:"paragraph",text:["This Gift summons forth the chill of a hundred winters in the space of a few heartbeats. The Storm Lords speak reverently of this Gift as “the breath of Winter Wolf.”"]}],fullCost:"1 Essence",dicePool:"Manipulation + Survival + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift’s power turns against the werewolf. The user immediately takes two points of lethal damage from the cold."]},{type:"line",label:"Failure",text:["The temperature drops by only a degree or two."]},{type:"line",label:"Success",text:["The temperature suddenly drops below freezing within 10 yards per dot of Primal Urge of the user. Frost forms on surfaces, and water freezes. If the Gift is used within a rainstorm, the sudden freezing rain might down power lines and break tree branches. Living creatures take two points of bashing damage from the sudden chill. In addition, anyone in the area suffers a -2 penalty to Strength and Dexterity rolls for as long as the cold lasts (though they don’t take additional damage in subsequent turns). The reduced temperature lasts for one turn per success. At the Storyteller’s discretion, any creatures who are appropriately protected from the cold may take less damage or be immune to the imposed penalties.",{type:"lineBreak"},"The Gift user is protected from the direct effects of the cold, but may be subject by secondary effects. The cold doesn’t injure him or cause any debilitating effects, but he might still slip when trying to move across ice or be injured by a falling power line.",{type:"lineBreak"},"This Gift can be used only once per scene."]},{type:"line",label:"Exceptional Success",text:["The sudden shock of cold is particularly vicious; living creatures suffer three points of damage instead of two."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+2","Winter"],["-2","Summer"]]}]},{Rank:"•••••",Name:"Thunderbolt",Description:"Summon a thunderbolt upon his opponent (4 points + 1 per success of lethal damage)",Cost:"●",Book:"WtF 147",fullDescription:[{type:"paragraph",text:["This Gift implores a mighty thunderbird to turn its gaze earthward and fix its flashing eyes on a select target. At the werewolf’s command, lightning strikes his foe, its power capable of killing most mortals and severely wounding even supernatural opponents."]}],fullCost:"1 Essence",dicePool:"Intelligence + Survival + Glory – Defense",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The bolt strikes a random target nearby, be it friend or foe."]},{type:"line",label:"Failure",text:["The werewolf’s call is ignored."]},{type:"line",label:"Success",text:["The bolt deals a base of five points of lethal damage, plus any extra successes from the activation roll after the first. The werewolf can nominate any target within his line of sight, as long as the victim is outdoors or standing near a window."]},{type:"line",label:"Exceptional Success",text:["The blast also deafens the target for two turns."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["+2","Rain or windy weather"],["+1","Cloudy day"],["–3","Cloudless sky"]]}]}]},{Name:"Witch's Moon",Description:"",Cost:"",Book:"Lore 91",Content:[{type:"paragraph",text:"The Gifts of the Witch’s Moon focus on the interaction between the flesh and the Shadow, in ways that are often dangerous and, to outside eyes, even sinister. They allow an Ithaeur to entice and then disrupt the affairs of spirits, as well as hex victims of a more physical nature."}],Ranks:[{Rank:"•",Name:"Shadow-Speaking",Description:"Act as a vessel for spirits to speak",Cost:"-",Book:"Lore 91",fullDescription:[{type:"paragraph",text:["The idea that a spirit or spirits may choose to contact mortals by speaking through a mortal vessel is a concept as old as humanity — and likely older. This Gift allows the Ithaeur to become that vessel. The Ithaeur opens herself to contact with spirits on the other side of the Gauntlet, allowing willing spirits on the other side to speak through her. The spirit speaks with her voice, and looks with her eyes. This Gift is obviously at its most useful when the pack is unwilling or unable to cross the Gauntlet at a particular location, yet desire to interrogate the spirits of the area."]}],fullCost:"None",dicePool:"Intelligence + Occult + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Ithaeur makes the wrong sort of contact, drawing the attention of something she shouldn’t have."]},{type:"line",label:"Failure",text:["The Ithaeur is unable to push her consciousness through the Gauntlet and make contact."]},{type:"line",label:"Success",text:["The Ithaeur becomes a limited conduit between the physical world and the spirit. Any spirit that is within the Shadow reflection of her immediate area (such as in the same room with her) may choose to contact the pack through the Ithaeur. This is not possession, and the spirit becomes no more able to affect the physical world than usual; the only thing that is facilitated is communication. Though nothing compels a spirit to take the Ithaeur up on her offer, it is an interesting enough invitation that usually a spirit will do so out of curiosity. Naturally, the spirit will speak in the First Tongue. The Ithaeur cannot herself speak while the Gift lasts, but she is awake and able to witness the entire conversation.",{type:"lineBreak"},"If multiple spirits are present across the Gauntlet, they may vie for the “honor” of parley. Usually the strongest spirit manages to establish and retain contact, but it’s also possible that the Ithaeur will speak in the garbled voices of multiple spirits.",{type:"lineBreak"},"The Gift lasts for as long as the Ithaeur is willing to maintain concentration."]},{type:"line",label:"Exceptional Success",text:["The spirit is entranced by the experience. Any Social rolls made to influence the spirit during the conversation are made at an additional +1."]}]},{Rank:"••",Name:"Shadow Discord",Description:"Reduce spirits influence in a zone",Cost:"●",Book:"Lore 92",fullDescription:[{type:"paragraph",text:["A skilled wolf-witch can call on the Shadow to jinx a material foe, but she can also make things more difficult for those entities trying to reach across the Gauntlet. This Gift causes a form of supernatural interference, countering a spirit’s ability to influence the things it exemplifies."]}],fullCost:"1 Essence",dicePool:"Presence + Occult + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift fails to take effect. For the next scene, the Ithaeur is at a -2 penalty to any rolls made to resist a spirit’s Influences."]},{type:"line",label:"Failure",text:["The Gift has no effect."]},{type:"line",label:"Success",text:["The Gift creates a field of spiritual static that radiates out from the Ithaeur for 10 yards per success and moves with her. For the next scene, any attempt by a spirit to use its Influences within the affected area is at a dice pool penalty equal to the Ithaeur’s Resolve + 2."]},{type:"line",label:"Exceptional Success",text:["The penalty to any Influence dice pools is increased to the Ithaeur’s Resolve + 4."]}]},{Rank:"•••",Name:"Luck-Eating",Description:"Transfer luck from target to the Ithaeur",Cost:"●",Book:"Lore 92",fullDescription:[{type:"paragraph",text:["Some Ithaeur are able to hex their enemies in a particularly subtle fashion. With this Gift, the Crescent Moon can devour a portion of her target’s luck for her own use. The Ithaeur must touch the target in order to activate this Gift; any touch will do, even casually brushing against him in a crowd. The Gift is a subtle one, and the victim fails to realize that anything has happened until something goes terribly wrong."]}],fullCost:"1 Essence",dicePool:"Wits + Occult + Cunning versus target’s Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift’s effects fail. In addition, the target is now aware that the Ithaeur tried to do ",{text:"something",italic:!0}," to him, though he might not know just what."]},{type:"line",label:"Failure",text:["The Gift’s effects fail."]},{type:"line",label:"Success",text:["The Ithaeur successfully establishes contact. At any point before the next moonrise, the Ithaeur may choose to devour a portion of the target’s luck as a reflexive action. Once she does so, the target suffers a –3 penalty to his next dice roll, and the Ithaeur gains a +3 bonus to her next dice roll. An Ithaeur can only be “attached” to one victim at a time through means of this Gift."]},{type:"line",label:"Exceptional Success",text:["The stolen luck rises to five dice rather than three."]}]},{Rank:"••••",Name:"Cage the Rider",Description:"Emprison a spirit into the Ithaeur body",Cost:"●+",Book:"Lore 93",fullDescription:[{type:"paragraph",text:["Many of the spirits that cause the most trouble for Uratha are those that attempt to Ride living creatures. This particularly risky Gift allows the Ithaeur to act as bait to such spirits and then to trap them within herself. Some Ithaeur refer to this Gift as “catching a spirit in my ribcage,” while others liken it to swallowing a spirit for a time or caging a spirit within the mind. Most frequently, this Gift is used either to frighten a spirit into complying with the pack’s demands, or as a temporary way to catch a spirit until a formal Rite of Binding or other means of disposal can be prepared."]}],fullCost:"1 Essence to activate + 1 Essence per scene of entrapment",dicePool:"Resolve + Intimidate + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The internal “spirit cage” does not form, but the enticing aura still manifests in a way, drawing the attention of nearby spirits without disguising the werewolf’s nature. The Ithaeur is likely to suffer from unwanted spirit attention for the remainder of the scene."]},{type:"line",label:"Failure",text:["The Gift does not work, and spirits regard the Ithaeur as different in no particular way."]},{type:"line",label:"Success",text:["Until the next moonrise, the Ithaeur exudes a spiritual aura that is particularly enticing to spirits that possess the Living Fetter, Possession or Claim Numina. The werewolf appears to be the ideal host to such a spirit, and the spirit is unlikely to even notice that the Ithaeur is a werewolf at all. Obviously, this Gift is not used lightly; around a nest of spirits with such Numina, it could start a minor war. A spirit that is more than one Rank above the Ithaeur’s effective Rank is not affected by this Gift, and most do not notice the lure (though it’s possible that one might).",{type:"lineBreak"},"When a spirit attempts to fetter, claim or possess the Ithaeur via a Numen, the trap activates. The player rolls Intelligence + Occult + Wisdom as a reflexive action to attempt to trap the spirit; the spirit contests the roll by rolling Power. If the roll is a tie or the spirit gets more successes, the Gift effects end, and the spirit breaks free (and may attack or flee, depending on its mental state).",{type:"lineBreak"},"If the player gets more successes, though, the spirit is effectively trapped for a scene; the Ithaeur may extend the duration of the imprisonment by spending one Essence per scene. The spirit shares the same space as the Ithaeur, yet cannot break free or manifest itself. The spirit cannot use any Influences or Numina while bound within the Ithaeur. Once per day, at sunrise, the spirit may make a new attempt to break free by rolling Power contested by the Ithaeur’s Resolve + Occult. If the spirit breaks free, or is released by the Ithaeur (the Ithaeur may do so at any time as a reflexive action), it wins free of the werewolf’s body. If the Ithaeur is in the physical world at this time, the spirit will appear in a state of Twilight.",{type:"lineBreak"},"An Ithaeur can have only one spirit bound within her at a time by means of this Gift."]},{type:"line",label:"Exceptional Success",text:["The trap is particularly cunningly crafted. The player gains two extra dice to the roll made to initially trap the spirit."]}]},{Rank:"•••••",Name:"Poisoned Essence",Description:"Make essence expenditure to deal damage",Cost:"●",Book:"Lore 93",fullDescription:[{type:"paragraph",text:["The final trick taught by the witch’s moon is a curse, and a dangerous one at that. The Ithaeur can levy a hex on an opponent that taints the very Essence within him. As the victim attempts to use his Essence reserve, the tainted energy sends painful shocks throughout his body, eventually causing physical damage as the poison worsens."]},{type:"paragraph",text:["This Gift works only on targets that have an Essence trait, such as spirits or other werewolves; it cannot be used to poison a vampire’s blood pool, for instance."]}],fullCost:"1 Essence",dicePool:"Wits + Occult + Honor versus Resolve + Primal Urge",action:"Contested; resistance is reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Ithaeur loses two points of Essence as her own spiritual reserve is partly tainted and must be expunged."]},{type:"line",label:"Failure",text:["The target is unaffected."]},{type:"line",label:"Success",text:["The hex takes hold. For the duration of the scene, the target takes one point of bashing damage for every point of Essence he spends."]},{type:"line",label:"Exceptional Success",text:["As above, but the damage is lethal."]}]}]},{Name:"Wisdom",Description:"",Cost:"",Book:"SotM 67",Content:[{type:"paragraph",text:["The Ithalunim are wise, but theirs is a terrible, uncompromising wisdom, bereft of the comforting self-delusions to which all mortal beings sometimes fall prey. Theirs is the cold, pale light of truth, and although the knowledge they grant is useful, it carries with it the dangers of madness borne of understanding things that the mortal mind was not meant to know. In addition to the Crescent Moon Gifts described on pp. 104–106 of ",{text:"Werewolf: The Forsaken",bold:!0},", the Ithalunim can teach Wisdom Gifts."]},{type:"paragraph",text:"Wisdom Gifts are only available to Ithaeur, and require that the werewolf have a Wisdom Renown equal to the dot rating of the Gift. This requirement applies even if the Ithaeur is otherwise capable of learning the Gift without raising her Wisdom. For example, a Storm Lord Ithaeur uses Wisdom and Honor as her primary Renown. When her Honor reaches 4, she is eligible to learn rank 4 Gifts from most Gift lists, but in order to learn Master’s Counsel, she must raise her Wisdom to 4 as well."},{type:"paragraph",text:"These gifts are considered affinity Gifts for Ithaeur."}],Ranks:[{Rank:"•",Name:"The Heart of Things",Description:"Add Wisdom to any Mental or Social roll to infer knowledge for a scene",Cost:"●",Book:"SotM 67",fullDescription:[{type:"paragraph",text:["With wisdom comes insight, and with insight comes power. This Gift allows a werewolf to size up a situation in the blink of an eye, instantly divining who is friend and who is foe, or piecing together the nature of some event based on a quick examination of the evidence left behind. Activating this Gift causes the user’s eyes to reflect a thin, crescent-shaped sliver of light, as though the Ithalunim shines through them, using its own sight to pull together an accurate picture of the scene."]},{type:"paragraph",text:["When this Gift is activated, the player adds the character’s Wisdom Renown to the dice pool of any Mental or Social roll made to infer some piece of knowledge from observation (e.g. Wits + Empathy to guess whether someone is lying, Intelligence + Investigation to piece together the nature of a crime from evidence left behind) for the rest of the scene. In addition, if the action required to infer this knowledge requires longer than a single turn (or one turn per roll in the case of extended actions), the character may expend another point of Essence to reduce the time required to an instant action (or one turn per roll, for extended actions)."]},{type:"paragraph",text:["The wisdom of the Ithalunim comes not without some risk. Should the character fail any action that benefits from this Gift, she gains a temporary fixation derangement (p. 97, ",{text:"World of Darkness Rulebook",bold:!0},") bent towards “solving” the mystery. This derangement fades after 24 hours."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Befuddle",Description:"Target suffers penalty equal to Ithaeur Wisdom on mental rolls",Cost:"●",Book:"SotM 67",fullDescription:[{type:"paragraph",text:["Wisdom is a precarious thing, and as the old adage goes, the truly wise man is the man who knows he is a fool. Just as the Ithalunim can bring wisdom, they can also obfuscate truth and cloud men’s minds with false knowledge. By speaking in riddles and apparently paradoxical koans, the character sets an Ithalunim upon a rival, confusing him and twisting his perceptions. The victim begins to question his own beliefs, and even the very nature of his soul."]},{type:"paragraph",text:["Befuddle is of questionable use in battle, but then, battle isn’t where Ithaeur shine. This Gift is phenomenally useful when negotiating with spirits or engaging in contests of wit and debates. While the Ithaeur’s opponent trips over words and expresses half-formed, illogical views, she sits calm and serene, espousing the wisdom of the Ithalunim."]}],fullCost:"1 Essence",dicePool:"Wits + Expression + Wisdom versus Composure + Primal Urge or Resistance (for spirits)",action:"Contested",rollResults:[{type:"line",label:"Dramatic Failure",text:["The target is not affected by the Gift, and is immune to any other attempted uses until the next crescent moon. In addition, the Ithaeur gains a temporary paranoia derangement that lasts for 24 hours. The paranoia focuses on the belief that the Ithaeur’s wisdom is false and that she herself is the fool."]},{type:"line",label:"Failure",text:["The target is not affected by the Gift."]},{type:"line",label:"Success",text:["The Ithaeur’s words befuddle the target, crippling him with uncertainty and self doubt. The target suffers a penalty equal to the Ithaeur’s Wisdom Renown on all Mental Skill or Attribute rolls for the rest of the scene."]},{type:"line",label:"Exceptional Success",text:["The penalty lasts until the next crescent moon instead."]}]},{Rank:"•••",Name:"The Wisdom of Patience",Description:"Skip a turn in combat to gain various benefits to next attack",Cost:"none",Book:"SotM 67",fullDescription:[{type:"paragraph",text:["Fools rush in where wise men fear to tread, as the saying goes. By patiently waiting for the perfect moment to strike, the wise warrior lands a decisive blow. He might not hit as often as his packmates, but when he does hit, he hits hard and cripples his foe."]},{type:"paragraph",text:["Whenever the character delays her action in combat for one full turn (for example, if the character’s Initiative count was 10, she must delay until the count of 10 in the next turn) as described on p. 151 of the ",{text:"World of Darkness Rulebook",bold:!0},", she may add one of the following benefits to her next attack roll:"]},{type:"list",items:[["The player adds three dice to her attack dice pool, as though she had spent a point of Willpower. She may still spend Willpower on the roll if she desires."],["The player may ignore the attack penalty for making a called shot."],["The player may upgrade the damage from an attack that inflicts bashing damage to lethal."],["If the attack hits, it causes the target to lose his Defense against the ",{text:"next",italic:!0}," attack that hits him."],["If the attack hits, the target loses his next action."]]},{type:"paragraph",text:["The character may delay multiple turns in order to receive multiple benefits, up to a maximum number of benefits equal to her Wisdom Renown. The Ithaeur may choose not to activate this Gift if she desires."]},{type:"paragraph",text:["If the character misses with her first attack after invoking this Gift, she gains a temporary irrationality derangement that lasts for 24 hours."]}],fullCost:"None",dicePool:"This Gift does not require a roll.",action:"None. This Gift triggers automatically when the character delays unless she chooses not to activate it.",rollResults:[]},{Rank:"••••",Name:"Mothers Counsel",Description:"Add Ithaeur's Wisdom as an equipment bonus to another's skill for 24 hours",Cost:"●",Book:"SotM 68",fullDescription:[{type:"paragraph",text:["Wisdom hoarded is wisdom wasted, and though Ithaeur know many things are best kept secret, they are expected to be advisors to their packmates, offering their knowledge in difficult situations. This Gift allows the Ithaeur to consult the Ithalunim for guidance in a particular action, allowing the Crescent Moon to suggest a course of action that will benefit her pack."]},{type:"paragraph",text:["In order to use this Gift, the Ithaeur must be able to see and communicate with the target. She need not be physically present; a televisual link and radio communication is sufficient, but the communication must be in real-time and the quality of the image must be good (the typical home video camera or surveillance camera is okay, the camera found in a typical cell phone probably isn’t). The Ithaeur cannot use this Gift on herself."]},{type:"paragraph",text:["When this Gift is activated, the target adds the Ithaeur’s Wisdom Renown to his rating in any single Skill. These bonus dots are considered actual Skill dots, not merely bonus dice (so, for example, if the target has no dots in the Skill, this Gift negates the untrained penalty). The bonus lasts as long as it takes to accomplish a single task with that Skill ",{text:"or",italic:!0}," 24 hours, whichever comes first. If a task requires longer than 24 hours to complete, a second use of this Gift is required. A single character cannot benefit from this Gift more than once in a 24-hour period."]},{type:"paragraph",text:["If the target of the Gift fails in the action enhanced by the Ithaeur’s Wisdom (not just a single roll in the case of an extended action, but the entire action), the Ithaeur gains a temporary depression derangement focused on the failure of his advice. This derangement lasts for 24 hours."]}],fullCost:"1 Essence",dicePool:"This Gift does not require a roll.",action:"Reflexive.",rollResults:[]},{Rank:"•••••",Name:"Forbidden Knowledge",Description:"Target does not make the next roll, instead automatically gets success equal to Ithaeur's Wisdom",Cost:"●●●○",Book:"SotM 68",fullDescription:[{type:"paragraph",text:["Some knowledge in this world is not meant for man or Uratha. Beyond the rude boundaries of physics and rational law lies the Shadow. Beyond the Shadow lies the yawning abyss of nothingness upon which the world floats, like an island in a sea of oblivion. In that vast emptiness, ",{text:"things",italic:!0}," swim, things antithetical to all life and as alien as the ",{text:"idigam",italic:!0},", if not more so. The Ithalunim have knowledge of such things (and some Ithaeur even suggest that said knowledge is the reason for the Oracle choir’s madness), and though they exact a terrible toll for sharing it, Ithaeur who master this Gift can compel them to share that knowledge; using this blasphemous knowledge, the character cuts through uncertainty and chance, acting with perfect certainty of success."]},{type:"paragraph",text:["When the character activates this Gift, the player does not roll for the next instant action he takes before the end of the scene. Instead, the player is considered to have automatically garnered one success per point of Wisdom Renown (since this is a rank 5 Gift, that usually means five successes). On uncontested or resisted rolls, this is enough to ensure an exceptional success. For contested actions, the contesting player rolls normally against the Ithaeur’s pool of automatic successes."]},{type:"paragraph",text:["The power of this Gift comes at a punishing cost: the sheer alien nature of the knowledge given by the Ithalunim causes lasting, physical harm to the body, leeching out life simply by exposure to that horrible nothingness. Upon using this Gift, the character takes one point of lethal damage per dot of her Wisdom Renown. This damage heals at the rate a ",{text:"human",italic:!0}," would heal lethal damage (one point per two days unless the character has the Fast Healer Merit), and cannot be healed through Essence expenditure. Mark these wounds on the character sheet with a small dot below the Health box to track these wounds separately from any other wounds. The character also gains a severe derangement of the Storyteller’s choice, which lasts until the next crescent moon."]},{type:"paragraph",text:["This Gift can only be used once per chapter."]}],fullCost:"3 Essence and 1 Willpower",dicePool:"This power does not require a roll.",action:"Instant",rollResults:[]}]},{Name:"Wolfslayer",Description:"",Cost:"",Book:"WAtP 48",Content:[{type:"paragraph",text:"The Wolfslayer Gifts are powers only effective against werewolves and, unlike some Rage or auspice-related Gifts, Wolfslayer Gifts are almost always harmful or negative. Some Uratha disapprove of these Gifts because there is only one real reason to learn them: to fight other werewolves. Spirits are often reluctant to teach these to the Forsaken, less than eager to reveal their arsenal of anti-werewolf powers. Other spirits are happy to share the knowledge, considering it a warning of their capabilities or hoping that the People will use them to tear itself apart. Rebellious and warlike spirits teach these Gifts, the ones that the Forsaken consider most likely to rise up in arms against the continued policing of the werewolves. Greed-spirits, envy-spirits and panther-spirits can be teachers, among others."}],Ranks:[{Rank:"•",Name:"Form Lock",Description:"Make it harder for a werewolf to shapeshift",Cost:"●",Book:"WAtP 48",fullDescription:[{type:"paragraph",text:["Shifting shape is instinctive to the People. It’s as completely natural as clenching a fist or flipping off the guy who’s tailing you. So, when shapeshifting is denied a werewolf, it is very frustrating. Some even panic, unaware that hostile magic is affecting their change."]}],fullCost:"1 Essence",dicePool:"Charisma + Science + Purity vs. Resolve + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift not only fails to affect the target, its residue hinders the shapechanging of the werewolf who invoked it. The character suffers a –2 dice penalty to all shapechanging rolls."]},{type:"line",label:"Failure",text:["The Gift fails to reduce the target’s shapeshifting pool."]},{type:"line",label:"Success",text:["Each success on the roll reduces the target werewolf’s shapeshifting pool for one minute by the character’s Purity. Any successful, voluntary change on the target’s part eliminates the penalty."]},{type:"line",label:"Exceptional Success",text:["The target’s shapeshifting pool remains penalized for one ",{text:"hour",italic:!0},"; each successful change reduces the remaining duration by five minutes."]}]},{Rank:"••",Name:"Patronless Pack",Description:"Temporarily remove Totem benefits for a pack",Cost:"●",Book:"WAtP 49",fullDescription:[{type:"paragraph",text:["Nearly every werewolf pack has a personal and specific totem, which lends them a portion of its power in exchange for children among the Uratha. Werewolves with this Gift can temporarily sever the bond between pack and totem, eliminating some of the advantages her enemies have."]}],fullCost:"1 Essence",dicePool:"Intelligence + Occult + Cunning – totem’s Resistance",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["Offended by the attempt, the spirits instead separate the werewolf from her totem for one day. Werewolves without totems are unaffected and fail simply."]},{type:"line",label:"Failure",text:["The werewolf is unable to remove her opponents’ totem’s influence."]},{type:"line",label:"Success",text:["The werewolf targets a pack and temporarily drives a wedge between them and their totem. They lose any and all totem benefits for the rest of the scene. She affects all werewolves she can see that belong to the same pack; she need not know the pack’s name to target it — looking at an enemy werewolf and concentrating on ",{text:"that",italic:!0}," pack is enough. Members of the affected pack not present are unaffected by the Gift and remain blessed by the totem. (This may mean that one lone werewolf is the only one available to use pack Attributes or Skills, or the only one who can call upon story bonuses.) Some werewolves consider being under the effect of this Gift to free them from the constraints of their totem’s ban until the Gift ends, but few totem spirits see it that way."]},{type:"line",label:"Exceptional Success",text:["Even members of the pack who are not present are cut off from the totem spirit. The pack is sure to have a few words about why their totem is so susceptible to enemy Gifts later on."]}]},{Rank:"•••",Name:"Return to Birth",Description:"Force a werewolf into human form",Cost:"●",Book:"WAtP 49",fullDescription:[{type:"paragraph",text:["Hishu, while the best form for hiding among the six billion sheep on Earth, is one of the least combat-effective and everyone knows it. This Gift forces a werewolf back into human form, though it can’t keep her there."]}],fullCost:"1 Essence",dicePool:"Charisma + Science + Purity vs. Resolve + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The attempt fails, and the werewolf cannot use this Gift again for 24 hours."]},{type:"line",label:"Failure",text:["The werewolf fails to force his target into her human shape."]},{type:"line",label:"Success",text:["The target reverts immediately to Hishu form and cannot use her next action to change shape. For werewolves already suffering from Form Lock, this forced change does not end that effect. A werewolf currently suffering ",{text:"Kuruth",italic:!0}," is immune to this Gift."]},{type:"line",label:"Exceptional Success",text:["The target’s system is so shocked by being forced into Hishu form that she cannot attempt to change into another shape for five turns."]}]},{Rank:"••••",Name:"Human Health",Description:"Remove werewolf regeneration",Cost:"●",Book:"WAtP 49",fullDescription:[{type:"paragraph",text:["One of the Uratha’s most serious advantages in battle is their ability to bounce back from nearly any wound, and quickly. Take that away, and a werewolf goes down that much faster. Even worse, a werewolf in Gauru knows he has to release the form soon or go berserk, and if he’s taken so many wounds that he would die by shifting back to human, he’s in a very bad place."]}],fullCost:"1 Essence",dicePool:"Wits + Medicine + Purity vs. Composure + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["Rather than shutting down, the target’s enhanced healing blurs into action. As if the werewolf spent a point of Essence on her target’s behalf, the target immediately heals a point of lethal damage."]},{type:"line",label:"Failure",text:["The target continues to heal as normal (for a werewolf)."]},{type:"line",label:"Success",text:["For the next hour, the target heals as a human does. See p. 175 of the ",{text:"World of Darkness Rulebook",bold:!0}," for full details on human rates of healing. He cannot spend Essence to heal lethal wounds instantly, though it will heal bashing wounds."]},{type:"line",label:"Exceptional Success",text:["The effect lasts a full day, and the target werewolf cannot even spend Essence to heal bashing damage."]}]},{Rank:"•••••",Name:"Object of Piercing Clarity",Description:"Witnesses view target as if they had +4 Willpower for purposes of Lunacy",Cost:"●",Book:"WAtP 50",fullDescription:[{type:"paragraph",text:"One of the People’s greatest defenses is Lunacy. Against mortals, it is usually effective enough to end a fight. When the fight is with other supernaturals, Lunacy can blank the minds of those annoying witnesses. It may be hard to deal with in personal life, but it’s a great blessing when worrying about “the herd,” especially when a war spills into the streets. This frightening Gift frees a werewolf from the curse of Lunacy for a time. While it may seem like a boon for those Uratha who still try to live a human life, it is definitely a double-edged sword."}],fullCost:"1 Essence",dicePool:"Presence + Expression + Glory vs. Composure + Primal Urge",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"Some measure of the werewolf’s Lunacy shifts from him to his target. Mortals viewing him in a form that induces Lunacy gain +2 to Willpower for the purposes of dealing with Lunacy, cumulative with bonuses for wolf blood and less-frightening forms. Mortals viewing the target lose –2 from Willpower for the same purpose. Both effects last a half-hour."},{type:"line",label:"Failure",text:"The Gift fails to dampen the target’s cloak of Lunacy."},{type:"line",label:"Success",text:`The werewolf temporarily subdues his target’s Lunacy; the target senses this diminishment. Treat all onlookers as if they have +4 Willpower for the purposes of dealing with the target’s Lunacy. This bonus is cumulative with others. Successful use of the Gift does not mean that a person with six dots of Willpower (treated as 10 after this Gift takes effect) is automatically unafraid of a werewolf in Gauru, because it would be stupid not to fear a giant wolf-monster. But significantly more people are going to see the werewolf for what she truly is and be in control of their own actions. The effect lasts for a half-hour.

Object of Piercing Clarity has multiple potential effects on the target. A werewolf concerned with the Oaths of the Moon might break off the fight and retreat, more wary of revealing herself than usual. Or the humans that see her in an impossible shape — and recognize it, thanks to the Gift — might assault her, especially if her opponent looks like nothing more than a fellow mortal.

Use of this Gift can be very tactically effective, but many Uratha do not approve. It is a few hairs-breadths short of actively revealing the People to humanity, which no sane werewolf desires.`},{type:"line",label:"Exceptional Success",text:"The werewolf completely subdues his target’s Lunacy for a full hour. Even the weakest-willed mortals are unaffected (at least supernaturally), even by the terrifying Gauru form."}]}]},{Name:"Wound",Description:"",Cost:"",Book:"Blas 139",Content:[{type:"paragraph",text:["These particularly vile Gifts are learned from the spirits serving the Maeljin. The Gifts draw on saturation in negative resonance, and become fearsome weapons in the arsenal of the ",{text:"Asah Gadar",italic:!0},"."]}],Ranks:[{Rank:"•",Name:"Wound-Born",Description:"The Bale Hound becomes immune to the foul resonance emanating out from a Wound. He no longer suffers the penalties of entering and interacting within Wounds",Cost:"-",Book:"Blas 139",fullDescription:[{type:"paragraph",text:["With this Gift, the Maeltinet blesses the werewolf with the ability to cope with the taint of Wounded places, as if she had been born in a Wound like one of the Maeljin’s own avatars, and saturated in such resonance from birth."]},{type:"paragraph",text:["The Bale Hound becomes immune to the foul resonance emanating out from a Wound. He no longer suffers the penalties of entering and interacting within Wounds, as described on p. 259 of ",{text:"Werewolf: The Forsaken",bold:!0},". This Gift requires no expenditure or dice roll to activate, only a moment’s concentration."]}],fullCost:"None",dicePool:"No roll is required.",action:"Reflexive",rollResults:[]},{Rank:"••",Name:"Lord of the Wounds",Description:"To Wound-born spirits, the Bale Hound now appears as one of the Maeltinet. Any Bale Hound with this Gift adds a +2 bonus on all rolls to bargain, bribe or command spirits",Cost:"●",Book:"Blas 140",fullDescription:[{type:"paragraph",text:["With this power, the werewolf’s “spirit-half” is tainted by the Maeltinet. To Wound-born spirits, the Bale Hound now appears as one of the Maeltinet (albeit in a strange, half-fleshly form) and his words (and bribes) are accorded greater weight. Any Bale Hound with this Gift adds a +2 bonus on all rolls to bargain, bribe or command spirits. This Gift lasts for the duration of a scene."]}],fullCost:"1 Essence",dicePool:"No roll is required.",action:"Instant",rollResults:[]},{Rank:"•••",Name:"Blessing of Pain",Description:"The target is suddenly wracked with sickness, and suffers all the penalties of entering a Wound. The effects last for one turn per success on the roll",Cost:"●",Book:"Blas 140",fullDescription:[{type:"paragraph",text:["Wounds cause very real spiritual pain to those who enter them. They are poisoned sections of the world, where aberrations and abominations are born in the Shadow, and they are the very worst of the sickest and most tainted place in the two worlds. The Maeltinet can teach a Bale Hound how to harness the sickening power of a Wound, and force her opponents to feel the spiritual pain of a corrupted world with a single caress. The Bale Hound must touch her target to activate this Gift, though it cannot be “transferred” by a claw or bite."]}],fullCost:"1 Essence",dicePool:"Intelligence + Occult + Purity – target’s Resolve",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Bale Hound is struck with the feelings of pain and unease that he was trying to force on the target. Until the next moonrise, the Bale Hound suffers an additional Health point of damage from all injuries he sustains."]},{type:"line",label:"Failure",text:["Nothing happens."]},{type:"line",label:"Success",text:["The target is suddenly wracked with sickness, and suffers all the penalties of entering a Wound, as detailed on p. 259 of ",{text:"Werewolf: The Forsaken",bold:!0},". The effects last for one turn per success on the roll."]},{type:"line",label:"Exceptional Success",text:["The effects last until the end of the scene, and the roiling, impure sickness is potentially enough to drive the target insane. The target must make a Harmony (substitute Morality or the appropriate trait for non-werewolves) roll with four dice, and suffers a derangement if he fails. Creatures with no Harmony equivalent, such as spirits or Hosts, are immune to this effect."]}]},{Rank:"••••",Name:"Siphon Suffering",Description:"The target is struck by powerful feelings of apathy and lethargy. The Bale Hound gains a point of Essence, and the human suffers a -1 to all dice rolls until she next sleeps and recovers with rest.",Cost:"-",Book:"Blas 140",fullDescription:[{type:"paragraph",text:["The Maeltinet teach the Bale Hounds how to draw the suffering of others to replenish their personal energies, much how a spirit feeds on occurrences of its primary Influence. This Gift allows the Bale Hound to attempt to siphon Essence from a mortal experiencing a negative emotion or urge — lust, wrath, greed and so on. The Gift only works on normal human beings, and only if the target is feeling a negative urge or emotion, such as a Vice, one of the Maeljin’s Influences or an obviously dark emotion such as hatred."]}],fullCost:"N/A",dicePool:"Manipulation + Empathy + Cunning versus the subject’s Morality",action:"Instant and Contested; resistance is reflexive.",rollResults:[{type:"line",label:"Dramatic Failure",text:["The attempt fails, and the Bale Hound is unable to summon the spiritual willpower to spend Essence points until the following moonrise."]},{type:"line",label:"Failure",text:["Nothing happens."]},{type:"line",label:"Success",text:["The target is struck by powerful feelings of apathy and lethargy, as her emotions are spiritually ripped from her mind. The Bale Hound gains a point of Essence, and the human suffers a –1 to all dice rolls until she next sleeps and recovers with rest."]},{type:"line",label:"Exceptional Success",text:["The Bale Hound receives two Essence points instead of one."]}]},{Rank:"•••••",Name:"Communion With the Wounds",Description:"The character immediately gains full knowledge of all Wounds within a 5-mile radius, their proximity to loci, the number of spirits around the areas, the name of the Maeltinet present within each (if any) and general terrain features. When in the area of one of the Wounds he has seen, the Bale Hound gains a +2 to Defense and Initiative",Cost:"●",Book:"Blas 140",fullDescription:[{type:"paragraph",text:["A perverted version of the Knowledge Gift: Communion With the Land, this power is granted to the most powerful Bale Hounds so that they might know the location and details of every Wound nearby. The werewolf opens his mind to the pulsating, sick pressure of the Wounds, and gains the knowledge of what is occurring in each Wounded area within several miles. This knowledge increases the Bale Hound’s understanding of just how to most efficiently defend each Wound, as well as getting a look at the current state of the surrounding areas."]}],fullCost:"1 Essence",dicePool:"Intelligence + Survival + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Bale Hound receives conflicting images and messages from the spirits of the Wounds. She suffers a –1 penalty to all rolls for the rest of the scene as her senses are overwhelmed with the backlash."]},{type:"line",label:"Failure",text:["The werewolf receives no images or messages from nearby Wounds."]},{type:"line",label:"Success",text:["The character immediately gains full knowledge of all Wounds within a 5-mile radius, their proximity to loci, the number of spirits around the areas, the name of the Maeltinet present within each (if any) and general terrain features. When in the area of one of the Wounds he has seen, the Bale Hound gains a +2 to Defense and Initiative. The Gift’s effects lasts for a scene."]},{type:"line",label:"Exceptional Success",text:["As success, but the distance of the knowledge spreads to 10 miles, and the bonus to Defense and Initiative is +3."]}]}]},{Name:"Urban",Description:"",Cost:"",Book:"BotW 62",Content:[{type:"paragraph",text:"Like Nature Gifts, the Gifts of the urban world focus on creatures and spirits of a particular environment, in this case the cities of humans. While useful even in small towns, Gifts are of the most benefit in large cities. Urban Gifts are an affinity Gift list for Iron Masters."},{type:"paragraph",text:"Artificial-spirits and animal-spirits adapted to the world of humans, such as rats, roaches and pigeons, can teach this list of Gifts."}],Ranks:[{Rank:"•",Name:"Concrete Bolt-Hole",Description:"Secure a minor hiding place in the city, adding a +2 to Stealth rolls.",Cost:"●",Book:"BotW 62",fullDescription:[{type:"paragraph",text:["Uratha often need a speedy exit from a messy scene or a place to conceal themselves for a quick change of skins. In the city, this is can be hard to come by. Strip malls and supercenters are crowded and sometimes electronically monitored. This Gift directs the werewolf toward the nearest adequate place to conceal oneself for a scene. This Gift functions only in cities."]}],fullCost:"1 Essence",dicePool:"Wits + Subterfuge + Cunning",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:["The bolt-hole turns out to be automatically compromised in some way. The dumpster is filled with rot-liquefied fish; the alley is full of cops making a drug bust, etc."]},{type:"line",label:"Failure",text:["No hiding place is apparent."]},{type:"line",label:"Success",text:["The nearest useful bolt-hole is discovered. The character receives a +2 bonus to any Stealth rolls made to enter the hiding place without being detected."]},{type:"line",label:"Exceptional Success",text:["The bolt-hole might be large enough for the whole pack, or contain something the character needs or have some added benefit, such as a secondary means of egress."]}]},{Rank:"••",Name:"Foot In The Door",Description:"Gain access over the phone to an expert or contact necessary for one's needs.",Cost:"●",Book:"BotW 62",fullDescription:[{type:"paragraph",text:["Even the most well-connected Uratha runs dry of associates after a while; this Gift can open new doors for her. When the character is in a situation in which she needs the services of a certain kind of professional, she can use this Gift to contact the professional. The character enacts the Gift and then uses some form of communication to contact the person. This may be done via phone, email, IM, letter, smoke signal — whatever form of long-distance communication the Uratha has at hand and knows how to use. This Gift does not speed up the communication, or make a broken cell phone work. In essence, the Uratha is asking a communication-spirit for help in the form of a connection to the resource she needs."]},{type:"paragraph",text:["The Gift does not reward the Uratha with a name or introduction of any sort, just a means to communicate with whomever she needs via a ring tone or a fortuitously delivered piece of mail. The Gift cannot make a broken cell phone work or otherwise create a miraculous line of contact; a means of communication must be at hand before the Gift can be used."]},{type:"paragraph",text:["The Gift can’t be used to contact a particular professional. A character can’t use it to contact “the hitman who killed Mayor Franklin,” although she could use it to contact a contract killer. Nor could she contact “the mayor,” but she could state “someone with the ability to stop Proposition 82.” Of course, the person on the other end is not any way predisposed to work for you, nor are you provided with a ready explanation as to how you got the number."]},{type:"paragraph",text:["For example, a character’s sister gets shot in a strange part of town, and he needs to quickly contact a back-alley doctor to fix her up without alerting the authorities. The Uratha could enact this Gift, asking for “the best black-market doctor available in the city,” and then hit the dial button on his cell phone. If successful, this Gift will dial the appropriate person. It’s up to the character from there."]}],fullCost:"1 Essence",dicePool:"Presence + Streetwise + Glory",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift contacts an enemy, the police or in some other way provokes the authorities."]},{type:"line",label:"Failure",text:["The communication fails — a wrong number, busy signal, out of service area, unexpected network delay, dead letter office or similar result."]},{type:"line",label:"Success",text:["The number of successes indicates the dots in the particular Skill that governs the profession of the person contacted, up to the normal maximums."]},{type:"line",label:"Exceptional Success",text:["The person contacted may have some reason to need a job, or may have otherwise been in a generous mood when contacted."]}]},{Rank:"•••",Name:"Windfall",Description:"Receive a bounty from the city that must be returned once its necessity is expired.",Cost:"●○",Book:"BotW 63",fullDescription:[{type:"paragraph",text:["Some Uratha are forced by circumstance, or perhaps by choice, into a state of near-poverty. Rather than resort to a dangerous spree of petty theft, the Uratha can use this Gift to receive a mundane item or modern convenience that the werewolf needs for a short period of time."]},{type:"paragraph",text:["This Gift calls upon powerful spirits of money and good fortune to put something in the Uratha’s hands for a brief period of time. The Uratha cannot ask for fetishes or cash, although she could ask for the key to a hotel room with a well-stocked mini-bar, for example. The Uratha cannot ask for something that is practically impossible or obviously supernatural."]},{type:"paragraph",text:["It is up to the Storyteller to provide the item. Small items might be found in a trash can; larger items could be found just around the corner from the Uratha’s location."]},{type:"paragraph",text:["There is a huge catch to this Gift; no matter what, the item cannot be retained for longer than the time asked for. The werewolf who breaks this ban suffers a penalty (–4) to use this gift until a Rite of Contrition is performed, and she gives away enough funds or property as an act of chiminage to permanently reduce her Resources by one."]},{type:"paragraph",text:["This Gift cannot be used to gain more than one item at a time."]}],fullCost:"1 Essence and 1 Willpower",dicePool:"Manipulation + Persuasion + Honor",action:"Standard",rollResults:[{type:"line",label:"Dramatic Failure",text:["The item produced is defective, often dangerously so."]},{type:"line",label:"Failure",text:["Nothing happens."]},{type:"line",label:"Success",text:["The Uratha must achieve a number of successes equal to the Resources normally necessary to purchase the item (the monthly rating, not the total assets). For instance, three successes could temporarily call up an item worth up to $1,000. Fewer successes produce a similar item of inferior quality. For instance, if the werewolf has “requested” a van, the Storyteller would determine that a used van would go for about $10,000, and thus require four successes. When the player achieves two successes on the roll, the resulting van is a clunker worth only about $1,000 — it’ll run, but it lacks amenities and is in real danger of breaking down."]},{type:"line",label:"Exceptional Success",text:["No particular bonus apart from the higher wealth limit."]},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["–4","The character has previously kept an item gained from this Gift longer than the allowed time span."],["0","Use of the item for a scene (a couple of hours)."],["–2","Use of the item for a day."],["–4","Use of the item for a week."]]}]},{Rank:"••••",Name:"Urban Awareness",Description:"Gain total awareness of what happens in an urban area.",Cost:"●",Book:"BotW 64",fullDescription:[{type:"paragraph",text:["This Gift allows the werewolf to commune with the spirit of the city itself — gathering information about the state of the neighborhood in her immediate area. The Uratha can see through the eyes of the local fauna, feel the rhythm of the street and sense any presence that is out of the ordinary and/or dangerous. Remember that the perspective is that of the current urban landscape, not the Uratha. Most likely, the area will consider the Uratha a stranger unless the character is a local."]}],fullCost:"1 Essence",dicePool:"Manipulation + Streetwise + Wisdom",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The character is overcome by the riotous sounds and smells of the city and suffers a –1 to all Wits rolls for the remainder of the scene."]},{type:"line",label:"Failure",text:["The city-spirit ignores the character."]},{type:"line",label:"Success",text:["As with Forest Communion, the character slips into a trancelike state. Successful activation of the Urban Awareness Gift allows basic information (presence of strangers, potential threats to the area, such as police, gangs, etc.) up to 500 yards from the werewolf. Each additional success increases the radius by an additional 100 yards and increases the detail of information learned. One success could tell the presence of strangers, while three successes could reveal the species and gender of those intruders. The Gift lasts as long as the user remains in the trance, but she is unaware of and cannot react to the outside world, nor can she relay her findings while the Gift is active. This Gift doesn’t function in a wilderness environment."]},{type:"line",label:"Exceptional Success",text:["No additional effect apart from greater range and increased information."]}]},{Rank:"•••••",Name:"Vermin Riot",Description:"Call up the vermin of the city to attack a target (-2 to any Skill, -2 to Speed, 1 bashing damage per turn)",Cost:"●",Book:"BotW 65",fullDescription:[{type:"paragraph",text:["This Gift wakens the lowliest of lifeforms that have embraced the urban environment to defend it. The streets darken with hordes of rats, lice, cockroaches, ants or termites, or the skies are filled with flocks of swallows or pigeons or clouds of flying insects. These swarms of the city’s vermin attack the Uratha’s foes."]}],fullCost:"1 Essence",dicePool:"Intelligence + Animal Ken + Purity",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Gift runs out of control; the vermin are stirred up into frenzied activity, but swarm erratically rather than attacking a given foe. The Gift cannot be used again for the duration of the scene."]},{type:"line",label:"Failure",text:["The city’s parasites ignore the werewolf’s pleas."]},{type:"line",label:"Success",text:["Each success fills 25 square yards with ever-renewing hordes of vermin deemed appropriate to the location by the Storyteller — pigeons aren’t likely to appear in the subway, for instance.",{type:"lineBreak"},"The swarm can be guided to attack anyone caught within its mass; the werewolf may nominate a target as a reflexive action. This attack has three effects. First, the Speed of anyone targeted with this is automatically reduced by –2. In addition, anyone caught within the swarm suffers one point of bashing damage per turn. Finally, anyone caught in the swarm is at a –2 penalty to any Skill use due to pain, distraction and/or obscured vision.",{type:"lineBreak"},"The swarm lasts for two turns per success, or until the werewolf dismisses it."]},{type:"line",label:"Exceptional Success",text:["No additional effect apart from increased duration."]}]}]}],h=o.flatMap(({Ranks:e=[],...t})=>[t,...e]),s=o.filter(({Content:e=[]})=>Array.isArray(e)&&e.length>0).map(({Ranks:e=[],Content:t=[],...a})=>({...a,Rank:"N/A",fullDescription:t})),i=o.flatMap(({Ranks:e=[],...t})=>e.map(a=>({...a,Name:a.Name||t.Name,Gift:t.Name,GiftBook:t.Book,GiftDescription:t.Description}))),r=[{Name:"Backstage Synchronicity",Description:"When working with the pack members in harmony to come up with new ideas and clever plans, they get a bonus with their wits and restore essence.",prerequisites:"Cunning •••••, Harmony •••••",fullDescription:[{type:"paragraph",text:["Red Wolf grants this Gift to the select few who truly impress him. Those who receive this blessing are never out of the eyes of the Irralunim. They tap in to an ancient compact forged between the spirits and Red Wolf to send Essence flowing through the most audacious plans."]},{type:"paragraph",text:["When the pack members work in harmony to come up with new ideas and clever plans, Backstage Synchronicity rewards the pack with a gift of Essence from the watching Irralunim. This Gift comes into play whenever the pack plans something that counts as a notable feat of Cunning (see p. 194 of ",{text:"Werewolf: The Forsaken",bold:!0},"). The spirits must be impressed with the plan, but while the character remains one of Sagrim-Ur’s chosen, they consider all members of the pack equally. In addition, when the pack puts its plan into action, the character can tap into her innate cunning, increasing her pack’s chances of pulling the plan off. There is no limit to how close her packmates must be, though this Gift works only for deeds committed by members of a pack bound together with a totem. Others who hang around the pack, be they wolf-blooded, vampire, human or anything stranger, cannot perform the deeds required for this Gift. The Irralunim understand only the sacred bonds between pack members."]},{type:"paragraph",text:["Since this is a Milestone Gift, only Iron Masters who perform some great service to their tribe can learn Backstage Synchronicity (see “Milestone Gifts,” p. 12). Normally, Red Wolf chooses those who come up with a truly unique means of pacifying opposition. If the character’s Harmony falls below 6 after he learns this Gift, he has one cycle of the moon to regain spiritual balance, during which he must perform a feat of cunning dedicated to Red Wolf. Sagrim-Ur won’t help ",{text:"Farsil Luhal",italic:!0}," who rest on their laurels. If the character fails, he loses Backstage Synchronicity and can never regain it."]},{type:"paragraph",text:["When carrying out this plan, the werewolf can tap in to her reserves of cunning. She adds a number of dots equal to her Cunning to any pack member’s Wits — she can use this bonus herself, or donate her expertise to help another. This bonus lasts until the end of the scene, or until the plan is complete (whichever comes first), and can only be used once for each plan. If her pack came up with the plan more than a week ago, the Irralunim lose interest, and she must activate this Gift again in order to tap her Cunning."]}],fullCost:"None",dicePool:"Wits + Occult + Cunning",action:"Reflexive",rollResults:[{type:"line",label:"Dramatic Failure",text:"The plan may be good, but the Irralunim have seen vital flaws that offend their mercurial nature. They strip two points of Essence from the character."},{type:"line",label:"Failure",text:"The spirits do not notice, or are not sufficiently impressed by the act to think it worth reward."},{type:"line",label:"Success",text:"The Irralunim are impressed. When the plan is formed, they grant the every pack member two points of Essence. Pack members may have more Essence than their Primal Urge score would normally allow, but any excess points are lost at the end of the scene."},{type:"line",label:"Dramatic Success",text:"The spirits let the character know just how impressed they are. In addition to the effects of a success, the character regains two points of Willpower."},{type:"table",title:"Suggested Modifiers",headers:["Modifier","Situation"],rows:[["–5","The pack have already used a similar plan with this Gift."],["–3","The deed would not be notable for a character with Cunning 2 or above."],["–1","The pack has received Essence for a similar plan, but later decided not to go through with it."],["–1","The deed would not be notable for a character with Cunning 3 or above."],["+1","The deed would be notable for a character with Cunning 4."],["+3","The deed would be notable even for a character with Cunning 5."]]}],Book:"Tribes 149"},{Name:"Destoyer’s Jaws, The",Description:"Whenever you fill an enemy’s rightmost Health box, that enemy dies instantly",Prequisites:"",Book:"Tribes 46",prerequisites:"Glory 5, Honor 3, Harmony 6 or greater",fullDescription:[{type:"paragraph",text:["This Gift is granted by ",{text:"Fenris-Ur",italic:!0}," himself, in recognition of a Blood Talon who embodies the warrior ideal. This blessed personage need not be a Rahu the Destroyer Wolf recognizes the role of the warrior in all his children. This Gift allows the Blood Talon to take on an aspect of his patron spirit’s terrible destructive rage, losing himself in a killing frenzy that inspires witnesses to recall stories of Shiva, or the Fenrisulfr of Norse mythology."]},{type:"paragraph",text:["Once earned, this Gift is permanent and requires no activation roll. Any time the Talon enters Death Rage, he takes on the Destroyer’s Jaws: his muzzle becomes a huge, distended mass of razor-sharp and saw-edged fangs, and when he opens his jaws to bite, witnesses see only an utter, absolute blackness like the end of all things. His howls seem to make reality itself shake on its foundation, and in the power of his limbs, it seems as though the glory of Father Wolf is come to the world once again. The Destroyer’s Jaws is devastating in combat: whenever the Blood Talon fills an enemy’s rightmost Health box, that enemy dies instantly. Even if the wound was only bashing or lethal, it is instantly fatal. The recipient of this Gift gains a point of Essence for every creature he kills while in Death Rage."]}],fullCost:"",dicePool:"",action:"",rollResults:[]},{Name:"Eyes of Death Wolf",Description:"Exchange your eyes with the eyes of Death Wolf, so it can can see into or out of the Shadow merely by concentrating, identify Ridden and other possessed beings on site and know the name of any spirit he encounters.",prerequisites:"Wisdom 5, Harmony 6 or greater",fullDescription:[{type:"paragraph",text:["Death Wolf herself bestows this Gift upon deserving Bone Shadows, and the method isn’t at all pleasant. The Bone Shadow has dreams for a month, during which Lunes and other spirits congratulate him on receiving the honor of the Eyes of the Death Wolf. Then, when the werewolf steps into the Shadow, a great wolf-spirit pounces and drags him into the darkness. His packmates can give chase, but wind up pursuing phantoms and smoke. Death Wolf has the Uratha now."]},{type:"paragraph",text:["Back at her den, Death Wolf attacks the werewolf and plucks out his eyes, consuming them. The Uratha spends hours (though to her, the wait is interminable) blind in the den of his tribal totem. At last, Death Wolf instructs the werewolf to pluck out her eyes — carefully! — and replace his own with them. From that point onward, the Bone Shadow can see into or out of the Shadow merely by concentrating. He can’t see both areas at once, but he can identify Ridden and other possessed beings on site, and the player can spend one Essence point for the character to know the name of any spirit he encounters."]},{type:"paragraph",text:["As a Milestone Gift, Eyes of the Death Wolf is only available to Bone Shadows who perform some great service for the tribe or their packs, usually in the name of protecting werewolves or wolf-blooded from spirits or otherwise upholding the tribal vow (see “Milestone Gifts,” p. 12). If the character’s Harmony drops below 6 after he learns this Gift, he has three cycles of the moon to regain this level of spiritual balance, during which he must perform the Rite of Contrition to Death Wolf. If he fails to do this, he loses the Eyes of the Death Wolf and can never regain it — which unfortunately means he goes blind, forever."]}],fullCost:"",dicePool:"",action:"",rollResults:[],Book:"Tribes 78"},{Name:"Hunter’s Bounty, The",Description:"Allows to replenish essence simply by hunting and catching food",prerequisites:"Purity 5, Harmony 6 or greater",fullDescription:[{type:"paragraph",text:["This Gift, granted by Black Wolf herself, allows the Hunter to replenish his spiritual energy simply by hunting and catching his own food. Any werewolf can hunt and kill wolves, humans or other werewolves and steal their Essence, but this is a grievous violation of Harmony and the Oath of the Moon, and those Uratha who practice such cannibalism wind up ",{text:"Zi’ir",italic:!0}," in short order. A ",{text:"Meninna",italic:!0}," with this Gift, however, can hunt and kill any animal that would serve as prey for a wolf and regain Essence from it. The Hunter’s Bounty allows the wolf to consume prey animals only for Essence; while a wolf might conceivably eat other predators if it had the opportunity or grew hungry enough, Black Wolf frowns on hunting such animals for food."]},{type:"paragraph",text:["This Gift, once granted, is permanent. The Hunter in Darkness regains one point of Essence for every point of Health that the animal possesses, provided that he strips all usable meat from the carcass (that is, the werewolf doesn’t need to eat the bones). If the Hunter is part of a pack, he can regurgitate meat for his packmates (along with as much Essence as he wishes), which they can then consume to regain Essence. Since this treatment usually implies a mother-cub relationship, though, some werewolves don’t feel comfortable accepting such treatment from another Uratha (to say nothing of the fact that some werewolves might feel disgusted by the prospect)."]},{type:"paragraph",text:["As a Milestone Gift, The Hunter’s Bounty is available only to Hunters in Darkness who perform some great service for the tribe or their packs, usually in the name of protecting a sacred place (see “Milestone Gifts,” p. 12). If the character’s Harmony drops below 6 after he learns this Gift, he has one cycle of the moon to regain this level of spiritual balance, during which he must perform the Rite of Contrition to Black Wolf. If he fails to do this, he loses The Hunter’s Bounty and can never regain it."]}],fullCost:"",dicePool:"",action:"",rollResults:[],Book:"Tribes 112"},{Name:"Storm’s Whisper",Description:"Once per game session, one member of her pack to receive a blessing (+2 to any rolls) and one to receive castigation (-2 to any rolls)",prerequisites:"Honor 5, Wisdom 2, Harmony 6 or greater",fullDescription:[{type:"paragraph",text:["Honor is a duplicitous thing. Luna is divided by honor: one side of her face is dark and punishing, the other light and rewarding. Those with profound Honor, those within the Storm Lords, must walk the line between those two realms. The proper Storm Lord is just and generous, and has the authority to dole out rewards, or mete out justice."]},{type:"paragraph",text:["This Gift is granted by Skolis-Ur himself in recognition of a Storm Lord who embodies the ideals of his tribe and of Honor Renown. Winter Wolf recognizes the role of arbiter and ruler in this werewolf, and grants his child a measure of judgment."]},{type:"paragraph",text:["For some, this Gift is both boon and bane. Once per game session, the Storm Lord imbued with this Milestone Gift ",{text:"must",italic:!0}," select one member of her pack to receive a blessing from Winter Wolf, and one to receive castigation from Skolis. The blessing is a +2 bonus to all rolls, while the castigation comes in the form of a –2 penalty to all rolls. These modifiers last for one lunar cycle, or until the Storm Lord uses Storm’s Whisper to select new recipients of the reward and punishment."]},{type:"paragraph",text:["How she selects the chosen members of her pack is up to her: she can accept input from the pack, or she can decide in her own authoritative manner. Perhaps she always chooses the lowliest member of the pack to receive the curse and the alpha to receive the blessing. She may not select herself for either of them. Her decisions, however she makes them, are sure to earn her some level of enmity from her pack, but this is by Winter Wolf’s design: leaders and judges are not to be loved, only to be obeyed."]},{type:"paragraph",text:["Note that this Milestone Gift is named after the legendary member of the tribe, Storm’s Whisper (p. 168). When the werewolf possessing this Gift uses it to choose the two packmates, she must whisper in each Uratha’s ear to deliver the boon or bane. It’s said that her voice is different during that whisper: a sentence delivered not by the Storm Lord but by Storm’s Whisper."]},{type:"paragraph",text:["As a Milestone Gift, Storm’s Whisper is available only to a Storm Lord who performs some great service to his tribe or pack, often heroically demonstrating the skills of a leader or a judge — one who offers only strength and never weakness (see “Milestone Gifts,” p. 12). If the character’s Harmony drops below 6 after he learns this Gift, he has one cycle of the moon to regain this level of spiritual balance, during which he must perform the Rite of Contrition to Winter Wolf. If the character fails to do this, he loses Storm’s Whisper and can never regain it. In addition, he gains a mild derangement as a result."]}],fullCost:"",dicePool:"",action:"",rollResults:[],Book:"Tribes 183"},{Name:"Thief of Shadows",Description:"Become able to purchase the supernatural powers of any other creatures",prerequisites:"Cunning 5",fullDescription:[{type:"paragraph",text:["Innumerable shadows exist under Mother Moon and countless strange creatures hide within them. Sorcerers cast ancient magics, while dead-but-living things feast upon the vitality of the herd, ghosts walk unseen through a dark reflection of life, and spirits exert their alien powers over the world in a multitude of ways. The Irraka walks within all of these shadows, impelled by Luna’s inviolable mandate."]},{type:"paragraph",text:["Bound to the creed of Cunning, a New Moon steals what he needs from any and all who possess what he can best use to serve his pack and his People. Through careful observation, some legendary Irraka learn how to pilfer the secrets of the other entities that walk under the Mother’s concealing darkness, transforming their abilities into something like the Gifts of the Uratha."]},{type:"paragraph",text:["The Irralunim, Nih Mehar — one of the Greater Incarnae, sworn directly in service to Amahan Iduth — judges the Irraka’s worthiness of this potent Gift through tests and trials, inflicted upon him without his knowledge. The spirit watches the Stalker’s progress upon the path, occasionally taking on earthly forms to help or hinder him (typically through good or bad advice from strangers or relatively insignificant spirits). Nih Mehar is much more interested in the Irraka’s ability to apply unorthodox thinking to the problems that beset him than in his success or failure; living up to every ideal of Cunning and falling short is infinitely preferable to succeeding through crude and unimaginative means. The Irralunim tests each of the ",{text:"other four",italic:!0}," Renowns, to see how the Stalker applies the tenets of Cunning to them."]},{type:"paragraph",text:["First, the spirit challenges the Irraka with an ordeal of Wisdom, setting forth a quandary that can only be solved through clever thinking: a choice between saving the life of a beloved wolf-blooded mate and getting a message to one’s packmates regarding the imminent intrusion of a pack of Bale Hounds into their territory, for example, or the need to overcome a powerful spirit of reason in a weeks-long riddle contest with deadly stakes. Only by applying trickery, treachery, and unorthodox thinking to the problem can the Stalker truly triumph."]},{type:"paragraph",text:["Next, Nih Mehar tests the Irraka’s Honor, offering temptation at the cost of Harmony, a violation of the Oath of the Moon, or even just personal principles: a potent fetish to be gained only through the breaking of one’s solemn vow or a meaningful victory against the Pure only attainable through betrayal of one’s pack. To succeed in the trial, the Stalker must find a way to gain the object of contention through Cunning means that break the rules of the test without neglecting the demands of Honor."]},{type:"paragraph",text:["The spirit’s next ordeal is one of Glory, giving the Stalker the chance to take the spotlight, but at the cost of some significant advantage that could have been maintained had he remained in the shadows: defeating a powerful enemy spirit through an act that tips the pack’s hand and reveals the full extent of both its strengths and its weaknesses to other werewolves or being the lynchpin of the victory that ends a protracted war against a number of local Pure packs, only to lose a number of important territories. To overcome, the Irraka must somehow cheat his way through the choice placed before him to successfully perform the Glorious deed without relinquishing the threatened resource."]},{type:"paragraph",text:["Nih Mehar’s final test is one of Purity. The Irralunim save this most perilous task for last, giving the New Moon the opportunity to satisfy his own wishes at the expense of what makes him Uratha: a chance to viciously ruin the life of and ultimately murder the Ivory Claw that killed his packmate or gaining great advantage for the members of his pack through encouraging them in acts that compromise their Harmony. Only by acquiring the object of desire while remaining true — necessitating deep, but subtle, treachery — does the Stalker satisfy the spirit."]},{type:"paragraph",text:["Nih Mehar reveals itself to those few who meet or exceed its harsh standards, offering them the knowledge of its Gift. Those who are privileged with such lore soon come to perceive the invisible motions of the spirits behind ",{text:"all",italic:!0}," things, even the indirect ways in which they interact with powers alien to their kind… and to the Uratha. By studying the intricate weave of these energies, the Irraka can begin to replicate them by rote, compelling similar effects through duplicating the effects upon the spiritual environment."]},{type:"paragraph",text:["Thief of Shadows enables a New Moon to purchase the supernatural powers of other creatures — vampires, mages, ghosts, spirits, and the like — as though they were Gifts. The Irraka must be able to closely study the power in use in order to make use of this ability. Merely having a paranormal ability used upon her isn’t enough; she must observe the power’s impact both in the material realm and in Shadow, and watch the way in which its use ripples outward among the spirits. Like making an image of something by using its impression as a mold, the Stalker gradually teaches herself to imitate the ability’s reflection in Shadow and, thereby, to mimic what she sees."]}],fullCost:"5 Essence per roll, plus 1 Willpower dot",dicePool:"Wits + Subterfuge + Cunning",action:"Extended (5 successes per dot level of the power, or 30 successes for a spirit or ghost Numen)",rollResults:[{type:"line",label:"Dramatic Failure",text:["The Irraka may ",{text:"never",italic:!0}," gain the particular power that she is attempting to acquire and loses a dot of Willpower, anyway."]},{type:"line",label:"Failure",text:"The character makes no progress toward learning the power she wishes to replicate."},{type:"line",label:"Success",text:"The character makes progress toward duplicating the supernatural ability in question."},{type:"line",label:"Exceptional Success",text:"Significant progress is made."},{type:"paragraph",text:["Each time the New Moon observes a use of the specific power that she wishes to steal, her player may roll this Gift’s dice pool, spending the necessary Essence and banking her successes, if any. When the necessary number of successes is acquired, the character spends a permanent dot of Willpower (which may be repurchased at a cost of eight experience points) and may then buy the specific supernatural ability studied at a cost of eight experience points per dot level of the power. In other words, if the Irraka methodically haunts the steps of a vampire using the fourth dot of one of her paranormal abilities to repeatedly strike terrible fear into the hearts of others and the player eventually accrues 20 successes on the Gift’s extended roll while observing the power in use, then she may spend 32 experience points and one of the character’s Willpower dots to purchase that power for her character, who may use it as though it were a Gift."]},{type:"paragraph",text:["The power uses the same Attribute + Skill combination as normal, though Cunning is substituted as the third component of the power’s dice pool. For spirit and ghost Numina, the Storyteller is instead encouraged to come up with an appropriate Attribute + Skill combination for the New Moon (a Numen intended to strike out at someone with telekinetic force might pair Strength and Intimidation, for example, while one that discerns the presence of strange phenomena might make use of Wits and Occult). The Irraka cannot teach these “pseudo-Gifts” to others; they are hers and hers alone."]}],Book:"SotM 34"},{Name:"Words of Power",Description:"Once per chapter, may resolve any rite as an instant action instead of an extended action.",prerequisites:"Wisdom 5, Harmony 7+",fullDescription:[{type:"paragraph",text:["The truly powerful shamans of old could call up and banish spirits with a single word, their very voices laden with the power of Father Wolf and Mother Luna. Some say those stories are just myths, that they exaggerated the abilities of their protagonists for dramatic effect, or that if such Crescent Moons did exist, that the days in which such things were possible are long gone."]},{type:"paragraph",text:["They are wrong."]},{type:"paragraph",text:["To earn the right to speak the Words of Power, an Ithaeur must pass three tests (the character is not aware that she is being tested, but Mother Luna and her Ithalunim watch all of her children for signs of greatness)."]},{type:"paragraph",text:["First, she must fail in some important task or goal. This shouldn’t be a simple failure resulting from the luck of the dice (e.g. if it’s vitally important that a powerful spirit be bound into a fetish, a mere failure on the ritual’s roll shouldn’t count), but a true failing on the character’s part. Perhaps she underestimated the spirit’s power, or assumed (incorrectly) that she knew its ban, leading to her failure. Once she has realized her failure, the Ithaeur must learn from it and correct it. Wisdom does not come from perfection, but from making mistakes and learning from them."]},{type:"paragraph",text:["Second, the Ithaeur must venture into the Shadow and converse with a spirit of at least Rank 5 and come away from the encounter with knowledge. The nature of what she learns doesn’t matter to the Ithalunim, as long as it is knowledge the character needs. Not only must she gain knowledge, she must, in the eyes of the Lunes, have gotten the better end of the deal. This is largely up to the Storyteller’s discretion: if the Ithaeur gains some arcane piece of knowledge about an enemy but must give up half the loci in her territory to the spirit, that probably doesn’t count as the better end of the deal (unless, for instance, the knowledge gained from the exchange will later allow the Ithaeur to retake those loci)."]},{type:"paragraph",text:["Finally, the character must earn Wisdom Renown in a manner auspicious enough to draw the respect of the Ithalunim. Since even learning the Gift requires Wisdom 5, this requirement is usually the first one met."]},{type:"paragraph",text:["If all of these conditions are met, the Ithaeur might be taken deep into the Shadow, into places that have no reflection in the physical realm, by one of the Ithalunim. The character is stripped of all her possessions and told this is a test from Luna: if she can make her way back to the physical world before the next crescent moon dawns, she will be proven worthy. The Ithaeur may refuse the test, in which case the Ithalunim returns her to her territory, but she can never learn the Words of Power. Should she fail, she likewise cannot learn the Words of Power. If, however, she succeeds in the spirit’s challenge, the Ithalunim open her eyes and her mind, teaching her ancient, terrible words in the First Tongue, which no other Uratha knows."]}],fullCost:"None (If the character wishes to use this Gift more than once per chapter, each subsequent use costs 5 Essence.)",dicePool:"None",action:"Reflexive",rollResults:[{type:"paragraph",text:["Once per chapter, the Ithaeur may resolve any rite she knows as an instant action instead of an extended action. The mechanics of the rite remain unchanged, with the following exceptions:"]},{type:"list",items:["The rite’s action type changes to instant.","The number of required successes is ignored. Like most other instant actions, a single success is enough to activate the rite, with five or more successes earning an exceptional success. If the rite’s effects are tied to the number of successes (for example, the Rite of Shared Scent normally requires five successes per pack member), reduce the number of successes to one. To continue the Rite of Shared Scent example, each success would allow the ritemaster to affect a single packmate.","If the rite is contested, the target rolls its contesting dice pool as a reflexive action, and whoever earns the most successes wins the contest."]},{type:"paragraph",text:["This Gift does not remove any material requirements from the rite (for example, the Call Gaffling rite still requires “chiminage” and a howl of summoning, the Fetish Rite still requires a vessel)."]},{type:"paragraph",text:[{text:"Example:",bold:!0,italic:!0}," ",{text:"Jessie Shaker needs to banish the disease-spirit that just put her pack down back to the Shadow in a hurry. She uses the Banish Spirit rite (",italic:!0},{text:"Werewolf: The Forsaken",bold:!0,italic:!0},{text:" p. 152) in conjunction with Words of Power. This is the first time during this chapter she has used her Milestone Gift, so she doesn’t have to pay 5 Essence. Banish Spirit is normally an extended and contested action, with each participant aiming for 10 successes, but in this case the action is resolved in a single contested roll. Jessie’s player rolls Jessie’s Harmony of 8 and gets 3 successes, while the Storyteller rolls the spirit’s Resistance of 6 and gets 2 successes. The spirit vanishes and returns to the Shadow. Jessie’s roll is high enough to earn an exceptional success, but the Banish Spirit rite doesn’t have any additional effects for an exceptional success.",italic:!0}]},{type:"paragraph",text:[{text:"After the battle, Jessie wants to heal her gravely-injured packmates with the Rite of Healing (",italic:!0},{text:"Werewolf: The Forsaken",bold:!0,italic:!0},{text:" p. 159). She doesn’t have hours to sit around and perform the rite, so she again invokes the Words of Power. This time it costs her 5 Essence. Jessie’s player rolls Jessie’s Harmony and gets 5 successes. She can heal up to five points of aggravated damage with that roll, but each point healed costs 2 Essence. Jessie only has 8 Essence left after spending the Essence to use Words of Power, so she spends those 8 points and heals a total of four points of aggravated damage her packmates have suffered.",italic:!0}]}],Book:"SotM 69"},{Name:"Absolute Authority",Description:"Any Empathy, Investigation, or Politics rolls made to uncover truth are Rote Actions, sees everything, including ghosts and spirits in Twilight, can send the restless dead on to whatever awaits them, banish spirits to the Shadow and humans to the physical world, unravel illusions, and free minds from the influences of others.",prerequisites:"Harmony ••••••, Honor •••••",fullDescription:[{type:"paragraph",text:["While most Elodoth come to the attention of the Elunim, only a handful in each generation lives up to the choir’s ideals. Those few feel the eyes of the spirits on them at all times, watching and judging them — but also reinforcing their judgments. A werewolf chosen by the Half Moon choir is no longer just an Elodoth. She is the spirits’ envoy, a walking paragon of honor and justice, an avatar of ultimate truth. But Lunes are dangerous spirits, and if their chosen ones anger the choir, their revenge is terrible."]},{type:"paragraph",text:["A werewolf who possesses this Gift instinctively knows how to find the truth in any conflict. She doesn’t just know which side in an argument is the closest to being right, but by careful questioning and investigation can discover the objective truth. Any Empathy, Investigation, or Politics rolls made to uncover truth are Rote Actions (see ",{text:"The World of Darkness",bold:!0},", p. 134)."]},{type:"paragraph",text:["Discovering the truth is just one facet of the Elunim’s ultimate Gift. The Elodoth is charged with ",{text:"enforcing",italic:!0}," that truth in the world — as walker of the boundaries, she must make sure everything remains where it should be. When she does so, half her body shines as if in moonlight and half is shrouded in darkness. She sees everything, including ghosts and spirits in Twilight. With a glare she can send the restless dead on to whatever awaits them, banish spirits to the Shadow and humans to the physical world, unravel illusions, and free minds from the influences of others."]},{type:"paragraph",text:["As a Milestone Gift, only Elodoth who perform some great act that embodies their auspice can learn Absolute Authority (Milestone Gifts are described in the Introduction, p. 5). Normally, the Elunim choose those who try to live up to the inherent contradictions of the Half Moon, taking every role rather than focusing on just one side of things. If the character’s Harmony falls below 6 after he learns this Gift, he has one cycle of the moon to regain spiritual balance, during which time he must perform a feat of honor dedicated to the Elunim — striking a temporary truce between Forsaken and Pure against some far greater foe, or binding the Shadow Archon that troubled Lycurgus the Bold with a powerful oath. If the character fails, he loses Absolute Authority and can never regain it."]}],fullCost:"2 Willpower",dicePool:"Presence + Intimidation + Honor",action:"Instant",rollResults:[{type:"line",label:"Dramatic Failure",text:"The werewolf attunes himself to the true nature of the world, but it all happens too fast. Overwhelmed with confusing, conflicting information, she suffers a –3 penalty to all actions until the end of the scene."},{type:"line",label:"Failure",text:"The Elunim withhold their authority for some reason. Has the character displeased them, or are the spirits merely fickle servants of the mad Mother?"},{type:"line",label:"Success",text:"With one eye pearly white and one absolute black, the Elodoth becomes gatekeeper to the world, returning things to their rightful place and showing illusions as falsehoods."},{type:"list",items:["The werewolf can see creatures in Twilight, and can move them to where they should be. By expending a point of Essence, she can send a Twilight being to its rightful place — sending spirits into the Shadow and ghosts on to the Underworld. To resist the shift, a spirit or ghost spends a point of Willpower and rolls Resistance. If the immaterial being gets more successes than the werewolf did when activating this part of the Gift, it remains where it is. Beings that have Attributes and Skills such as disembodied mages roll Resolve + Composure instead. Uratha, being half-spirit, can spend a point of Essence to be forced into the Shadow rather than materializing fully.","She can also detect illusions by scent, and free those afflicted. By touching someone taken in by any illusion, she can spend a point of Essence to render that person immune to all illusions until the end of the scene.","The werewolf can also free people from all forms of mental control or compulsion, returning control of the target’s faculties to himself for a scene. She gains the benefits of this part of the Gift as soon as she succeeds at the roll.","The effects of this Gift last for a scene. At the end of that scene, the character loses all her remaining points of Essence, and for the next scene her Essence maximum is set to 0."]},{type:"line",label:"Exceptional Success",text:"The Elunim bless the character, leaving her with a small reserve of spiritual power rather than taking it all from her when the Gift’s effects end. The character loses all but two points of Essence (if she had more than two at the end of the scene) and for the next scene her Essence maximum is set to 2."}],Book:"SotM 104"},{Name:"Songs of Uplifting Glory",Description:"If use willpower to enhance a roll, if tthe roll fails, count the roll as having a single success. If the roll succeeds with fewer than five successes, consider to have resulted in five successes. If are attained five or more successes, does not lose the Willpower point spent and gains an additional point of Willpower",prerequisites:"Glory 5",fullDescription:[{type:"paragraph",text:["To satisfy the Cahalunim that a Cahalith is a walking legend among her people, she must honor an ancient pact with the Gibbous choir by showing visions of the past, present, and future. To do this, she must arouse the interest of Luna herself, so that she sends her emissaries, Ubita, Uda and Egir."]},{type:"paragraph",text:["To satisfy Ubita, Lune of Glories Past, the Cahalith must in some way restore a story or tale that has been otherwise lost from the world. A snippet of private information from a slumbering spirit is not enough, as indeed the story restored must be something of lasting impact. Revealing the past names and bans of an ",{text:"idigam",italic:!0}," would suffice, while recounting an older story about a minor rage spirit would simply not satisfy Ubita."]},{type:"paragraph",text:["To satisfy Uda, the Lune of Glories Now, the werewolf must be of such fame or notoriety that Cahalith on five separate continents must have sung the praises of the character at the same time. (This usually requires the character having at least a Glory of four or five dots.)"]},{type:"paragraph",text:["To satisfy Egir, the Lune of Glories Yet to Come, the Cahalith must have had a vision of a terrible fate to befall her, and accept Luna’s cold grace. Furthermore, the Cahalith must have done nothing to prevent that fate from occurring, enduring it instead. Simply knowing that a date will go poorly, or that a fight might not be successful but going through it anyway will not do. In the case of Egir’s blessing, the Cahalith must face some terrible reality; maybe the inevitable death of a packmate, or even the destruction of a locus, but no matter what, he face the fate unflinchingly. Of course, telling which visions are meant to be changed and which are meant to be accepted is no simple thing, and so this is a mark of a truly great Cahalith."]},{type:"paragraph",text:["Once the Cahalith has satisfied the Three Sisters in these ways, she may be considered an inspiration to any and all around her, but one final hurdle awaits. Once charged by the Three Sisters, the Cahalith must find a potent spirit (at least a lesser Jaggling), and tell that spirit a story that evokes an emotion contrary to its nature. The Cahalith might seek out a spirit of murder and tell a tale so sad that it is driven to tears, or seek out a spirit of sorrow and make it laugh. With that complete, the Three Sisters call their choir together to sing the story of the Cahalith and infuse her forever with those songs of praise."]},{type:"paragraph",text:[{text:"System:",bold:!0}," This Gift does not require activation. Once the Cahalith has learned it, its effects are permanent, adding additional advantage to Willpower expenditure. A legend of this caliber does not just succeed; she excels, she inspires, she overwhelms opposition. More importantly, she never fails when it matters."]},{type:"paragraph",text:["Any time the Cahalith spends a point of Willpower to enhance her rolls, she does not get the traditional three-dice benefit. Instead, if her roll fails, count the roll as having a single success. If her roll succeeds with fewer than five successes, consider the roll to have resulted in five successes. If she attained five or more successes, not only does she not lose the Willpower point spent, but also she gains an additional point of Willpower, not to exceed her limit. With any use of this power, all those favorable witnesses to her greatness gain a point of Willpower, similar to the use of the Inspiring Merit."]}],fullCost:"",dicePool:"",action:"",rollResults:[],Book:"SotM 144"},{Name:"Luna's Gaze",Description:"Can always see in even pitch dark, become impossible to surprise, cannot fail rolls to spot hidden opponents.",prerequisites:"Purity 5, Harmony 7+",fullDescription:[{type:"paragraph",text:["Any werewolf can fight, but only a few are true warriors. Luna sometimes sends her Ralunim to bestow this Gift upon Rahu who are diligent in protecting and guiding their packs, and who maintain their commitment to Harmony no matter what the cost."]},{type:"paragraph",text:["In order to be granted this Gift, the werewolf must fulfill three criteria. First, he must suffer temptation to break the Oath of the Moon and resist it. The temptation that he suffers need not be commensurate with his current level of Harmony (that is, it might be as simple as being tempted to forego a hunt for a more human concern, such as a good friend’s wedding), but often the temptation involves one of the most important precepts of the Oath. The Rahu might meet a werewolf that he feels would make an ideal mate — or, conversely, that he feels the world would be better off without. In any case, no matter what justifications he might otherwise be able to make for breaking the Oath, he ",{text:"must",italic:!0}," keep to the precepts of Purity."]},{type:"paragraph",text:["Second, the werewolf must uncover a serious threat to his pack ",{text:"before",italic:!0}," it gains an advantage on him. Learning that a local vampire is gathering data on the pack and eliminating said ",{text:"muth luzuk",italic:!0}," would qualify, even if the vampire had no immediate plans to harm the werewolf."]},{type:"paragraph",text:["Finally, the Rahu must earn Purity in a manner that catches the attention of the Ralunim (since the Gift requires Purity 5, this is usually not a problem)."]},{type:"paragraph",text:["Once the character has fulfilled all of these criteria, Luna sometimes, though not always, sends a Lune to open the character’s eyes. The Ralunim grasps the werewolf by the head and exhales moonlight into him. The character becomes blind, but the Lune informs him that this is a Gift from Luna and he must not question it. He remains blind until the next full moon. If he rails against his fate, curses Luna or complains even the slightest bit, his sight returns, but he risks degeneration (roll three dice) and can never gain this Gift. If he suffers this test well, his sight returns as the full moon rises, and his eyes forever after glow with faint moonlight."]},{type:"paragraph",text:[{text:"System:",bold:!0}," The character can always see in even pitch dark. In addition, the character is impossible to surprise. Reaction to Surprise rolls always succeed, but the player should still roll to check for an exceptional success (see p. 46 of the ",{text:"World of Darkness Rulebook",bold:!0},"). Finally, the character cannot fail rolls to spot hidden opponents; opposed rolls to find such characters always have at least one success, regardless of what the player rolls. In addition, ties always go to the Rahu on these actions."]}],fullCost:"",dicePool:"",action:"",rollResults:[],Book:"SotM 180"}],n=r.map(e=>({...e,Gift:"Milestone Gift"})),l=[...s,...i,...n];export{o as giftData,l as giftDetailData,h as giftFlatData,s as giftOverviewDetailData,i as giftRankDetailData,n as milestoneGiftDetailData,r as milestoneGifts};
